                Translate(GUID, null, "[c:bR]The Clock[c:] and your [c:bR]" + value.DisplayedNameLocalized + "[c:] will remain in that abandoned time.", "[c:bR]시계[c:]와 네 [c:bR]" + value.DisplayedNameLocalized + "[c:]은(는) 버려진 시간에 남는다.", Language.Korean);
                Translate(GUID, null, "False " + value.DisplayedNameLocalized, "가짜 " + value.DisplayedNameLocalized, Language.Korean);
                Translate(GUID, null, "[c:bB]That " + value.DisplayedNameLocalized + " costs more energy than you have.[c:]", "[c:bB]" + value.DisplayedNameLocalized + "의 비용이 보유 에너지보다 많다.[c:]", Language.Korean);
