                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped to play [c:bG]" + value.DisplayedNameLocalized + "[c:].", "네 [c:bG]저울[c:]이 너무 기울어 [c:bG]" + value.DisplayedNameLocalized + "[c:]을(를) 낼 수 없다.", Language.Korean);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]" + value.DisplayedNameLocalized + "[c:] requires you to pay in life, in which you can not fullfill without killing yourself.", "[c:bG]" + value.DisplayedNameLocalized + "[c:]은(는) 생명을 지불해야 하며, 그러면 스스로 죽게 된다.", Language.Korean);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You would kill yourself if you played [c:bG]" + value.DisplayedNameLocalized + "[c:]. Your [c:bG]Scales[c:] are too tipped", "[c:bG]" + value.DisplayedNameLocalized + "[c:]을(를) 내면 죽게 된다. 네 [c:bG]저울[c:]이 너무 기울었다.", Language.Korean);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped and you lack the [c:gray]Foils[c:] to play " + value.DisplayedNameLocalized + ".", "[c:bG]저울[c:]이 너무 기울었고 [c:gray]포일[c:]도 부족해 " + value.DisplayedNameLocalized + "을(를) 낼 수 없다.", Language.Korean);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You lack the foils to play that [c:gray]" + value.DisplayedNameLocalized + "[c:].", "[c:gray]" + value.DisplayedNameLocalized + "[c:]을(를) 낼 포일이 부족하다.", Language.Korean);
                for (int count = 0; count <= 20; count++)
                {
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:gray]" + value.DisplayedNameLocalized + "[c:] requires you pay it's cost in [c:gray]foils[c:], that which you have [c:gray]" + count.ToString() + "[c:].", "[c:gray]" + value.DisplayedNameLocalized + "[c:]의 비용은 [c:gray]포일[c:]로 지불하며, 보유량은 [c:gray]" + count.ToString() + "[c:]이다.", Language.Korean);
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That [c:gray]" + value.DisplayedNameLocalized + "[c:] has the cost of [c:gray]" + count.ToString() + "[c:] foils, which you do not have.", "[c:gray]" + value.DisplayedNameLocalized + "[c:]의 비용은 포일 [c:gray]" + count.ToString() + "[c:]이지만 부족하다.", Language.Korean);
                }
            }

            // Sire_MoDeers
            if (source == null) Debug.Log("Post Register Translations for Sire_MoDeers");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, value.DisplayedName + "'s Protector", value.DisplayedNameLocalized + "의 수호자", Language.Korean);
            }

            if (source == null) Debug.Log("Post Register Translations Ended");
            stopwatch.Stop();
            if (source == null) Debug.Log($"PostRegisterTranslations 执行时间: {stopwatch.ElapsedMilliseconds} ms");
        }

        private static List<PostRegisterCardData> CachePostRegisterCardData(IEnumerable<CardInfo> source)
        {
            var cards = new List<PostRegisterCardData>();
            foreach (var card in source)
            {
                if (card.SafeIsUnityNull()) continue;
                cards.Add(new PostRegisterCardData(card, card.IsBaseGameCard()));
            }
            return cards;
        }

        private sealed class PostRegisterCardData
        {
            public PostRegisterCardData(CardInfo card, bool isBaseGameCard)
            {
                IsBaseGameCard = isBaseGameCard;
                DisplayedNameEnglish = card.DisplayedNameEnglish;
                DisplayedNameLocalized = card.DisplayedNameLocalized;
                DisplayedName = card.displayedName;
                Description = card.description;
                Name = card.name;
                Attack = card.Attack;
                Health = card.Health;
                Abilities = card.Abilities?.ToArray() ?? Array.Empty<Ability>();
            }

            public bool IsBaseGameCard { get; }
            public string DisplayedNameEnglish { get; }
            public string DisplayedNameLocalized { get; }
            public string DisplayedName { get; }
            public string Description { get; }
            public string Name { get; }
            public int Attack { get; }
            public int Health { get; }
            public Ability[] Abilities { get; }
            public bool HasDisplayedNameEnglish => DisplayedNameEnglish != null;
            public bool HasDisplayedName => DisplayedName != null;
        }
        private static bool NameStartsWithVowel(string name)
        {
            if (string.IsNullOrEmpty(name))
            {
                return false;
            }
            char c = name.ToLowerInvariant()[0];
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        }

    }

