    public class MagnificusMod
    {
        public static Dictionary<string, string> Cards = new();
        public static Dictionary<string, List<KeyValuePair<string, string>>> CardsDescription = new();

        public static Dictionary<string, string> Abilities = new();

        public static void RegisterCard(string en, string zh, string desen, string deszh)
        {
            if (!Cards.ContainsKey(en))
            {
                Cards.Add(en, zh);
            }
            if (!CardsDescription.ContainsKey(en))
            {
                CardsDescription[en] = new List<KeyValuePair<string, string>>();
            }
            CardsDescription[en].Add(new KeyValuePair<string, string>(desen, deszh));
        }

        public static void RegisterAbility(string en, string zh)
        {
            Abilities.Add(en, zh);
        }

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Magnificus Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "New Magnificus Run", "매그니피쿠스 새 도전", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW MAGNIFICUS RUN", "매그니피쿠스 새 도전", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "View Deck", "덱 보기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TOWER OF MAGICKS", "마법의 탑", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOO DUNGEON", "점액 던전", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LAVA DUNGEON", "용암 지하감옥", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VOID DUNGEON", "공허 지하감옥", Language.Korean);

            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automatically unlocks every challenge and starter deck in Magnificus' Kaycees Mod. This does NOT change your magnificus challenge point value. If you have a change of heart and decide to unlock the challenges fairly, your challenge points will remain the same.", "매그니피쿠스의 케이시 모드에서 모든 도전과 초기 덱을 자동으로 해제한다. 매그니피쿠스 도전 점수는 바뀌지 않는다. 나중에 마음이 바뀌어 정당한 방법으로 도전을 해제하기로 해도 도전 점수는 그대로 유지된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Base wizard cards from act 2 will keep their original statlines.", "2막의 기본 마법사 카드들은 원래 능력치를 유지한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use the old 2D flat card designs instead of the new 3D models.", "새 3D 모델 대신 예전 2D 평면 카드 디자인을 사용한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add paint splashes to the background of every card (like in the original magnificus finale).", "원작 매그니피쿠스 최종전처럼 모든 카드의 배경에 물감이 튀는 효과를 추가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third person perspective for magnificus' game. Disable if you want the classic first person experience.", "매그니피쿠스의 게임을 삼인칭 시점으로 플레이한다. 기존 일인칭 시점을 원하면 비활성화한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Show a grid around the player in tabletop mode.", "탁상 모드에서 플레이어 주변에 격자를 표시한다.", Language.Korean);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Mox", "빈 목스", Language.Korean);
            RegisterAbility("Blank Mox", "빈 목스");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, it will materialize into a random Mox Crystal. \n When on another card, the card will generate a random Mox Crystal.", "이 도장을 지닌 카드를 뽑으면 무작위 목스 수정으로 실체화한다.\n다른 카드에 이 도장이 있으면 그 카드가 무작위 목스 수정을 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undecided Mox", "형체 없는 목스", Language.Korean);
            RegisterAbility("Undecided Mox", "형체 없는 목스");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, select a mox type for this card to provide.", "이 도장을 지닌 카드를 내면 이 카드가 제공할 목스 종류를 선택한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Heart", "루비 심장", Language.Korean);
            RegisterAbility("Ruby Heart", "루비 심장");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Ruby Mox in its place.", "이 도장을 지닌 카드가 사망하면 원래 자리에 루비 목스를 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Heart", "사파이어 심장", Language.Korean);
            RegisterAbility("Sapphire Heart", "사파이어 심장");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Sapphire Mox in its place.", "이 도장을 지닌 카드가 사망하면 원래 자리에 사파이어 목스를 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Marrow", "골수", Language.Korean);
            RegisterAbility("Bone Marrow", "골수");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When one of your non-gem cards perishes, a card bearing this sigil gains 1 power, maxing out at 5.", "내 보석이 아닌 카드가 사망하면 이 도장을 지닌 카드의 공격력이 1 증가한다. 최대 5까지 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation", "자극", Language.Korean);
            RegisterAbility("Stimulation", "자극");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 1 power, maxing out at 4.", "매 턴 종료 시 이 도장을 지닌 카드의 공격력이 1 증가한다. 최대치는 4다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation (Health)", "자극(체력)", Language.Korean);
            RegisterAbility("Stimulation (Health)", "자극(체력)");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 2 health, maxes out at 10.", "매 턴 종료 시 이 도장을 지닌 카드의 체력이 2 증가한다. 최대치는 10이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Draw", "죽음의 약탈", Language.Korean);
            RegisterAbility("Dead Draw", "죽음의 약탈");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card dies, draw a card from your deck.", "보석이 아닌 카드가 죽으면 내 덱에서 카드를 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Heart", "에메랄드 심장", Language.Korean);
            RegisterAbility("Emerald Heart", "에메랄드 심장");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates an Emerald Mox in its place.", "이 도장을 지닌 카드가 사망하면 원래 자리에 에메랄드 목스를 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gooey", "점액", Language.Korean);
            RegisterAbility("Gooey", "점액");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, the striker loses 1 attack.", "이 도장을 지닌 카드가 공격받으면 공격한 카드의 공격력이 1 감소한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mental Gemnastics", "심리적 뵤기", Language.Korean);
            RegisterAbility("Mental Gemnastics", "심리적 뵤기");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw cards from your deck based on how many Gems are on the board.", "이 도장을 지닌 카드를 내면 보드의 보석 수만큼 내 덱에서 카드를 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loot", "노획", Language.Korean);
            RegisterAbility("Loot", "노획");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, draw cards from your deck based on how much damage was dealt.", "이 도장을 지닌 카드가 직접 피해를 입히면 입힌 피해량만큼 내 덱에서 카드를 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life Steal", "생명력 흡수", Language.Korean);
            RegisterAbility("Life Steal", "생명력 흡수");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, the amount dealt will be healed to the owner of this card.", "이 도장을 지닌 카드가 직접 피해를 입히면 그 주인이 입힌 피해량만큼 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knockback Hit", "시간을 밀어내는 일격", Language.Korean);
            RegisterAbility("Knockback Hit", "시간을 밀어내는 일격");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil hits an opposing card, the opposing card will be kicked in the direction inscrybed in the sigil.", "이 도장을 지닌 카드가 맞은편 카드를 타격하면 그 카드를 도장에 표시된 방향으로 걷어찬다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Impaled", "창 소환", Language.Korean);
            RegisterAbility("Impaled", "창 소환");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Spear in its placed. A spear is defined as Sharp, 0 power, 3 health.", "이 도장을 지닌 카드가 사망하면 원래 자리에 창을 생성한다. 창은 뾰족한 깃 도장, 공격력 0, 체력 3을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnus Mox", "마그누스 목스", Language.Korean);
            RegisterAbility("Magnus Mox", "마그누스 목스");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, it provides an orange gem, a blue gem and a green gem to its owner.", "이 도장을 지닌 카드가 보드에 있는 동안 주인에게 오렌지색, 파란색, 녹색 보석을 각각 하나씩 제공한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resurrection", "부활 재생", Language.Korean);
            RegisterAbility("Resurrection", "부활 재생");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card perishes, the dead card will be brought back to life, but this card loses 3 health.", "보석이 아닌 카드가 사망하면 죽은 카드가 되살아나지만, 이 도장을 지닌 카드는 체력을 3 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rerolls", "주사위의 힘", Language.Korean);
            RegisterAbility("Rerolls", "주사위의 힘");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigils' base power will be increased by a random value between 0 and 3.", "매 턴 종료 시 이 도장을 지닌 카드의 공격력을 다시 굴려 0부터 3 사이의 무작위 값으로 바꾼다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Steel Trap", "강철 덫", Language.Korean);
            RegisterAbility("Steel Trap", "강철 덫");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the opposing card also perishes.", "이 도장을 지닌 카드가 사망하면 맞은편 카드도 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Shield", "보석 방패", Language.Korean);
            RegisterAbility("Gem Shield", "보석 방패");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on the board gain a shield.", "이 도장을 지닌 카드를 내면 보드의 모든 보석이 보호막을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plating Work", "도금 작업", Language.Korean);
            RegisterAbility("Plating Work", "도금 작업");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all gems on your side of the board gain the Sharp Quills sigil, and 2 health.", "이 도장을 지닌 카드가 보드에 있는 동안 내 쪽의 모든 보석이 뾰족한 깃 도장과 체력 2를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animator", "인형 조종사", Language.Korean);
            RegisterAbility("Animator", "인형 조종사");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all non-mox cards with 0 power gain 2 power", "이 도장을 지닌 카드가 보드에 있는 동안 공격력이 0이며 목스가 아닌 모든 카드가 공격력을 2 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "보석 흡수자", Language.Korean);
            RegisterAbility("Gem Absorber", "보석 흡수자");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on your side of the board will perish. For each gem absorbed, gain 1 power and 2 health.", "이 도장을 지닌 카드를 내면 내 쪽의 모든 보석이 사망한다. 흡수한 보석 하나마다 이 카드가 공격력 1과 체력 2를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerge", "잠수", Language.Korean);
            RegisterAbility("Submerge", "잠수");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil will submerge. Upon resubmerging, this card will become a random Tentacle Card.", "턴 종료 시 이 도장을 지닌 카드는 물속으로 잠수한다. 다시 떠오르면 무작위 촉수 카드로 변한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Familiar", "사역마", Language.Korean);
            RegisterAbility("Familiar", "사역마");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish if there are no non-gem cards on the board.", "보드에 보석이 아닌 카드가 없으면 이 도장을 지닌 카드는 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fading", "소멸", Language.Korean);
            RegisterAbility("Fading", "소멸");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish at the end of the turn.", "이 도장을 지닌 카드는 턴 종료 시 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morph", "부정형 변이체", Language.Korean);
            RegisterAbility("Morph", "부정형 변이체");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will mimic the card opposing it. If there is no card opposing it, this card will perish.", "이 도장을 지닌 카드를 내면 맞은편 카드를 모방한다. 맞은편에 카드가 없으면 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication", "행렬 곱셈", Language.Korean);
            RegisterAbility("Multiplication", "행렬 곱셈");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw another of this card, but with a different gem cost.", "이 도장을 지닌 카드를 내면 보석 비용이 다른 같은 카드를 한 장 더 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Cycle", "목스 순환", Language.Korean);
            RegisterAbility("Mox Cycle", "목스 순환");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, all the mox on the board will cycle into different gems.", "매 턴 종료 시 보드의 모든 목스가 다른 보석으로 순환한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Strafe", "목스 떨어뜨리기", Language.Korean);
            RegisterAbility("Mox Strafe", "목스 떨어뜨리기");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, this card will move to the direction inscrybed on the sigil, and leave behind a mox.", "턴 종료 시 이 카드는 도장에 표시된 방향으로 이동하고 원래 자리에 목스를 남긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purist", "순수주의", Language.Korean);
            RegisterAbility("Purist", "순수주의");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any card directly opposing this one will have all it's sigils removed.", "이 카드와 정면으로 마주한 카드는 모든 도장을 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brewery", "양조장", Language.Korean);
            RegisterAbility("Brewery", "양조장");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, you automatically draw a mox card from your side deck.", "매 턴 종료 시 내 보조 덱에서 목스 카드를 자동으로 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "불붙이기", Language.Korean);
            RegisterAbility("Ignite", "불붙이기");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, every empty opposing slot will be filled with flames. A flame is defined as a 0/1, Annoying.", "이 도장을 지닌 카드를 내면 상대의 모든 빈 슬롯을 불꽃으로 채운다. 불꽃은 공격력 0, 체력 1이며 구타유발자 도장을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Projection", "별하늘 투영", Language.Korean);
            RegisterAbility("Projection", "별하늘 투영");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is stuck, it will move and leave behind an astral projection of itself.", "이 도장을 지닌 카드가 공격받으면 이동하면서 자신의 성체 투영을 남긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Book", "주문 대전", Language.Korean);
            RegisterAbility("Spell Book", "주문 대전");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random spell card.", "이 도장을 지닌 카드를 내면 무작위 주문 카드를 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scholar", "주술 학자", Language.Korean);
            RegisterAbility("Scholar", "주술 학자");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random one of Bleene's Books.", "이 도장을 지닌 카드를 내면 블린의 책 중 하나를 무작위로 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Midas' Touch", "황금의 손길", Language.Korean);
            RegisterAbility("Midas' Touch", "황금의 손길");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil attacks another card, the attacked card will lose all of it's attack and turn to gold.", "이 도장을 지닌 카드가 다른 카드를 공격하면 공격받은 카드는 공격력을 모두 잃고 금으로 변한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Made of Gold", "황금의 몸", Language.Korean);
            RegisterAbility("Made of Gold", "황금의 몸");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the killer will gain 2 crystals.", "이 도장을 지닌 카드가 사망하면 처치한 쪽이 수정을 2개 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Runes", "기폭 소환", Language.Korean);
            RegisterAbility("Summon Runes", "기폭 소환");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will summon two runes beside it. A rune is defined as 0 power, 1 health, Detonator.", "이 도장을 지닌 카드를 내면 양옆에 룬 두 개를 소환한다. 룬은 공격력 0, 체력 1이며 기폭 장치 도장을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Health", "체력 주문", Language.Korean);
            RegisterAbility("Spell of Health", "체력 주문");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +2 health.", "이 도장을 지닌 주문을 내면 내 쪽의 모든 카드가 체력 +2를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Attack", "공격 주문", Language.Korean);
            RegisterAbility("Spell of Attack", "공격 주문");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +1 attack.", "이 도장을 지닌 주문을 내면 내 쪽의 모든 카드가 공격력 +1을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Spell", "서리 주문", Language.Korean);
            RegisterAbility("Frost Spell", "서리 주문");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards belonging to the opponent will have their attack set to 0, but given +2 health.", "이 도장을 지닌 주문을 내면 상대 소유의 모든 카드의 공격력이 0이 되는 대신 체력 +2를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Wind", "강풍 주문", Language.Korean);
            RegisterAbility("Spell of Wind", "강풍 주문");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board will become airborne.", "이 도장을 지닌 주문을 내면 내 쪽의 모든 카드가 공수를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruckus", "시계 방향의 속삭임", Language.Korean);
            RegisterAbility("Ruckus", "시계 방향의 속삭임");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all cards on the board will move clockwise.", "이 도장을 지닌 카드를 내면 보드의 모든 카드가 시계 방향으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Water", "정수 주문", Language.Korean);
            RegisterAbility("Spell of Water", "정수 주문");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, every card on the board will have their sigils erased.", "이 도장을 지닌 주문을 내면 보드의 모든 카드의 도장이 지워진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Flame", "화염 주문", Language.Korean);
            RegisterAbility("Spell of Flame", "화염 주문");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a side of the board, every card on that side will lose 2 health (without perishing) and have their attack increased by 1.", "보드의 한쪽을 고른다. 그쪽의 모든 카드는 체력을 2 잃고 공격력이 1 증가한다. 이 체력 감소로 사망하지는 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Set Ablaze", "불붙이기", Language.Korean);
            RegisterAbility("Set Ablaze", "불붙이기");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every card on the opposite side will lose 2 health (without perishing) and have their attack increased by 1.", "반대쪽의 모든 카드는 체력을 2 잃고 공격력이 1 증가한다. 이 체력 감소로 사망하지는 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Time Spell", "일회용 주문", Language.Korean);
            RegisterAbility("One Time Spell", "일회용 주문");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the turn ends, a spell bearing this sigil will perish and be removed from your deck.", "턴 종료 시 이 도장을 지닌 주문은 사망하고 내 덱에서 제거된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vase of Greed", "탐욕의 항아리", Language.Korean);
            RegisterAbility("Vase of Greed", "탐욕의 항아리");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, discard your current hand and draw 4 new cards.", "이 도장을 지닌 주문을 내면 현재 패를 모두 버리고 새 카드를 4장 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gnomification", "노움화", Language.Korean);
            RegisterAbility("Gnomification", "노움화");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a slot to summon a Gnome card in.", "노움 카드를 소환할 슬롯을 고른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed", "저주", Language.Korean);
            RegisterAbility("Cursed", "저주");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, it will immediately perish.", "이 도장을 지닌 주문을 내면 즉시 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspiration", "영감", Language.Korean);
            RegisterAbility("Inspiration", "영감");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to give Airborne + Looter for 1 turn.", "카드를 골라 1턴 동안 공수와 노획자를 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calculus", "미적분", Language.Korean);
            RegisterAbility("Calculus", "미적분");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to swap stats.", "카드를 골라 공격력과 체력을 서로 바꾼다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rage", "격노", Language.Korean);
            RegisterAbility("Rage", "격노");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to kill. The opponent of the card will recieve damage equal to the amount of health the card had.", "처치할 카드를 고른다. 그 카드 주인의 상대는 카드가 지녔던 체력만큼 피해를 입는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "화염구 주문", Language.Korean);
            RegisterAbility("Fireball", "화염구 주문");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to take 2 damage.", "카드를 골라 피해를 2 입힌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cold to the Touch", "빙결의 손길", Language.Korean);
            RegisterAbility("Cold to the Touch", "빙결의 손길");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigils attack another card, that card will lose 1 attack.", "이 도장을 지닌 카드가 다른 카드를 공격하면 공격받은 카드의 공격력이 1 감소한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen", "빙결", Language.Korean);
            RegisterAbility("Frozen", "빙결");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, this card will lose its frozen health. When all frozen health is depleted, or this card is struck, it will defrost.", "매 턴 종료 시 이 카드는 빙결 체력을 잃는다. 빙결 체력이 모두 소진되거나 공격받으면 해동된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Pull", "강력 견인", Language.Korean);
            RegisterAbility("Strong Pull", "강력 견인");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every opposing card will be inclined to hit this card instead of any other.", "상대의 모든 카드는 다른 카드보다 이 카드를 우선해서 공격하려 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Displacement", "치환 반응", Language.Korean);
            RegisterAbility("Displacement", "치환 반응");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, another of this card will be added randomly into your deck", "이 도장을 지닌 카드를 뽑으면 같은 카드 한 장이 내 덱의 무작위 위치에 추가된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Reckoning", "보석 청산", Language.Korean);
            RegisterAbility("Gem Reckoning", "보석 청산");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, if the owner of this card does not control any gems, the leftmost card in your hand is discarded.", "매 턴 종료 시 이 카드의 주인이 보석을 하나도 제어하지 않으면 내 패의 맨 왼쪽 카드를 버린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Power", "목스 공격력", Language.Korean);
            RegisterAbility("Mox Power", "목스 공격력");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "이 도장이 나타내는 값은 주인 쪽 탁자에 있는 목스 카드의 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Health", "목스 체력", Language.Korean);
            RegisterAbility("Mox Health", "목스 체력");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "이 도장이 나타내는 값은 주인 쪽 탁자에 있는 목스 카드의 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candle Proximity", "촛불 근접", Language.Korean);
            RegisterAbility("Candle Proximity", "촛불 근접");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to how close this card is to the Candle on the table.", "이 도장이 나타내는 값은 이 카드가 탁자 위 양초에 얼마나 가까운지에 따라 정해진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Murder Power", "살육의 힘", Language.Korean);
            RegisterAbility("Murder Power", "살육의 힘");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal the total amount of power on the opponents board.", "이 도장이 나타내는 값은 상대 보드의 공격력 합계와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to half the total amount of power on your board.", "이 도장이 나타내는 값은 내 보드의 공격력 합계의 절반과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Power", "주문의 힘", Language.Korean);
            RegisterAbility("Spell Power", "주문의 힘");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during this current dungeon.", "이 도장이 나타내는 값은 현재 던전에서 낸 주문의 총수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during the battle.", "이 도장이 나타내는 값은 이번 전투에서 낸 주문의 총수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counterbattery Power", "반격 공격력", Language.Korean);
            RegisterAbility("Counterbattery Power", "반격 공격력");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the amount of damage taken by you this battle, divided by two.", "이 도장이 나타내는 값은 이번 전투에서 내가 받은 총 피해량을 둘로 나눈 값과 같다.", Language.Korean);
            foreach (Ability ability in Enum.GetValues(typeof(Ability)))
            {
                var info = AbilitiesUtil.GetInfo(ability);
                if (info == null || info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的info，已跳过。");
                    continue;
                }
                if (info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的rulebookName，或本身已注册，已跳过。");
                    continue;
                }
                RegisterAbility(info.rulebookName, KoreanLanguagePack.Localize(info.rulebookName));
            }

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox", "목스", Language.Korean);
