            RegisterCard("Emerald Mox", "에메랄드 목스", "its a me moxio", "나다, 목시오!");
            RegisterCard("Sapphire Mox", "사파이어 목스", "its a me moxio", "나다, 목시오!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "its a me moxio", "나다, 목시오!", Language.Korean);
