            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "draft token aka pelt no way jose", "선택 토큰, 일명 가죽. 아니, 말도 안 되지.", Language.Korean);
