            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A scholar proficient in Chaos Theory, channeling a scramble unto the entire board.", "혼돈 이론에 능숙한 학자. 보드 전체를 뒤섞는 힘을 흘려보낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Spell", "마법 주문 도장", Language.Korean);
            RegisterCard("Magic Spell", "마법 주문 도장", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Detonator", "보석 기폭 장치", Language.Korean);
            RegisterCard("Gem Detonator", "보석 기폭 장치", "It went berserk after hearing mysterious whispers in a crypt.", "묘굴에서 수수께끼의 속삭임을 듣고 광란에 빠졌다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It went berserk after hearing mysterious whispers in a crypt.", "묘굴에서 수수께끼의 속삭임을 듣고 광란에 빠졌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "he", "그", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "its he.", "그야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homunculus", "호문쿨루스", Language.Korean);
            RegisterCard("Homunculus", "호문쿨루스", "A strange, to say the least creature.", "좋게 말해도 기이한 피조물이다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange, to say the least creature.", "좋게 말해도 기이한 피조물이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mimagius", "미마기우스", Language.Korean);
            RegisterCard("Mimagius", "미마기우스", "It distorts itself into the form of the opposing card.", "자신을 뒤틀어 맞은편 카드의 모습으로 변한다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It distorts itself into the form of the opposing card.", "자신을 뒤틀어 맞은편 카드의 모습으로 변한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deflector", "편향 장치", Language.Korean);
            RegisterCard("Deflector", "편향 장치", "You would not want to end up on the wrong side of it..", "적으로 돌리고 싶지는 않을걸…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You would not want to end up on the wrong side of it..", "적으로 돌리고 싶지는 않을걸…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Auspex", "점성술사", Language.Korean);
            RegisterCard("Auspex", "점성술사", "It harnesses the power of the stars for you..", "널 위해 별들의 힘을 다룬다…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It harnesses the power of the stars for you..", "널 위해 별들의 힘을 다룬다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astral Sorcerer", "성계 마법사", Language.Korean);
            RegisterCard("Astral Sorcerer", "성계 마법사", "A sorcerer proficient in summoning astral projections to protect itself when in danger.", "위험할 때 성체 투영을 소환해 자신을 지키는 데 능숙한 마법사.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sorcerer proficient in summoning astral projections to protect itself when in danger.", "위험할 때 성체 투영을 소환해 자신을 지키는 데 능숙한 마법사.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astral Projection", "성체 투영", Language.Korean);
            RegisterCard("Astral Projection", "성체 투영", "real", "진짜");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "real", "진짜", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trinket Bearer", "싸구려 장신구", Language.Korean);
            RegisterCard("Trinket Bearer", "싸구려 장신구", "A mischevious little goblin creature. It carries around valueables in its backpack.", "장난꾸러기 작은 고블린. 배낭에 귀중품을 넣어 다닌다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mischevious little goblin creature. It carries around valueables in its backpack.", "장난꾸러기 작은 고블린. 배낭에 귀중품을 넣어 다닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backpack", "배낭", Language.Korean);
            RegisterCard("Backpack", "배낭", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimbot", "자극봇", Language.Korean);
            RegisterCard("Stimbot", "자극봇", "Powered by stimulation, and steam..", "자극과 증기로 움직인다…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powered by stimulation, and steam..", "자극과 증기로 움직인다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magimorph", "변신 마법사", Language.Korean);
            RegisterCard("Magimorph", "변신 마법사", "Its disgusting gooey body warps and distorts into distant forms. It's wonderous if you look at it right.", "역겨운 끈적한 몸이 뒤틀리며 낯선 모습으로 변한다. 잘 보면 경이롭기도 하다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its disgusting gooey body warps and distorts into distant forms. It's wonderous if you look at it right.", "역겨운 끈적한 몸이 뒤틀리며 낯선 모습으로 변한다. 잘 보면 경이롭기도 하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Performer", "공연자", Language.Korean);
            RegisterCard("Performer", "공연자", "Watch it create a rabbit out of its wand..", "지팡이에서 토끼를 만들어 내는 모습을 보아라…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch it create a rabbit out of its wand..", "지팡이에서 토끼를 만들어 내는 모습을 보아라…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Senior Sage", "상급 현자", Language.Korean);
            RegisterCard("Senior Sage", "상급 현자", "A Junior Sage that has mastered the art of Magicks.", "마법의 기술을 통달한 견습 현자.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Junior Sage that has mastered the art of Magicks.", "마법의 기술을 통달한 견습 현자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Mech", "사파이어 기갑", Language.Korean);
            RegisterCard("Sapphire Mech", "사파이어 기갑", "A mage-like automaton piloted by a sapphire mox.. Admirable.", "사파이어 목스가 조종하는 마법사형 자동 장치… 감탄스럽군.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage-like automaton piloted by a sapphire mox.. Admirable.", "사파이어 목스가 조종하는 마법사형 자동 장치… 감탄스럽군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Titan", "루비 타이탄", Language.Korean);
            RegisterCard("Ruby Titan", "루비 타이탄", "A perfected construct of a ruby golem, a monstrous machine of destruction.", "루비 골렘의 완성된 구조체. 괴물 같은 파괴 기계다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A perfected construct of a ruby golem, a monstrous machine of destruction.", "루비 골렘의 완성된 구조체. 괴물 같은 파괴 기계다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleene's Scholar", "블린의 학자", Language.Korean);
            RegisterCard("Bleene's Scholar", "블린의 학자", "A scholar in training, currently studying the works of Master Bleene.", "수련 중인 학자. 현재 마스터 블린의 저작을 연구하고 있다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A scholar in training, currently studying the works of Master Bleene.", "수련 중인 학자. 현재 마스터 블린의 저작을 연구하고 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goranj's Warrior", "고란즈의 전사", Language.Korean);
            RegisterCard("Goranj's Warrior", "고란즈의 전사", "A foe mentored by Master Goranj, proficient at dual striking.", "마스터 고란즈의 지도를 받은 적. 이중 타격에 능숙하다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A foe mentored by Master Goranj, proficient at dual striking.", "마스터 고란즈의 지도를 받은 적. 이중 타격에 능숙하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cider Mage", "사과주 마법사", Language.Korean);
            RegisterCard("Cider Mage", "사과주 마법사", "This mage has a secret formula of cider that nullifies the opponents spells..", "상대의 주문을 무효로 하는 사과주 비법을 가진 마법사…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage has a secret formula of cider that nullifies the opponents spells..", "상대의 주문을 무효로 하는 사과주 비법을 가진 마법사…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brewer Sage", "양조 현자", Language.Korean);
            RegisterCard("Brewer Sage", "양조 현자", "A sage, sitting still and perfecting his art of brewing..", "가만히 앉아 양조 기술을 완성해 가는 현자…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sage, sitting still and perfecting his art of brewing..", "가만히 앉아 양조 기술을 완성해 가는 현자…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soda Mage", "탄산 마법사", Language.Korean);
            RegisterCard("Soda Mage", "탄산 마법사", "This pathetic mage melted away from drinking too much carbonated liquid..", "탄산음료를 너무 많이 마셔 녹아 버린 불쌍한 마법사…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This pathetic mage melted away from drinking too much carbonated liquid..", "탄산음료를 너무 많이 마셔 녹아 버린 불쌍한 마법사…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whitesmith", "보석 대장장이", Language.Korean);
            RegisterCard("Whitesmith", "보석 대장장이", "Their life's work was dedicated to reinforcing gems.", "평생을 보석 강화에 바쳤다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their life's work was dedicated to reinforcing gems.", "평생을 보석 강화에 바쳤다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppeteer", "인형사", Language.Korean);
            RegisterCard("Puppeteer", "인형사", "Its mastery of control magicks lets even Practice Wizards contribute.", "뛰어난 제어 마법 덕분에 견습 마법사까지 도움이 된다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its mastery of control magicks lets even Practice Wizards contribute.", "뛰어난 제어 마법 덕분에 견습 마법사까지 도움이 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juggler", "저글러", Language.Korean);
            RegisterCard("Juggler", "저글러", "It juggles around your mox cards, as if they were juggling balls..", "마치 저글링 공처럼 네 목스 카드들을 던지고 받는다…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It juggles around your mox cards, as if they were juggling balls..", "마치 저글링 공처럼 네 목스 카드들을 던지고 받는다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Joker", "조커", Language.Korean);
            RegisterCard("Joker", "조커", "Dedicated to the art of fun.. though most only find it annoying.", "즐거움의 기술에 전념한다… 다만 대부분은 성가시다고만 느낀다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dedicated to the art of fun.. though most only find it annoying.", "즐거움의 기술에 전념한다… 다만 대부분은 성가시다고만 느낀다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valkyrie", "발키리", Language.Korean);
            RegisterCard("Valkyrie", "발키리", "A student that has trained under Master Orlu. It has become an expert in airborne magicks.", "마스터 오를루 밑에서 수련한 학생. 공중 마법의 전문가가 되었다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A student that has trained under Master Orlu. It has become an expert in airborne magicks.", "마스터 오를루 밑에서 수련한 학생. 공중 마법의 전문가가 되었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valkyrie Thief", "발키리 도적", Language.Korean);
            RegisterCard("Valkyrie Thief", "발키리 도적", "liar liar chicken friar.", "거짓말쟁이, 거짓말쟁이, 닭 수도사.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "liar liar chicken friar.", "거짓말쟁이, 거짓말쟁이, 닭 수도사.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Maniac", "에메랄드 광인", Language.Korean);
            RegisterCard("Emerald Maniac", "에메랄드 광인", "A crazed maniac.. Drawing out health from the mox..", "미쳐 버린 광인… 목스에서 체력을 끌어낸다…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A crazed maniac.. Drawing out health from the mox..", "미쳐 버린 광인… 목스에서 체력을 끌어낸다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Daemon", "루비 악마", Language.Korean);
            RegisterCard("Ruby Daemon", "루비 악마", "If not properly sustained, it will destroy your hand to fuel itself..", "제대로 먹여 주지 않으면 네 패를 파괴해 자신을 유지한다…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If not properly sustained, it will destroy your hand to fuel itself..", "제대로 먹여 주지 않으면 네 패를 파괴해 자신을 유지한다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Friend", "보석 친구", Language.Korean);
            RegisterCard("Gem Friend", "보석 친구", "fren", "칭구");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "fren", "칭구", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Druid", "드루이드", Language.Korean);
            RegisterCard("Druid", "드루이드", "Just look at what you've done..", "네가 무슨 짓을 했는지 봐…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just look at what you've done..", "네가 무슨 짓을 했는지 봐…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chained Legs", "사슬에 묶인 다리", Language.Korean);
            RegisterCard("Chained Legs", "사슬에 묶인 다리", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sealed Body", "봉인된 몸", Language.Korean);
            RegisterCard("Sealed Body", "봉인된 몸", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bound Arms", "구속의 팔", Language.Korean);
            RegisterCard("Bound Arms", "구속의 팔", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imprisoned Tyrant", "갇힌 폭군", Language.Korean);
            RegisterCard("Imprisoned Tyrant", "갇힌 폭군", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication mage", "행렬 마법사", Language.Korean);
            RegisterCard("Multiplication mage", "행렬 마법사", "This cycle can go on forever..", "이 순환은 영원히 이어질 수 있다…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cycle can go on forever..", "이 순환은 영원히 이어질 수 있다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Invisible mage", "투명 마법사", Language.Korean);
            RegisterCard("Invisible mage", "투명 마법사", "It drank the wrong potion and ended up invisible. How clumsy.", "물약을 잘못 마셔 투명해졌다. 덜렁대기도 하지.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It drank the wrong potion and ended up invisible. How clumsy.", "물약을 잘못 마셔 투명해졌다. 덜렁대기도 하지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Sage", "수정 현자", Language.Korean);
            RegisterCard("Crystal Sage", "수정 현자", "A young scholar, profoundly studying mana crystals.", "마나 수정을 깊이 연구하는 젊은 학자.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A young scholar, profoundly studying mana crystals.", "마나 수정을 깊이 연구하는 젊은 학자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Guardian", "보석 수호자", Language.Korean);
            RegisterCard("Gem Guardian", "보석 수호자", "The inverse of the Gem Detonator, this one seeks to protect all mox.", "보석 기폭 장치와 반대로 모든 목스를 지키려 한다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The inverse of the Gem Detonator, this one seeks to protect all mox.", "보석 기폭 장치와 반대로 모든 목스를 지키려 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembound Ripper", "보석지향 리퍼", Language.Korean);
            RegisterCard("Gembound Ripper", "보석지향 리퍼", "It is unstable, but such is the price for unending power.", "불안정하지만 끝없는 힘에는 그런 대가가 따른다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is unstable, but such is the price for unending power.", "불안정하지만 끝없는 힘에는 그런 대가가 따른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "보석 포식자", Language.Korean);
            RegisterCard("Gem Absorber", "보석 포식자", "It seeks out to consume all mana within Mox to grow stronger.", "목스 속 마나를 모두 먹어 치워 더 강해지려 한다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seeks out to consume all mana within Mox to grow stronger.", "목스 속 마나를 모두 먹어 치워 더 강해지려 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemagus", "뼈 마법사", Language.Korean);
            RegisterCard("Skelemagus", "뼈 마법사", "Great power for a few, fleeting moments..", "강대한 힘은 그저 덧없는 잠깐 동안만…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great power for a few, fleeting moments..", "강대한 힘은 그저 덧없는 잠깐 동안만…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelesage", "해골 현자", Language.Korean);
            RegisterCard("Skelesage", "해골 현자", "One of my own Junior Sages, lost and revived.", "내 견습 현자 중 하나. 잃었다가 되살아났다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of my own Junior Sages, lost and revived.", "내 견습 현자 중 하나. 잃었다가 되살아났다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic Scholar", "성마른 학자", Language.Korean);
            RegisterCard("Erratic Scholar", "성마른 학자", "A panicked scholar.. Always running from its problems..", "겁에 질린 학자… 언제나 자신의 문제에서 달아난다…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A panicked scholar.. Always running from its problems..", "겁에 질린 학자… 언제나 자신의 문제에서 달아난다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Mage", "목스 마법사", Language.Korean);
            RegisterCard("Mox Mage", "목스 마법사", "A Mox disguised as a mage.. It's not going to fool anyone.", "마법사로 변장한 목스… 아무도 속지 않겠는데.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Mox disguised as a mage.. It's not going to fool anyone.", "마법사로 변장한 목스… 아무도 속지 않겠는데.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aurumtact", "황금 연금술사", Language.Korean);
            RegisterCard("Aurumtact", "황금 연금술사", "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "탐욕 때문에 저주받은 늙은 학자. 닿는 모든 것을 순금 속에 가둔다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "탐욕 때문에 저주받은 늙은 학자. 닿는 모든 것을 순금 속에 가둔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chained Mox", "연쇄 목스", Language.Korean);
            RegisterCard("Chained Mox", "연쇄 목스", "A collection of 3 moxen, tangled together, combining their mana energy.", "목스 3개가 뒤얽힌 집합체. 서로의 마나 에너지를 합친다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of 3 moxen, tangled together, combining their mana energy.", "목스 3개가 뒤얽힌 집합체. 서로의 마나 에너지를 합친다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maux", "모크스", Language.Korean);
            RegisterCard("Maux", "모크스", "In all my years, I have NEVER seen an imitation cruder than this.", "살면서 이보다 조잡한 모방품은 본 적이 없다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In all my years, I have NEVER seen an imitation cruder than this.", "살면서 이보다 조잡한 모방품은 본 적이 없다.", Language.Korean);
            RegisterCard("Stim Mage", "자극 마법사", "It strives to grow stronger, disregarding its own wellbeing..", "자기 안위는 돌보지 않고 더 강해지려 애쓴다…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It strives to grow stronger, disregarding its own wellbeing..", "자기 안위는 돌보지 않고 더 강해지려 애쓴다…", Language.Korean);
            RegisterCard("Gourmage", "미식마법사", "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "내 쓰러진 동료들의 시체를 먹고 강해지는 탐식하는 마법사… 역겹군.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "내 쓰러진 동료들의 시체를 먹고 강해지는 탐식하는 마법사… 역겹군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunce", "바보 마법사", Language.Korean);
            RegisterCard("Dunce", "바보 마법사", "This one can never seem to hit its target..", "아무래도 목표를 맞히는 법이 없는 것 같다…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to hit its target..", "아무래도 목표를 맞히는 법이 없는 것 같다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grootslang", "그루트슬랑", Language.Korean);
            RegisterCard("Grootslang", "그루트슬랑", "The mere graze of its fangs is enough to kill any creature. No matter the size.", "송곳니가 살짝 스치기만 해도 어떤 피조물이든 죽는다. 크기는 상관없다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mere graze of its fangs is enough to kill any creature. No matter the size.", "송곳니가 살짝 스치기만 해도 어떤 피조물이든 죽는다. 크기는 상관없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bookworm", "책벌레", Language.Korean);
            RegisterCard("Bookworm", "책벌레", "A rare kind of insect that absorbs knowledge out of books.", "책에서 지식을 흡수하는 희귀한 곤충.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rare kind of insect that absorbs knowledge out of books.", "책에서 지식을 흡수하는 희귀한 곤충.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemist", "연금술사", Language.Korean);
            RegisterCard("Alchemist", "연금술사", "A supporting one. It brews potions to empower your cards.", "지원 역할이다. 물약을 만들어 네 카드들을 강화한다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A supporting one. It brews potions to empower your cards.", "지원 역할이다. 물약을 만들어 네 카드들을 강화한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Mage", "종 마법사", Language.Korean);
            RegisterCard("Chime Mage", "종 마법사", "Its chime can prove to be quite annoying..", "그 종소리는 제법 성가시게 느껴질 수 있다…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its chime can prove to be quite annoying..", "그 종소리는 제법 성가시게 느껴질 수 있다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revivor", "소생자", Language.Korean);
            RegisterCard("Revivor", "소생자", "It brings a mage back from the dead, at the cost of its own health.", "자신의 체력을 대가로 마법사를 죽음에서 되살린다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It brings a mage back from the dead, at the cost of its own health.", "자신의 체력을 대가로 마법사를 죽음에서 되살린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune Mage", "룬 마법사", Language.Korean);
            RegisterCard("Rune Mage", "룬 마법사", "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "소환되면 양옆에 폭발하는 룬을 만들어 낸다. 말해 두지만 좋은 생각은 아니다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "소환되면 양옆에 폭발하는 룬을 만들어 낸다. 말해 두지만 좋은 생각은 아니다.", Language.Korean);
            RegisterCard("--~~--~~--", "--~~--~~--", "So it arrives.", "그리하여 도착했다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So it arrives.", "그리하여 도착했다.", Language.Korean);
            RegisterCard("~-~-~-~-~-~", "~-~-~-~-~-~", "I foresaw its arrival.", "그 도착을 예견했지.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I foresaw its arrival.", "그 도착을 예견했지.", Language.Korean);
            RegisterCard("~~--~~--~~", "~~--~~--~~", "At last, it is here.", "마침내 이곳에 왔다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At last, it is here.", "마침내 이곳에 왔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sniper Sage", "저격 현자", Language.Korean);
            RegisterCard("Sniper Sage", "저격 현자", "A mage whose training allows it to cast spells from afar.", "훈련을 통해 멀리서 주문을 시전하는 마법사.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage whose training allows it to cast spells from afar.", "훈련을 통해 멀리서 주문을 시전하는 마법사.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune", "룬", Language.Korean);
            RegisterCard("Rune", "룬", "This is the last call, for alcohol.", "술 주문 마감이다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "술 주문 마감이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame", "마염", Language.Korean);
            RegisterCard("Flame", "마염", "This is the last call, for alcohol.", "술 주문 마감이다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "술 주문 마감이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbit", "토끼", Language.Korean);
            RegisterCard("Rabbit", "토끼", "This is the last call, for alcohol.", "술 주문 마감이다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "술 주문 마감이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for booze.", "독주 주문 마감이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for ale.", "에일 주문 마감이다.", Language.Korean);
            RegisterCard("Master Goranj", "마스터 고란즈", "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "우뚝 솟은 마스터 고란즈. 무시무시한 마법을 시전할 뿐 아니라 흔들림 없는 자세도 갖췄다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "우뚝 솟은 마스터 고란즈. 무시무시한 마법을 시전할 뿐 아니라 흔들림 없는 자세도 갖췄다.", Language.Korean);
            RegisterCard("Master Bleene", "마스터 블린", "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "이타적인 마스터 블린. 위급할 때 너를 돕는다… 자신을 지킬 능력을 희생하면서. 존경스럽군.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "이타적인 마스터 블린. 위급할 때 너를 돕는다… 자신을 지킬 능력을 희생하면서. 존경스럽군.", Language.Korean);
            RegisterCard("Master Orlu", "마스터 오를루", "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "위대한 마스터 오를루. 창백한 날개로 날아올라 위에서 공격하고 아래에서 카드를 끌어온다…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "위대한 마스터 오를루. 창백한 날개로 날아올라 위에서 공격하고 아래에서 카드를 끌어온다…", Language.Korean);
            RegisterCard("Master Magnus", "마스터 마그누스", "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "내 이름은… 셰이크 줄라! 마이크의 지배자! 구식 멋쟁이! 짜릿한 걸 원해? 내가 가져다주지…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "내 이름은… 셰이크 줄라! 마이크의 지배자! 구식 멋쟁이! 짜릿한 걸 원해? 내가 가져다주지…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Magnus", "마스터 마그누스", Language.Korean);
            RegisterCard("Master Magnus", "마스터 마그누스", "Frylock yeah Im on top rock you like a cop, meatwad you're up next with your knock knock!", "프라일록, 그래 내가 최고! 경찰처럼 널 흔들어 놓지. 미트와드, 다음은 네 차례, 똑똑 농담을 해 봐!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frylock yeah Im on top rock you like a cop, meatwad you're up next with your knock knock!", "프라일록, 그래 내가 최고! 경찰처럼 널 흔들어 놓지. 미트와드, 다음은 네 차례, 똑똑 농담을 해 봐!", Language.Korean);
            RegisterCard("Master Magnus", "마스터 마그누스", "Meatwad get the money, see. Meatwad get the honeys, G. ", "미트와드는 돈을 벌지, 알겠어? 미트와드는 여자들에게 인기야, 친구.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meatwad get the money, see. Meatwad get the honeys, G. ", "미트와드는 돈을 벌지, 알겠어? 미트와드는 여자들에게 인기야, 친구.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phoenix", "불사조", Language.Korean);
            RegisterCard("Phoenix", "불사조", "Majestic avian, rumoured to have been an accomplice to Master Orlu...", "위엄 있는 새. 마스터 오를루의 공범이었다는 소문이 있다…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majestic avian, rumoured to have been an accomplice to Master Orlu...", "위엄 있는 새. 마스터 오를루의 공범이었다는 소문이 있다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleenehound", "보물 사냥개", Language.Korean);
            RegisterCard("Bleenehound", "보물 사냥개", "Loyalist canine, rumoured to have been Master Bleene's loyal companion.", "충직한 개. 마스터 블린의 충성스러운 동료였다는 소문이 있다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loyalist canine, rumoured to have been Master Bleene's loyal companion.", "충직한 개. 마스터 블린의 충성스러운 동료였다는 소문이 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemy 101", "연금술 입문", Language.Korean);
            RegisterCard("Alchemy 101", "연금술 입문", "[c:g2]Alchemy 101[c:]\n[c:g3]I[c:] [c:g1]never[c:] [c:g3]was[c:] [c:g1]that[c:] [c:g3]great[c:] [c:g1]at[c:] [c:g3]alchemy..[c:]", "[c:g2]연금술 입문[c:]\n[c:g3]나는[c:] [c:g1]언제나[c:] [c:g3]연금술에[c:] [c:g1]그리[c:] [c:g3]능숙한[c:] [c:g1]편은[c:] [c:g3]아니었다…[c:]");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]Alchemy 101[c:]\n[c:g3]I[c:] [c:g1]never[c:] [c:g3]was[c:] [c:g1]that[c:] [c:g3]great[c:] [c:g1]at[c:] [c:g3]alchemy..[c:]", "[c:g2]연금술 입문[c:]\n[c:g3]나는[c:] [c:g1]언제나[c:] [c:g3]연금술에[c:] [c:g1]그리[c:] [c:g3]능숙한[c:] [c:g1]편은[c:] [c:g3]아니었다…[c:]", Language.Korean);
