            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conjure a plain old garden gnome on the board..", "보드에 평범한 정원 노움을 만들어 낸다…", Language.Korean);
