            RegisterCard("Cursed Skull", "저주받은 두개골", "Hmm, a cursed skull. Handle it with care.", "흠, 저주받은 두개골이군. 조심해서 다뤄라.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm, a cursed skull. Handle it with care.", "흠, 저주받은 두개골이군. 조심해서 다뤄라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspiration", "영감", Language.Korean);
