            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A culmination of the great Master Orlu's essence.", "위대한 마스터 오를루의 정수가 집약된 것.", Language.Korean);
