            RegisterCard("Rage", "분노의 불꽃", "The embodiement of the tenacious Master Goranj.", "끈질긴 마스터 고란즈의 화신.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The embodiement of the tenacious Master Goranj.", "끈질긴 마스터 고란즈의 화신.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calculus", "미적분", Language.Korean);
