            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The spirit of the brave Master Bleene.", "용감한 마스터 블린의 영혼.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "화염구 주문", Language.Korean);
