            // Achievement
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnificus Mod Achievements", "매그니피쿠스 모드 도전 과제", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magical Labyrinth", "마법 미궁", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat the final boss.", "최종 보스를 쓰러뜨린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Skull", "수정 두개골", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete a run with every challenge active, and no anti challenges. (You may use the map)", "모든 도전을 활성화하고 역도전 없이 도전을 완료한다. (지도는 사용 가능.)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Humanoid Slime", "인간형 슬라임", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat the first boss without having any cards get their power reduced at the start of phase 2.", "두 번째 단계 시작 시 어떤 카드도 공격력이 감소하지 않은 채 첫 번째 보스를 쓰러뜨린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headless Knight", "목 없는 기사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat the second boss without triggering any Enchanted Spears.", "마력이 깃든 창을 하나도 발동시키지 않고 두 번째 보스를 쓰러뜨린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quick Summon", "빠른 소환", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat the third boss without letting the turn timer expire once.", "턴 제한 시간을 한 번도 소진하지 않고 세 번째 보스를 쓰러뜨린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mischief of the Time Goddess", "시간 여신의 장난", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let the third boss's timer run out 5 times, and still win the fight.", "세 번째 보스의 제한 시간을 5번 소진하고도 전투에서 승리한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rush Recklessly", "무모한 돌진", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat the first boss after using only 3 or less events.", "이벤트를 3번 이하로 거친 뒤 첫 번째 보스를 쓰러뜨린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crowning of the Emperor", "황제의 대관식", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Eyes White Dragon", "푸른 눈의 백룡", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deal 10 damage in a single turn.", "한 턴에 피해를 10 입힌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card of Sacrifice", "희생의 카드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have 10 or less cards by the time you reach the final boss.", "최종 보스에 도달할 때 카드가 10장 이하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owl of the Black Forest", "검은 숲의 올빼미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Banish the Ficticious Master Magnus.", "가짜 마스터 마그누스를 추방한다.", Language.Korean);

            // Consumable

            // ShowUntilInput
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT? BUT DON'T I GET TO LEAVE?", "뭐? 나갈 수 있는 거 아니었어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I STILL HAVE SO MUCH STIMULATION TO GET!!", "아직 받아야 할 자극이 그렇게나 많은데!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]PLEASE, CHALLENGER,[c:] YOU HAVE TO GET ME-", "[c:g2]부탁이야, 도전자,[c:] 나를 데리고―", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hush.", "조용히.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm?", "흠?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you expect me to restore your [c:g1]life painting[c:]?", "내가 네 [c:g1]생명 그림[c:]을 복원해 줄 줄 알았나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm.. That's not how it works here, challenger..", "흠… 여기서는 그런 식으로 되지 않아, 도전자…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleach is not easily restorable.", "표백된 것은 쉽게 복원되지 않지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may only pick a [c:g3]rare card[c:].", "[c:g3]레어 카드[c:]만 고를 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you engage in combat, you notice ethereal runes surrounding you..", "전투에 돌입하자 주위에 실체 없는 룬들이 떠 있음을 알아차렸다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems as though they were placing a [c:g2]pact[c:] on you..", "네게 [c:g2]계약[c:]을 거는 듯하다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your olden sigils shant be of any use in this battle.", "네 예전 도장은 이 전투에서 아무 쓸모가 없을 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As the smoke of combat clears, the mysterious runes reveal themselves to you.", "전투의 연기가 걷히자 수수께끼의 룬들이 모습을 드러낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, but this one does not interest the runes.", "아, 하지만 이건 룬의 관심을 끌지 못하는군.", Language.Korean);
            foreach (var kvp in Cards)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The pact takes its effect on your " + kvp.Key + "..", "계약이 네 " + kvp.Value + "에게 효력을 발휘한다……", Language.Korean);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sigil, replaced, for better or for worse.", "도장은 바뀌었다. 더 나아졌을지, 나빠졌을지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]Hmm..?[c:] [c:g1]Another[c:] [c:g3]student[c:] [c:g1]here?[c:]", "[c:g3]흠…?[c:] [c:g1]또[c:] [c:g3]학생이[c:] [c:g1]왔나?[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]Have[c:] [c:g1]you[c:] [c:g3]come[c:] [c:g1]to[c:] [c:g3]assist[c:] [c:g1]my[c:] [c:g3]studies?[c:]", "[c:g3]너는[c:] [c:g1]내[c:] [c:g3]연구를[c:] [c:g1]도와주러[c:] [c:g3]이곳에[c:] [c:g1]찾아온[c:] [c:g3]것이냐?[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]Hmm..[c:] [c:g1]I[c:] [c:g3]think[c:] [c:g1]it's[c:] [c:g3]time[c:] [c:g1]to[c:] [c:g3]play[c:] [c:g1]some[c:] [c:g3]more...[c:]  [c:g2]forbidden[c:] [c:g1]books[c:]", "[c:g3]흠…[c:] [c:g1]내[c:] [c:g3]생각에는[c:] [c:g1]이제[c:] [c:g3]또[c:] [c:g1]조금[c:] [c:g3]더[c:] [c:g1]놀아야[c:] [c:g3]할 때야…[c:] [c:g2]금지된[c:] [c:g1]책으로.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]An[c:] [c:g1]excellent[c:] [c:g3]portrait[c:] [c:g1]by[c:] [c:g3]the[c:] [c:g1]Master.[c:]", "[c:g3]이건[c:] [c:g1]대가가[c:] [c:g3]직접[c:] [c:g1]그린[c:] [c:g3]훌륭한[c:] [c:g1]초상화다.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]Looks[c:] [c:g1]like[c:] [c:g3]you[c:] [c:g1]got[c:] [c:g3]a[c:] [c:g1]hound[c:] [c:g3]of[c:] [c:g1]your[c:] [c:g3]own![c:]", "[c:g3]보아하니[c:] [c:g1]이제[c:] [c:g3]너에게도[c:] [c:g1]너만의[c:] [c:g3]사냥개가[c:] [c:g1]한[c:] [c:g3]마리[c:] [c:g1]생긴[c:] [c:g3]모양이구나![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]Oh[c:] [c:g1]yes,[c:] [c:g3]I[c:] [c:g1]do[c:] [c:g3]love[c:] [c:g1]a[c:] [c:g3]good[c:] [c:g1]book.[c:]", "[c:g3]아,[c:] [c:g1]그렇지.[c:] [c:g3]나는[c:] [c:g1]정말로[c:] [c:g3]좋은[c:] [c:g1]책을[c:] [c:g3]무척[c:] [c:g1]좋아해.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]Let[c:] [c:g1]me[c:] [c:g3]share[c:] [c:g1]some[c:] [c:g3]of[c:] [c:g1]my[c:] [c:g3]favourites[c:] [c:g1]with[c:] [c:g3]you.[c:]", "[c:g3]내가[c:] [c:g1]가장[c:] [c:g3]좋아하는[c:] [c:g1]책을[c:] [c:g3]몇[c:] [c:g1]권[c:] [c:g3]너와[c:] [c:g1]나누어[c:] [c:g3]보마.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just imagine.. You are an ice cube, slowly melting in a hot pan..", "상상해 봐… 너는 얼음덩이가 되어 뜨거운 팬 위에서 천천히 녹는 거야…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These enchanted spears won't just damage your cards..", "이 마력이 깃든 창은 네 카드들에 피해만 주는 게 아니지…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hah! Using one of my own spells against me?", "하! 내 주문으로 나를 상대하겠다고?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you think those cards are a little too powerful?", "저 카드들이 좀 너무 강하다고 생각하지 않나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's better.", "이게 낫군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]How did you get that?[c:]", "[c:g1]그건 어떻게 얻었지?[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, ".. Where on earth is my [c:g1]Goo Mage[c:]?", "…내 [c:g1]점액 마법사[c:]는 대체 어디 있지?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have your.. Modifications removed him?", "네… 개조가 그를 없앤 건가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This tampering has gone on for far too long. I shall not allow it anymore.", "이런 변조는 너무 오래 계속되었다. 더는 허용하지 않겠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When we face off, I won't be holding myself back.", "맞붙을 때는 조금도 봐주지 않겠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Halt![c:] [c:g2]A[c:] [c:g1]challenger[c:] [c:g2]dare[c:] [c:g1]approach?![c:]", "[c:g1]멈춰라![c:] [c:g2]도전자가[c:] [c:g1]감히[c:] [c:g2]다가온[c:] [c:g1]것이냐?![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Quaint,[c:] [c:g2]I[c:] [c:g1]shall[c:] [c:g2]make[c:] [c:g1]mince[c:] [c:g2]meat[c:] [c:g1]out[c:] [c:g2]of[c:] [c:g1]you.[c:]", "[c:g1]우습군.[c:] [c:g2]내가[c:] [c:g1]지금[c:] [c:g2]너를[c:] [c:g1]아주[c:] [c:g2]잘게[c:] [c:g1]다져서[c:] [c:g2]고기로[c:] [c:g1]만들겠다.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Irritating,[c:] [c:g2]you[c:] [c:g1]persist.[c:] [c:g2]You[c:] [c:g1]have[c:] [c:g2]bound[c:] [c:g1]me[c:] [c:g2]to[c:] [c:g1]excert[c:] [c:g2]my[c:] [c:g1]blade.[c:]", "[c:g1]성가시군.[c:] [c:g2]네가[c:] [c:g1]계속[c:] [c:g2]버티다니.[c:] [c:g1]너는[c:] [c:g2]결국[c:] [c:g1]내가[c:] [c:g2]이[c:] [c:g1]칼날을[c:] [c:g2]뽑게[c:] [c:g1]만들었다.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Eh?[c:] [c:g2]Some[c:] [c:g1]sort[c:] [c:g2]of[c:] [c:g1]immitation[c:] [c:g2]of[c:] [c:g1]me?[c:]", "[c:g1]응?[c:] [c:g2]이건[c:] [c:g1]나를[c:] [c:g2]흉내[c:] [c:g1]낸[c:] [c:g2]무언가[c:][c:g1]인가?[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "c:g1]Pathetic.[c:] [c:g2]My[c:] [c:g1]Drake[c:] [c:g2]was[c:] [c:g1]much[c:] [c:g2]grander[c:] [c:g1]than[c:] [c:g2]that.[c:]", "[c:g1]한심하군.[c:] [c:g2]내[c:] [c:g1]거룡은[c:] [c:g2]그런[c:] [c:g1]것보다[c:] [c:g2]훨씬[c:] [c:g1]더[c:] [c:g2]위대했다.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "W-What? A challenger?", "뭐, 뭐라고? 도전자?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FINALLY!! STIMULATION!", "드디어!! 자극이다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M STILL NOT STIMULATED ENOUGH!!", "아직 자극이 부족해!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I HAVE THE URGE TO SEARCH A CARD PILE!", "카드 더미를 뒤지고 싶어 못 참겠어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M GROWING IMPATIENT!\nI NEED MORE STIMULATION!!", "점점 조급해져!\n자극이 더 필요해!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WOW!! I REMEMBER BREWING THAT!", "와!! 그거 만들었던 게 기억나!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HEY.. YOU DON'T HAVE ANY CARDS LEFT?", "이봐… 카드가 하나도 안 남았어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BORING!", "지루해!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WOW! COOL CARD!!", "와! 멋진 카드다!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FINDERS KEEPERS!", "찾은 사람이 임자!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm afraid you've doomed us all, challenger..", "도전자, 네가 우리 모두를 파멸시킨 것 같구나…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps I am slowing down with age..", "나이를 먹어 느려진 모양이군…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I must use the brush to my advantage yet again.", "다시 한번 붓을 유리하게 활용해야겠군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have impressed me, you truly have..", "인상적이었어. 정말로 그랬지…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "2 lives down now.", "이제 목숨을 2개 잃었군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unfortunately for you, I still have a few tricks up my sleeve.", "안됐지만 아직 비장의 수가 몇 개 남아 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I could never allow myself to go down that easily.", "그렇게 쉽게 쓰러질 수는 없지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utter folly.. Getting outside assitance, are we?", "어리석기 짝이 없군… 외부의 도움을 받겠다는 건가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Free Legs", "자유의 다리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unsealed Body", "봉인 해제된 몸", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Released Arms", "해방된 팔", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unleashed Tyrant", "해방된 폭군", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just what do you think you're doing?", "대체 무슨 짓을 하는 거지?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do not.", "하지 마라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trying to pull a trick as dirty as that..", "그렇게 더러운 속임수를 쓰려 하다니…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upsetting. I seem to be losing.", "불쾌하군. 내가 지고 있는 모양이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How about a new rule.", "새 규칙은 어떤가.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everytime [c:g2]you[c:] play a mox, [c:g2]I[c:] restore 1 health.", "[c:g2]네가[c:] 목스를 낼 때마다 [c:g2]나는[c:] 체력을 1 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frustrating. I must use my last resort.", "답답하군. 최후의 수단을 써야겠어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]We[c:] [c:g2]have[c:] [c:g3]become[c:] four!", "[c:g1]우리는[c:] [c:g2]이제[c:] [c:g3]넷이[c:] 되었다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]Hmm?[c:] [c:g3]An[c:] [c:g2]opponent..?[c:]", "[c:g2]흠?[c:] [c:g3]상대가[c:] [c:g2]왔나…?[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]I[c:] [c:g3]haven't[c:] [c:g2]had[c:] [c:g3]a[c:] [c:g2]duel[c:] [c:g3]in[c:] [c:g2]a[c:] [c:g3]century![c:]", "[c:g2]나는[c:] [c:g3]벌써[c:] [c:g2]꼬박[c:] [c:g3]한[c:] [c:g2]세기[c:] [c:g3]동안[c:] [c:g2]결투를[c:] [c:g3]못 했다![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]Have[c:] [c:g3]at[c:] [c:g2]thee![c:]", "[c:g2]자,[c:] [c:g3]덤벼[c:] [c:g2]보아라![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]A[c:] [c:g3]fierce[c:] [c:g2]opponent[c:] [c:g3]you[c:] [c:g2]are![c:]", "[c:g2]너는[c:] [c:g3]참으로[c:] [c:g2]만만찮은[c:] [c:g3]상대[c:][c:g2]로구나![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]I'll[c:] [c:g3]just[c:] [c:g2]have[c:] [c:g3]to[c:] [c:g2]use[c:] [c:g3]some[c:] [c:g2]more[c:] [c:g3]dirty[c:] [c:g2]tricks[c:] [c:g3]to[c:] [c:g2]beat[c:] [c:g3]you![c:]", "[c:g2]너를[c:] [c:g3]이기려면[c:] [c:g2]나는[c:] [c:g3]그저[c:] [c:g2]조금[c:] [c:g3]더[c:] [c:g2]비열한[c:] [c:g3]속임수를[c:] [c:g2]써야만[c:] [c:g3]할[c:] [c:g2]것[c:] [c:g3]같구나![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]And[c:] [c:g3]something[c:] [c:g2]else,[c:] [c:g3]why[c:] [c:g2]not.[c:]", "[c:g2]거기에[c:] [c:g3]다른[c:] [c:g2]것도[c:] [c:g3]써 보면[c:] [c:g2]어때.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]Ooh![c:] [c:g3]What[c:] [c:g2]a[c:] [c:g3]great[c:] [c:g2]portrait![c:]", "[c:g2]오![c:] [c:g3]정말[c:] [c:g2]멋진[c:] [c:g3]초상화[c:][c:g2]로구나![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]A[c:] [c:g3]replica[c:] [c:g2]of[c:] [c:g3]my[c:] [c:g2]loyal[c:] [c:g3]phoenix,[c:] [c:g2]isn't[c:] [c:g3]she[c:] [c:g2]absolutely[c:] [c:g3]stunning?[c:]", "[c:g2]내[c:] [c:g3]충직한[c:] [c:g2]불사조의[c:] [c:g3]복제체다.[c:] [c:g2]그녀는[c:] [c:g3]정말[c:] [c:g2]눈부실[c:] [c:g3]정도로[c:] [c:g2]아름답지[c:] [c:g3]않니?[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]I[c:] [c:g3]see[c:] [c:g2]you've[c:] [c:g3]done[c:] [c:g2]a[c:] [c:g3]fair[c:] [c:g2]bit[c:] [c:g3]of[c:] [c:g2]damage![c:]", "[c:g2]보아하니[c:] [c:g3]네가[c:] [c:g2]벌써[c:] [c:g3]꽤나[c:] [c:g2]상당한[c:] [c:g3]피해를[c:] [c:g2]입힌[c:] [c:g3]것[c:] [c:g2]같구나![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]Don't[c:] [c:g3]mind[c:] [c:g2]if[c:] [c:g3]I[c:] [c:g2]just[c:] [c:g3]place[c:] [c:g2]my[c:] [c:g3]thieves..[c:]", "[c:g2]내가[c:] [c:g3]여기에[c:] [c:g2]내[c:] [c:g3]도둑들을[c:] [c:g2]그냥[c:] [c:g3]좀[c:] [c:g2]놓아도[c:] [c:g3]괜찮겠지…[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Out of cards..", "카드가 없군…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dissapointing. I had high hopes for you.", "실망스럽군. 큰 기대를 걸었는데.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a tiny collection of cards..", "카드가 이렇게 조금뿐이라니…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I highly doubt you will win.", "네가 이길 수 있을지 몹시 의심스럽군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With a blaze of Magick, you end the battle. You managed to deal more damage than needed.", "마법의 불꽃과 함께 전투를 끝냈다. 필요한 것보다 더 많은 피해를 입혔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The excess Magick you cast turns into [c:g3] Crystals. [c:] You may spend them at any meek store you happen to find.", "초과한 마법은 [c:g3]수정[c:]으로 변한다. 도중에 만나는 작은 가게에서 쓸 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Welcome back.", "돌아온 것을 환영한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're the first in a while to get this far.", "여기까지 온 자는 오랜만이군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will now bestow upon you, the highest honour I can possibly give.", "이제 내가 줄 수 있는 최고의 영예를 내리겠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To be painted, and immortalised forever, as a card.", "카드로 그려져 영원히 불멸하는 영예다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The dummy stares lifelessly back at you.", "인형이 생기 없이 너를 마주 본다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Then, suddenly it springs to motion!", "그러다 갑자기 움직이기 시작한다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The dummy's hinges creak back into position, and it returns to it's lifeless stare.", "인형의 경첩이 삐걱이며 원래 위치로 돌아가고 다시 생기 없이 응시한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So you finally arrive..", "마침내 왔군…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hopefully you have prepared yourself well enough to face the Scrybe of Magicks.", "마력의 필경자를 상대할 준비는 충분히 했겠지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will be your final exam.", "이것이 네 최종 시험이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let us dance.", "춤을 추자꾸나.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]You[c:] are finally here.", "[c:g2]네가[c:] 드디어 왔구나.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope you realise that this is truly it.", "이번이 정말 마지막이라는 걸 알기 바란다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may have removed my student's battles,", "내 학생들과의 전투를 없앴을지 모르고,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may have tampered with my entire game..", "내 게임 전체를 변조했을지도 모르지만…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time.", "때가 되었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greetings, challenger.", "반갑다, 도전자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears that all of your mox has been erased.", "네 목스가 모두 지워진 모양이군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curiosity killed the cat..", "호기심이 고양이를 죽인다지…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a shame you got defeated so early..", "이렇게 일찍 패배하다니 안됐군…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a shame you got defeated so easily.", "그렇게 쉽게 패배하다니 안됐군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a shame you got defeated so far in.", "이렇게 멀리 와서 패배하다니 안됐군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I had such high hopes, but you lost it all..", "큰 기대를 걸었건만 너는 모두 잃었구나…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems my slime mage got the best of you. How dissapointing.", "내 슬라임 마법사에게 당한 모양이군. 실망스럽다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It looks like my pike mage tactically took you out..", "내 장창 마법사가 전술로 너를 쓰러뜨린 모양이군…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like that lonely mage got to you..", "저 외로운 마법사에게 당한 모양이군…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though it does not matter.", "하지만 상관없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I do not have any more use for you.", "너는 더는 쓸모가 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, take your leave.", "이만 떠나라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looking for something?", "뭔가 찾고 있나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm afraid the object you seek has been.. [c:g1]relocated[c:]..", "찾는 물건은 이미… [c:g1]옮겨 두었다[c:]만…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Look at what you've unleashed..", "무엇을 풀어 놓았는지 봐라…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Was it truly worth finding?", "정말 찾을 가치가 있었나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph.. I did not intend for you to get out here..", "흥… 여기까지 나오게 할 생각은 없었다만…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have forseen it though. Despite my best attempts you persist.", "하지만 예견은 했지. 내가 최선을 다해도 너는 포기하지 않아.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We shall duel here..", "여기서 결투를 벌이자…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though, lets up the stakes.", "다만 판돈을 올려 보지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you lose here, your entire [c:g1]life painting[c:] will get bleached..", "여기서 지면 네 [c:g1]생명 그림[c:] 전체가 표백된다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Step forth if you dare.", "감히 할 수 있다면 앞으로 나와라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You persist again?", "또 포기하지 않는 건가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see..", "그렇군…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We shall duel again!", "다시 결투를 벌이자!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah.. Finally, you arrive.", "아… 드디어 왔구나.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've been watching you from up here, for your entire journey.", "네 여정 내내 이 위에서 지켜보았다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've come a long way, challenger.", "멀리도 왔구나, 도전자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unfortunately, that will all come to an end here.", "안됐지만 모두 여기서 끝이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One last duel, to decide your fate..", "마지막 결투로 네 운명을 정하자…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time to put an end to this.. [c:g1]foolery[c:] of yours.", "네 이… [c:g1]어리석은 짓[c:]을 끝낼 시간이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you consider these cheats fair, then I might as well use some cheats of my own.", "그런 부정행위가 공정하다고 생각한다면 나도 내 방식대로 부정행위를 해도 되겠지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Normally, I would have you expelled right on the spot.. But I'm feeling generous.", "보통이라면 그 자리에서 퇴학시켰겠지만… 지금은 너그러운 기분이군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let us duel.", "결투를 시작하자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whats the matter? Stumped?", "왜 그러지? 막혔나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try searching around the dungeon.. There may be certain [c:g1]markings[c:] you missed..", "던전을 둘러봐라… 놓친 [c:g1]표식[c:]이 있을지도 모르지…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm?", "흠?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you wondering what this book is for?", "이 책이 무슨 용도인지 궁금한가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That is your [c:g1]spell book[c:]. You may use it to draw one of your [c:g3]spell cards[c:].", "그건 네 [c:g1]주문 대전[c:]이다. 사용하면 네 [c:g3]주문 카드[c:] 중 한 장을 뽑을 수 있지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But only [c:g1]one[c:] per turn..", "하지만 한 턴에 [c:g1]한 장[c:]뿐이다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You land in a sticky puddle of goo, stretching out into what seems like an endless void..", "끈적한 점액 웅덩이에 내려섰다. 끝없는 공허까지 뻗어 있는 듯하다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruined pillars and ancient walls surround your vision, overtaken by yet more slime..", "무너진 기둥과 고대 벽이 시야를 둘러싸고 더 많은 점액에 뒤덮여 있다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The glistening heavens above shine brightly unto you.", "머리 위 반짝이는 하늘이 너를 환히 비춘다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You arrive in the..", "네가 도착한 곳은…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sudden influx of heat surrounds you..", "갑자기 열기가 밀려와 너를 둘러싼다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimly lit and dingy chambers spread out as far as you can see.", "어둡고 지저분한 방들이 보이는 곳 끝까지 펼쳐진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Long forgotten echoes of ancient sparring fill the room.", "오래전에 잊힌 고대 대련의 메아리가 방을 채운다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You find yourself in the..", "네가 있는 곳은…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dusty old smell fills your nostrills..", "먼지 쌓인 오래된 냄새가 콧속을 채운다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hundreds of walls containing books, laying untouched for eons, fill the quiet landscape.", "책을 품은 수백 개의 벽이 고요한 풍경을 채운다. 아득한 세월 동안 아무도 손대지 않았다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ethereal runes, containing lost, forbidden knowledge surround you.", "잃어버린 금단의 지식을 품은 실체 없는 룬들이 너를 둘러싼다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You awake in the..", "네가 깨어난 곳은…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmmm. It seems a new student is woven onto my canvas.", "흠. 새로운 학생이 내 화폭에 짜인 모양이군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you look behind yourself, you may see a [c:g1]shop[c:].", "뒤를 돌아보면 [c:g1]상점[c:]이 보일지도 모르지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may view your deck and rearange your side deck.", "덱을 확인하고 보조 덱을 다시 구성할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though, do not be alarmed. You may find a shop later on your adventures.", "하지만 놀랄 것 없다. 모험 도중에도 상점을 찾을 수 있을 테니.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you are ready to proceed, you may step forth and enter into the unknown.", "나아갈 준비가 되었다면 앞으로 걸어 미지로 들어가라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm.. A young student appears,", "흠… 어린 학생이 나타났군,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So foolish, your predesscor didn't even manage to get past my [c:g1]Goo Mage[c:].", "어리석군. 네 전임자는 내 [c:g1]점액 마법사[c:]도 넘지 못했어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah well.. Maybe you will manage such a feat.", "뭐, 좋아… 너라면 해낼지도 모르지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another appears.", "또 하나 나타났군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe you will manage to get further than those before you.", "앞선 자들보다 멀리 갈 수 있을지도 모르지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You young understudies still have much to learn.", "너희 어린 견습생들은 아직 배울 게 많다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah. I had expectations for my previous mage,", "아, 이전 마법사에게는 기대를 걸었지,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They even managed to get past my [c:g2]Pike Mage[c:].", "내 [c:g2]장창 마법사[c:]까지 넘었으니.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A great feat, it seems now you must follow in their footsteps...", "대단한 업적이었어. 이제는 네가 그 발자취를 따라야 할 모양이군…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So, yet another steps up to be my student.", "자, 또 하나 내 학생이 되려고 나섰군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must learn yourself, to overcome my many obstacles and challenges.", "스스로 배워서 내가 마련한 수많은 장애물과 도전을 극복해야 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you do succeed, I shall bestow upon you a great honour..", "성공한다면 큰 영예를 내리겠다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm.. Something feels off..", "흠… 뭔가 이상하군…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have you [c:g1]modded[c:] my game, challenger?", "도전자, 내 게임에 [c:g1]모드를 설치한[c:] 건가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph! How disrespectful!", "흥! 무례하군!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Was my game not enough for you?", "내 게임만으로는 부족했나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alas, I have no choice but to allow it..", "아아, 허용하는 수밖에 없군…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just what is going on here..?", "대체 무슨 일이 벌어지는 거지…?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These cards,", "이 카드들,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did that [c:g2]foul little..[c:] get in here..?", "저 [c:g2]더러운 작은…[c:] 것이 들어왔나…?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I believe you are in the wrong place, challenger.", "도전자, 장소를 잘못 찾은 것 같군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hold still.", "가만히 있어라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are a simpleton for expecting scales.", "저울을 기대하다니 멍청하군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is a simple race to 0.", "이건 그저 0을 향한 경주다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOW ITS TIME FOR ME TO PRACTICE MY BREWING MAGICKS!!", "이제 내 양조 마법을 연습할 시간이야!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT IS DONE!!! GO TAKE IT!!", "다 됐어!!! 어서 가져가!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GO!!", "가!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]GET OUT OF HERE!![c:]", "[c:g2]여기서 나가!![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WOAH! LOOKS LIKE SOMETHING YOU PUT INTO THE POTION MADE IT A BIT.. [c:g1]PRICY[c:]..", "와! 물약에 넣은 뭔가 때문에 좀… [c:g1]비싸진[c:] 모양이야…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "W-What? Am I finally free?", "뭐, 뭐야? 드디어 자유야?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A break from that endless darkness?", "그 끝없는 어둠에서 벗어난 거야?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nevermind.. It's just potion making..", "아니구나… 그냥 물약 만들기야…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, Hi Challenger!!", "오, 안녕, 도전자!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow, someone new!!", "와, 새로운 사람이야!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just give me two cards of yours and we'll make a potion out of them!!", "네 카드를 두 장만 주면 그걸로 물약을 만들자!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can later give this potion to your cards and they gain some silly effects!", "나중에 카드들에게 물약을 주면 재미있는 효과를 얻을 수 있어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come on!! It will be fun!!", "어서!! 재미있을 거야!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And stimulating..", "그리고 자극적이지…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So stimulating", "정말 자극적이야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello there challenger!!", "안녕, 도전자!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know how this works now", "이제 어떻게 하는지 알지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just give me two cards and we'll make a potion!", "카드를 두 장 주면 물약을 만들자!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woah.. What.. Is this place?", "와… 여긴… 어디야?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So bright..", "너무 밝아…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, Hi there!!", "오, 안녕!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's make some potions!!", "물약을 만들자!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just hand over two cards and we'll be done with it..", "카드 두 장만 건네면 금방 끝나…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WAIT!! YOUR SPELLBOOK IS FULL", "잠깐!! 주문 대전이 가득 찼어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GET RID OF ONE OF YOUR SPELLS, OR YOU WONT BE ABLE TO TAKE OUR POTION!!", "주문 하나를 버려! 안 그러면 우리 물약을 가져갈 수 없어!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your card's cost has been changed..", "네 카드의 비용이 바뀌었어…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you have a card that has a cost you are unsatisfied with?", "비용이 마음에 들지 않는 카드가 있나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No. It appears not.", "없군. 그런 모양이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS SEE HERE..", "어디 보자…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HMM?", "흠?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT DO YOU THINK?", "어떻게 생각해?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WELL?", "어때?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT WOULD THE MASTER THINK?", "대가는 어떻게 생각하실까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WOULD THE MASTER BE PROUD?", "대가가 자랑스러워하실까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IS IT GOOD?", "잘됐어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GRREETINGS CHALLENGER!", "반가아압다, 도전자!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU'RE ALREADY HERE?", "벌써 여기 왔어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I DON'T REALLY RECALL US BATTLING..", "우리가 싸운 기억은 별로 없는데…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WELL ANYWAYS.. WHAT CARD WHOULD I PRACTICE ON?", "뭐, 어쨌든… 어느 카드로 연습할까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT WOULD SEEM THAT YOU HAVE DISGRACED ME!", "나를 망신시켰구나!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BUT IT IS ALRIGHT, I FORGIVE YOU.", "하지만 괜찮아. 용서할게.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SAY, CHALLENGER, I WOULD LIKE TO PRACTICE MY [c:g2]ART[c:]..", "이봐, 도전자. 내 [c:g2]그림 솜씨[c:]를 연습하고 싶어…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ONE DAY I MIGHT EVEN BE AS GOOD AS THE MASTER!", "언젠가는 대가만큼 잘하게 될지도 몰라!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU WOULDN'T MIND GIVING ME ONE OF YOUR THERE CARDS, RIGHT?", "네 카드 중 하나를 줘도 괜찮지?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT CARD SHOULD I PRACTICE ON?", "어느 카드로 연습할까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'LL NEED A CARD TO HONE MY SKILLS ON.", "솜씨를 갈고닦을 카드가 필요해.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I DON'T THINK WE'VE MET BEFORE!", "우리는 처음 보는 것 같은데!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU ARENT SUPPOSED TO SEE ME UNTILL LATER, BUT..", "원래는 나중에 나를 만나야 하는데, 그래도…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, ".. It appears you have nothing else to offer..", "…다른 바칠 것은 없는 모양이군…", Language.Korean);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your" + value + " sits on the enchanted grounds...\nYou could either leave it there, to enchant it..", "네 " + value + "이(가) 마법이 깃든 땅 위에 있다……\n그곳에 두고 마법을 부여할 수 있다……", Language.Korean);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Or you can slaughter it to improve the enchantment, dictated by the [c:g1]Ethereal Sigils[c:].", "아니면 죽여서 [c:g1]공허 도장[c:]이 정하는 대로 마법 부여를 강화할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The choice is yours.", "선택은 네 몫이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Ethereal Sigils[c:] hover around the grounds.", "[c:g1]공허 도장[c:]이 땅 주위를 맴돈다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may use them to predict a possible outcome..", "그것들로 가능한 결과를 예측할 수 있다…", Language.Korean);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your " + value + " has been burdened with Glass Cannon!", "네 " + value + "에게 유리 대포의 저주가 걸렸다!", Language.Korean);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your " + value + " has been burdened with Tank!", "네 " + value + "에게 탱크의 저주가 걸렸다!", Language.Korean);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your " + value + " has been blessed!", "네 " + value + "이(가) 축복받았다!", Language.Korean);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your " + value + " has been burdened!", "네 " + value + "에게 저주가 걸렸다!", Language.Korean);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your " + value + " is now free.. But more unstable..", "네 " + value + "의 비용이 없어졌다…… 하지만 더 불안정해졌다……", Language.Korean);
                foreach (var kvp in Abilities)
                {
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your" + value + " has been blessed with " + kvp.Key + "!", "네 " + value + "이(가) " + kvp.Value + "의 축복을 받았다!", Language.Korean);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your" + value + " has been burdened with " + kvp.Key + "!", "네 " + value + "에게 " + kvp.Value + "의 저주가 걸렸다!", Language.Korean);
                }
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:g1]Sacrifical Grounds[c:] stand before you.\nLegends tell of cards growing exponentially in power here, under the right circumstances..", "[c:g1]희생의 땅[c:]이 앞에 있다.\n알맞은 조건에서는 이곳에서 카드의 힘이 기하급수적으로 커진다고 한다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, ".. However, it appears that you don't have anything to offer to the enchanted grounds..", "…하지만 이 마력이 깃든 땅에 바칠 것이 없는 모양이다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Enchanted Grounds seem to be slightly improved.", "마력이 깃든 땅이 조금 강화된 듯하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Enchanted Grounds are unsatisfied..", "마력이 깃든 땅은 만족하지 않는다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Enchanted Grounds dimly light up with sacrifical energy.", "마력이 깃든 땅이 희생의 에너지로 희미하게 빛난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Enchanted Grounds are displeased..", "마력이 깃든 땅이 언짢아한다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Enchanted Grounds light up with supernatural energy.", "마력이 깃든 땅이 초자연적 에너지로 빛난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Enchanted Grounds are angered..", "마력이 깃든 땅이 화가 났다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Enchanted Grounds The Enchanted Grounds are absolutely bursting with sacrifical energy.", "마력이 깃든 땅은 희생의 에너지로 터질 듯하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Enchanted Grounds The Enchanted Grounds are furious.", "마력이 깃든 땅이 격노했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eurgh.. This place is disgusting..", "으으… 역겨운 곳이군…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seems like I'm forced to train spellcasting in here.", "이곳에서 강제로 주문 시전을 연습해야 하는 모양이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give me a [c:g1]spell[c:] of yours, and make it quick.", "네 [c:g1]주문[c:] 하나를 내놔. 빨리.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greetings..", "안녕…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give me one of your [c:g1]spells[c:]", "네 [c:g1]주문[c:] 하나를 줘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give me one of your [c:g1]spells[c:].", "네 [c:g1]주문[c:] 하나를 줘.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh.. Greetings... I don't believe we've been introduced..", "아… 안녕… 아직 소개받지 못한 것 같은데…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've been force- er.. asked to train my spellcasting here.", "여기서 주문 시전을 연습하라고 강요… 아니, 부탁받았어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why don't you give me some of your [c:g1]spells[c:]?", "네 [c:g1]주문[c:]을 좀 주지 않을래?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm? Oh, hello again.. We still haven't been formally introduced.", "응? 아, 또 만났네… 아직 정식으로 소개하지 않았지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll need one of your [c:g1]spells[c:] for my training..", "연습하려면 네 [c:g1]주문[c:] 하나가 필요해…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh.. Hello there.", "아… 안녕.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The master asked me to practice my spellcasting..", "대가가 주문 시전을 연습하라고 했어…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh.. Spellcasting. Right..", "아… 주문 시전. 그렇지…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What? Oh.. This must be.. [c:g3]his[c:] area..", "뭐? 아…… 여긴 분명…… [c:g3]그분[c:]의 구역이겠지……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, anyway.. The master asked me to train my spellcasting.", "뭐, 아무튼…… 스승님이 주문 시전 연습을 하라고 하셨어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm..?", "음……?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here already? We haven't even battled..", "벌써 왔어? 아직 대결도 안 했는데……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well anyways, just hand over a [c:g1]spell[c:].", "아무튼 [c:g1]주문[c:] 카드 한 장을 줘.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh.. You don't have any spells?", "아…… 주문이 하나도 없어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess I could give you one of my upgraded ones.. Hopefully they're good.", "그럼 내가 강화한 걸 하나 줄게…… 쓸 만하면 좋겠네.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now your spell will last forever..", "이제 네 주문은 영원히 남을 거야……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So, you truly wish to release that tyrant..", "그러니 정말로 그 폭군을 풀어 줄 생각이로군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope you understand the type of power you are dealing with..", "네가 어떤 힘에 손을 대고 있는지 이해하고 있기를 바란다……", Language.Korean);
            foreach (var kvp in Cards)
            {
                foreach (var kvp2 in Abilities)
                {
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your " + kvp.Key + " is now free of its " + kvp2.Key + "...", "네 " + kvp.Value + "이(가) " + kvp2.Value + "에서 벗어났다……", Language.Korean);
                }
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm.. The essence of that sigil does not resonate with your card..", "흠…… 그 도장의 정수는 네 카드와 공명하지 않는군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "..It appears nothing was gained", "……아무것도 얻지 못한 모양이군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The essence of the sigil has imbued the card with more power.", "도장의 정수가 카드의 능력치를 더 높였다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The essence of the sigil has imbued the card with more gourd.", "도장의 정수가 카드에 더 큰 생명력을 불어넣었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The essence of the sigil has imbued the card with more strength.", "도장의 정수가 카드에 더 큰 힘을 불어넣었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph.. My bleach.. failed?", "흥…… 내 표백제가…… 듣지 않았다고?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Was this your doing, challenger?", "네 짓인가, 도전자여?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph..", "흥……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to imbue with a lost sigils strength..", "잃어버릴 도장의 힘을 불어넣을 카드를 골라라……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here I will allow you to [c:g1]bleach[c:] a card of one of its sigils..", "여기서는 카드의 도장 하나를 [c:g1]표백제[c:]로 지우게 해 주마……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When bleached, the card will imbue the power of its lost sigil,", "표백하면 카드는 잃어버린 도장의 힘을 흡수하고,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and get much [c:g2]stronger[c:] depending on the sigils raw strength.", "도장 본연의 힘에 따라 훨씬 [c:g2]강해진다[c:].", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, but your [c:g1]spell book[c:] is full...", "아, 하지만 네 [c:g1]주문 대전[c:]은 가득 찼군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You step foot into a small store.. A brief respite from your winding travels.", "작은 가게에 발을 들인다…… 굽이진 여정 속 잠깐의 휴식이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You step foot into a small store...", "작은 가게에 발을 들인다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:g1]deck[c:] is stored in this pile.. ", "네 [c:g1]덱[c:]은 이 더미에 보관되어 있다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, ".. And your [c:g1]side deck[c:] is stored here, where you can adjust it as you see fit. ", "……그리고 네 [c:g1]보조 덱[c:]은 여기 있다. 원하는 대로 조정해라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, ".. Hmmph, I guess it was not meant to be..", "……흥, 인연이 아니었던 모양이군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twisted and warped by the fungi, a new card emerges. Only through pain can one grow…", "곰팡이에 뒤틀리고 변형된 새 카드가 나타난다. 고통을 겪어야만 성장할 수 있다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now the mushrooms require a card that they will attach.. Increasing the stats of the host.", "이제 버섯이 달라붙을 카드가 필요하다…… 숙주의 능력치를 높이기 위해.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You encounter the abnormally disgusting fungi that infests this dungeon.", "이 지하 미궁에 퍼져 있는 유난히 역겨운 곰팡이와 마주친다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is said to possess strange properties..", "기이한 성질을 지녔다고 한다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mushrooms yearn for a card they can use as a.. [c:g1]host[c:] of sorts.", "버섯은 카드 한 장을 갈망한다…… 일종의 [c:g1]숙주[c:]로 쓸 수 있는 카드를.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One that they will attack to.", "그 위에 달라붙으려는 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You encounter the disgusting fungi yet again..", "또다시 그 역겨운 곰팡이와 마주친다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The fungi yearn for a card they can use as a [c:g1]host[c:].. to attach to.", "곰팡이는 [c:g1]숙주[c:]로 삼을 카드를 갈망한다…… 달라붙을 대상을.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yet... It seems you do not have two cards worthy of the fungi's touch. Wearisome.", "하지만…… 곰팡이가 손댈 만한 카드가 두 장 없는 모양이다. 맥 빠지는군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have the honours of naming it.", "이름을 지을 영광은 네게 주마.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finished?", "다 했나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:g1]cost[c:] and [c:g2]portrait[c:] I will handle myself..", "[c:g1]비용[c:]과 [c:g2]카드 그림[c:]은 내가 정하겠다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was nice meeting you, my student.", "만나서 반가웠다, 나의 제자여.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But this is where we say farewell..", "하지만 여기서 작별해야겠구나……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just hold still for a second.", "잠시만 가만히 있거라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will base it off of cards in your deck.", "네 덱에 있는 카드를 바탕으로 정하겠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First, the stats.", "우선은 능력치다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:g1]sigils[c:].", "다음은 [c:g1]도장[c:]이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm.. You're out of paint.", "흠…… 물감이 다 떨어졌군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can bleach your drawing.. or consider it finished.", "그림을 표백해 지워도 좋고…… 완성한 것으로 해도 좋다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A neccesary part of each student's training is art..", "미술은 모든 제자가 반드시 배워야 하는 과목이지……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's start with the portrait..", "카드 그림부터 시작하자……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can use the bleach on the left to wipe your work..", "왼쪽의 표백제로 그린 것을 지울 수 있다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are currently holding a [c:g1]replica brush[c:].. If you feel you need a smaller one, you can grab the one on the right.", "지금 들고 있는 것은 [c:g1]복제 붓[c:]이다…… 더 작은 게 필요하면 오른쪽의 붓을 집어도 좋다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use that brush in the back to change your color.", "뒤쪽의 붓으로 색을 바꿔라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My pupil's portraits never fail to amuse me..", "제자들이 그린 카드 그림은 언제나 나를 즐겁게 하지……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now let's choose which card's [c:g1]stats[c:] to imbue.", "이제 어느 카드의 [c:g1]능력치[c:]를 불어넣을지 골라라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now, the [c:g1]sigils[c:].", "이제 [c:g1]도장[c:]이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, but your spell book is full..", "아, 하지만 네 주문 대전은 가득 찼군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Either discard this one...", "이 카드를 버리거나……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Or, remove one of your spells..", "네 주문 카드 중 한 장을 제거해라……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have any cards to use that [c:g1]potion[c:] on.", "그 [c:g1]마법약[c:]을 쓸 카드가 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You won't have any cards to use that spell on.", "그 주문을 쓸 카드가 없어질 거다.", Language.Korean);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your " + value + " wields no mana.", "네 " + value + "에게는 마나가 없다.", Language.Korean);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That doesn't have any mana.", "그 카드에는 마나가 없다.", Language.Korean);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The " + value + " has no mana.", value + "에게는 마나가 없다.", Language.Korean);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can not draw mana from that.", "거기서는 마나를 끌어낼 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Through this maze of paintings and illusions, there may be some that deign to join your deck.\nChoose carefully.", "이 그림과 환영의 미궁에는 네 덱에 들어와 주겠다는 존재가 있을지도 모른다.\n신중히 골라라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... Curious.", "……흥미롭군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I thought I had completely removed this.. [c:g2]filth[c:].", "이런…… [c:g2]오물[c:]은 완전히 없앴다고 생각했는데.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You humor me challenger..", "웃겨 주는군, 도전자여……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you expect your measely [c:g1]hammer[c:] to work on such a creature as the [c:g1]ouroberyl[c:]?", "그 하찮은 [c:g1]망치[c:]가 [c:g1]우로베릴[c:] 같은 피조물에게 통할 줄 알았나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How foolish.", "어리석군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your hammer is now [c:g1]broken[c:], and may not be used for the remainder of the battle.", "네 망치는 이제 [c:g1]부서졌다[c:]. 이번 전투가 끝날 때까지 사용할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems that you lost..", "패배한 모양이군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "See this portrait?", "이 초상화가 보이나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This portrait will act as your life counter.", "이 초상화가 네 남은 목숨을 표시한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once all the [c:g1]m[c:][c:g2]o[c:][c:g3]x[c:] [c:g1]g[c:][c:g2]e[c:][c:g3]m[c:][c:g1]s[c:] go out.. You lose the game.", "[c:g1]목[c:][c:g2]스[c:] [c:g3]보[c:][c:g1]석[c:][c:g2]이[c:] [c:g3]모[c:][c:g1]두[c:] 꺼지면…… 게임에서 패배한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Since you lost.. I will have to remove one gem.", "패배했으니…… 보석 하나를 제거해야겠군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The deed has been done.", "처리는 끝났다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like you have been knocked down by your opponent.", "상대에게 쓰러진 모양이군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stand tall, and continue forth.", "당당히 일어서서 계속 나아가라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems as though you should study up on mox.", "목스에 대해 좀 더 공부해야 할 것 같군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though you should not lose hope, as you still have 2 more lives.", "하지만 희망을 버리지 마라. 아직 목숨이 2개 더 남아 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You make a last effort to succeed, yet fail. It seems you lose, again.", "마지막까지 성공하려 애썼지만 실패했다. 또다시 패배한 모양이군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You shall continue forward.", "계속 나아가거라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It takes just one more blow for you to fall to the ground.", "한 번만 더 맞으면 쓰러진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Losing a life, you must continue forward.", "목숨 하나를 잃었어도 계속 나아가야 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems the show shall end… for now..", "이제 막을 내려야 할 것 같군…… 당분간은……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just what is going on here?", "대체 무슨 일이 벌어지고 있는 거지?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Master Magnus'..", "'마스터 마그누스'라……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is [c:g2]NO[c:] such master!", "그런 스승은 [c:g2]존재하지 않는다[c:]!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Argh.. I guess, if you truly wish to play with such additions, I am truly unable to stop you.", "크윽…… 정말로 그런 것들을 추가해서 즐기겠다면 내가 막을 수는 없겠군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though, I do NOT approve of this.", "하지만 나는 절대로 찬성하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears that the ficticious Master Magnus has showed itself.", "허구의 마스터 마그누스가 모습을 드러낸 모양이군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That horrid [c:g1]thing[c:] rears it's ugly head.", "그 끔찍한 [c:g1]것[c:]이 추한 머리를 들이미는군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The released Master Magnus approaches.", "풀려난 마스터 마그누스가 다가온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful. That horrible master is here.", "조심해라. 그 끔찍한 스승이 왔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Magnus has arrived. Be cautious.", "마스터 마그누스가 도착했다. 경계해라.", Language.Korean);
            foreach (var kvp in Cards)
            {
                var key = kvp.Key;
                var value = kvp.Value;
                foreach (var kv in CardsDescription[key])
                {
                    var descKey = kv.Key;
                    var descValue = kv.Value;
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You glance at a " + key + ". " + descKey, "너는 " + value + "을(를) 힐끗 보았다. " + descValue, Language.Korean);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A " + key + " appears from within the portrait. " + descKey, "초상화에서 " + value + "이(가) 나타났다. " + descValue, Language.Korean);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You gaze at a " + key + ". " + descKey, "너는 " + value + "을(를) 바라보았다. " + descValue, Language.Korean);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You glance at an " + key + ". " + descKey, "너는 " + value + "을(를) 힐끗 보았다. " + descValue, Language.Korean);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An " + key + " appears from within the portrait. " + descKey, "초상화에서 " + value + "이(가) 나타났다. " + descValue, Language.Korean);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You gaze at an " + key + ". " + descKey, "너는 " + value + "을(를) 바라보았다. " + descValue, Language.Korean);
                }
            }

            // ShowThenClear
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose wisely.", "현명하게 골라라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARRGH!!!", "크아아악!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]STRIKE![c:]", "[c:g1]공격![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]STRIKE![c:]", "[c:g2]공격![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Au Revoir", "잘 가거라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How reckless.", "무모하군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm.. I see..", "흠…… 그렇군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But you'll [c:g2]NEVER[c:] delete me, the Scrybe of Magicks!", "하지만 마력의 필경자인 나를 [c:g2]절대로[c:] 삭제하지 못할 것이다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GRRAHH!!", "크아아악!!", Language.Korean);
            Dictionary<GemType, string> gemTypesEn = new Dictionary<GemType, string>
            {
                { GemType.Orange, "오렌지색" },
                { GemType.Blue, "파란색" },
                { GemType.Green, "녹색" },
            };
            Dictionary<GemType, string> gemTypes = new Dictionary<GemType, string>
            {
                { GemType.Orange, "오렌지색" },
                { GemType.Blue, "파란색" },
                { GemType.Green, "녹색" },
            };
            foreach (var gemType in gemTypes.Keys)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have two " + HintsHandler.GetColorCodeForGem(gemType) + gemTypesEn[gemType] + "</color> gems to play that.", "이 카드를 낼 " + HintsHandler.GetColorCodeForGem(gemType) + gemTypes[gemType] + "</color> 보석 두 개가 없다.", Language.Korean);
                foreach (var value in Cards.Values)
                {
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll need two " + HintsHandler.GetColorCodeForGem(gemType) + gemTypesEn[gemType] + "</color> gems to play your " + value + ".", "네 " + value + "을(를) 내려면 " + HintsHandler.GetColorCodeForGem(gemType) + gemTypes[gemType] + "</color> 보석 두 개가 필요하다.", Language.Korean);
                    SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough " + HintsHandler.GetColorCodeForGem(gemType) + gemTypesEn[gemType] + "</color> gems on the board to play that " + value + ".", "보드에 " + HintsHandler.GetColorCodeForGem(gemType) + gemTypes[gemType] + "</color> 보석이 부족해 " + value + "을(를) 낼 수 없다.", Language.Korean);
                }
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need two " + HintsHandler.GetColorCodeForGem(gemType) + gemTypesEn[gemType] + "</color> gems on the board.", "보드에 " + HintsHandler.GetColorCodeForGem(gemType) + gemTypes[gemType] + "</color> 보석 두 개가 필요하다.", Language.Korean);
            }

            // ShowMessage
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "whats up", "무슨 일이야", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:g1]Goo Mage[c:] falls by your hands.. I expected more from him..", "내 [c:g1]점액 마법사[c:]가 네 손에 쓰러졌군…… 좀 더 기대했건만……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph.. My [c:g1]Goo Mage[c:] dissapoints me again..", "흥…… 내 [c:g1]점액 마법사[c:]가 또 나를 실망시키는군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yet again, my pathetic [c:g1]Goo Mage[c:] falls..", "내 한심한 [c:g1]점액 마법사[c:]가 또 쓰러졌군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]What..?[c:] [c:g2]Me,[c:] [c:g1]defeated..?[c:]", "[c:g1]뭐……?[c:] [c:g2]내가,[c:] [c:g1]졌다고……?[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Blargh..[c:] [c:g2]I've[c:] [c:g1]been[c:] [c:g2]taken[c:] [c:g1]out[c:] [c:g2]by[c:] [c:g1]you??[c:] ", "[c:g1]크윽……[c:] [c:g2]내가[c:] [c:g1]너한테[c:] [c:g2]당해서[c:] [c:g1]이렇게[c:] [c:g2]쓰러지고[c:] [c:g1]말았다고??[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Impossible..[c:] [c:g2]I've[c:] [c:g1]been[c:] [c:g2]defeated..[c:]", "[c:g1]말도 안 돼……[c:] [c:g2]내가[c:] [c:g1]패배하고[c:] [c:g2]말았어……[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahh.. I see you've defeated my [c:g2]Pike Mage[c:]..", "아…… 내 [c:g2]장창 마법사[c:]를 쓰러뜨렸군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:g2]Pike Mage[c:] falls.. Dissapointing.", "내 [c:g2]장창 마법사[c:]가 쓰러졌군…… 실망스럽다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll admit challenger.. You've gotten farther than most.", "인정하마, 도전자여…… 너는 대부분의 사람보다 멀리 왔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]A[c:] [c:g3]fantastic[c:] [c:g2]duel[c:] [c:g3]we[c:] [c:g2]had![c:]", "[c:g2]우리의[c:] [c:g3]결투는[c:] [c:g2]참으로[c:] [c:g3]멋진[c:] [c:g2]승부였군![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]'Twas[c:] [c:g3]an[c:] [c:g2]excellent[c:] [c:g3]battle.[c:]", "[c:g2]이번[c:] [c:g3]전투는[c:] [c:g2]정말[c:] [c:g3]훌륭했군.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]Great[c:] [c:g3]fighting,[c:] [c:g2]young[c:] [c:g3]mage.[c:]", "[c:g2]훌륭하게[c:] [c:g3]싸웠다,[c:] [c:g2]젊은[c:] [c:g3]마법사여.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well challenger.. Now that you have defeated the [c:g3]Lonely Mage[c:]. You may now face me.", "좋다, 도전자여…… [c:g3]외로운 마법사[c:]를 쓰러뜨렸으니 이제 나와 맞서도 좋다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've defeated all my students.. I will await your arrival.", "내 제자들을 모두 쓰러뜨렸군…… 네가 오기를 기다리겠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:g3]Lonely Mage[c:] falls.. this is unexpected.. But now, I await your arrival.", "내 [c:g3]외로운 마법사[c:]가 쓰러졌군…… 뜻밖이야…… 이제 네가 오기를 기다리겠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]An[c:] [c:g1]excellent[c:] [c:g3]fight![c:]", "[c:g3]정말[c:] [c:g1]훌륭한[c:] [c:g3]승부였어![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]Despite[c:] [c:g1]my[c:] [c:g3]deadliest[c:] [c:g1]books,[c:] [c:g3]you[c:] [c:g1]still[c:] [c:g3]won![c:]", "[c:g3]내가[c:] [c:g1]가진[c:] [c:g3]가장 치명적인[c:] [c:g1]책을 썼는데도,[c:] [c:g3]너는[c:] [c:g1]결국[c:] [c:g3]이겼군![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]You[c:] [c:g1]managed[c:] [c:g3]to[c:] [c:g1]overcome[c:] [c:g3]my[c:] [c:g1]deadliest[c:] [c:g3]tomes,[c:] [c:g1]impressive![c:]", "[c:g3]너는[c:] [c:g1]기어이[c:] [c:g3]내[c:] [c:g1]가장[c:] [c:g3]치명적인[c:] [c:g1]마도서들을[c:] [c:g3]극복했군.[c:] [c:g1]대단해![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]Whoops![c:] [c:g1]Looks[c:] [c:g3]you[c:] [c:g1]need[c:] [c:g3]to[c:] [c:g1]study[c:] [c:g3]up[c:] [c:g1]on[c:] [c:g3]mox.[c:]", "[c:g3]이런![c:] [c:g1]아무래도[c:] [c:g3]너는[c:] [c:g1]좀[c:] [c:g3]더[c:] [c:g1]열심히[c:] [c:g3]목스에[c:] [c:g1]대해[c:] [c:g3]공부해야겠네.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My Pike Mage bests another opponent...", "내 장창 마법사가 또 상대를 물리쳤군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dissapointing...", "실망스럽군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g1]Yet[c:] [c:g2]another[c:] [c:g1]soul[c:] [c:g2]I[c:] [c:g1]claim.[c:] [c:g2]Banish[c:] [c:g1]yourself[c:] [c:g2]to[c:] [c:g1]the[c:] [c:g2]depths,[c:] [c:g1]and[c:] [c:g2]do[c:] [c:g1]not[c:] [c:g2]return.[c:]", "[c:g1]또[c:] [c:g2]하나의[c:] [c:g1]영혼을[c:] [c:g2]내가[c:] [c:g1]차지했다.[c:] [c:g2]스스로[c:] [c:g1]깊은[c:] [c:g2]심연[c:] [c:g1]속으로[c:] [c:g2]꺼져라.[c:] [c:g1]그리고[c:] [c:g2]다시는[c:] [c:g1]돌아오지[c:] [c:g2]마라.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yet another student, hit off guard by my Lonely Mage..", "또 제자 하나가 내 외로운 마법사에게 허를 찔렸군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You got so far.....", "그렇게 멀리까지 왔건만……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak.", "약하군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g2]Farewell,[c:] [c:g3]young[c:] [c:g2]mage![c:] [c:g3]'Twas[c:] [c:g2]a[c:] [c:g3]fantastic[c:] [c:g2]duel.[c:]", "[c:g2]잘 가게,[c:] [c:g3]젊은[c:] [c:g2]마법사여![c:] [c:g3]참으로[c:] [c:g2]멋진[c:] [c:g3]결투[c:][c:g2]였네.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "~ Goo Dungeon ~", "~ 점액 던전 ~", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "~ Lava Dungeon ~", "~ 용암 지하감옥 ~", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "~ Void Dungeon ~", "~ 공허 지하감옥 ~", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "~ Tower of Magicks ~", "~ 마법의 탑 ~", Language.Korean);
            for (int currency = 0; currency <= 100; currency++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:g3]~ " + currency + " Crystals ~[c:]", "[c:g3]~ 수정 " + currency + "개 ~[c:]", Language.Korean);
            }

            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Mox", "빈 목스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your sidedeck's mox is completely random.", "보조 덱의 목스가 완전히 무작위가 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weaker Bleach", "약한 표백제", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bleaching Event can no longer remove negative sigils.", "표백 이벤트에서 부정적인 도장을 제거할 수 없게 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turn Wipeout", "턴 초과 피해", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When you ring the bell past turn 6 (12 on bosses) you take 1 damage.", "6턴이 지난 뒤에 종을 울리면 피해를 1 받는다. 보스전에서는 12턴이 지난 뒤부터 적용된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stronger Opponent", "더 강한 상대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your battle opponent starts with 5 extra health points.", "전투 상대가 체력을 5 더 가진 상태로 시작한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiny Spellbook", "작은 주문서", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your spellbook can only hold 4 spells instead of 8.", "주문서에 주문을 8개 대신 4개만 넣을 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Displeased Spirits", "불쾌한 영혼들", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The enchanted grounds will always be displeased.", "마력이 깃든 땅이 항상 불쾌해한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armored Shell", "장갑 껍질", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your opponent cant take more than 4 damage per turn.", "상대가 한 턴에 받는 피해가 4를 넘지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iron Maiden", "철의 처녀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every turn, each mox on your side of the board takes 1 damage.", "매 턴 당신 측 보드에 있는 목스가 각각 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magickal Paint", "마법 물감", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Queued cards will occasionally get additional sigils painted on them.", "대기열의 카드에 가끔 추가 도장이 그려진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fleeting Life", "덧없는 생명", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have 75 health, but it does not replenish inbetween battles.", "체력이 75가 되지만 전투 사이에 회복되지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intrusive Presence", "불청객", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An unwelcome prescence will follow you into card battles.", "반갑지 않은 존재가 카드 전투까지 따라온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Bosses", "마스터 보스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every bossfight is replaced with one of the Mox Masters.", "모든 보스전이 목스 마스터 중 한 명과의 전투로 바뀐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Dependant Starters", "보석에 의존하는 시작 덱", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards in your starting deck have the gem dependant sigil.", "시작 덱의 카드가 보석 의존증 도장을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnificus Challenge Level: {0}", "매그니피쿠스 도전 레벨: {0}", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnificus Challenge Points: {0}", "매그니피쿠스 도전 점수: {0}", Language.Korean);

        }
    }

    public class UndeadTempleINKCMMod
    {

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for UndeadTempleINKCM Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Banshee", "각성한 밴시", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pile of bones, paying for bones in exchange for strength.", "뼈를 지불하고 힘을 얻는 뼈 무더기.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Bone Heap", "각성한 뼈 무더기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Bonehound", "각성한 본하운드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even after being dead, it remains loyal.", "죽은 뒤에도 충성을 지킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Dead Hand", "각성한 죽은 손", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hand of death, but with life.", "생명이 깃든 죽음의 손.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Draugr", "각성한 드라우그르", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen ghouls, break and come out.", "얼어붙은 구울이 깨고 나온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened DrownedSoul", "각성한 익사한 영혼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The drowned soul wanders with resentment in the water.", "익사한 영혼이 원한을 품고 물속을 떠돈다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Family", "각성한 망자의 가족", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A family that died unexpectedly.", "뜻밖의 죽음을 맞은 가족.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frankenstein.", "프랑켄슈타인.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A ghost ship that produces a steady stream of skeletons.", "끊임없이 해골을 만들어 내는 유령선.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Ghost Ship", "각성한 유령선", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Frank & Stein", "각성한 프랭크 & 스타인", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Gravedigger", "각성한 도굴꾼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A diligent gravedigger, he constantly supplies bones.", "부지런한 도굴꾼이 끊임없이 뼈를 공급한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Knight, the assassin in hell.", "죽음의 기사, 지옥의 암살자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Knight", "각성한 기사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Horn", "각성한 뿔", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bonelord sheds its old horns, they take on a life of their own, to one day usurp their masters.", "뼈의 왕이 벗어 버린 낡은 뿔에 생명이 깃든다. 언젠가 주인의 자리를 빼앗기 위해.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mummy God", "미라의 신", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The King of Terror.", "공포의 왕.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Necromancer", "각성한 네크로맨서", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Born solely for revenge.", "오직 복수를 위해 태어났다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Revenant", "각성한 망령", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A formidable sarcophagus with terrifying creations sealed inside.", "무시무시한 창조물이 봉인된 가공할 석관.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Pile", "뼈 더미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Bone Pile", "각성한 뼈 더미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Tomb Robber", "각성한 도굴꾼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if he dies, he still robs tombs.", "죽어서도 무덤을 도굴한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A desperate man.", "절망에 빠진 남자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Zombie", "각성한 좀비", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Devouring Soul", "영혼을 먹는 망령", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A skeleton devouring the soul.", "영혼을 집어삼키는 해골.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Devouring Soul", "각성한 영혼을 먹는 망령", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Dead Eye", "각성한 죽은 자의 눈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Both Deadeye and Dead Hand are said to be body parts of the same, now dead, god.", "죽은 자의 눈과 죽은 손은 지금은 죽은 같은 신의 신체 일부라고 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ferry Crow", "영혼을 나르는 뼈 까마귀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Ferry Crow", "각성한 영혼을 나르는 뼈 까마귀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mournful cry of looking down upon the undead after death.", "죽은 뒤 언데드를 내려다보며 구슬프게 운다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grave", "묘비", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope no one will disturb it.", "아무도 방해하지 않기를.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headless Man", "머리 없는 남자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An incompetent headless person, as if searching for something he had lost.", "잃어버린 무언가를 찾는 듯한 무능한 머리 없는 남자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Kennel", "각성한 개집", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dog house, hopefully no one will mess with the things inside.", "개집. 아무도 안에 있는 것을 건드리지 않기를.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pharmacist", "약사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Pharmacist", "각성한 약사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dead pharmacist who poisons all creations that oppose him.", "자신에게 맞서는 모든 창조물에 독을 쓰는 죽은 약사.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleader", "망자의 지도자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A skeleton leader, once on stage, is surrounded by skeletons.", "등장하자마자 해골에 둘러싸이는 망자의 지도자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Skeleader", "각성한 망자의 지도자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Sniper", "해골 저격수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dead sniper.", "죽은 저격수.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Skeleton Sniper", "각성한 해골 저격수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Threaded Skeleton", "기만자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Some people are born puppets, while others still control others after death.", "누군가는 태어나면서부터 꼭두각시이고, 누군가는 죽어서도 남을 조종한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Threaded Skeleton", "각성한 기만자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Elk", "불사의 엘크", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The undead elk, a former husk of of what it once was.", "한때의 껍데기만 남은 불사의 엘크.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Elk Cub", "불사의 새끼 엘크", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even death carries vitality and desire.", "죽어서도 활력과 욕망을 품는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Moose", "불사의 큰사슴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rotting carcass of a long-departed imposing beast.", "오래전에 죽은 위풍당당한 야수의 썩어 가는 사체.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Undead Moose", "각성한 불사의 큰사슴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Predator", "약탈하는 망자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warriors who die in war will never bow down.", "전쟁에서 죽은 전사들은 결코 굴복하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Undead Predator", "각성한 약탈하는 망자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead RedHart", "불사의 붉은사슴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "its decaying mind retains the strength of sacrifice.", "썩어 가는 정신에 희생의 힘이 남아 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Undead RedHart", "각성한 불사의 붉은사슴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Snapper", "늑대거북의 잔해", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Undead Snapper", "각성한 늑대거북의 잔해", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The corpse of a stiff terrestrial creation.", "육지 창조물의 뻣뻣한 시체.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Dragon", "해골 마룡", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Dragon, its remaining skeletons still roar with the destructive fury of old.", "해골 마룡. 남은 뼈대는 옛 파괴의 분노를 담아 여전히 포효한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Skeleton Dragon", "각성한 해골 마룡", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Free Revenant", "자유로운 망령", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Free Revenant", "각성한 자유로운 망령", Language.Korean);


            // Ability / Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleader", "망자의 지도자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When placing [creature], skeleton cards will appear in nearby empty spaces. Skeleton has: 1 power, 1 health, Brittle.", "[creature] 카드를 배치하면 인접한 빈칸에 해골 카드가 나타난다. 해골은 공격력 1, 체력 1, 취약성 도장을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Original Undead Card", "원작 언데드 부족 카드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cards for the Undead Tribe are in the original game.(ACT2)", "원작 두 번째 막에 등장하는 언데드 부족 카드.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NonOriginal Undead Card", "비원작 언데드 부족 카드팩", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The expansion cards for the Undead Tribe are not in the original game.", "원작에 없는 언데드 부족 확장 카드.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cards for the Undead Tribe are in the ACT2 original game, It contains [count] cards.", "원작 두 번째 막에 등장하는 언데드 부족 카드. 카드 [count]장이 들어 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The expansion cards for the Undead Tribe are not in the original game, It contains [count] cards.", "원작에 없는 언데드 부족 확장 카드. 카드 [count]장이 들어 있다.", Language.Korean);

        }
    }

    public class WildernessLegendMod
    {

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for WildernessLegend Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amalgam Pup", "새끼 결합물", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When you grow up, you can see that it is terrible.", "자라면 얼마나 무서운지 알게 될 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chicken", "닭", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dud Egg", "부화하지 않는 알", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An egg that doesn't grow? Maybe you can help it.", "자라지 않는 알? 네가 도울 수 있을지도.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funny chiking", "재미있는 닭", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A very stinky chicken, but it has a sharp beak.", "아주 냄새가 고약하지만 부리가 날카로운 닭.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roc", "대붕", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky Chiking", "구린 닭", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every chicken has a dream.", "모든 병아리에게는 꿈이 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Dog", "짜증나는 개", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such an annoying dog, perhaps, is the author of a certain pixel game.", "이렇게 짜증나는 개는 어쩌면 어떤 픽셀 게임의 제작자일지도 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arctic Fox", "북극여우", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A solitary Vulpes lagopus with great strength.", "홀로 지내며 강한 힘을 지닌 북극여우.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Dog", "뼈 찾는 강아지", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Running and running, just to find its bones.", "오직 제 뼈를 찾으려고 달리고 또 달린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fox", "여우", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hyena", "하이에나", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone seeking bandits in the wilderness.", "황야에서 뼈를 찾는 도적.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Loky", "늑대왕 로키", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The king of the whole pack of wolves, very, very powerful.", "늑대 무리 전체를 다스리는 왕. 아주, 아주 강하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pastoral Dog", "중국 토종개", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loyal Chinese pastoral dogs, they guard and protect their owners' houses.", "주인의 집을 지키고 보호하는 충직한 중국 토종개.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spotted Hyena", "점박이하이에나", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spotted hyenas searching for bones, they grow stronger with their thirst for blood.", "뼈를 찾는 점박이하이에나. 피를 갈망할수록 강해진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lion", "사자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strong lion with a fairly strong attack.", "상당한 공격력을 지닌 건장한 사자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lioness", "암사자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lioness guarding the lion herd are always on guard against external invasions.", "무리를 지키는 암사자는 외부의 침입을 늘 경계한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lynx", "스라소니", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The solitary Lynx attacks with its sharp claws and teeth.", "홀로 다니는 스라소니가 날카로운 발톱과 이빨로 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puma", "퓨마", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Puma, the leader among feline animals.", "고양잇과 동물 중에서도 손꼽히는 강인한 퓨마.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puma Cub", "새끼 퓨마", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The immature Puma cub. It will grow into a Puma after a turn.", "아직 어린 새끼 퓨마. 한 턴 뒤에는 퓨마로 자란다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thunder Tiger", "번개 호랑이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They came with thunder and then suddenly left.", "천둥과 함께 왔다가 갑자기 떠난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Axolotl", "우파루파", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cute little guy has a very special tail.", "이 귀여운 꼬마에게는 아주 특별한 꼬리가 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Axolotl Tail", "우파루파 꼬리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carp", "잉어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The fish in the Chinese totem is said to have unfathomable powers.", "중국 토템에 등장하는 물고기. 헤아릴 수 없는 힘을 지녔다고 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coral Polyp", "산호 폴립", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They coexist with the terrain.", "지형과 공생한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Globefish", "복어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any creature that dreams of harming it will regret it.", "해치려는 생각을 품은 피조물은 모두 후회하게 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shark Egg", "상어 알", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've never seen a shark egg look like this before.", "이렇게 생긴 상어 알은 처음 본다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squidge", "오징어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What kind of creature will the little one grow into?", "이 작은 녀석은 어떤 피조물로 자랄까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor little ones......", "불쌍한 작은 녀석들……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Joannes", "요하네스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar creature that only exists in nightmares.", "악몽 속에만 존재하는 기묘한 피조물.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Joannes", "요하네스 신", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miemie Method", "미에미에 메서드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A little cute who can write code.", "코드를 짤 줄 아는 귀여운 꼬마.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Potato Elk", "감자사슴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The potatoes have sprouted.", "감자에서 싹이 났다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Potato Elk Cub", "새끼 감자사슴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A deer with potatoes on its antlers, it seems that the potato is the owner.", "뿔에 감자가 달린 사슴. 아무래도 감자가 주인인 듯하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wapiti", "와피티사슴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strong and vital deer.", "건장하고 활력 넘치는 사슴.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cicada", "매미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They gather in groups, calling on friends, which is annoying.", "무리 지어 모여 친구들을 불러 대니 성가시다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dragonfly", "잠자리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dragonflies that point to where to hit.", "겨누는 곳을 정확히 때리는 잠자리.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Centipede", "거대 지네", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The giant centipedes hidden deep underground use their sharp fangs to defend their territory.", "땅속 깊이 숨어 사는 거대 지네가 날카로운 송곳니로 영역을 지킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leafcutter ant", "잎꾼개미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They have sharp claws.", "날카로운 발톱을 지녔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Locust swarms", "메뚜기 떼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A large number of locusts swept in, and it was a disaster for the peasants.", "수많은 메뚜기가 몰려오면 농민에게는 재앙이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shield bug", "노린재", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disgusting stink bugs, no one wants to approach them.", "아무도 가까이 가고 싶어 하지 않는 역겨운 노린재.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soldier Ant", "병정개미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soldier Ant that point to where to hit.", "겨누는 곳을 정확히 때리는 병정개미.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acorn", "도토리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armadillo", "아르마딜로", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The 'Shield Dwarves' of the wilderness have both offense and defense when curled up.", "황야의 '방패 난쟁이'. 몸을 웅크리면 공격과 방어를 모두 갖춘다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CowBoy", "카우보이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The skilled marksman cowboy who hits every shot.", "백발백중의 명사수 카우보이.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elephant", "코끼리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The largest creation on land, it has tenacious vitality and defense.", "육지에서 가장 큰 창조물. 끈질긴 생명력과 방어력을 지녔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzly Cub", "새끼 회색곰", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The little bear has not yet grown up, but it is already prepared to face the darkness.", "아직 다 자라지 않은 아기 곰이지만 어둠과 맞설 준비는 되어 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Honey badger", "벌꿀오소리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vengeful honey badgers never feel afraid.", "복수심 강한 벌꿀오소리는 두려움을 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meerkat", "미어캣", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The watchful Meerkat, it attacks swiftly upon detecting a threat.", "경계심 강한 미어캣. 위협을 발견하면 재빨리 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mongoose", "몽구스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The incorruptable Mongoose is resistent to most toxins.", "꺾이지 않는 몽구스. 대부분의 독소에 저항력이 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stunted Grizzly", "발육부진 회색곰", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a poor, scarred beast- what must have befallen it?", "온몸이 상처투성이인 불쌍한 야수…… 대체 무슨 일을 겪었을까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Uri", "작은 털뭉치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abandoned children learn to be independent outside.", "버려진 아이는 바깥에서 자립하는 법을 배운다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Uryli", "야인", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wild man who has learned to be independent.", "자립하는 법을 배운 야인.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chipmunk", "다람쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small striped rodent of the forest, carrying an acorn with it as a meal.", "숲에 사는 작은 줄무늬 설치류. 먹을 도토리를 지니고 다닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pushing Mouse", "밀쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A huge southern mouse.", "남쪽의 거대한 쥐.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rat Cub", "새끼 쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A weak rat can grow into a noble rat king.", "약한 쥐도 고귀한 쥐의 왕으로 자랄 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buff Frog", "돌연변이 황소개구리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mutated frog that has gained power.", "힘을 얻은 돌연변이 개구리.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Frog", "돌연변이 황소개구리 신", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creeper", "크리퍼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A terrifying creature from the world of Minecraft.", "마인크래프트 세계에서 온 무시무시한 피조물.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crocodile", "악어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An animal with a strong biting force.", "무는 힘이 강한 동물.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rattler egg", "방울뱀 알", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A snake egg that is about to hatch, although it is very fragile.", "아주 약하지만 곧 부화할 뱀의 알.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sea Turtle", "바다거북", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vibrant sea turtles will not die even after being sacrificed.", "생명력이 강한 바다거북은 희생되어도 죽지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thorny Devil", "가시도마뱀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This guy's characteristics are just like its name.", "이 녀석의 특징은 이름 그대로다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thorny Devil Tail", "가시도마뱀 꼬리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Free Rattler egg", "무료 방울뱀 알", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amalgam Egg", "결합물 알", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Walking Stone", "걷는 돌", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stone that has traveled over mountains and rivers.", "산을 넘고 강을 건너 여행한 돌.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stone Deer", "돌사슴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stone deer statue carved by skilled craftsmen.", "뛰어난 장인이 조각한 돌사슴.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stone Wolf", "돌늑대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stone wolf statue carved by skilled craftsmen.", "뛰어난 장인이 조각한 돌늑대.", Language.Korean);

            // Other
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wilderness Legend", "황야의 전설", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add some simple cards based on the original imprint.", "기존 도장을 바탕으로 간단한 카드 몇 장을 추가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acorns", "도토리 찾기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When placing [creature], draw an acorn.", "[creature] 카드를 배치하면 도토리 카드 한 장을 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cutting Wings", "날개 절단자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying cards struck by [creature] will take 1 damage each time it declares an attack, and renders their wings useless.", "[creature] 카드에 맞은 비행 카드는 즉시 비행 능력을 잃고 이후 그 카드 자신이 공격을 선언할 때마다 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swarm", "매미의 여름", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "when [creature] is placed, the remaining slots on the owner's side are filled with cicadas", "[creature] 카드를 배치하면 주인 측의 남은 슬롯이 매미로 채워진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrain Creator", "지형 생성자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When placing [creature] on the field, randomly draw a terrain card.", "[creature] 카드를 보드에 배치하면 무작위 지형 카드 한 장을 뽑는다.", Language.Korean);

            //WLD-DLC
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Azure Dragon", "청룡", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The head of the four divine beasts, it has absolute suppressive power.", "네 신수의 우두머리. 절대적인 압도력을 지녔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chinese Loong", "중국 용", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Chinese Loong in myths and legends is the master of all things.", "신화와 전설 속 중국 용. 만물의 지배자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God long", "강림한 신룡", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Andrealphus", "안드레알푸스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sixty-fifth demon god of King Solomon.", "솔로몬 왕의 예순다섯 번째 마신.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Ostrich", "각성한 타조", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black-tailed Gull", "괭이갈매기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The black tailed gull at the dock will entrust its soul to the next destined person.", "부둣가의 괭이갈매기는 다음 운명의 상대에게 영혼을 맡긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black tailed gulls at the dock", "부둣가의 괭이갈매기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Egg", "불사조 알", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After hatching, there is eternity.", "부화한 뒤에는 영원이 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eagle", "독수리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A powerful eagle overlooking the underground.", "아래의 대지를 굽어보는 강력한 독수리.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Falcon", "매", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eager peregrine falcons, they attack as soon as they are laid down.", "성급한 매는 배치되자마자 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hot Chiking", "매운 닭", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The chicken that is about to become a god.", "곧 신이 될 닭.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ling Bird", "영우", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A soaring divine bird will bless a friend to inherit its attributes after death.", "하늘을 나는 신조는 아군을 축복하여 자신이 죽은 뒤 능력치를 물려준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Night Owl", "밤올빼미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They become stronger when faced with strength.", "강한 힘과 마주하면 스스로도 강해진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ostrich", "타조", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ostrich running around, its behavior is unpredictable.", "종잡을 수 없이 이리저리 뛰어다니는 타조.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pelican", "펠리컨", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The insatiable pelican swallowed the entire creation without digesting it.", "탐욕스러운 펠리컨은 피조물을 통째로 삼키고도 소화하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pigeon", "비둘기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The dove symbolizes peace, and its harm depends on the birds on the field.", "비둘기는 평화를 상징한다. 그 피해량은 보드의 새들에 달려 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rosefinch", "주작", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of the four great mythical beasts in Chinese mythology, constantly burning itself.", "중국 신화의 네 신수 중 하나. 끊임없이 자신을 불태운다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire God Rosefinch", "화신 주작", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Secular Bird", "불사조", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Secular Bird", "불사의 신조", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Super Chiking", "슈퍼 닭", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The chicken that became a god.", "신이 된 닭.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Chiking", "신의 닭", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Hawk", "부서진 매", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These broken cards remind me of my past life, even though they are far weaker than regular cards.", "이 부서진 카드들은 평범한 카드보다 훨씬 약하지만 내 전생을 떠올리게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Raven", "부서진 큰까마귀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Grizzly", "부서진 회색곰", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Grizzly Cub", "부서진 새끼 회색곰", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Hunter", "부서진 사냥꾼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Stoat", "부서진 담비", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Wolf", "부서진 늑대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Wolf Cub", "부서진 새끼 늑대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Elk", "부서진 무스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Adder", "부서진 살무사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Barghest", "바게스트", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Barghest from hell love to see blood.", "지옥에서 온 바게스트는 피 보기를 좋아한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hell Barghest", "지옥의 바게스트", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Furry Man", "털북숭이 남자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why is this guy furry?", "이 녀석은 왜 털북숭이일까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ikungagaga", "역천", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An excellent dog with eternal strengthening and leadership.", "영원한 강화와 지도력을 갖춘 뛰어난 개.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ni Tian God Dog", "역천의 신견", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lone Wolf", "고독한 늑대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wolf who is out of the pack, but loneliness will give him strength.", "무리를 떠난 늑대. 고독이 힘을 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Naughty dog", "장난꾸러기 개", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mischievous little dog, if there is no creation on the other side, he will run to the other side.", "장난꾸러기 강아지. 맞은편에 피조물이 없으면 그쪽으로 달려간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabid Dog", "미친개", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angry dogs, whoever dares to provoke him will be doubly rewarded.", "성난 개. 건드리는 자에게는 두 배로 갚아 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Werewolf", "늑대인간", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zuo Dog", "대좌견", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bones and blood are both essential for it.", "뼈와 피 모두 필수다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jun Zuo Dog", "준좌견", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheetah", "치타", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Agile cheetahs will attack immediately upon their appearance.", "민첩한 치타는 나타나자마자 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hua Miao", "화먀오", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Dark One who masters the full challenge proficiently, everything is under his control.", "모든 도전에 통달한 수수께끼의 검은 고양이. 모든 것이 그 손안에 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leopard", "표범", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A ferocious Leopard with speed and damage.", "빠르고 피해량도 높은 사나운 표범.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smilodon", "스밀로돈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smilodon, a beast of prehistoric origin.", "스밀로돈. 선사 시대에 기원을 둔 야수.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smilodon Cub", "새끼 스밀로돈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak saber toothed tiger cubs, they help their mother collect bones.", "약한 새끼 스밀로돈이 어미의 뼈 수집을 돕는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "White Tiger", "백호", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of the four divine beasts, it has the most precious blood.", "네 신수 중 하나. 가장 귀한 피를 지녔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yin Tiger", "인호", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strong tiger that is good at hunting from behind.", "뒤에서 사냥하는 데 능한 강인한 호랑이.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Yin Tiger", "각성한 인호", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ziqi Cat", "쯔치 고양이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cat with strong auxiliary abilities is the overlord of cats.", "강력한 보조 능력을 지닌 고양이. 고양이들의 지배자다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ziqi God Cat", "쯔치 신묘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Papyrus", "파피루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A little angel from the underworld.", "지하 세계에서 온 작은 천사.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sans", "샌즈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A lazy bone and its hellish joke.", "게으른 뼈다귀와 지옥 같은 농담.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doom Trepang", "파멸의 해삼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An exploding Doom Trepang has always been devastating.", "파멸의 해삼이 일으키는 폭발은 언제나 파괴적이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Electric Eel", "전기뱀장어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Electric eels can cause damage to creations that attack their location.", "전기뱀장어는 자신이 있는 칸을 공격하는 피조물에게 피해를 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Humpback", "혹등고래", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those who possess absolute power in water.", "물속에서 절대적인 힘을 지닌 존재.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paper Boat", "종이배", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A paper boat full of bones is enough to make all animals salivate.", "뼈가 가득 실린 종이배는 모든 동물의 군침을 돌게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Biker", "바이커", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sailfish", "돛새치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sailfish that can't wait will attack as soon as they get on the field.", "성급한 돛새치는 보드에 나오자마자 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunhuang deer", "둔황 신령 사슴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunhuang deer from the East.", "동방에서 온 둔황 신령 사슴.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Jackalop with unlimited appreciation is a destroyer of ecology.", "끝없이 증식하는 재카로프는 생태계의 파괴자다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ovis Ammon", "아르갈리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The earth shaking ram kills its creations in exchange for power.", "대지를 흔드는 아르갈리. 적을 쓰러뜨리며 힘을 과시한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ovis Aries", "양", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak sheep attract other predators to hunt.", "약한 양은 다른 포식자들을 사냥하러 오게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhinoceros", "코뿔소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They carry thick skin, which is not easily damaged by ordinary creations.", "가죽이 두꺼워 평범한 피조물은 쉽게 해치지 못한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tibetan Antelope", "티베트영양", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The strong Tibetan antelope is a dancer on the plateau.", "강인한 티베트영양은 고원의 무용수다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Antelope", "티베트영양 신", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wildebeest", "누", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herd wildebeest, they unite to resist predators.", "무리 지은 누가 힘을 합쳐 포식자에 맞선다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant King", "개미 왕", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ant king who commands the army of ants.", "개미 군대를 지휘하는 개미 왕.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boss Z", "정 사장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This guy is greedy but selfless.", "이 녀석은 탐욕스럽지만 이타적이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Boss Z", "정 큰사장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Butterfly", "나비", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Butterflies that love flowers, they fly everywhere.", "꽃을 좋아하는 나비가 사방으로 날아다닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rockivores", "원석충", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This insect can feed on terrain.", "이 곤충은 지형을 먹을 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trilobite", "삼엽충", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ancient trilobites secreted acid.", "산을 분비하는 고대 삼엽충.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gluttonous Stoat", "폭식하는 담비", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep eating and eating.", "먹고 또 먹어라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hao Maomao", "하오마오마오", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Agile monkeys are good at imitating.", "민첩한 원숭이는 흉내 내기에 능하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hao Jiji", "하오지지", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Isaac", "아이작", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tragedy and suffering experienced in another world.", "다른 세계에서 겪은 비극과 고난.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kylin", "기린", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kylin steps on auspicious clouds, which are difficult to dispel in the human world.", "기린이 상서로운 구름을 밟으면 세상의 온갖 고난이 사라진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mammoths", "매머드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A terrifying artifact from ancient times.", "태고에서 온 무시무시한 존재.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Man with Big Life", "작은 사람 큰 인생", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As a small person, having a big life.", "작은 사람으로서 큰 인생을 살아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mini Moon", "작은 달", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh! How did such a tiny moon come about?", "오! 이렇게 작은 달은 어떻게 생긴 걸까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Moon", "신의 달", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lunar debris", "달의 파편", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Panda", "판다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "China's nationally protected animal, with rare blood, as well as its lazy nature.", "중국의 국가 보호 동물. 희귀한 피와 게으른 천성을 지녔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Picky Bear", "편식하는 곰", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A picky eating grizzly bear.", "먹을 것을 가리는 회색곰.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chinchilla", "친칠라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cute Chinchilla, attacking its creatures will make it feel guilty.", "귀여운 친칠라. 이 녀석을 공격한 피조물은 죄책감을 느낀다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hamster", "햄스터", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cute hamster invites friends.", "귀여운 햄스터가 친구들을 초대한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muscle Mouse", "근육쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have difficulties, it will come to help you.", "어려움에 처하면 도우러 온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rat Queen", "쥐의 여왕", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They gather in groups and obey the commands of the Rat Queen.", "무리 지어 모여 쥐의 여왕의 명령에 따른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scientist Rat", "과학자 쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This scientist discovered a method to search for tribes.", "이 과학자는 부족을 찾는 방법을 발견했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snake Eater", "뱀 먹는 쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even prey can become hunters.", "사냥감도 사냥꾼이 될 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Tortoise", "현무", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of the four divine beasts with the strongest defense.", "네 신수 중 하나로 가장 강력한 방어력을 지녔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Tortoise", "신 현무", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alligator", "앨리게이터", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The more eat, the stronger it becomes.", "먹을수록 강해진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hydrophis", "바다뱀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A deadly venomous snake in the sea.", "바다에 사는 치명적인 독사.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snake Eye", "뱀눈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Luck is also part of strength.", "운도 실력의 일부다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jackal", "자칼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as it is in the wolf pack, it has great power.", "늑대 무리 안에 있는 한 강한 힘을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avoider", "회피자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Survival or death, that's the question.", "살 것인가, 죽을 것인가. 그것이 문제다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Avoider", "각성한 회피자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Lotus", "피의 연꽃", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A unique blood lotus about to bloom.", "곧 피어날 독특한 피의 연꽃.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Make a song for you", "너에게 바치는 노래", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fishing Cat", "고기잡이삵", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All diving creatures cannot escape its eyes.", "잠수하는 피조물은 모두 그 눈을 피할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cloud Leopard", "구름표범", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They are doctors among feline animals.", "고양잇과 동물들의 의사다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Panther", "흑표범", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The greedy black panther will perish without bones.", "탐욕스러운 흑표범은 뼈가 없으면 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bandit Parrot", "무법자 앵무새", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The appearance of a skeleton parrot before its death They burned, killed, and looted everywhere together with pirates.", "해골 앵무새의 생전 모습. 해적과 함께 곳곳에서 방화와 살인, 약탈을 일삼았다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Capybara", "카피바라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The docile little ones don't like to fight.", "온순한 꼬마들은 싸움을 좋아하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elaphe Taeniura", "줄무늬뱀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The black browed snake, who loves squirrels, can unleash its true power by catering to its preferences.", "다람쥐를 좋아하는 줄무늬뱀. 취향에 맞춰 주면 진정한 힘을 발휘한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juvenile Lammergeier", "새끼 수염수리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ambitious Juvenile Lammergeier store food and have a promising future ahead.", "야심 찬 새끼 수염수리. 먹이를 비축하며 앞날이 기대된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mutated Hamster", "돌연변이 햄스터", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moon Cat", "달고양이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The moon cat with mysterious words on its forehead.", "이마에 신비로운 글자가 쓰인 달고양이.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wolf Magpie", "늑대까치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The physique of wolves and the posture of magpies combine bravery and agility.", "늑대의 체격과 까치의 자태. 용맹함과 민첩함을 겸비했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Grizzly", "해골 회색곰", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For some reason, even death cannot stop its thirst for food and blood.", "어째서인지 죽음조차 먹이와 피를 향한 갈망을 막지 못한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Skeleton Grizzly", "각성한 해골 회색곰", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will there still be people who sympathize with the nameless dead?", "이름 없는 망자를 동정해 줄 사람이 아직 있을까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nameless Dead", "이름 없는 망자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Name", "이름", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slow Cooling Bone", "천천히 식는 뼈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Slow Cooling Bone", "각성한 천천히 식는 뼈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who can comprehend the true meaning of death? Even Grimora cannot comprehend it.", "누가 죽음의 참뜻을 이해할 수 있을까? 그리모라조차 이해하지 못한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Anaconda", "그린아나콘다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The parthenogenetic Green Anaconda can swallow humans.", "단위생식을 하는 그린아나콘다는 사람도 삼킬 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Rider", "고스트 라이더", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Ghost Rider who emphasizes killing justice will burn away the sins of all things with anger.", "살인으로 정의를 관철하는 고스트 라이더. 분노로 만물의 죄악을 불태운다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Ghost Rider", "각성한 고스트 라이더", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Fire", "유명화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Ghost Fire", "각성한 유명화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Black Mouse", "큰 검은 쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The big black rats, who are home everywhere, are insatiable and helpless like weeds on the wall.", "어디서나 살아가는 큰 검은 쥐. 탐욕스럽고 담벼락의 잡초처럼 의지할 데가 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camel", "낙타", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camels who work tirelessly are frequent visitors on the Silk Road.", "묵묵히 일하는 낙타는 실크로드의 단골손님이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thin Camel", "앙상한 낙타", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A thin and shapeless camel, I don't know who could draw such a picture.", "형체를 알아보기 힘들 만큼 마른 낙타. 누가 이런 그림을 그렸을까.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Thin Camel", "각성한 앙상한 낙타", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Board Tentacle", "보드 촉수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't remember taking a photo of it.", "이 사진을 찍은 기억은 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Golden Tentacle", "황금 촉수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They traded death for their hands.", "죽음을 대가로 패를 얻었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Item Tentacle", "아이템 촉수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They become excited when they see props.", "아이템을 보면 흥분한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scaleten Tentacle", "저울 촉수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Viscera Tentacle", "내장 촉수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strengthen Eagle", "강화된 독수리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Mechanical Dog", "폭탄 기계 개", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is sacrificing one's life for something insignificant the purpose of creating machinery?", "하찮은 일을 위해 목숨을 희생하는 것이 기계를 만드는 목적인가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Mechanical Dog 2.0", "폭탄 기계 개 2.0", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salt Fish", "소금에 절인 생선", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's just a dead fish...", "그저 죽은 물고기일 뿐……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turning over salt fish", "뒤집힌 소금에 절인 생선", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice scaled Snow Snake", "얼음비늘 현사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice cast scales, cold snake hearts.", "얼음으로 빚은 비늘, 차디찬 뱀의 심장.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Joyful Wolf", "기쁨의 늑대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They always have a strange smile on their faces.", "얼굴에 늘 기묘한 웃음을 띠고 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frankenstein's Sheep", "프랑켄양", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Highly aggressive scientific monsters, as if their eyes are only focused on killing.", "눈에는 오직 살육만 보이는 듯한 극도로 공격적인 과학 괴물.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smoke Knight", "안개 속 암흑기사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ever-changing Smoke Knight, perhaps the old woman is right, death is not the end.", "끊임없이 변하는 안개 속 암흑기사. 어쩌면 그 노파의 말처럼 죽음은 끝이 아닐지도 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakened Smoke Knight", "각성한 안개 속 암흑기사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maneki-neko", "마네키네코", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pirate Crab", "해적 게", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excellent pirates never doubt their own value.", "뛰어난 해적은 자신의 가치를 의심하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Echo of MaoDie", "마오디에의 잔상", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Someone found an inexplicable sentence in its epitaph: \"Hakimi's green beans from north to south\".", "누군가 묘비명에서 영문 모를 문장을 발견했다. \"하키미 남북 녹두.\"", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Killer Beehive", "살인자 벌집", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's endless, endless.", "끝도 없이, 끝도 없이.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Wolf", "피의 늑대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This wolf is crazily craving for blood, to the point of endangering its life.", "이 늑대는 목숨이 위태로워질 만큼 미친 듯이 피를 갈망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fallen Hugag", "쓰러진 휴개그", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hugag", "휴개그", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The top-heavy guy may not be the same when it is reversed.", "머리가 무거운 이 녀석도 뒤집으면 완전히 달라질지 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "World Turtle", "세계 거북", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Three mud turtles support the earth.", "진흙거북 세 마리가 대지를 떠받친다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is it just an ordinary squirrel?", "그냥 평범한 다람쥐일까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shiba Inu", "시바견", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cerberus", "케르베로스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guardian of the Underworld—no living soul may enter, no dead soul may leave.", "저승의 수호자. 산 자는 들어갈 수 없고 죽은 자는 나갈 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pi Xiu", "비휴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If fierce beasts lie ahead, carry the Pi Xiu as your guardians.", "앞에 사나운 짐승이 있다면 비휴를 수호자로 데려가라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sea Urchin", "성게", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you accidentally stumble upon this, you might regret it.", "실수로 건드렸다가는 후회할지도 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goose and Duck", "거위와 오리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They turn a deaf ear to others' words.Talking past each other—sometimes useless conflicts are just senseless.", "남의 말에는 귀를 닫고 서로 엉뚱한 소리만 한다. 때로는 쓸데없는 다툼이 그저 무의미할 뿐이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hellcat", "지옥 고양이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cat of blazing hell, it walks upon fire;All foes who gaze upon it shall be reduced to scorched earth.", "불타는 지옥의 고양이가 불길을 밟고 걷는다. 그를 바라보는 적은 모두 잿더미가 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cactus cat", "선인장 고양이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such indescribable creations are destined to be inaccessible to humans.", "이 형언할 수 없는 창조물은 인간과 가까워질 수 없는 운명이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder Goose and Elder Duck", "장로 거위와 장로 오리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purgatory Cat", "연옥 고양이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bamboo Hat Panda", "삿갓 판다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignoring the affairs of the world, I only revel in the fragrance of bamboo; beneath the bamboo hat lies the panda's lazy jianghu.", "세상사에는 무심하고 대나무 향에만 취한다. 삿갓 아래에는 판다의 느긋한 강호가 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chang Qi Jin Xi", "창치진시", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ShadoWood Wolf", "그늘숲 늑대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadows creep through the woods; the wind is its stride.", "숲속을 기어가는 그림자. 바람 소리가 곧 그 발걸음이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhinoceros Beetle", "장수풍뎅이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clad in iron armor, armed with twin prongs,a fearless warrior of the woods.", "철갑을 두르고 두 갈래 뿔로 무장한 숲속의 용감한 전사.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant Egg", "개미 알", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An abandoned ant egg, once hatched, can return to its home.", "버려진 개미 알. 부화하면 집으로 돌아갈 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feathered Serpent", "흰깃 구렁이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This snake does not belong to the ordinary world; its illusory nature and existence are indistinguishable.", "이 뱀은 평범한 세계에 속하지 않는다. 환영인지 실재하는지 구분할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quetzalcoatl", "케찰코아틀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twin Varanoids", "쌍둥이 왕도마뱀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A matched pair of savage giant lizards, hunting together and bringing double the terror.", "짝을 이룬 사나운 거대 도마뱀. 함께 사냥하며 두 배의 공포를 안긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aether Serpent", "등사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Celestial serpent that soars through the clouds, untethered by earthly bounds.", "구름 사이를 날아다니는 천상의 영물 뱀. 속세에 얽매이지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VeggieMew", "채소냥냥", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whose pet is this that ran out?", "누구네 반려동물이 뛰쳐나온 걸까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snapper Egg", "늑대거북 알", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snapping turtle eggs found in the swamp may attract little attention.", "늪에서 발견한 늑대거북 알. 별다른 관심을 끌지 못할지도 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hedgehog", "고슴도치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid hedgehogs steal bones yet dare not attack head-on.", "겁 많은 고슴도치는 뼈를 훔쳐 먹지만 정면으로 공격할 엄두는 내지 못한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Echidna", "가시두더지", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fearless echidnas sacrifice themselves to stab hostile creatures.", "겁 없는 가시두더지는 자신을 희생해 적 피조물을 찌른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strange Tadpole", "기이한 올챙이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tadpole seems to have grown legs.", "이 올챙이는 다리가 난 것 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hippo", "하마", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong hippos keep hunting and strengthening themselves.", "강인한 하마는 끊임없이 사냥하며 자신을 강화한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rusty Bear", "녹슨 곰", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rusty Face", "녹슨 얼굴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is this a living or a dead thing? No one knows why rust would grow on that face.", "산 것인가, 죽은 것인가? 왜 그 얼굴에 녹이 스는지 아무도 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flerken", "플러큰", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beneath its fluffy rounded hide lies an enormous maw capable of devouring anything.", "둥글고 복슬복슬한 가죽 아래에는 무엇이든 삼킬 거대한 입이 숨어 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WayneSA", "웨인SA", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mosquito", "모기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying mosquitoes, disgusting bloodsuckers in summer.", "성가신 모기. 여름의 역겨운 흡혈귀.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acheron Viper", "피안의 뱀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It revives from the other shore, seeking its origin amid the hatred of the deceased.", "피안에서 되살아나 망자의 원한 속에서 뿌리를 찾는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ferry of Souls Snake", "영혼을 건네는 뱀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "old SA", "늙은 SA", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lycoris", "석산", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Razor Clam", "맛조개", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elongated shellfish dwelling in silt, its two thin shells forming its iconic razor shape.", "진흙과 모래에 사는 길쭉한 조개. 얇은 두 껍데기가 특유의 면도날 모양을 이룬다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Razor Clman", "맛조개 형님", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frenzied Rat", "광란의 쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant-Toothed Beaver", "거대 송곳니 비버", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A colossal beaver creature armed with massive tusks.", "거대한 엄니로 무장한 초대형 비버 피조물.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kangaroo Rat", "캥거루쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Equipped with large cheek pouches, the kangaroo rat is a master storer of desert seeds and barely needs to drink liquid water its whole life.", "큰 볼주머니를 지닌 캥거루쥐는 사막의 씨앗 저장 전문가다. 평생 액체 상태의 물을 거의 마시지 않아도 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plague Rat", "역병 쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rodent creature stricken with plague, festering blight spreads all around its body.", "역병에 걸린 설치류 피조물. 온몸에서 곪아 가는 역병을 퍼뜨린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rat Corpse", "쥐 시체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharp Dam", "날카로운 댐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mangrove", "맹그로브", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mangrove creature rooted in estuary mud, tangled roots binding silt and tides.", "하구 진흙에 뿌리내린 맹그로브. 얽힌 뿌리가 진흙과 조수를 붙든다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant ocean seabird, gliding endlessly on winds across vast seas.", "드넓은 바다를 건너는 거대한 원양 바닷새. 바람을 타고 끝없이 활공한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Electro Tiger", "전자기 호랑이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arcs leap across its fur, and thunder follows its charge.", "털 사이로 전기가 튀고 돌진 뒤로 천둥이 따른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It lurks in the corners of liminal spaces, silently staring at every intruder.", "경계 공간의 구석에 숨어 모든 침입자를 말없이 응시한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its arrival is regarded as an auspice, bringing fortune to its owner.", "그 등장은 길조로 여겨지며 주인에게 행운을 가져다준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Liminal Cat", "경계 공간 고양이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hallucigenia", "할루키게니아", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mucus", "점액", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Auspice Rat", "상서로운 쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buffalo", "물소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A ferocious giant of the savanna. Its helmet‑like massive horns strike fear into predators.", "초원의 사나운 거수. 투구 같은 거대한 뿔은 포식자마저 두렵게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fu Zhu", "부저", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A spirit‑deer of pure, mild mien, yet it bears the ill omen of incoming floods.", "맑고 온화한 모습의 영물 사슴. 하지만 홍수가 닥칠 흉조를 짊어졌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great Bustard", "느시", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A giant bird pacing the grasslands. Its great bulk is a heavy fetter for flight.", "초원을 거니는 거대한 새. 육중한 몸은 비상을 가로막는 무거운 족쇄다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All squirrels of the wood bow to its crown, willing to be offered.", "숲의 모든 다람쥐가 그 왕관 앞에 고개를 숙이고 기꺼이 제물이 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sun Wu Kong", "손오공", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The monkey king who once shook heaven, holds ruin even in stillness.", "한때 하늘을 뒤흔든 원숭이 왕. 고요히 있어도 파멸의 힘을 품는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great Sage Equal to Heaven", "제천대성", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The strong shall reign, and that throne is mine; Among heroes, only I dare take the lead.", "강자가 군림한다면 그 왕좌는 내 것이다. 영웅 중 앞장서기를 다투는 자는 나뿐이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Where my staff strikes, neither gods nor buddhas may stand.", "내 봉이 닿는 곳은 신도 부처도 막지 못한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beyond the Three Realms, unbound by the Five Elements.", "삼계를 벗어나 오행에도 얽매이지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strike the Southern Heaven, shatter the Firmament. If I return not, then return not I.", "남천을 치고 천궁을 부순다. 돌아오지 못한다면, 돌아오지 않을 뿐.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fiery eyes pierce illusion; one staff shapes all fate.", "불꽃의 눈이 허상을 꿰뚫고 봉 한 번에 천하의 운명이 정해진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiny in form, yet dares snarl at giants.", "몸은 작아도 거인에게 으르렁댄다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Northern Raccoon Dog", "북방너구리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Masked in dark fur, it haunts woods, dwelling in one mound.", "검은 털 가면을 쓰고 숲을 떠돌며 흙 언덕 하나에 산다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tao Tie", "도철", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It devours all it touches, never sated.", "닿는 모든 것을 집어삼켜도 결코 배부르지 않다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cauldron’s Dread Mask", "솥 위의 흉면", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bark beetle", "나무좀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parrot", "앵무새", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It repeats the words it has heard, speaking unheard secrets through human voices.", "들은 말을 되풀이하며 사람의 목소리로 아무도 모르는 비밀을 말한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It carves tunnels beneath tree bark, burying rot and its brood deep within the wood.", "나무껍질 아래에 굴을 파고 썩음과 자손을 목질 깊숙이 묻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stump borer", "나무 밑동 좀벌레", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the opponent's turn, if [creature] is on the board, generate a Stump in the owner's hand.", "상대의 턴이 끝날 때 [creature] 카드가 보드에 있으면 주인의 패에 나무 밑동 카드 한 장을 생성한다.", Language.Korean);

            //WLDLC-other
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly Aquasquirrel", "겁 많은 수상다람쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frail Squirrel", "연약한 다람쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Injured Goat", "다친 염소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legendary Squirrel", "전설의 다람쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nightmare Aquasquirrel", "악몽의 수상다람쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DLC_Fairy_Tale", "야생의 전설 DLC: 찬란한 동화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Added some cards based on myths, legends, and fictional elements.", "신화와 전설, 가상의 요소를 바탕으로 한 카드를 추가했다.", Language.Korean);

        }
    }

    public class OriginalModifiedMod
    {

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for OriginalModified Mod");
            // All
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amoeba Squirrel", "아메바 다람쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Aquasquirrel", "구타유발자 수상다람쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloody Stone", "희생의 돌", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explosion Aquasquirrel", "자폭 수상다람쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explosion Squirrel", "자폭 다람쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Killer Bee", "살인벌", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quality Squirrel", "고급 다람쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reach Squirrel", "높이뛰기 다람쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificable Boulder", "희생할 수 있는 바위", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tail Squirrel", "긴꼬리 다람쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hawk", "매", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious hawk. One of the most effective flying attackers.", "사나운 매. 가장 효율적인 비행 공격수 중 하나다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salmon", "연어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The athletic salmon. It swims quickly upstream.", "운동 능력이 뛰어난 연어. 물살을 거슬러 빠르게 헤엄친다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Ball", "다람쥐 공", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The peculiar squirrel ball. When it rolls, it leaves behind some stray squirrels.", "기묘한 다람쥐 공. 굴러가면서 길 잃은 다람쥐를 몇 마리 남긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Squirrel", "루비 다람쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Squirrel", "에메랄드 다람쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Squirrel", "사파이어 다람쥐", Language.Korean);
        }
    }
    public class CustomSideDeckMod
    {

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for CustomSideDeck Mod");
            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How the mod should handle side deck card backs for side decks that don't add their own custom card back. If enabled, automatically generates a unique card back based on the side deck's main card's portrait. Otherwise, the default squirrel back will be used.", "고유한 카드 뒷면이 없는 보조 덱의 뒷면을 모드가 처리하는 방식을 설정한다. 켜면 보조 덱의 주 카드 그림을 바탕으로 전용 뒷면을 자동 생성한다. 끄면 기본 다람쥐 뒷면을 사용한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whether to automatically add an Aqua version of all custom side decks. Buggy, not recommended.", "모든 사용자 지정 보조 덱의 수상 버전을 자동으로 추가할지 설정한다. 오류가 있어 권장하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whether or not Aquasquirrels and custom side decks marked as `CSDIsAqua` should be shown as options even when the Squirrel Fish challenge isn't on.", "다람쥐생선 도전을 켜지 않아도 수상다람쥐와 `CSDIsAqua`로 표시된 사용자 지정 보조 덱을 선택지에 표시할지 설정한다.", Language.Korean);

            // ShowText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select Side Deck", "보조 덱 선택", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Configure Side Deck", "보조 덱 설정", Language.Korean);
            for (int point = 0; point <= 100; point++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CURRENT SIDE DECK: <color=#eef4c6>" + point.ToString() + "</color> Challenge Points", "현재 보조 덱: <color=#eef4c6>" + point.ToString() + "</color> 도전 점수", Language.Korean);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CURRENT SIDE DECK: <color=#eef4c6>+" + point.ToString() + "</color> Challenge Points", "현재 보조 덱: <color=#eef4c6>+" + point.ToString() + "</color> 도전 점수", Language.Korean);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Total Challenge Points: <color=#eef4c6>" + point.ToString() + "</color>", "총 도전 점수: <color=#eef4c6>" + point.ToString() + "</color>", Language.Korean);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "\nContains {0} cards", "\n카드 {0}장 포함", Language.Korean); // todo

        }
    }

    public class PackManagementMod
    {

        public static Dictionary<string, string> EncountersTitle = new();
        public static Dictionary<string, KeyValuePair<string, string>> EncountersDescription = new();

        public static void RegisterEncounter(string en, string zh, string endes, string zhdes)
        {
            EncountersTitle.Add(en, zh);
            EncountersDescription.Add(en, new KeyValuePair<string, string>(endes, zhdes));
        }
