    public class MagicExpansionMod
    {

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MagicExpansion Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angry Witch", "분노의 마녀", Language.Korean);
            MagnificusMod.RegisterCard("Angry Witch", "분노의 마녀", "The witch in charge of anger will ignite flames in the opposite battlefield.", "분노를 관장하는 마녀가 반대편 전장에 불길을 일으킨다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of anger will ignite flames in the opposite battlefield.", "분노를 관장하는 마녀가 반대편 전장에 불길을 일으킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arrogant Witch", "오만의 마녀", Language.Korean);
            MagnificusMod.RegisterCard("Arrogant Witch", "오만의 마녀", "The witch who mastered the power of arrogance appeared with the demon.", "오만의 힘을 다루는 마녀가 악마와 함께 나타난다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who mastered the power of arrogance appeared with the demon.", "오만의 힘을 다루는 마녀가 악마와 함께 나타난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Mage", "커피 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Coffee Mage", "커피 마법사", "Mages who love coffee use gems to regulate their breath.", "커피를 좋아하는 마법사가 보석으로 호흡을 가다듬는다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mages who love coffee use gems to regulate their breath.", "커피를 좋아하는 마법사가 보석으로 호흡을 가다듬는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funny MagiChiking", "재미있는 마법 닭", Language.Korean);
            MagnificusMod.RegisterCard("Funny MagiChiking", "재미있는 마법 닭", "A smelly Rooster who has learned magic.", "마법을 배운 냄새 고약한 수탉.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A smelly Rooster who has learned magic.", "마법을 배운 냄새 고약한 수탉.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gluttonous Witch", "폭식의 마녀", Language.Korean);
            MagnificusMod.RegisterCard("Gluttonous Witch", "폭식의 마녀", "The witch in charge of gluttony committed a terrible sin.", "폭식을 관장하는 마녀는 끔찍한 죄를 저질렀다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of gluttony committed a terrible sin.", "폭식을 관장하는 마녀는 끔찍한 죄를 저질렀다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greedy Witch", "탐욕스러운 마녀", Language.Korean);
            MagnificusMod.RegisterCard("Greedy Witch", "탐욕스러운 마녀", "The witch who controls the power of greed, unfortunately, can only bring value to us after death.", "탐욕의 힘을 다루는 마녀. 안타깝게도 죽은 뒤에야 우리에게 가치를 가져다준다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who controls the power of greed, unfortunately, can only bring value to us after death.", "탐욕의 힘을 다루는 마녀. 안타깝게도 죽은 뒤에야 우리에게 가치를 가져다준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inquisitive Witch", "탐욕스러운 마녀", Language.Korean);
            MagnificusMod.RegisterCard("Inquisitive Witch", "탐욕스러운 마녀", "Nothing is more powerful than her curiosity.", "그녀의 호기심보다 강력한 것은 없다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing is more powerful than her curiosity.", "그녀의 호기심보다 강력한 것은 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jealous Witch", "질투의 마녀", Language.Korean);
            MagnificusMod.RegisterCard("Jealous Witch", "질투의 마녀", "The witch in charge of jealousy has powerful magic and power.", "질투를 관장하는 마녀는 강력한 마법과 힘을 지녔다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of jealousy has powerful magic and power.", "질투를 관장하는 마녀는 강력한 마법과 힘을 지녔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Witch", "나태의 마녀", Language.Korean);
            MagnificusMod.RegisterCard("Lazy Witch", "나태의 마녀", "The witch in charge of the power of laziness is really a lazy guy.", "나태의 힘을 다루는 마녀는 정말 게으른 녀석이다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of the power of laziness is really a lazy guy.", "나태의 힘을 다루는 마녀는 정말 게으른 녀석이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lust Witch", "색욕의 마녀", Language.Korean);
            MagnificusMod.RegisterCard("Lust Witch", "색욕의 마녀", "The witch in charge of lust, don't look into her eyes.", "색욕을 관장하는 마녀. 눈을 바라보지 마라.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of lust, don't look into her eyes.", "색욕을 관장하는 마녀. 눈을 바라보지 마라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nine Color Deer", "아홉 빛깔 사슴", Language.Korean);
            MagnificusMod.RegisterCard("Nine Color Deer", "아홉 빛깔 사슴", "The colorful nine color deer has precious value.", "다채로운 아홉 빛깔 사슴은 귀중한 가치를 지녔다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The colorful nine color deer has precious value.", "다채로운 아홉 빛깔 사슴은 귀중한 가치를 지녔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky MagiChiking", "마법의 악취 치킨", Language.Korean);
            MagnificusMod.RegisterCard("Stinky MagiChiking", "마법의 악취 치킨", "Hatched by magic eggs.", "마법 알에서 부화했다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hatched by magic eggs.", "마법 알에서 부화했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Maniac", "폭탄광", Language.Korean);
            MagnificusMod.RegisterCard("Bomb Maniac", "폭탄광", "Even if it detonates itself, it never surrenders to others.", "스스로 폭발하더라도 결코 남에게 굴복하지 않는다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if it detonates itself, it never surrenders to others.", "스스로 폭발하더라도 결코 남에게 굴복하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earl Bunny", "토끼 백작", Language.Korean);
            MagnificusMod.RegisterCard("Earl Bunny", "토끼 백작", "The versatile Earl Bunny, not everyone can comprehend this art.", "다재다능한 토끼 백작. 누구나 이 예술을 이해할 수 있는 것은 아니다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The versatile Earl Bunny, not everyone can comprehend this art.", "다재다능한 토끼 백작. 누구나 이 예술을 이해할 수 있는 것은 아니다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chinese Loong", "중국 용", Language.Korean);
            MagnificusMod.RegisterCard("Chinese Loong", "중국 용", "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "심연에 잠기면 사해를 평안하게 하고 하늘을 날면 만물을 지킨다. 용이 먼 길을 가는 것은 어디서나 길조다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "심연에 잠기면 사해를 평안하게 하고 하늘을 날면 만물을 지킨다. 용이 먼 길을 가는 것은 어디서나 길조다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "치즈 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Cheese Wizard", "치즈 마법사", "A humorous wizard who is proficient in cooking, his cheese has magical power.", "요리에 능통한 유쾌한 마법사. 그의 치즈에는 신비한 마력이 있다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A humorous wizard who is proficient in cooking, his cheese has magical power.", "요리에 능통한 유쾌한 마법사. 그의 치즈에는 신비한 마력이 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Golem", "서리 골렘", Language.Korean);
            MagnificusMod.RegisterCard("Frost Golem", "서리 골렘", "Once on the field, there is a strong sense of oppression.", "보드에 나오기만 해도 강한 압박감이 느껴진다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once on the field, there is a strong sense of oppression.", "보드에 나오기만 해도 강한 압박감이 느껴진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "야구 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Baseball Mage", "야구 마법사", "His soul is bound under sportswear and can never be liberated.", "그의 영혼은 운동복 아래에 묶여 영원히 해방될 수 없다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His soul is bound under sportswear and can never be liberated.", "그의 영혼은 운동복 아래에 묶여 영원히 해방될 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raid Mage", "급습 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Raid Mage", "급습 마법사", "You will understand how terrifying it is for a robber to master magic.", "강도가 마법을 익히면 얼마나 무서운지 알게 될 것이다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will understand how terrifying it is for a robber to master magic.", "강도가 마법을 익히면 얼마나 무서운지 알게 될 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jade Turtle", "비취 마법 거북", Language.Korean);
            MagnificusMod.RegisterCard("Jade Turtle", "비취 마법 거북", "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "머리부터 발끝까지 에메랄드로 덮인 거북. 이런 그림이 존재한다는 사실에 감탄할 수밖에 없다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "머리부터 발끝까지 에메랄드로 덮인 거북. 이런 그림이 존재한다는 사실에 감탄할 수밖에 없다.", Language.Korean);
