            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "창 마법사의 수습생. 현명한 자는 늘 다음 수를 준비해 둔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Eye of Darkness", "어둠의 눈", Language.Korean);
