            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forest Spell", "숲 주문", Language.Korean);
            MagnificusMod.RegisterCard("Forest Spell", "숲 주문", "The forest spell obtained from Leshy can provide the most primitive defense.", "레쉬에게 얻은 숲 주문은 가장 원초적인 방어를 제공한다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The forest spell obtained from Leshy can provide the most primitive defense.", "레쉬에게 얻은 숲 주문은 가장 원초적인 방어를 제공한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MoxShield", "목스 마법 방패", Language.Korean);
            MagnificusMod.RegisterCard("MoxShield", "목스 마법 방패", "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "보석이 박힌 마법 방패. 그 존재만으로 늘 안심이 된다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "보석이 박힌 마법 방패. 그 존재만으로 늘 안심이 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nebula Storm", "성운 폭풍", Language.Korean);
            MagnificusMod.RegisterCard("Nebula Storm", "성운 폭풍", "This cruel storm can directly take away an enemy.", "이 잔혹한 폭풍은 적 하나를 곧바로 데려갈 수 있다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cruel storm can directly take away an enemy.", "이 잔혹한 폭풍은 적 하나를 곧바로 데려갈 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Contract", "영혼 계약", Language.Korean);
            MagnificusMod.RegisterCard("Soul Contract", "영혼 계약", "Perhaps you need more card assistance, and a soul contract is a great choice.", "카드의 도움이 더 필요할지도 모른다. 영혼 계약은 좋은 선택이다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you need more card assistance, and a soul contract is a great choice.", "카드의 도움이 더 필요할지도 모른다. 영혼 계약은 좋은 선택이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wailing Wall", "통곡의 벽", Language.Korean);
            MagnificusMod.RegisterCard("Wailing Wall", "통곡의 벽", "Such perseverance even moves the thorny walls to weep.", "그런 끈기는 가시 벽마저 눈물짓게 한다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such perseverance even moves the thorny walls to weep.", "그런 끈기는 가시 벽마저 눈물짓게 한다.", Language.Korean);
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Time", "커피 시간", Language.Korean);
            MagnificusMod.RegisterAbility("Coffee Time", "커피 시간");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] receives the first damage, it gains 2 strength.", "[creature] 카드가 처음 피해를 받으면 공격력이 2 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Arrogance", "오만의 죽음", Language.Korean);
            MagnificusMod.RegisterAbility("Death of Arrogance", "오만의 죽음");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 2 power.", "[creature] 카드가 사망하면 인접한 카드의 공격력이 2 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Greed", "탐욕의 죽음", Language.Korean);
            MagnificusMod.RegisterAbility("Death of Greed", "탐욕의 죽음");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 3 health.", "[creature] 카드가 사망하면 인접한 카드의 체력이 3 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Made", "신의 피조물", Language.Korean);
            MagnificusMod.RegisterAbility("God Made", "신의 피조물");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Homunculus is created on each empty adjacent space. The Homunculus has : 1 power, 1 health, Familiar.", "[creature] 카드를 내면 인접한 각 빈칸에 호문쿨루스가 생성된다. 호문쿨루스는 공격력 1, 체력 1, 사역마 도장을 지닌다.", Language.Korean);
            MagnificusMod.RegisterAbility("Fir Caller", "숲을 부르는 자");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the empty slot on the cardholder's side is filled with Great Firs. Great Fir has: 0 Power, 3 Health, Mighty Leap.", "[creature] 카드가 사망하면 주인 측 빈 슬롯이 큰 전나무로 채워진다. 큰 전나무는 공격력 0, 체력 3, 위대한 도약 도장을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering Taste", "잊을 수 없는 맛", Language.Korean);
            MagnificusMod.RegisterAbility("Lingering Taste", "잊을 수 없는 맛");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 1 health.", "[creature] 카드가 사망하면 인접한 카드의 체력이 1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love of Cheese", "치즈 사랑", Language.Korean);
            MagnificusMod.RegisterAbility("Love of Cheese", "치즈 사랑");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw a cheese card, cheese has: 0 power, 2 health,Lingering Taste.", "[creature] 카드를 내면 치즈 카드 한 장을 뽑는다. 치즈는 공격력 0, 체력 2, 잊을 수 없는 맛 도장을 지닌다.", Language.Korean);
            // Other
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Expansion", "마법 확장팩", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here comes the card of the fantasy world! More content will be added in the future!", "판타지 세계의 카드가 왔다! 앞으로 더 많은 콘텐츠가 추가될 예정이다!", Language.Korean);
        }
