            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnificus", "매그니피쿠스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimora", "그리모라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer", "소여", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee", "케이시", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal", "로얄", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Training Dummy", "훈련용 허수아비", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goobert", "구버트", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pike Mage", "장창 마법사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonely Wizard", "외로운 마법사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspector", "검사자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Melter", "용해자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dredger", "준설공", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prospector", "광부", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angler", "낚시꾼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trapper", "덫 사냥꾼", Language.Korean);

            // ShowUntilInput
            Dictionary<GemType, string> gemTypesEn = new Dictionary<GemType, string>
            {
                { GemType.Orange, "오렌지색" },
                { GemType.Blue, "파란색" },
                { GemType.Green, "녹색" },
            };
            Dictionary<GemType, string> gemTypes = new Dictionary<GemType, string>
            {
                { GemType.Orange, "오렌지" },
                { GemType.Blue, "파랑" },
                { GemType.Green, "초록" },
            };
            foreach (var gemType in gemTypes.Keys)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have the two " + HintsHandler.GetColorCodeForGem(gemType) + gemTypesEn[gemType] + "[c:] Gems needed to play that. Gain Gems by playing Mox cards.", "이 카드를 낼 " + HintsHandler.GetColorCodeForGem(gemType) + gemTypes[gemType] + "[c:] 보석 두 개가 없다. 목스 카드를 내면 보석을 얻는다.", Language.Korean);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The gem skeptic sigil prevents you from playing that gem.", "보석 회의론자 도장 때문에 그 보석을 낼 수 없어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't play that until you're 3 off dying.", "패배까지 남은 피해가 3 이하일 때만 그 카드를 낼 수 있어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You want to play that? Start losing.", "그걸 내고 싶어? 우선 지기 시작해 봐.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't play it, genius.", "그건 못 내, 천재야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You cannot play that card with the scales in this state.", "저울이 이런 상태에서는 그 카드를 낼 수 없어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't play that one.", "그 카드는 낼 수 없어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm afraid that one's forbidden, dear.", "얘야, 안타깝지만 그건 금지란다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't allow you to play that card.", "그 카드를 내는 건 허락하지 않겠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't play a gem card while a creature with the Gem Skeptic sigil is on your side of the board!", "당신 측 보드에 보석 회의론자 도장을 지닌 피조물이 있으면 보석 카드를 낼 수 없다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card cannot be played unless you are three or less damage from losing!", "패배까지 남은 피해가 셋 이하일 때만 이 카드를 낼 수 있다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card cannot be played.", "이 카드는 낼 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blocked on both sides...", "양쪽 다 막혔군……", Language.Korean);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Absorber", "흡수자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a creature adjacent to [creature] is struck, [creature] will gain health equal to the amount of damage dealt.", "[creature] 카드에 인접한 피조물이 공격받으면 [creature] 카드의 체력이 그 피조물이 받은 피해만큼 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not attack unless forced to attack by another effect.", "[creature] 카드는 다른 효과로 공격을 강제당하지 않는 한 공격하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trinket Bearer", "싸구려 장신구", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it grants it's owner a random item.", "[creature] 카드를 내면 주인이 무작위 아이템 하나를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] pulls out a random item.", "[creature] 카드가 무작위 아이템 하나를 꺼낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodbait", "피의 미끼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood to return [creature] to your hand.", "피 1을 소비해 [creature] 카드를 패로 돌려보낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonefed", "뼈 먹이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 bones to heal [creature] for up to 3 health.", "뼈 2개를 소비해 [creature] 카드의 체력을 최대 3 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Strike", "뼈의 일격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 bones to deal 1 damage to the creature opposing [creature].", "뼈 2개를 소비해 [creature] 카드 맞은편의 피조물에게 피해를 1 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broodfeast", "둥지의 향연", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, pay 1 blood to create a copy of [creature] in your hand.", "턴당 한 번, 피 1을 소비해 패에 [creature] 카드의 사본 한 장을 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carnivore", "육식동물", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 blood to increase the power of [creature] by 3.", "피 2를 소비해 [creature] 카드의 공격력을 3 높인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Causality", "인과관계", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 currency to trigger a random effect.", "화폐 1을 소비해 무작위 효과를 발동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The universe seems in harmony already... nothing changes.", "우주는 이미 조화로운 모양이다…… 아무것도 달라지지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing happened...", "아무 일도 일어나지 않았다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing? Huh, that's disappointing.", "아무것도 없어? 흠, 실망이네.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Power buff, lucky you...", "공격력 강화라, 운 좋군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Health buff, could be a lot better...", "체력 강화라니, 훨씬 더 좋을 수도 있었는데……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have dealt me a blow...", "내게 한 방 먹였군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dealt one direct damage!", "직접 피해를 하나 줬다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guess playing a perfect game is no match for pay to win mechanics.", "완벽한 플레이도 돈으로 이기는 체계에는 못 당하나 보군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deadbeat", "기력 소진", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a creature on the same side of the board. That creature will perish.", "보드의 같은 편에 있는 피조물 하나를 선택한다. 그 피조물은 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deck Drain", "덱 흡수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Up to 3 times per turn, pay 1 blood to draw a random card from your deck.", "턴당 최대 3번, 피 1을 소비해 덱에서 무작위 카드 한 장을 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dredge", "준설", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Bones to search your deck for any card, and add it to your hand.", "뼈 4개를 소비해 덱에서 원하는 카드 한 장을 찾아 패에 넣는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Escape", "탈출", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have a green gem, return [creature] to your hand.", "녹색 보석이 있으면 [creature] 카드를 패로 돌려보낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eternal Gallop", "영원한 질주", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Move [creature] in the direction inscribed on the sigil.", "[creature] 카드를 도장에 표시된 방향으로 이동시킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exalted Rune", "숭고한 룬", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood to create a 'Mox Pillar' in your hand. A mox pillar is defined as: 0 power, 4 health, Mox Sigil, Mighty Leap.", "피 1을 소비해 패에 '목스 기둥' 카드 한 장을 생성한다. 목스 기둥은 공격력 0, 체력 4, 목스 도장과 위대한 도약 도장을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fair Trade", "공정 거래", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 pelt to remove an opponent's creature from the board, and add it to your hand.", "가죽 1장을 소비해 상대 피조물 하나를 보드에서 제거하고 당신의 패에 넣는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fetch", "뼈의 질주", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to make [creature] move in the direction inscribed in the sigil.", "뼈 1개를 소비해 [creature] 카드를 도장에 표시된 방향으로 이동시킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flip", "도박 버튼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "50/50 chance to either kill [creature] or give it +1 power and health.", "50/50 확률로 [creature] 카드를 죽이거나 공격력과 체력을 각각 +1 높인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gorge", "폭식", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] has less than 10 health, pay 1 blood to grant it +3 health.", "[creature] 카드의 체력이 10 미만이면 피 1을 소비해 체력을 +3 높인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You spent the last of your foils!.", "마지막 포일까지 다 썼다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have 0 foil remaining.", "남은 포일은 0개다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have 1 foil remaining.", "남은 포일은 1개다.", Language.Korean);
            for (int currency = 2; currency <= 100; currency++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have " + currency + " foils remaining.", "포일이 " + currency + "개 남았다.", Language.Korean);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough teeth.", "이빨이 부족하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need more teeth to use that ability.", "그 능력을 쓰려면 이빨이 더 필요하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You cannot pay the cost", "비용을 지불할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you deaf? Get more Robobucks.", "귀먹었어? 로봇 코인이나 더 벌어 와.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not running a charity, get more money.", "여긴 자선 단체가 아니야. 돈을 더 가져와.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No robobucks, no sigil.", "로봇 코인이 없으면 도장도 없어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No dice.", "안 돼.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm.", "흠.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough teeth to pay the cost.", "비용을 지불할 이빨이 부족하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll need to perform better in battle if you wish to use that ability.", "그 능력을 쓰고 싶다면 전투에서 더 잘해야 한다.", Language.Korean);
            for (int currency = 0; currency <= 100; currency++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You require more foils to use this ability! You have " + currency + " foils.", "이 능력을 쓰려면 포일이 더 필요하다! 현재 포일은 " + currency + "개다.", Language.Korean);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ugh.", "으윽.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need more Robobucks to use that sigil, and I don't give credit.", "그 도장을 쓰려면 로봇 코인이 더 필요해. 외상은 안 돼.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come back when you're a little... mmm... richer.", "좀 더…… 음…… 부자가 되면 다시 와.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Picky Eater", "편식가", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood to draw bones equal to the health of the sacrificed creature.", "피 1을 소비해 희생한 피조물의 체력과 같은 수의 뼈를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Punching Bag", "샌드백", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, choose any creature. That creature will strike this card for 1 damage. Afterwards, this card regains 1 health.", "턴당 한 번, 원하는 피조물 하나를 선택한다. 그 피조물이 이 카드를 공격해 피해를 1 준다. 그 뒤 이 카드는 체력을 1 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remove", "제거 버튼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill [creature].", "[creature] 카드를 죽인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharpen", "연마", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have an orange mox gem, sacrifice it to give [creature] +1 attack power.", "오렌지 목스 보석이 있으면 그것을 희생해 [creature] 카드의 공격력을 +1 높인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] sacrifices an orange gem to sharpen it's attack!", "[creature] 카드가 오렌지색 보석을 희생해 공격을 가다듬는다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spellsword", "주문의 검", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All gems on the same side of the board as[creature] gain 2 power, attack, and perish.", "보드에서 [creature] 카드와 같은 편에 있는 모든 보석의 공격력이 2 증가하고 공격한 뒤 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trained Flier", "비행 훈련", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grant [creature] the effect of the Airborne sigil until next upkeep. If the card already has Airborne, this will remove it's effect until next upkeep.", "[creature] 카드에 다음 유지 단계까지 공수 도장의 효과를 부여한다. 이미 공수가 있으면 대신 다음 유지 단계까지 그 효과를 제거한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trained Swimmer", "수영 훈련", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creature will gain the effect of the Waterborne sigil for one turn.", "피조물이 한 턴 동안 수생 도장의 효과를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upgrade Subroutine", "업그레이드 서브루틴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] destroys another bot, this gains 1 point. When activated, the owner is presented with a choice of three sigils to permanently augment the card. Selecting a sigil spends points, and the more points accumulated when the sigil is activated, the higher quality the presented sigils will be.", "[creature] 카드가 다른 봇을 파괴하면 점수를 1 얻는다. 활성화하면 주인이 세 도장 중 하나를 골라 카드를 영구적으로 강화할 수 있다. 도장을 선택하면 점수를 소비한다. 활성화할 때 쌓인 점수가 많을수록 더 좋은 도장이 제시된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aculeate Grip", "가시 포옹", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played on the same side of the board as [creature], [creature] will move towards them as far as possible, dealing them one damage and increasing it's own health by 1.", "[creature] 카드와 같은 편 보드에 피조물이 나오면 [creature] 카드가 그쪽으로 최대한 가까이 이동해 피해 한 점을 주고 자신의 체력을 1 높인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allure", "매혹", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the round, [creature] will draw opposing creatures in front of itself.", "플레이어의 턴 시작 시 [creature] 카드가 상대 피조물을 자신의 정면으로 끌어당긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annihilation", "섬멸", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, all creatures on the board are dealt 10 damage.", "[creature] 카드가 사망하면 보드의 모든 피조물이 피해를 10 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant Guardian", "개미 수호자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal damage equal to it's attack power to any card which strikes a friendly ant.", "아군 개미를 공격한 카드에게 [creature] 카드가 자신의 공격력만큼 피해를 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antimagic", "반마법", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any mox gems played while [creature] is on the board will immediately perish. [creature] will move to the position of the destroyed gem, gain 1 health, and immediately attack.", "[creature] 카드가 보드에 있는 동안 나오는 모든 목스 보석은 즉시 사망한다. [creature] 카드는 파괴된 보석의 위치로 이동하고 체력이 1 증가하며 즉시 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] destroys the played gem!", "[creature] 카드가 나온 보석을 파괴한다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armortify", "장갑화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, this card gains the armored sigil.", "[creature] 카드가 맞은편 피조물을 공격해 죽이면 이 카드가 장갑 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Artistic License", "예술적 허용", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the creature opposing it loses all sigils.", "[creature] 카드를 내면 맞은편 피조물이 모든 도장을 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trying to plunder me sigils? Yer a sour spoilsport!", "내 도장을 약탈하려고? 흥을 깨는 망할 놈!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Despite your artistry, the soul of the moon is impervious...", "네 예술적 기교로도 달의 영혼은 흔들리지 않는다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backup", "백업", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, the first card in it's owner's hand is played in it's place.", "[creature] 카드가 전투로 사망하면 주인의 패에서 첫 번째 카드가 그 자리에 나온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] calls in backup.", "[creature] 카드가 지원을 부른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bandage Weaver", "붕대 직조자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn,[creature] will heal the cards to it's left and right for 1 health.", "턴이 끝날 때 [creature] 카드가 양옆 카드의 체력을 각각 1 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bastion", "요새", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] recieves damage, it only takes half the damage it normally would, rounded up.", "[creature] 카드가 피해를 받으면 원래 피해의 절반만 받으며 소수점은 올림한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Batch Delete", "일괄 삭제", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a creature and it perishes, any creatures on the board which share the same cost as the target perish also.", "[creature] 카드가 피조물을 공격해 죽이면 보드에서 그 대상과 비용이 같은 피조물도 모두 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] shreds any other cards with the same cost as it's victim...", "[creature] 카드가 희생자와 비용이 같은 다른 카드를 모두 갈가리 찢는다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bejeweled", "보석 맞추기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the field, lining up three gems of the same colour will remove those gems from the field. Any creatures which opposed those gems will be removed as well, and the opponent will take damage directly equal to their combined attack power. ", "[creature] 카드가 보드에 있는 동안 같은 색 보석 셋을 일렬로 놓으면 그 보석들이 보드에서 제거된다. 그 보석 맞은편의 피조물도 제거되며 상대는 그 피조물들의 공격력 합계만큼 직접 피해를 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bewilder", "혼란", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may choose any creature. Swap that creatures power and health.", "[creature] 카드를 내면 주인이 원하는 피조물 하나를 골라 공격력과 체력을 맞바꿀 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bifurcated When Gempowered", "보석 강화 갈래 공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If its owner has an Orange Gem, [creature] will strike each opposing space to the left and right of the space across from it.", "주인에게 오렌지색 보석이 있으면 [creature] 카드는 정면 칸의 왼쪽과 오른쪽 칸을 각각 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bisection", "이분", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, two copies of the victim are created in the owner's hand with zero power and halved health.", "[creature] 카드가 다른 피조물을 죽이면 주인의 패에 그 피조물의 사본 두 장이 생성된다. 공격력은 영이고 체력은 절반이 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleach", "표백제", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all opponent creatures lose all sigils.", "[creature] 카드를 내면 상대 피조물이 모두 모든 도장을 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloated", "비대한 몸", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is worth blood equal to its health when sacrificed.", "[creature] 카드는 희생될 때 자신의 체력만큼 피를 제공한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Artist", "피의 예술가", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every three cards which perish by combat while [creature] is on the board, [creature] will give it's owner a deathcard constructed from the cost, stats, and sigils of those creatures.", "[creature] 카드가 보드에 있는 동안 카드 세 장이 전투로 사망할 때마다 [creature] 카드가 그 피조물들의 비용, 능력치, 도장을 조합한 죽음 카드를 주인에게 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] constructs a deathcard from previous creatures deaths...", "[creature] 카드가 앞서 죽은 피조물들로 죽음 카드를 만든다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it transforms to or from it's alternate form instead of perishing.", "[creature] 카드가 희생되면 죽는 대신 다른 형태로 변하거나 원래 형태로 돌아온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Dependent", "피 의존", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] does not strike another creature during the attack phase, it will perish at the start of the owner's next turn.", "[creature] 카드가 공격 단계에 다른 피조물을 때리지 못하면 주인의 다음 턴이 시작될 때 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood From Stone", "돌에서 피를", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may sacrifice terrain cards in order to play [creature].", "지형 카드를 희생해 [creature] 카드를 낼 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Gusher", "피 분출", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, this card, as well as creatures to the left and right of this card, gain 1 health.", "[creature] 카드가 맞은편 피조물을 공격해 죽이면 이 카드와 양옆 피조물의 체력이 각각 1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "피고래", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] deals damage to a creature, it gains 1 Health for each damage dealt.", "[creature] 카드가 피조물에게 피해를 주면 피해 한 점당 자신의 체력이 1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] consumes the blood of its prey!", "[creature] 카드가 사냥감의 피를 빨아 먹는다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Magic", "피의 마법", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the field, its owner may sacrifice any gems, even if those gems normally cannot be sacrificed.", "[creature] 카드가 보드에 있는 동안 주인은 평소에는 희생할 수 없는 보석도 포함해 모든 보석을 희생할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodrunner", "피의 주자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage to a creature, it will move in the direction inscribed in the sigil.", "[creature] 카드가 피조물에게 피해를 주면 도장에 표시된 방향으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Inspiration", "푸른 영감", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly creatures which cost a blue gem will gain a random sigil when played.", "[creature] 카드가 보드에 있는 동안 파란 보석을 비용으로 요구하는 아군 피조물은 나올 때 무작위 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] empowers the Blue Gem cost creature with a random sigil!", "[creature] 카드가 파란 보석을 비용으로 요구하는 피조물에게 무작위 도장을 부여한다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombjuration", "폭탄 소환", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may choose an empty slot on either side of the board. A magic bomb is created in the chosen slot.", "[creature] 카드를 내면 주인이 보드의 어느 편이든 빈 슬롯 하나를 고를 수 있다. 선택한 슬롯에 마법 폭탄이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombs Away", "폭탄 투하", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Payload is created in the opposing slot. [define:SigilNevernamed Payload]", "[creature] 카드를 내면 맞은편 슬롯에 탑재체가 생성된다. [define:SigilNevernamed Payload]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] drops a payload into the opposing slot!", "[creature] 카드가 맞은편 슬롯에 탑재체를 투하한다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Dependent", "뼈 의존", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the user has 0 Bones, [creature] will perish.", "사용자의 뼈가 0개면 [creature] 카드가 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Duke", "뼈 공작", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, 3 Bones are awarded instead of 1.", "[creature] 카드가 죽으면 뼈를 1개 대신 3개 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonelust", "뼈 갈망", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, it generates 3 bones for its owner.", "[creature] 카드가 다른 피조물을 죽이면 주인을 위해 뼈 3개를 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Spurs", "뼈 돌기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it generates a bone for it's owner.", "[creature] 카드가 공격받으면 주인을 위해 뼈 하나를 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will target the least powerful opposing card when it attacks.", "[creature] 카드는 공격할 때 공격력이 가장 낮은 상대 카드를 노린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning", "연소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] takes 1 damage. Also, when [creature] is struck, the striker gains this sigil.", "주인의 턴이 끝날 때 [creature] 카드가 피해를 1 받는다. 또한 [creature] 카드가 공격받으면 공격자가 이 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buzz Off", "하루살이 비행", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil and leave a mayfly in it's old place. A mayfly is defined as 1 power, 1 health, airborne, brittle.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 이동하고 원래 자리에 하루살이를 남긴다. 하루살이는 공격력 1, 체력 1, 공수와 취약성 도장을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Call To Arms", "전투 소집", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the creatures to it's left and right will immediately attack.", "[creature] 카드를 내면 양옆 피조물이 즉시 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Shedder", "카드 탈피", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil and leave a card in it's wake.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 이동하고 뒤에 카드 한 장을 남긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caustic", "부식독", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it's killer perishes as well.", "[creature] 카드가 사망하면 죽인 피조물도 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Center Strike", "중앙 공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack all opponent slots except for those in the leftmost and rightmost lanes.", "[creature] 카드는 맨 왼쪽과 맨 오른쪽 공격로를 제외한 상대의 모든 슬롯을 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Strike", "혼돈 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced by a random strike modifier sigil.", "[creature] 카드를 뽑으면 이 도장이 공격 방식을 바꾸는 무작위 도장으로 교체된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheater", "부정행위자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, the opponent is dealt 1 damage.", "[creature] 카드가 맞은편 피조물을 공격해 죽이면 상대가 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Circuit Maker", "회로 생성", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a conduit card is created to its left and right.", "[creature] 카드를 내면 양옆에 전도체 카드가 한 장씩 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Claw", "날카로운 발톱", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will lose all attack power if it is not directly adjacent to a card bearing the clawed sigil.", "[creature] 카드는 날카로운 부리와 발톱 도장을 지닌 카드에 바로 인접해 있지 않으면 공격력을 모두 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clawed", "날카로운 부리와 발톱", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, claws are created to the left and right. Any creatures in those spaces will be killed.", "[creature] 카드를 내면 양옆에 발톱이 생성된다. 그 칸에 있던 피조물은 모두 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clawing Hand", "발톱의 손", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is dealt damage equal to the number of cards in the owner's hand.", "[creature] 카드가 공격받으면 공격자가 주인의 패에 있는 카드 수만큼 피해를 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleaving", "양단", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes another creature, that creature will be cut in half. Half of the creature will move to the right, while the other half remains in place.", "[creature] 카드가 다른 피조물을 공격하면 그 피조물이 반으로 잘린다. 절반은 오른쪽으로 이동하고 나머지 절반은 원래 자리에 남는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cleaves it's target in half!", "[creature] 카드가 대상을 반으로 가른다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coastguard", "해안 경비", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerges during the opponent's turn. When an opposing creature is placed opposite to an empty space, [creature] will move to that empty space while submerged.", "상대의 턴 동안 잠수한다. 상대 피조물이 빈칸 맞은편에 배치되면 [creature] 카드가 잠수한 채 그 빈칸으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Collateral Damage", "부수 피해", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if [creature] is on the board, the nearest creature to this card will be dealt ten damage.", "주인의 턴이 끝날 때 [creature] 카드가 보드에 있으면 이 카드와 가장 가까운 피조물이 피해 열 점을 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Collector", "수집가", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn,[creature] will move in the direction inscribed on the sigil. Creatures in the way will be returned to the owner's hand.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 이동한다. 길을 막는 피조물은 주인의 패로 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Commander", "지휘관", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the creatures to it's left and right will attack the striker.", "[creature] 카드가 공격받으면 양옆 피조물이 공격자를 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Strike When Powered", "전력 주입 시 이중 공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit, it will strike the opposing space an additional time when it attacks.", "[creature] 카드가 회로 안에 있으면 공격할 때 맞은편 칸을 한 번 더 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gift When Powered", "전력 주입 시 선물", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit when it perishes, a random card is created in your hand.", "[creature] 카드가 사망할 때 회로 안에 있으면 당신의 패에 무작위 카드 한 장이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morsel When Powered", "전력 주입 시 한 입", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] is sacrificed while inside a completed circuit, ⁣it adds its stat values to the card it was sacrificed for.", "[creature] 카드가 완성된 회로 안에서 희생되면 그 희생으로 낸 카드에 자신의 능력치를 더한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Omnipotent When Powered", "전력 주입 시 전방위 공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit, it will strike every opposing space containing a card when it attacks. [creature] will strike directly if no creatures oppose it, or if it is not in a circuit.", "[creature] 카드가 회로 안에 있으면 공격할 때 카드가 있는 상대 칸을 모두 공격한다. 맞서는 피조물이 없거나 회로 안에 있지 않으면 [creature] 카드는 직접 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powered Quills", "전력 주입 시 뾰족한 깃", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck while inside a completed circuit, the striker is dealt 2 damage.", "[creature] 카드가 완성된 회로 안에서 공격받으면 공격자가 피해를 2 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Print When Powered", "전력 주입 시 인쇄", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is inside a completed circuit, a gem will be created in its owners hand at the start of their turn.", "[creature] 카드가 완성된 회로 안에 있으면 주인의 턴이 시작될 때 그 주인의 패에 보석 하나가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] prints a mox gem for its owner!", "[creature] 카드가 주인을 위해 목스 보석을 인쇄한다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repulsive When Powered", "전력 주입 시 역겨움", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is within a conduit, if another creature would strike it, it does not.", "[creature] 카드가 회로 안에 있는 동안 다른 피조물이 이 카드를 공격하려 하면 공격하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scavenge When Powered", "전력 주입 시 시체 청소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is inside a completed circuit, opposing creatures also grant Bones upon death.", "[creature] 카드가 완성된 회로 안에 있는 동안 상대 피조물도 죽으면 뼈를 제공한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Splash Damage When Powered", "전력 주입 시 확산 피해", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is within a conduit when it strikes a slot, creatures to the left and right of the struck slot will be dealt 1 damage.", "[creature] 카드가 회로 안에서 슬롯을 공격하면 공격받은 슬롯의 양옆 피조물이 각각 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulate When Powered", "전력 주입 시 자극", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is inside a completed circuit, it gains 2 health at the start of its owners turn.", "[creature] 카드가 완성된 회로 안에 있는 동안 주인의 턴이 시작될 때 자신의 체력이 2 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] stimulates its health!", "[creature] 카드가 자신의 체력을 자극한다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Billowing Bond", "비행의 유대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures within a bond completed by [creature] gain the power of flight at the start of each turn.", "[creature] 카드가 완성한 유대 범위 안의 피조물은 매 턴이 시작될 때 비행 능력을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elder Conduit", "보석 해골 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature within a circuit completed by [creature] perishes, a Gem Skeleton will be created in it's place.", "[creature] 카드가 완성한 회로 안에서 피조물이 사망하면 그 자리에 보석 해골이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] calls forth a Gem Skeleton with the old magics!", "[creature] 카드가 고대 마법으로 보석 해골을 불러낸다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Conduit", "에메랄드 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is part of a completed circuit, its owner gains a green gem.", "[creature] 카드가 완성된 회로의 일부면 주인이 녹색 보석 하나를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] completes a circuit, and grants its owner a green gem!", "[creature] 카드가 회로를 완성하고 주인에게 녹색 보석을 준다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] no longer completes a circuit, and no longer grants a green gem!", "[creature] 카드가 더는 회로를 완성하지 않아 녹색 보석도 제공하지 않는다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Friendship Bond", "우정의 유대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empty spaces within a bond completed by [creature] spawn Squirrels at the end of the owner's turn.", "주인의 턴이 끝날 때 [creature] 카드가 완성한 유대 범위 안의 빈칸에 다람쥐가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grave Conduit", "뼈 발굴 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Completes a circuit. At the end of the owner's turn, [creature] will generate one bone for each creature contained within the circuit it completes.", "회로를 완성한다. 주인의 턴이 끝날 때 [creature] 카드가 자신이 완성한 회로 안의 피조물마다 뼈 하나를 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] grants a bone for every creature in it's circuit.", "[creature] 카드가 자신의 회로 안의 피조물마다 뼈 하나를 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gun Conduit", "총 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the slot opposing a card in a circuit completed by [creature], the moved creature is dealt 1 damage.", "[creature] 카드가 완성한 회로 안의 카드 맞은편 슬롯으로 피조물이 이동하면 그 피조물이 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] takes a free shot!", "[creature] 카드가 공짜로 한 발 쏜다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hot Conduit", "작열 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature within a circuit completed by [creature] is struck, the striker gains the Burning Sigil. Also, creatures within this card's circuit do not take damage from the Burning sigil.", "[creature] 카드가 완성한 회로 안의 피조물이 공격받으면 공격자가 연소 도장을 얻는다. 또한 이 카드의 회로 안에 있는 피조물은 연소 도장으로 피해를 받지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loot Conduit", "약탈 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Completes a circuit. At the start of the owner's turn, [creature] will draw 1 card to the owners hand for every empty space in the circuit it completes.", "회로를 완성한다. 주인의 턴이 시작될 때 [creature] 카드가 자신이 완성한 회로의 빈칸마다 카드 1장을 뽑아 주인의 패에 넣는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] draws a card for every empty space in it's circuit!", "[creature] 카드가 자신의 회로 안의 빈칸마다 카드 한 장을 뽑는다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malfunctioning Conduit", "고장 난 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Completes a circuit. At the end of its owner's turn, random cards from its owners hand will be played in random spaces inside of the circuit completed by [creature]. Those cards gain the Burning Sigil.", "회로를 완성한다. 주인의 턴이 끝날 때 주인의 패에서 무작위 카드들이 [creature] 카드가 완성한 회로 안의 무작위 칸에 나온다. 그 카드들은 연소 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] draws cards into it's circuit!", "[creature] 카드가 자신의 회로 안으로 카드를 끌어들인다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meaningless Bond", "무의미한 유대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may complete a bond, but provides no additional effect.", "[creature] 카드는 유대를 완성할 수 있지만 추가 효과는 제공하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nano Conduit", "나노 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owners turn, creatures within a circuit completed by [creature] gain the Armored sigil.", "주인의 턴이 끝날 때 [creature] 카드가 완성한 회로 안의 피조물이 장갑 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] shields all creatures in its circuit!", "[creature] 카드가 자신의 회로 안의 모든 피조물에게 보호막을 제공한다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Conduit", "루비 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is part of a completed circuit, its owner gains an orange gem.", "[creature] 카드가 완성된 회로의 일부면 주인이 오렌지색 보석 하나를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] completes a circuit, and grants its owner an orange gem!", "[creature] 카드가 회로를 완성하고 주인에게 오렌지색 보석을 준다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] no longer completes a circuit, and no longer grants an orange gem!", "[creature] 카드가 더는 회로를 완성하지 않아 오렌지색 보석도 제공하지 않는다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Conduit", "사파이어 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is part of a completed circuit, its owner gains a blue gem.", "[creature] 카드가 완성된 회로의 일부면 주인이 파란색 보석 하나를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] completes a circuit, and grants its owner a blue gem!", "[creature] 카드가 회로를 완성하고 주인에게 파란색 보석을 준다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] no longer completes a circuit, and no longer grants a blue gem!", "[creature] 카드가 더는 회로를 완성하지 않아 파란색 보석도 제공하지 않는다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stim Conduit", "자극 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owners turn, creatures within a circuit completed by [creature] gain 1 Health.", "주인의 턴이 끝날 때 [creature] 카드가 완성한 회로 안의 피조물의 체력이 각각 1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] increases the health of every creature in it's circuit!", "[creature] 카드가 자신의 회로 안의 모든 피조물의 체력을 높인다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tender Bond", "다정한 유대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures within a bond completed by [creature] heal to full health at the start of the owner's turn.", "주인의 턴이 시작될 때 [creature] 카드가 완성한 유대 범위 안의 피조물은 체력을 모두 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thorny Conduit", "가시 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature within a circuit completed by [creature] is struck, the striker is then dealt a single damage point.", "[creature] 카드가 완성한 회로 안의 피조물이 공격받으면 공격자가 그 뒤 피해 한 점을 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Confusion", "혼동", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played opposite an opponents creature, swap that creatures power and health.", "[creature] 카드가 상대 피조물 맞은편에 나오면 그 피조물의 공격력과 체력을 맞바꾼다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card opposing [creature] is confused!", "[creature] 카드 맞은편의 카드가 혼란에 빠졌다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Copier", "복사 장치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a copy of it's murderer is created in your hand.", "[creature] 카드가 사망하면 당신의 패에 이 카드를 죽인 피조물의 사본 한 장이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coward", "겁쟁이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is targeted, it will leap out of the way.", "[creature] 카드가 목표가 되면 뛰어 비킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crooked Strike Left", "왼쪽 비껴 공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack the space to the left of it's intended target.", "[creature] 카드는 원래 목표의 왼쪽 칸을 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crooked Strike Right", "오른쪽 비껴 공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack the space to the right of it's intended target.", "[creature] 카드는 원래 목표의 오른쪽 칸을 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crossbones", "십자 뼈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it grants 2 bones to it's owner.", "[creature] 카드를 내면 주인이 뼈 2개를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crunchy", "바삭함", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it generates one bone for its owner.", "[creature] 카드가 희생되면 주인을 위해 뼈 하나를 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cute", "귀여운", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures that strike [creature] feel guilty, and will skip their next strike.", "[creature] 카드를 공격한 피조물은 죄책감을 느껴 다음 공격을 건너뛴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Data Breach", "데이터 유출", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner must draw a card from their deck and immediately discard it. The opponent is dealt damage equal to the drawn creatures attack power.", "[creature] 카드가 사망하면 주인이 덱에서 카드 한 장을 뽑고 즉시 버려야 한다. 상대는 뽑은 피조물의 공격력만큼 피해를 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deadringer", "죽음의 종지기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive and on the board, it gains +1 power each time the bell is rung, if it has less than 5 power.", "[creature] 카드가 살아서 보드에 있는 동안 종이 울릴 때마다 공격력이 5 미만이면 공격력이 +1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] powers up!", "[creature] 카드의 공격력이 오른다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Snatch", "죽음의 강탈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, draw a card from your deck.", "[creature] 카드가 사망하면 당신의 덱에서 카드 한 장을 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Decked Out", "완전무장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, a card from a random temple's side deck is created in your hand.", "[creature] 카드가 공격받으면 무작위 사원의 보조 덱 카드 한 장이 당신의 패에 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defiler", "오염자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner must draw a card from their deck and immediately discard it.", "[creature] 카드가 사망하면 주인이 덱에서 카드 한 장을 뽑고 즉시 버려야 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desperate", "필사적 저항", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it deals one point of damage to the opponent.", "[creature] 카드가 사망하면 상대에게 피해 한 점을 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals a free point of damage as it perishes.", "[creature] 카드가 사망하면서 공짜로 피해 한 점을 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deus Hoof", "발굽의 신", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All friendly hooved creatures gain +1 Power and Health while [creature] is on the board. Also, all hooved creatures will attack anything that strikes [creature].", "[creature] 카드가 보드에 있는 동안 모든 아군 유제류 피조물의 공격력과 체력이 각각 +1 증가한다. 또한 모든 유제류 피조물이 [creature] 카드를 공격한 대상을 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dexter Strike", "오른쪽 추가 공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will also strike the slot to the right of the opposing slot when it attacks.", "[creature] 카드는 공격할 때 정면 슬롯의 오른쪽 슬롯도 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diagonal Strike", "대각선 공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, it will strike either to the left or right of its original target, prioritising striking slots containing creatures. If both or neither slots adjacent to the target contain creatures, [creature] will attack to the left or right at random.", "[creature] 카드는 공격할 때 원래 목표의 왼쪽이나 오른쪽 슬롯을 공격하며 피조물이 있는 쪽을 우선한다. 목표의 양옆에 모두 피조물이 있거나 모두 없으면 [creature] 카드는 왼쪽이나 오른쪽을 무작위로 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disembowel", "내장 적출", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, an amount of guts equal to its remaining health are created in its owners hand.", "[creature] 카드가 희생되면 남은 체력과 같은 수의 내장이 주인의 패에 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s guts explode into your hands.", "[creature] 카드의 내장이 터져 당신의 손에 쏟아진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Distraction", "주의 분산", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, a distraction is left in its place and [creature] moves to the right.", "[creature] 카드가 공격받으려 하면 원래 자리에 미끼를 남기고 [creature] 카드는 오른쪽으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diver", "잠행자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can strike the opposing card even while it is submerged.", "[creature] 카드는 맞은편 카드가 잠수 중이어도 공격할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The next card drawn while [creature] is alive and on the board will be duplicated.", "[creature] 카드가 살아서 보드에 있는 동안 다음으로 뽑는 카드가 복제된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Divisibility Strike", "홀짝 전환 공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, [creature] will alternate between striking all odd indexed opponent slots, and all even indexed opponent slots.", "주인의 턴이 끝날 때 [creature] 카드는 상대의 모든 홀수 번호 슬롯을 공격하는 상태와 모든 짝수 번호 슬롯을 공격하는 상태를 번갈아 전환한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Docile", "온순함", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will wait a set number of turns in between being allowed to attack.", "[creature] 카드는 공격 사이에 정해진 턴 수만큼 기다려야 다시 공격할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doomed", "운명에 묶인 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will perish.", "턴이 끝날 때 [creature] 카드가 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Tap", "협동 공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a friendly creature strikes an opponent creature, [creature] will also attack that opponent creature.", "아군 피조물이 상대 피조물을 공격하면 [creature] 카드도 그 상대 피조물을 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] aids its comrades in battle!", "[creature] 카드가 전투 중 동료를 돕는다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Downdraft", "하강기류", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will grant the power of flight to creatures to it's left and right.", "[creature] 카드는 양옆 피조물에게 비행 능력을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw", "카드 뽑기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, its owner draws cards equal to the number inscribed on this sigil.", "[creature] 카드를 내면 주인이 이 도장에 표시된 숫자만큼 카드를 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dripping", "흘리기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil and leave part of it's own body in it's wake.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 이동하고 뒤에 자기 몸의 일부를 남긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drop", "첫 패 출전", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If[creature] is drawn as part of your opening hand, it will be automatically played on a random board space for free.", "[creature] 카드가 시작 패로 뽑히면 보드의 무작위 칸에 비용 없이 자동으로 나온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may search your deck for any card and create a duplicate of it in your hand.", "[creature] 카드를 내면 덱에서 원하는 카드를 찾아 패에 그 사본 한 장을 생성할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Duppelgang", "이중주", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw copies of cards adjacent to it from your deck to your hand.", "[creature] 카드를 내면 인접한 카드와 같은 카드를 덱에서 패로 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eager", "갈망", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain +2 power for the duration of it's first turn on the board.", "[creature] 카드는 보드에 있는 첫 턴 동안 공격력이 +2 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Easy Pickings", "손쉬운 먹잇감", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all other creatures on the board with 1 health will perish.", "[creature] 카드를 내면 보드에서 체력이 1인 다른 피조물이 모두 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emancipation", "해방", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, copies of any bottled cards the owner possesses are created in the owner's hand.", "[creature] 카드를 내면 주인이 가진 모든 병 속 카드의 사본이 주인의 패에 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Core", "에메랄드 핵", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, an Emerald Vessel is created in its place.", "[creature] 카드가 사망하면 그 자리에 에메랄드 그릇이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Heart", "에메랄드 심장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, an Emerald Mox is created in its place.", "[creature] 카드가 사망하면 그 자리에 에메랄드 목스가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanting", "마력 부여", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all creatures you control gain one of its other sigils, at random.", "[creature] 카드를 내면 당신이 조종하는 모든 피조물이 그 카드의 다른 도장 중 하나를 무작위로 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endangered", "멸종 위기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] has a one in four chance to perish.", "턴이 끝날 때 [creature] 카드가 사분의 일 확률로 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enemy Lines", "적진", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, it will target all opponent slots that it is NOT directly opposing.", "[creature] 카드는 공격할 때 정면을 제외한 상대의 모든 슬롯을 노린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Dependent", "에너지 의존", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the user has 0 Energy, [creature] will perish.", "사용자의 에너지가 0이면 [creature] 카드가 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enraged", "격노", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it gains 1 attack power.", "[creature] 카드가 공격받으면 공격력이 1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Entangle", "얽기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its killer has their power reduced by half and rounded down for one turn.", "[creature] 카드가 사망하면 죽인 피조물의 공격력이 한 턴 동안 절반이 되며 소수점은 버림한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic", "변덕", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed on the sigil. It will not move if the target slot is obstructed. Direction has a 50/50 chance to change after moving.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 이동한다. 목표 슬롯이 막혀 있으면 이동하지 않는다. 이동한 뒤 방향이 50/50 확률로 바뀐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Esprit De Corps", "단결심", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, creatures in the leftmost and rightmost slots on the same side of the board gain 1 power.", "[creature] 카드가 보드에 있는 동안 같은 편의 맨 왼쪽과 맨 오른쪽 슬롯에 있는 피조물의 공격력이 1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While[creature] is alive and on the board, its owner may not take fatal damage.", "[creature] 카드가 살아서 보드에 있는 동안 주인은 치명적인 피해를 받지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even Strike", "짝수 공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike all opposing spaces in even indexed columns when it attacks. Column index is counted from the left, starting at 1.", "[creature] 카드는 공격할 때 짝수 번호 열의 맞은편 칸을 모두 공격한다. 열 번호는 왼쪽에서 1부터 센다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exceptional Sacrifice", "파격적인 희생", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] counts as 6 Blood rather than 1 Blood when sacrificed. Does not pair well with many lives.", "[creature] 카드는 희생될 때 피 1 대신 피 6으로 계산한다. 많은 목숨과는 궁합이 좋지 않다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodstarved Beast", "피에 굶주린 야수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may search their graveyard for a card, and add that card to their hand.", "[creature] 카드를 내면 주인이 자신의 묘지에서 카드 한 장을 찾아 패에 넣을 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exploding Corpse", "폭발 시체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, all empty spaces on the board are filled with it's innards.", "[creature] 카드가 사망하면 보드의 모든 빈칸이 그 내장으로 채워진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Expulsion", "토해 내기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] takes damage, it regurgitates it's contents into the adjacent space to the right.", "[creature] 카드가 피해를 받으면 속에 든 것을 오른쪽 인접 칸에 토해 낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exsanguination", "방혈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, friendly creatures have their blood cost reduced by 1.", "[creature] 카드가 보드에 있는 동안 아군 피조물의 피 비용이 1 감소한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eye For Battle", "전투의 눈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will lose all attack power if it is not directly opposing an opponent's creature.", "[creature] 카드는 상대 피조물을 정면으로 마주하고 있지 않으면 공격력을 모두 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Face To Face", "대면", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, it morphs to mimic the current opponent.", "[creature] 카드를 뽑으면 현재 상대를 흉내 내는 모습으로 변한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fan Tailed", "부채 꼬리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all friendly creatures on the board take flight.", "[creature] 카드를 내면 보드의 모든 아군 피조물이 비행 능력을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fatal Flank", "죽음의 측면", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes to combat, it creates a specific creature in all empty adjacent slots.", "[creature] 카드가 전투로 사망하면 인접한 모든 빈 슬롯에 특정 피조물을 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fearsome", "공포의 위압", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] targets a slot occupied by another creature, that creature will move to make way for it if there is room to do so.", "[creature] 카드가 공격할 때 다른 피조물이 있는 슬롯을 목표로 삼으면 인접한 빈칸이 있을 경우 그 피조물이 그곳으로 도망쳐 길을 비킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "File Explorer", "파일 탐색기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, choose two creatures from random selection of your deck. These creatures will define this cards power and health at random. If this card dies, the creatures used to define its stats perish as well.", "[creature] 카드를 내면 덱에서 무작위로 제시된 후보 중 피조물 둘을 고른다. 그 피조물들이 이 카드의 공격력과 체력을 무작위로 결정한다. 이 카드가 죽으면 능력치를 정하는 데 사용한 피조물들도 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filter Feeder", "여과 섭식자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature perishes adjacent to [creature], the card will gain either 1 power or 1 health.", "[creature] 카드에 인접한 피조물이 사망하면 이 카드의 공격력이 1 증가하거나 체력이 1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firebomb", "소이탄", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, creatures adjacent to it and opposing it take 2 damage and gain the Burning sigil.", "[creature] 카드가 사망하면 인접한 피조물과 맞은편 피조물이 피해를 2 받고 연소 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] explodes, spraying fire everywhere!", "[creature] 카드가 폭발해 사방에 불을 뿌린다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire In The Hole", "폭파 주의", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it's owner may choose an opponent slot. The creature in that slot will take ten damage.", "[creature] 카드가 사망하면 주인이 상대 슬롯 하나를 고를 수 있다. 그 슬롯의 피조물은 피해 열 점을 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire Resistant", "내화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not take damage from the Burning sigil.", "[creature] 카드는 연소 도장으로 피해를 받지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flank Blast", "측면 폭파", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, adjacent friendly creatures are dealt 10 damage.", "[creature] 카드가 죽으면 인접한 아군 피조물이 피해를 10 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flea Ridden", "벼룩투성이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes to combat, it creates a Flea in all empty adjacent slots. A Flea is defined as 0 Power, 1 Health, Eager, Frail", "[creature] 카드가 전투로 사망하면 인접한 모든 빈 슬롯에 벼룩을 생성한다. 벼룩은 공격력 0, 체력 1, 갈망과 연약한 도장을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flighty", "들뜬 움직임", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will move to a random available space.", "턴이 끝날 때 [creature] 카드가 이동 가능한 무작위 칸으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fossil Record", "화석 기록", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, terrain cards will award 3 additional bones when destroyed.", "[creature] 카드가 보드에 있는 동안 지형 카드가 파괴되면 뼈를 3개 더 제공한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frail", "연약한", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it will perish.", "[creature] 카드는 공격받으면 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frail Sacrifice", "연약한 희생", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, the creature it was sacrificed for gains the Frail Sigil.", "[creature] 카드가 희생되면 그 희생으로 낸 피조물이 연약한 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freefall", "자유 낙하", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all airborne creatures require exactly 1 less of their respective cost to be played.", "[creature] 카드가 보드에 있는 동안 모든 공수 피조물을 내는 데 필요한 각각의 비용이 정확히 1 줄어든다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Friend Finder", "친구 찾기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random friend is created in the slots to it's left and right.", "[creature] 카드를 내면 양옆 슬롯에 무작위 친구가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fringe Strike", "양끝 공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will always attack the leftmost and rightmost opponent lanes.", "[creature] 카드는 항상 상대의 맨 왼쪽과 맨 오른쪽 공격로를 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frog Friend", "개구리의 친구", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscrybed in the sigil. You may search your deck for any 'frog' or 'toad' creatures, and play them in [creature]'s old space.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 이동한다. 덱에서 원하는 '개구리'나 '두꺼비' 피조물을 찾아 [creature] 카드의 원래 자리에 낼 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Dependant", "에메랄드 의존", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls no green mox gems, it will perish.", "[creature] 카드의 주인이 초록 목스 보석을 하나도 조종하지 않으면 이 카드는 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] requires an emerald mox to exist and perishes.", "[creature] 카드는 생존에 필요한 에메랄드 목스가 없어 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Dependant", "루비 의존", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls no orange mox gems, it will perish.", "[creature] 카드의 주인이 오렌지 목스 보석을 하나도 조종하지 않으면 이 카드는 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] requires a ruby mox to exist and perishes.", "[creature] 카드는 생존에 필요한 루비 목스가 없어 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Dependant", "사파이어 의존", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls no blue mox gems, it will perish.", "[creature] 카드의 주인이 파란 목스 보석을 하나도 조종하지 않으면 이 카드는 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] requires a sapphire mox to exist and perishes.", "[creature] 카드는 생존에 필요한 사파이어 목스가 없어 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Shedder", "보석 탈피", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscrybed in the sigil and drop a random Gem in its old place.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 이동하고 원래 자리에 무작위 보석을 남긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Skeptic", "보석 회의론자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, its owner may not play any mox gems.", "[creature] 카드가 보드에 있는 동안 주인은 목스 보석을 낼 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant", "거인", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, any strikes against its owner will target it instead.", "[creature] 카드가 보드에 있는 동안 주인을 향한 모든 공격은 대신 이 카드를 목표로 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gift Bearer", "선물 운반자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a random creature is created in your hand.", "[creature] 카드가 사망하면 당신의 패에 무작위 피조물이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glitterheart", "빛나는 심장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, playing a mox gem will increase its health by 1.", "[creature] 카드가 보드에 있는 동안 목스 보석이 나오면 이 카드의 체력이 1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is bolstered by the played gem.", "[creature] 카드가 나온 보석으로 강화된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Globetrotter", "세계 방랑자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn,[creature] will move in the direction inscribed on the sigil. If obstructed, it will move to the other side of the board and begin to circle back.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 이동한다. 막혀 있으면 보드 반대쪽 끝으로 이동해 돌아오기 시작한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Black Goat is created in its owners hand.", "[creature] 카드를 내면 주인의 패에 흑염소 카드 한 장이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gold Digger", "금 채굴자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 currency, up to five times per battle.", "주인의 턴이 끝날 때 [creature] 카드가 화폐를 1 생성한다. 전투당 최대 다섯 번까지 발동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gold Rush", "골드러시", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all opponent cards on the board perish, and are replaced by Gold Nuggets.", "[creature] 카드를 내면 보드의 모든 상대 카드가 사망하고 황금 덩어리로 바뀐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gooey", "점액", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker loses 1 power.", "[creature] 카드가 공격받으면 공격자의 공격력이 1 감소한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrape that gunk off the hull, lads! Full steam ahead!", "선체의 끈적한 걸 긁어내라, 얘들아! 전속력으로 전진!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No amount of ooze can slow the motion of a celestial body...", "아무리 많은 점액도 천체의 움직임을 늦출 수는 없다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Graveyard Shift", "묘지 야간 근무", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, it leaves something else in it's old space. Unlike Frozen Away, this new creature will retain the sigils and buffs of the original.", "[creature] 카드가 전투로 사망하면 원래 자리에 다른 피조물을 남긴다. 해빙과 달리 새 피조물은 원래의 도장과 강화 효과를 유지한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravity", "중력", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may choose any opponent creature, and move it to any open space on their side of the board.", "[creature] 카드를 내면 주인이 원하는 상대 피조물 하나를 골라 자신 측 보드의 빈칸으로 이동시킬 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Inspiration", "초록 영감", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly creatures which cost a green gem gain +2 health.", "[creature] 카드가 보드에 있는 동안 녹색 보석을 비용으로 요구하는 모든 아군 피조물의 체력이 +2 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gut Spewer", "내장 구토자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, its innards are created in your hand.", "[creature] 카드를 내면 그 내장이 당신의 패에 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harbinger", "선구자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a friendly creatures perishes, [creature] will move to fill it's empty space.", "아군 피조물이 사망하면 [creature] 카드가 그 빈칸을 채우러 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harts Within", "마음속 사슴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, a random creature from the hooved tribe is created in your hand.", "[creature] 카드가 공격받으면 당신의 패에 무작위 유제류 부족 피조물이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunter", "망령", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies to combat, it haunts the space it died in. Creatures that enter this space absorb its old sigils.", "[creature] 카드가 전투로 죽으면 죽은 칸에 깃든다. 그 칸에 들어오는 피조물은 원래 지니던 도장을 흡수한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] leaves its sigils behind in the ethereal plane!", "[creature] 카드가 영계에 도장을 남긴다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature]s owner may choose a creature they control. That creature gains 1 health.", "주인의 턴이 끝날 때 [creature] 카드의 주인이 자신이 조종하는 피조물 하나를 고를 수 있다. 그 피조물의 체력이 1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healshield", "치유 보호막", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] does not take damage during a turn, it will gain Armor at the start of its owner's next turn.", "[creature] 카드가 한 턴 동안 피해를 받지 않으면 주인의 다음 턴이 시작될 때 방어구를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herald", "전령", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] attacks an opposing creature and it perishes, creatures to the left and right of this card gain 1 power.", "[creature] 카드가 맞은편 피조물을 공격해 죽이면 이 카드 양옆의 피조물의 공격력이 1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "High Powered", "고출력", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of its owners turn, [creature] will consume 1 energy.", "주인의 턴이 시작될 때 [creature] 카드가 에너지를 1 소비한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Home Run", "홈런", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will remember the lane in which it was played, and will always attack that lane.", "[creature] 카드는 자신이 나온 공격로를 기억하고 항상 그 공격로를 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hook Line And Sinker", "낚시 미끼 세트", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, the opposing creature will be pulled into it's old space.", "[creature] 카드가 전투로 사망하면 맞은편 피조물이 원래 자리로 끌려온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hypermorphic", "초변형", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, [creature] will transform into a random card of the same type and quality.", "매 턴이 끝날 때 [creature] 카드가 같은 유형과 품질의 무작위 카드로 변한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignition", "점화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a creature, that creature gains the Burning sigil.", "[creature] 카드가 피조물을 공격하면 그 피조물이 연소 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Immaculate Form", "무결한 형상", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, the gems cost of all friendly creatures is reduced by 2 gems.", "[creature] 카드가 보드에 있는 동안 모든 아군 피조물의 보석 비용이 2개 감소한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Immaterial", "실체 없는 존재", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any attacks made against [creature] during the opponents turn will pass straight through, and hit the creature's owner directly.", "상대의 턴 동안 [creature] 카드를 향한 공격은 그대로 통과해 주인에게 직접 적중한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Immortal Coil", "불멸의 고리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive on the board, any friendly creatures that die to combat will return to the owner's hand, though slightly weakened.", "[creature] 카드가 살아서 보드에 있는 동안 전투로 죽은 아군 피조물은 조금 약해진 채 주인의 패로 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incontinent", "실금", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, a mess is created in its place and a card bearing this sigil moves to the right.", "[creature] 카드가 공격받으려 하면 원래 자리에 오물 덩어리가 생성되고 이 도장을 지닌 카드는 오른쪽으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspiring Sacrifice", "고무하는 희생", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it grants its sigils to the creature it was sacrificed for.", "[creature] 카드가 희생되면 그 희생으로 낸 피조물에게 자신의 도장을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Instant Effect", "즉시 효과", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After resolving on the board, [creature] will immediately perish.", "[creature] 카드는 보드에서 효과를 처리한 뒤 즉시 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Killing Joke", "살인 농담", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly creatures which cost an orange gem will either gain +1 power or -1 power when played.", "[creature] 카드가 보드에 있는 동안 오렌지색 보석을 비용으로 요구하는 모든 아군 피조물은 나올 때 공격력이 +1 또는 -1 변한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] randomly modifies the power of the Orange Gem cost card!", "[creature] 카드가 오렌지색 보석을 비용으로 요구하는 카드의 공격력을 무작위로 바꾼다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kin Bearer", "친족 운반자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a random creature of the same tribe is created in your hand.", "[creature] 카드가 사망하면 같은 부족의 무작위 피조물이 당신의 패에 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kindred", "동족", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, random common creatures of the same tribe will be played for free to its left and right.", "[creature] 카드를 내면 양옆에 같은 부족의 무작위 일반 피조물이 비용 없이 나온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "L33p Leaver", "점프봇 남기기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn,[creature] will move in the direction inscrybed in the sigil and drop a L33pB0t in its old place.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 이동하고 원래 자리에 L33pB0t을 남긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Landscaper", "조경사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] is played, any terrain cards on the board are removed and added to it's owner's hand.", "[creature] 카드를 내면 보드의 모든 지형 카드가 제거되어 이 카드 주인의 패에 들어간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lash Out", "난격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn,[creature] will attack a random opposing slot.", "주인의 턴이 끝날 때 [creature] 카드가 상대의 무작위 슬롯을 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Airborne Latch", "공수 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the airborne sigil.", "[creature] 카드가 사망하면 주인이 피조물 하나를 골라 공수 도장을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Latch", "구타유발자 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the annoying sigil.", "[creature] 카드가 사망하면 주인이 피조물 하나를 골라 구타유발자 도장을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Latch", "연소 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the burning sigil.", "[creature] 카드가 사망하면 주인이 피조물 하나를 골라 연소 도장을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burrower Latch", "굴살이 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the burrower sigil.", "[creature] 카드가 사망하면 주인이 피조물 하나를 골라 굴살이 도장을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frail Latch", "연약함 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the frail sigil.", "[creature] 카드가 사망하면 주인이 피조물 하나를 골라 연약한 도장을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temporarily Gemified", "일시적 보석화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] has been temporarily gemified until the end of battle.", "[creature] 카드는 전투가 끝날 때까지 일시적으로 보석화되어 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Latch", "보석 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When[creature] perishes, its owner chooses a creature to become gemified.", "[creature] 카드가 사망하면 주인이 피조물 하나를 골라 보석화한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunter Latch", "망령 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the haunter sigil.", "[creature] 카드가 사망하면 주인이 피조물 하나를 골라 망령 도장을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Null Latch", "무효화 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the null conduit sigil.", "[creature] 카드가 사망하면 주인이 피조물 하나를 골라 무효화 전도체 도장을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overclocked Latch", "오버클록 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain 1 power, and the overclocked sigil.", "[creature] 카드가 사망하면 주인이 피조물 하나를 골라 공격력을 1 높이고 오버클록 도장을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sniper Latch", "저격 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the sniper sigil.", "[creature] 카드가 사망하면 주인이 피조물 하나를 골라 저격자 도장을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sprinter Latch", "질주자 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the sprinter sigil.", "[creature] 카드가 사망하면 주인이 피조물 하나를 골라 질주자 도장을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalwart Latch", "굳건함 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the stalwart sigil.", "[creature] 카드가 사망하면 주인이 피조물 하나를 골라 굳건함 도장을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Totem Latch", "토템 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the sigil on their current totem.", "[creature] 카드가 사망하면 주인이 피조물 하나를 골라 자신의 현재 토템에 있는 도장을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Waterborne Latch", "수생 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the waterborne sigil.", "[creature] 카드가 사망하면 주인이 피조물 하나를 골라 수생 도장을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaper", "뛰어넘기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil, leaping over single card obstructions.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 이동하며 카드 한 장짜리 장애물을 뛰어넘는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it creates a number of cards in the owner's hand equal to it's remaining HP, then perishes.", "[creature] 카드가 공격받으면 남은 체력만큼 주인의 패에 카드를 생성한 뒤 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lockdown", "봉쇄", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the opposing creature loses attack power equal to the power of this card and gains the Stalwart sigil.", "[creature] 카드를 내면 맞은편 피조물의 공격력이 이 카드의 공격력만큼 감소하고 굳건함 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] locks the opposing creature in place!", "[creature] 카드가 맞은편 피조물을 그 자리에 묶는다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonesome", "외로운", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains +1 power for each adjacent empty space.", "인접한 빈칸마다 [creature] 카드의 공격력이 +1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lurk", "잠복 보초", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerges during the opponent's turn. When a creature moves into the space opposing [creature], they are dealt 1 damage.", "상대의 턴 동안 잠수한다. 피조물이 [creature] 카드 맞은편 칸으로 이동하면 그 피조물이 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magitech", "마법 공학", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive and on the board, playing a mox gem will provide it's owner with an energy cell.", "[creature] 카드가 살아서 보드에 있는 동안 목스 보석이 나오면 주인에게 에너지 셀 하나가 제공된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] channels electrical power through your gems!", "[creature] 카드가 당신의 보석을 통해 전력을 흐르게 한다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malware", "악성코드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may not play [creature] unless you are three or less damage away from losing the game.", "패배까지 남은 피해가 셋 이하일 때만 [creature] 카드를 낼 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marcescent", "시들어도 남음", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, this card gains it's attack power.", "[creature] 카드가 맞은편 피조물을 공격해 죽이면 이 카드가 그 피조물의 공격력을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mason", "석공", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random obelisk is created in your hand.", "[creature] 카드를 내면 당신의 패에 무작위 오벨리스크가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mauler", "맹타", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal overkill damage directly to the opponent.", "[creature] 카드는 초과 피해를 상대에게 직접 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Medicinal", "묘약", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it heals all friendly creatures by 2 and removes all negative sigils from friendly creatures.", "[creature] 카드를 내면 모든 아군 피조물의 체력을 2 회복하고 아군 피조물의 부정적인 도장을 모두 제거한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirrific", "거울 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it's owner chooses a creature to gain the Mirror rorriM ability.", "[creature] 카드가 사망하면 주인이 피조물 하나를 골라 '거울울거' 능력을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mockery", "조롱", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is played opposite an opponent's creature, it's stats change to mimic that creature's stats.", "[creature] 카드가 상대 피조물 맞은편에 나오면 자신의 능력치가 그 피조물과 같아진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morph Mover", "이동 변이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced by a random movement related sigil.", "[creature] 카드를 뽑으면 이 도장이 무작위 이동 관련 도장으로 교체된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Motivator", "투지의 원천", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a creature, that creature gains 1 power.", "[creature] 카드가 피조물을 공격하면 그 피조물의 공격력이 1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moxcraft", "목스크래프트", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, a random mox is created in your hand.", "[creature] 카드가 공격받으면 당신의 패에 무작위 목스가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Max", "목스 맥스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot be played unless two cards which grant its respective mox cost colour are present on the owners side of the board.", "주인 측 보드에 필요한 목스 비용의 색을 제공하는 카드가 두 장 있어야 [creature] 카드를 낼 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moxwarp", "목스 워프", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive on the board, any enemy attack that enters a sapphire mox will be returned out of all ruby mox, and vice versa.", "[creature] 카드가 살아서 보드에 있는 동안 사파이어 목스로 들어오는 모든 적의 공격은 모든 루비 목스에서 반사되어 나온다. 그 반대도 마찬가지다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mystery Mox", "신비의 목스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced by a random gem-granting sigil.", "[creature] 카드를 뽑으면 이 도장이 보석을 제공하는 무작위 도장으로 교체된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nature Of The Beast", "야수의 본성", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a completely random creature is created in the owner's hand.", "[creature] 카드가 사망하면 주인의 패에 완전히 무작위인 피조물이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obedient", "순종", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move to an empty space on the same side of the board, chosen by it's owner.", "주인의 턴이 끝날 때 [creature] 카드는 주인이 고른 같은 편 보드의 빈칸으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Odd Strike", "홀수 공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike all opposing spaces in odd indexed columns when it attacks. Column index is counted from the left, starting at 1.", "[creature] 카드는 공격할 때 홀수 번호 열의 맞은편 칸을 모두 공격한다. 열 번호는 왼쪽에서 1부터 센다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Omni Guardian", "전능한 수호자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all friendly creatures on the board gain armour.", "[creature] 카드를 내면 보드의 모든 아군 피조물이 방어구를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gives the Armored sigil to all friendly creatures.", "[creature] 카드가 모든 아군 피조물에게 장갑 도장을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crusher", "쇄석자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a terrain card.", "[creature] 카드는 지형 카드를 마주하면 공격력이 2 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deerly Departed", "사슴 사냥꾼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a creature of the Hooved tribe.", "[creature] 카드는 유제류 부족 피조물을 마주하면 공격력이 2 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dog Gone", "개 사냥꾼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a creature of the Canine tribe.", "[creature] 카드는 개 부족 피조물을 마주하면 공격력이 2 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fowl Play", "조류 농락", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a creature of the Avian tribe.", "[creature] 카드는 조류 부족 피조물을 마주하면 공격력이 2 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insectivore", "곤충 포식자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a creature of the Insect tribe.", "[creature] 카드는 곤충 부족 피조물을 마주하면 공격력이 2 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snakebite", "뱀 사냥꾼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 2 power when opposed by a creature of the Reptile tribe.", "[creature] 카드는 파충류 부족 피조물을 마주하면 공격력이 2 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Inspiration", "오렌지 영감", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While[creature] is on the board, all friendly cards which cost an orange gem gain +1 power.", "[creature] 카드가 보드에 있는 동안 오렌지색 보석을 비용으로 요구하는 모든 아군 카드의 공격력이 +1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Organ Thief", "장기 도둑", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, it's remains are created in your hand.", "[creature] 카드가 다른 피조물을 죽이면 그 피조물의 잔해가 당신의 패에 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Osteoklepty", "뼈 도둑질", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it steals all of the opponents bones for it's owner.", "[creature] 카드를 내면 상대의 모든 뼈를 훔쳐 주인에게 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Other Side", "저편", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, any friendly creatures that die in combat will be returned to the owner's hand as skeletons.", "[creature] 카드가 보드에 있는 동안 전투로 죽은 모든 아군 피조물은 해골이 되어 주인의 패로 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Presence", "고통스러운 존재", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On upkeep, all creatures adjacent to [creature] vertically, horizontally, or diagonally take 1 damage.", "주인의 턴 시작 시 [creature] 카드와 세로, 가로 또는 대각선으로 인접한 모든 피조물이 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paralytic", "마비", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a creature, that creature loses 1 power.", "[creature] 카드가 피조물을 공격해 맞히면 그 피조물은 공격력을 1 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parthenogenesis", "단위생식", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies to combat, a larval form is left in it's old space that evolves into an exact clone after 1 turn.", "[creature] 카드가 전투로 죽으면 원래 칸에 유충 형태를 남기며, 유충은 1턴 뒤 원본과 완전히 같은 복제체로 진화한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect Form", "완벽한 형태", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, the gems cost of all friendly creatures is reduced by 1 gem.", "[creature] 카드가 보드에 있는 동안 모든 아군 피조물의 보석 비용이 1개 줄어든다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantasmic", "환영 이동", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will move in the direction inscribed in the sigil, phasing past obstacles and wrapping around to the other side of the board if movement is impossible.", "턴 종료 시 [creature] 카드는 도장에 표시된 방향으로 장애물을 통과하며 이동하고, 이동할 수 없으면 보드의 반대쪽 끝으로 넘어간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Piercing", "관통", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a slot which has a creature queued behind it, the queued creature will take 1 damage.", "[creature] 카드가 공격한 슬롯 뒤에 대기 중인 피조물이 있으면 그 피조물은 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pinnacle Strike", "정점의 일격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike all opponent spaces when it attacks.", "[creature] 카드는 공격할 때 상대의 모든 칸을 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Point Nemo", "포인트 니모", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all creatures on the board gain the Waterborne sigil.", "[creature] 카드를 내면 보드의 모든 피조물이 수생 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Potent", "강력한 희생", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, the creature it was sacrificed for gains a random sigil.", "[creature] 카드가 희생되면 그 희생으로 낸 피조물이 무작위 도장을 하나 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Preemptive Strike", "선제공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack once when first played.", "[creature] 카드는 처음 내면 한 번 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] makes a free attack!", "[creature] 카드가 추가 공격을 한다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Propagation", "번식", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, a creature is created on the board to the left or right of this card.", "[creature] 카드가 맞은편 피조물을 공격해 죽이면 이 카드의 왼쪽이나 오른쪽 칸에 피조물이 하나 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prophecy", "예언", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may look at three cards from your deck and choose them in order. The next three cards you draw will be the cards you were shown, in the order that you chose them.", "[creature] 카드를 내면 덱의 카드 세 장을 보고 순서를 정할 수 있다. 다음에 뽑는 세 장은 여기서 정한 순서대로 그 카드들이 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will allow you to choose from three cards. These three cards will be the next three cards you draw from your deck, in the order you choose them here.", "카드 세 장 중에서 고르게 해 주지. 다음에 덱에서 뽑을 세 장은 이 카드들이다. 순서는 여기서 네가 정한 대로다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose three creatures, and alter your next draws.", "피조물 셋을 골라 다음에 뽑을 카드를 바꾸어라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know how this goes.", "어떻게 하는지는 알겠지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose from three cards. These three cards will be the next three cards you draw from your deck, in the order you chose them.", "카드 세 장 중에서 골라라. 다음에 덱에서 뽑을 세 장은 네가 고른 순서대로 이 카드들이 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose your next three draws.", "다음에 뽑을 카드 세 장을 골라라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmmm... your new prophecy overwrites the old, it would seem.", "흠... 새 예언이 옛 예언을 덮어쓴 모양이군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your new prophecy overwrites the old!", "새 예언이 옛 예언을 덮어썼다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm... very well", "흠... 좋다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not have enough cards left for a prophecy.", "남은 카드가 부족해 예언할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't have enough cards left to make a new prophecy!", "남은 카드가 부족해 새 예언을 할 수 없다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pure Heart", "순수한 마음", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Pinnacle Mox is created in its place.", "[creature] 카드가 죽으면 그 자리에 정점의 목스가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pushover", "만만한 상대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is opposed by an enemy creature, the card will perish.", "[creature] 카드의 맞은편에 적 피조물이 있으면 이 카드는 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Put Sentry Here", "여기에 보초 설치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Sentry Drone is created to its left and right.", "[creature] 카드를 내면 그 왼쪽과 오른쪽에 감시 드론이 하나씩 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quad Strike", "사연격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space to the left and right of the spaces across from it as well as striking the space in front of it an additional time.", "[creature] 카드는 맞은편 칸의 왼쪽과 오른쪽을 공격하며, 정면 칸을 추가로 한 번 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quickdraw", "속사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will automatically play itself from your deck onto a random space at the start of each battle.", "매 전투 시작 시 [creature] 카드는 당신의 덱에서 무작위 칸으로 자동으로 나온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ranger", "레인저", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may choose an opponent creature. That creature will take 10 damage.", "[creature] 카드를 내면 그 주인은 상대 피조물을 하나 선택할 수 있다. 선택한 피조물은 피해를 10 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ravenous", "굶주림", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills a creature, it will gain an additional strike against the opposing space until the end of combat.", "[creature] 카드가 피조물을 죽이면 전투가 끝날 때까지 맞은편 칸을 공격하는 횟수가 한 번 늘어난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recharge", "힘 모으기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner regains 1 energy. Does not affect the current energy maximum.", "[creature] 카드를 내면 그 주인은 에너지를 1 회복한다. 현재 에너지 최대치는 바뀌지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recycle", "재활용", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, when any friendly creature perishes by combat a special card will be created in the owners hand. The card created depends on the temple of the friendly card which perishesd.", "[creature] 카드가 보드에 있는 동안 아군 피조물이 전투로 죽을 때마다 주인의 패에 특수 카드가 생성된다. 생성되는 카드는 죽은 아군 카드의 사원에 따라 달라진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reflective", "반사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is opposed by a creature, it gains power equal to the opposing creatures power.", "[creature] 카드의 맞은편에 피조물이 있으면 그 피조물의 공격력만큼 공격력을 추가로 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regenerator", "재생자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owners turn, [creature] will heal 1 health.", "주인의 턴 시작 시 [creature] 카드는 체력을 1 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] regenerates one health!", "[creature] 카드가 체력을 1 회복한다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rememberance", "추억", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may search their graveyard for a card. This sigil is replaced by that cards sigils.", "[creature] 카드를 내면 그 주인은 묘지에서 카드 한 장을 선택할 수 있다. 이 도장은 선택한 카드의 도장들로 대체된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remote Controlled", "원격 조종", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Remote Controller is created in the owner's hand. When the remote controller is struck, [creature] will attack the striker.", "[creature] 카드를 내면 주인의 패에 리모컨이 생성된다. 리모컨이 공격받으면 [creature] 카드가 그 공격자를 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reroute", "경로 변경", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will swap places with a random creature on the same side of the board.", "턴 종료 시 [creature] 카드는 보드의 같은 편에 있는 무작위 피조물과 위치를 바꾼다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resilient", "강인함", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All damage taken by [creature] is reduced to 1.", "[creature] 카드가 받는 모든 피해가 1로 줄어든다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Retreat", "후퇴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it will move to a random empty space on the same side of the board.", "[creature] 카드가 공격받으면 보드의 같은 편에 있는 무작위 빈칸으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Return Strike", "반격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, it attacks in retaliation.", "[creature] 카드는 공격받으면 반격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revolve", "회전", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all cards on the board are moved one space clockwise.", "[creature] 카드를 내면 보드의 모든 카드가 시계 방향으로 한 칸 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ripper", "해체자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will move to and destroy any free, 1 health, non-terrain creatures played, and becomes stronger for each one consumed.", "[creature] 카드와 같은 편에 다른 지형이 아닌 피조물을 낼 때, 그 피조물이 비용이 없고 최대 체력이 1이거나 염소라면 이 카드는 이를 파괴하고 그 칸으로 이동한다(굳건함이 있으면 이동하지 않는다). 하나를 먹을 때마다 강해진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rock Eater", "바위 포식자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a Terrain card is played on the same side of the board as [creature], it will be consumed, granting it's stats and sigils to the card.", "[creature] 카드와 보드의 같은 편에 지형 카드를 내면 그 지형은 먹히고, 이 카드가 지형의 능력치와 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Core", "루비 핵", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Ruby Vessel is created in its place.", "[creature] 카드가 죽으면 그 자리에 루비 그릇이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Running Strike", "질주 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] will move in the direction inscribed on the sigil, striking the space opposing it's destination as it does so.", "공격 후 [creature] 카드는 도장에 표시된 방향으로 이동하며 목적지의 맞은편 칸을 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rupture", "파열", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage to a creature, half of that damage, rounded down, is also dealt to that creature's owner.", "[creature] 카드가 피조물에게 피해를 주면 그 피해의 절반을 내림한 만큼 그 피조물의 주인에게도 피해를 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sanguine", "핏빛 힘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is sacrificed, [creature] gains 1 power until the end of combat.", "피조물이 희생될 때마다 [creature] 카드는 전투가 끝날 때까지 공격력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Core", "사파이어 핵", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Sapphire Vessel is created in its place.", "[creature] 카드가 죽으면 그 자리에 사파이어 그릇이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Heart", "사파이어 심장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Sapphire Mox is created in its place.", "[creature] 카드가 죽으면 그 자리에 사파이어 목스가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Savage Ritual", "야만의 의식", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it attacks once before dying.", "[creature] 카드가 희생되면 죽기 전에 한 번 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sentriple", "삼중 보초", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], they, as well as any creatures to their left or right, are dealt 1 damage.", "피조물이 [creature] 카드의 맞은편 칸으로 이동하면 그 피조물과 그 왼쪽과 오른쪽의 피조물이 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharp Bones", "날카로운 뼈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is dealt damage equal to half the number of bones its owner has, rounded down.", "[creature] 카드가 공격받으면 공격자는 이 카드 주인의 뼈 수의 절반을 내림한 만큼 피해를 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharper Quills", "더 뾰족한 깃", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is dealt 2 damage.", "[creature] 카드가 공격받으면 공격자는 피해를 2 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharpest Quills", "가장 뾰족한 깃", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is dealt 3 damage.", "[creature] 카드가 공격받으면 공격자는 피해를 3 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sharp Shot", "날카로운 사격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it gains +2 power and attacks once before dying.", "[creature] 카드는 죽을 때 공격력을 +2 얻고 죽기 전에 한 번 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sigil Mimic", "도장 모방", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is played opposite an opponent's creature, this sigil is replaced by copies of that creatures sigils.", "상대 피조물의 맞은편에 [creature] 카드를 내면 이 도장은 그 피조물의 도장 복사본들로 대체된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will also strike the slot to the left of the opposing slot when it attacks.", "[creature] 카드는 공격할 때 맞은편 슬롯의 왼쪽 슬롯도 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Siphon", "흡수관", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures to the left of [creature] lose all attack power. That attack power is instead added to this card's power.", "[creature] 카드 왼쪽의 피조물은 공격력을 모두 잃고, 그 공격력이 대신 이 카드의 공격력에 더해진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skin Animator", "가죽 인형 조종사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive on the board, all pelts gain it's attack power.", "[creature] 카드가 살아서 보드에 있는 동안 모든 가죽은 이 카드의 공격력만큼 공격력을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skull Swarm", "해골 떼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive and on the board, all Skeletons will strike twice when attacking.", "[creature] 카드가 살아서 보드에 있는 동안 모든 해골은 공격할 때 두 번 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimeball", "점액 덩이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it permanently stains the opposing slot with slime. Any creatures in a slimy slot without made of stone lose 1 power.", "[creature] 카드를 내면 맞은편 슬롯을 영구적으로 점액으로 더럽힌다. 점액이 묻은 슬롯에 있는 굳건함 도장이 없는 피조물은 공격력을 1 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snapshot", "스냅샷", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the entire board reverts to the state it was in when [creature] was placed.", "[creature] 카드가 죽으면 보드 전체가 [creature] 카드를 놓았을 때의 상태로 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snare", "포획", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played opposite a creature, that creature is ensnared and stored within the bearer, being released when the bearer perishes.", "피조물의 맞은편에 [creature] 카드를 내면 그 피조물을 붙잡아 이 카드 안에 가둔다. 이 카드가 죽으면 풀려난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snip", "싹둑", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the creature opposing it is removed from the board without triggering on-death effects.", "[creature] 카드를 내면 맞은편 피조물은 죽음 효과를 발동하지 않고 보드에서 제거된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cuts it's opponent in half.", "[creature] 카드가 상대를 반으로 자른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soak", "흡수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any damage taken by [creature] is reduced by 1. Taking damage decrements the timer rendered on this sigil. When the timer rendered on this sigil reaches 0, the bearer will attack with power equal to it's health, then perish.", "[creature] 카드가 받는 피해가 1 줄어든다. 피해를 받을 때마다 이 도장에 표시된 타이머가 줄어든다. 타이머가 0이 되면 이 카드는 자신의 체력과 같은 공격력으로 공격한 뒤 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiders Web", "거미줄", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When any opponent card moves, with the exception of entering the board for the first time,[creature] will strike them for one damage.", "상대 카드가 움직일 때마다 처음 보드에 나오는 경우를 제외하고 [creature] 카드가 그 카드에 피해를 1 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Splash Damage", "범위 피해", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a slot, creatures to the left and right of the struck slot will be dealt 1 damage.", "[creature] 카드가 슬롯을 공격하면 그 슬롯의 왼쪽과 오른쪽에 있는 피조물은 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Splash Zone", "피해 확산 구역", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the creatures to it's left or right are also dealt 1 damage.", "[creature] 카드가 공격받으면 그 왼쪽이나 오른쪽의 피조물도 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The damage dealt to [creature] splashes out to its comrades.", "[creature] 카드가 받은 피해가 동료들에게 튄다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Split Detonation", "대각선 폭파", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, diagonally adjacent enemy creatures are dealt 10 damage.", "[creature] 카드가 죽으면 대각선으로 인접한 적 피조물은 피해를 10 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Split Sentry", "분산 보초", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], any creatures to their left or right are dealt 1 damage.", "피조물이 [creature] 카드의 맞은편 칸으로 이동하면 그 피조물의 왼쪽과 오른쪽에 있는 피조물은 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spurred", "박차", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power while the slot opposing it is occupied.", "맞은편 슬롯이 차 있는 동안 [creature] 카드는 공격력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Dependent", "다람쥐 의존", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls no Squirrels, [creature] will perish. If this card is a squirrel, it cannot support itself.", "[creature] 카드의 주인이 조종하는 다람쥐가 없으면 [creature] 카드는 죽는다. 이 카드 자신이 다람쥐여도 스스로를 유지할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel King", "다람쥐 왕", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature, a squirrel is created in the owner's hand.", "[creature] 카드가 맞은편 피조물을 공격하면 주인의 패에 다람쥐가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stalwart", "굳건함", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is moved from the space it was placed in, it will immediately move back, shunting any card which may have moved there in the meantime out of the way.", "[creature] 카드는 처음 놓인 칸에서 옮겨지면 즉시 원래 칸으로 돌아가며, 그사이 그 칸에 들어온 카드를 밀어낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sticky Trail", "점액 자취", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] enters a space on the board, it permantently marks that space with its slime. Any creatures that enter that space without the Made of Stone sigil lose 1 power.", "[creature] 카드가 보드의 칸에 들어가면 그 칸에 영구적으로 점액을 남긴다. 굳건함 도장이 없는 피조물이 그 칸에 들어가면 공격력을 1 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sturdy", "난공불락", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All damage taken by [creature] is reduced by 1.", "[creature] 카드가 받는 모든 피해가 1 줄어든다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Subaquatic Spines", "수중 가시", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will submerge during the opponent's turn. While submerged, opposing creatures attack it's owner directly, and will take 1 damage after attacking.", "[creature] 카드는 상대의 턴에 잠수한다. 잠수 중에는 맞은편 피조물이 이 카드의 주인을 직접 공격하고 공격 후 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "소환사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner may choose from a selection of random cards to add to their hand.", "[creature] 카드를 내면 그 주인은 무작위 카드 후보 중에서 한 장을 골라 패에 넣을 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Supercharge", "과충전", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it refreshes it's owner's energy to the current maximum.", "[creature] 카드를 내면 그 주인의 에너지가 현재 최대치까지 회복된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] restores it's owner's energy.", "[creature] 카드가 주인의 에너지를 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surging Quills", "솟구치는 깃", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, the striker is dealt damage equal to the amount of times this has been struck.", "[creature] 카드가 공격받으면 공격자는 이 카드가 공격받은 횟수만큼 피해를 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sweeping Strike Left", "왼쪽 휩쓸기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will always attack the leftmost opponent creature. Overkill damage travels to the right instead of to the backlane.", "[creature] 카드는 항상 맨 왼쪽 상대 피조물을 공격한다. 초과 피해는 뒷줄 대신 오른쪽으로 전달된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sweeping Strike Right", "오른쪽 휩쓸기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will always attack the rightmost opponent creature. Overkill damage travels to the left instead of to the backlane.", "[creature] 카드는 항상 맨 오른쪽 상대 피조물을 공격한다. 초과 피해는 뒷줄 대신 왼쪽으로 전달된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Switch Strike", "전환 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owners turn [creature] will alternate between striking to the left or right of the opposing slot when it attacks, in addition to striking the opposing slot.", "[creature] 카드는 일반 공격 시 맞은편 슬롯과 그 왼쪽이나 오른쪽을 함께 공격한다. 주인의 턴이 끝날 때 추가 공격의 방향이 바뀐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swooping Strike", "급강하 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing space a second time when attacking. Also, [creature]'s first strike each turn will occur directly, over opponent creatures.", "[creature] 카드는 공격할 때 맞은편 칸을 한 번 더 공격한다. 또한 [creature] 카드의 매 턴 첫 공격은 상대 피조물을 넘어 상대를 직접 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Telepathic", "텔레파시", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly creatures will stike the most powerful opponent card when they attack.", "[creature] 카드가 보드에 있는 동안 모든 아군 피조물은 공격할 때 상대 카드 중 공격력이 가장 높은 카드를 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tempting Target", "솔깃한 표적", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If an opponent creature would strike a space adjacent to [creature], it will instead strike [creature].", "상대 피조물이 [creature] 카드에 인접한 칸을 공격하려 하면 대신 [creature] 카드를 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Termatriarch", "흰개미 여왕", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] and a different card bearing the Termite King sigil are alive and on the board, a termite will be created in your hand at the start of your turn.", "[creature] 카드와 흰개미 왕 도장을 지닌 다른 카드가 살아서 보드에 있는 동안 당신의 턴 시작 시 패에 흰개미가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Termite King", "흰개미 왕", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] and a different card bearing the Termatriarch sigil are alive and on the board, a termite will be created in your hand at the start of your turn.", "[creature] 카드와 흰개미 여왕 도장을 지닌 다른 카드가 살아서 보드에 있는 동안 당신의 턴 시작 시 패에 흰개미가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TestSigil", "테스트 도장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will most likely fuck shit up.", "[creature] 카드는 십중팔구 모든 걸 존나 엉망으로 만들 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thief", "도둑", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will grant an amount of currency when it kills another creature.", "[creature] 카드가 다른 피조물을 죽이면 일정량의 화폐를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time Travel", "시간 여행", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is played, the opponent is obligated to skip their next turn.", "[creature] 카드를 내면 상대는 다음 턴을 건너뛰어야 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll pass my next turn.", "다음 턴은 넘기지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your opponent must skip their next turn!", "상대는 다음 턴을 건너뛰어야 한다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ugh. Fine. I'll pass.", "으. 알았어. 넘길게.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fair enough dear, I'll pass.", "그 정도면 공평하구나, 얘야. 넘기마.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tooth Puller", "이빨 뽑기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will add one damage to the scales in the owner's favour, regardless of it's attack power or obstruction.", "주인의 턴 종료 시 [creature] 카드는 공격력이나 방해물과 관계없이 저울에 주인에게 유리한 피해를 1 더한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxic", "맹독", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck but does not perish, the striker perishes. Does not affect Made of Stone cards.", "[creature] 카드가 공격받고도 살아남으면 공격자는 죽는다. 굳건함 카드에는 효과가 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s toxicity kills instantly!", "[creature] 카드의 맹독이 즉사시킨다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Traitor", "배신자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it will move onto the opponent's side of the board if unobstructed.", "[creature] 카드를 내면 가로막는 것이 없을 경우 상대편 보드로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trajectile Quills", "발사하는 깃", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck, an opponent creature of the owner's choosing is dealt 1 damage.", "[creature] 카드가 공격받으면 그 주인이 고른 상대 피조물이 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trampler", "짓밟는 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed on the sigil. Cards in the way will be killed, and grant +1 attack power to the sigil bearer.", "주인의 턴 종료 시 [creature] 카드는 도장에 표시된 방향으로 이동한다. 길을 막는 카드는 죽으며, 도장 보유자는 그 카드마다 공격력을 +1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transformer", "변신자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] will transform to or from it's alternate form.", "턴 종료 시 [creature] 카드는 다른 형태로 변하거나 원래 형태로 돌아온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transmogrification", "변형술", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] strikes a creature, that creature will be changed into another form.", "[creature] 카드가 피조물을 공격해 맞히면 그 피조물은 다른 형태로 변한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trapjaw", "덫턱", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack to the left and the right of the opposing space if those slots are obstructed. If those slots are not obstructed, the strikes will be transferred to the directly opposing space.", "[creature] 카드는 맞은편 칸의 왼쪽과 오른쪽을 공격한다. 각 칸이 막혀 있지 않으면 그 칸을 향한 공격은 정면 칸으로 옮겨진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trifling Sacrifice", "소소한 희생", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] counts as 2 Blood rather than 1 Blood when sacrificed.", "[creature] 카드는 희생될 때 피 1 대신 피 2로 계산된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trio", "트리오", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a copy of it is created to the left and right.", "[creature] 카드를 내면 그 왼쪽과 오른쪽에 이 카드의 사본이 한 장씩 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Triple Strike", "삼연격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing space two extra times when attacking.", "[creature] 카드는 공격할 때 맞은편 칸을 추가로 두 번 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trophy Hunter", "전리품 사냥꾼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will target the most powerful opposing card when it attacks.", "[creature] 카드는 공격할 때 상대 카드 중 공격력이 가장 높은 카드를 겨냥한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tuck And Roll", "웅크려 구르기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of combat, [creature] will move to the free space opposed by the least amount of attack power, taking into account queued creatures, flight, and Touch of Death.", "주인의 턴 시작 시 [creature] 카드는 맞서는 공격력이 가장 낮은 빈칸으로 이동한다. 대기 중인 피조물, 비행, 죽음의 손길도 계산에 포함한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tug", "잡아당기기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it will draw the queued opposing creature into the main opposing space, if possible.", "[creature] 카드를 내면 가능할 경우 맞은편에서 대기 중인 피조물을 정면의 앞줄 칸으로 끌어당긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twin Bond", "쌍둥이의 유대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a copy of it is created adjacent, killing other creatures to make room if there is none. These cards share a health pool, and when either card dies, it's twin will die as well.", "[creature] 카드를 내면 인접한 칸에 이 카드의 사본이 생성된다. 빈칸이 없으면 다른 피조물을 죽여 자리를 만든다. 두 카드는 체력을 공유하며, 한쪽이 죽으면 다른 쪽도 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twister", "뒤틀린 변신", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When struck, [creature] will transform to or from it's alternate form.", "[creature] 카드는 공격받으면 다른 형태로 변하거나 원래 형태로 돌아온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unbalanced Leadership", "불균형한 지휘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature directly to the left of [creature] gains 2 power.", "[creature] 카드의 바로 왼쪽에 있는 피조물은 공격력을 2 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Under Pressure", "압박 속에서", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, 2 damage is dealt to the opponent creature. Also, when [creature] perishes, any adjacent creatures with this sigil also take ten damage.", "[creature] 카드가 죽으면 맞은편 피조물은 피해를 2 받는다. 또한 [creature] 카드가 죽으면 이 도장을 지닌 인접한 피조물도 피해를 10 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] pops, dealing 2 damage to the opposing creature!", "[creature] 카드가 터지며 맞은편 피조물에게 피해를 2 준다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unfocused Strike", "무작정 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will target a random space when it attacks.", "[creature] 카드는 공격할 때 무작위 칸을 겨냥한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unhammerable", "망치 면역", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot be killed using the hammer.", "[creature] 카드는 망치로 죽일 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unlucky", "불운", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is alive on the board, cards played by the opponent have a chance to have debuffed stats, or lose a random sigil.", "[creature] 카드가 살아서 보드에 있는 동안 상대가 내는 카드는 일정 확률로 능력치가 약해지거나 무작위 도장 하나를 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unspeakable", "형언할 수 없음", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card you control resolves on the board without being played from your hand, you may choose to play [creature] from your hand or deck instead.", "당신이 조종하는 카드가 패에서 내지 않은 상태로 보드에 나와 효과 처리를 마치면, 대신 패나 덱에서 [creature] 카드를 내기로 선택할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unstable Gems", "불안정한 보석", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all friendly creatures which cost a mox gem will gain the brittle sigil when played.", "[creature] 카드가 보드에 있는 동안 목스 보석 비용이 필요한 모든 아군 피조물은 나올 때 취약성 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] renders the gem cost creature unstable!", "[creature] 카드가 보석 비용을 지닌 피조물을 불안정하게 만든다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valuable", "귀중함", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will grant an amount of currency when it perishes.", "[creature] 카드가 죽으면 일정량의 화폐를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vampiric", "흡혈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks an opposing creature and it perishes, this card gains 1 health.", "[creature] 카드가 맞은편 피조물을 공격해 죽이면 이 카드는 체력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Venator", "변신 사냥꾼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, it will transform to or from it's alternate form.", "[creature] 카드가 다른 피조물을 죽이면 다른 형태로 변하거나 원래 형태로 돌아온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vessel Shedder", "그릇 떨구기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscrybed in the sigil and drop an Empty Vessel in its old place.", "주인의 턴 종료 시 [creature] 카드는 도장에 표시된 방향으로 이동하고 원래 칸에 빈 그릇을 남긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Visceral", "피와 살의 전환", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, any leftover blood that is not used for the sacrifice will be converted into bones.", "[creature] 카드가 희생되면 희생 비용으로 쓰이지 않은 남은 피가 뼈로 바뀐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Viva La Revolution", "혁명 만세", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of its owners turn, [creature] will revolve all creatures on the board clockwise. Also, [creature] will not attack it's original owner.", "주인의 턴 시작 시 [creature] 카드는 보드의 모든 피조물을 시계 방향으로 회전시킨다. 또한 [creature] 카드는 원래 주인을 공격하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Waterbird", "물새", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] strikes a slot containing a submerged creature, that creature will re-emerge and [creature] will attack it instead of attacking directly.", "[creature] 카드가 잠수 중인 피조물이 있는 슬롯을 공격하면 그 피조물이 수면 위로 올라오며, [creature] 카드는 직접 공격하는 대신 그 피조물을 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wavering Strike", "흔들리는 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will alternate between striking to the left or right of where it would otherwise attack at the end of each turn.", "[creature] 카드는 일반 공격 시 원래 공격 대상의 왼쪽이나 오른쪽을 공격한다. 주인의 턴이 끝날 때 방향이 바뀐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weaver", "거미줄 짜는 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed on the sigil and leave a Web in it's old space. [creature] can move back over webs it has placed.", "주인의 턴 종료 시 [creature] 카드는 도장에 표시된 방향으로 이동하고 원래 칸에 거미줄을 남긴다. [creature] 카드는 자신이 놓은 거미줄 위로 돌아갈 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures in the insect tribe will not attack [creature].", "곤충 부족 피조물은 [creature] 카드를 공격하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weird Latch", "기묘한 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced by a random latch sigil.", "[creature] 카드를 뽑으면 이 도장은 무작위 랫치 도장으로 대체된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wild Shape", "야생의 변신", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it transforms based on what gem colours its owner controls.", "[creature] 카드를 내면 주인이 조종하는 보석의 색에 따라 변신한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] transforms based on its owner's gems...", "[creature] 카드가 주인의 보석에 따라 변신한다...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wimpy", "허약함", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage to a creature, it will always deal 1 less damage than it should.", "[creature] 카드가 피조물에게 주는 피해는 항상 원래보다 1 적다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wing Clipper", "날개 자르는 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all opponent creatures with the Airborne sigil lose the Airborne sigil.", "[creature] 카드를 내면 공수 도장을 지닌 모든 상대 피조물이 공수 도장을 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] grounds all its opponents!", "[creature] 카드가 모든 상대를 땅으로 끌어내린다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wingrider", "날개 타는 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a friendly airborne creature is played while [creature] is in the owner's hand, this card will be played adjacent to it.", "[creature] 카드가 주인의 패에 있을 때 아군 비행 피조물이 나오면 이 카드도 그 옆 칸에 나온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woodsie Lord", "숲의 영주", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Enchanted Pines are created on every empty space. An enchanted pine is defined as 0 power, 3 health.", "[creature] 카드를 내면 모든 빈칸에 마력이 깃든 소나무가 생성된다. 마력이 깃든 소나무는 공격력 0, 체력 3이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wriggle", "꿈틀거리기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played it deals 1 damage to all opponent creatures.", "[creature] 카드를 내면 모든 상대 피조물에게 피해를 1 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Writhe", "몸부림", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it will attack all opposing spaces for 1 damage.", "[creature] 카드가 죽으면 상대의 모든 칸을 공격해 각각 피해를 1 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ye filthy dog! Now one o' me maties needs to swab the poop deck!", "이 더러운 개자식! 이젠 내 동료가 선미 갑판을 닦아야 하잖아!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "1d4", "1d4 주사위", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil starts at 2, and will become a random number between 1 and 4 at the start of each subsequent turn.", "이 도장의 값은 처음에는 2이며, 이후 매 턴 시작 시 1부터 4 사이의 무작위 값으로 바뀐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power starts at 2, and will become a random number between 1 and 4 at the start of each subsequent turn.", "[creature] 카드의 공격력은 처음에는 2이며, 이후 매 턴 시작 시 1부터 4 사이의 무작위 값으로 바뀐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ambitious", "야심가", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to highest power number present on the board, regardless of whether the card bearing it is friend or foe. Updates at the start of both the player and opponent turn.", "이 도장의 값은 아군과 적군을 가리지 않고 보드에서 가장 높은 공격력과 같아진다. 플레이어와 상대 양쪽의 턴 시작 시 갱신된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the power of the creature with the highest attack power on the board. Recalculates each turn.", "[creature] 카드의 공격력은 보드에서 공격력이 가장 높은 피조물의 공격력과 같다. 매 턴 다시 계산한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ant Plus Two", "개미 더하기 둘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil is equal to the number of ants on the board, plus two.", "이 도장의 값은 도장을 지닌 카드와 같은 편 보드의 개미 수에 둘을 더한 값과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of friendly ants on the board, plus two.", "[creature] 카드의 공격력은 보드의 아군 개미 수에 둘을 더한 값과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Birds of a Feather", "같은 깃털의 무리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of avian tribe creatures on the board, including opponent creatures.", "이 도장의 값은 상대 피조물을 포함해 보드의 조류 부족 피조물 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of avian tribe creatures on the board, including opponent creatures.", "[creature] 카드의 공격력은 상대 피조물을 포함해 보드의 조류 부족 피조물 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood and Bone", "피와 뼈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the bone cost of the opposing card, or double the blood cost of the opposing card.", "이 도장의 값은 맞은편 카드의 뼈 비용에 피 비용의 두 배를 더한 값과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the bone cost of the opposing creature plus twice the blood cost of the opposing creature.", "[creature] 카드의 공격력은 맞은편 피조물의 뼈 비용에 피 비용의 두 배를 더한 값과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boned", "뼈의 기억", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of bones the owner possessed when the bearer was placed. Does not fluctuate with bone count changes post placement.", "이 도장의 값은 이 카드를 놓았을 때 주인이 보유한 뼈 수와 같다. 놓은 뒤 뼈 수가 바뀌어도 이 값은 변하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s health is equal to the number of bones the owner possessed when it was placed. Does not fluctuate with bone count changes post placement.", "[creature] 카드의 체력은 이 카드를 놓았을 때 주인이 보유한 뼈 수와 같다. 놓은 뒤 뼈 수가 바뀌어도 이 값은 변하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crab Dance", "게 춤", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of crustacean tribe creatures on the board, including opponent creatures.", "이 도장의 값은 상대 피조물을 포함해 보드의 갑각류 부족 피조물 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of crustacean tribe creatures on the board, including opponent creatures.", "[creature] 카드의 공격력은 상대 피조물을 포함해 보드의 갑각류 부족 피조물 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Damage Dice", "피해 주사위", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil starts at 3, and will become a random number between 1 and 6 at the start of each subsequent turn.", "이 도장의 값은 처음에는 3이며, 이후 매 턴 시작 시 1부터 6 사이의 무작위 값으로 바뀐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power starts at 3, and will become a random number between 1 and 6 at the start of each subsequent turn.", "[creature] 카드의 공격력은 처음에는 3이며, 이후 매 턴 시작 시 1부터 6 사이의 무작위 값으로 바뀐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Damage Scaling", "저울 피해", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to five minus the amount of damage until you lose the game.", "이 도장의 값은 패배하기까지 더 받을 수 있는 저울 피해를 다섯에서 뺀 값과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to five minus the amount of damage until you lose the game.", "[creature] 카드의 공격력은 패배하기까지 더 받을 수 있는 저울 피해를 다섯에서 뺀 값과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Director Of The Board", "보드 총괄자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of cards on the board, including opponent cards.", "이 도장의 값은 상대 카드를 포함해 보드의 카드 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the total number of cards on the board, including opponent creatures.", "[creature] 카드의 공격력은 상대 피조물을 포함해 보드의 카드 총수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawn Out", "뽑기의 힘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of cards you have drawn this turn while it's bearer is on the board.", "이 도장의 값은 이번 턴에 이 카드가 보드에 있는 동안 당신이 뽑은 카드 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of cards you have drawn this turn while it is on the board.", "[creature] 카드의 공격력은 이번 턴에 이 카드가 보드에 있는 동안 당신이 뽑은 카드 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fabled", "전설", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to twice the number of rare creatures on the board.", "이 도장의 값은 보드의 희귀 피조물 수의 두 배와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to twice the number of rare creatures on the board.", "[creature] 카드의 공격력은 보드의 희귀 피조물 수의 두 배와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firepower", "화력", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of creatures on the board with the Burning sigil.", "이 도장의 값은 보드에서 연소 도장을 지닌 피조물 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of creatures on the board with the Burning sigil.", "[creature] 카드의 공격력은 보드에서 연소 도장을 지닌 피조물 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Follow The Leader", "리더를 따라서", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the attack power of the first card in your hand.", "이 도장의 값은 당신의 패에서 첫 번째 카드의 공격력과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the attack power of the first card in your hand.", "[creature] 카드의 공격력은 당신의 패에서 첫 번째 카드의 공격력과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greenhorn", "풋내기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to twice the number of Green gems on the owner's side of the board when the bearer was played.", "이 도장의 값은 이 카드를 냈을 때 주인 측 보드에 있던 녹색 보석 수의 두 배와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s health is equal to twice the number of Green gems on it's owner's side of the board when it was played.", "[creature] 카드의 체력은 이 카드를 냈을 때 주인 측 보드에 있던 녹색 보석 수의 두 배와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Half Charged", "절반 충전", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to half the player's current energy, rounded up.", "이 도장의 값은 플레이어의 현재 에너지의 절반을 올림한 값과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to half your current energy, rounded up.", "[creature] 카드의 공격력은 당신의 현재 에너지의 절반을 올림한 값과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand On Heart", "패에 담긴 마음", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of cards in your hand.", "이 도장의 값은 당신의 패에 있는 카드 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s health is equal to the number of cards in your hand.", "[creature] 카드의 체력은 당신의 패에 있는 카드 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Health Damage", "체력 피해", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to it's bearer's current health.", "이 도장의 값은 이 도장을 지닌 피조물의 현재 체력과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to its health.", "[creature] 카드의 공격력은 자신의 체력과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herding Beast", "무리를 모는 야수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of hooved tribe creatures on the board, including opponent creatures.", "이 도장의 값은 상대 피조물을 포함해 보드의 유제류 부족 피조물 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of hooved tribe creatures on the board, including opponent creatures.", "[creature] 카드의 공격력은 상대 피조물을 포함해 보드의 유제류 부족 피조물 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lithophile", "돌을 좋아하는 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of terrain cards on the board.", "이 도장의 값은 보드의 지형 카드 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of terrain cards on the board.", "[creature] 카드의 공격력은 보드의 지형 카드 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magicke Power", "마법의 힘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil is equal to the number of sigils this card has removed with the Bleach Sigil or Artistic License Sigil.", "이 도장의 값은 이 카드가 표백제 도장 또는 예술적 허용 도장으로 제거한 도장 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of sigils it has removed with the Bleach Sigil or Artistic License Sigil.", "[creature] 카드의 공격력은 이 카드가 표백제 도장 또는 예술적 허용 도장으로 제거한 도장 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Half Squirrels", "다람쥐의 절반", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to half the number of Squirrels remaining in your side deck. ", "이 도장의 값은 당신의 보조 덱에 남은 다람쥐 수의 절반과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to half the number of Squirrels remaining in your side deck.", "[creature] 카드의 공격력은 당신의 보조 덱에 남은 다람쥐 수의 절반과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pack Hunter", "무리 사냥꾼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of canine tribe creatures on the board, including opponent creatures.", "이 도장의 값은 상대 피조물을 포함해 보드의 개 부족 피조물 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of canine tribe creatures on the board, including opponent creatures.", "[creature] 카드의 공격력은 상대 피조물을 포함해 보드의 개 부족 피조물 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pack Power", "아이템의 힘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of items the owner holds.", "이 도장의 값은 주인이 가진 아이템 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of items it's owner holds.", "[creature] 카드의 공격력은 주인이 가진 아이템 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pack Power Plus", "아이템의 힘 플러스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to twice the number of items the owner holds.", "이 도장의 값은 주인이 가진 아이템 수의 두 배와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to twice the number of items it's owner holds.", "[creature] 카드의 공격력은 주인이 가진 아이템 수의 두 배와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sanguine Bond", "피의 유대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of sacrifices made on the turn when the bearer was placed.", "이 도장의 값은 이 카드를 놓은 턴에 이루어진 희생 횟수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of sacrifices made on the turn when it was placed.", "[creature] 카드의 공격력은 이 카드를 놓은 턴에 이루어진 희생 횟수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sin Eater", "죄 포식자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the amount of sigils present on the creatures that were sacrificed to play it's bearer.", "이 도장의 값은 이 카드를 내기 위해 희생한 피조물들이 지녔던 도장 총수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the amount of sigils present on the creatures that were sacrificed to play it.", "[creature] 카드의 공격력은 이 카드를 내기 위해 희생한 피조물들이 지녔던 도장 총수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starved", "굶주린", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to seven minus the number of cards left in your deck.", "이 도장의 값은 당신의 덱에 남은 카드 수를 7에서 뺀 값과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to seven minus the number of cards left in your deck.", "[creature] 카드의 공격력은 당신의 덱에 남은 카드 수를 7에서 뺀 값과 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strength In Numbers", "다수의 힘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of creatures bearing this sigil on the board, including opponent creatures.", "이 도장의 값은 상대 피조물을 포함해 보드에서 이 도장을 지닌 피조물 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of creatures bearing the same special damage stat on the board, including opponent creatures.", "[creature] 카드의 공격력은 상대 피조물을 포함해 보드에서 같은 특수 피해 능력치를 지닌 피조물 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trinket Vitality", "장신구의 생명력", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to double the number of items the owner holds.", "이 도장의 값은 주인이 가진 아이템 수의 두 배와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s health is equal to twice the number of items it's owner holds.", "[creature] 카드의 체력은 주인이 가진 아이템 수의 두 배와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "World Wide Web", "월드 와이드 웹", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of arachnid tribe creatures on the board, including opponent creatures.", "이 도장의 값은 상대 피조물을 포함해 보드의 거미류 부족 피조물 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of arachnid tribe creatures on the board, including opponent creatures.", "[creature] 카드의 공격력은 상대 피조물을 포함해 보드의 거미류 부족 피조물 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abstain", "절제", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dupeglitch", "복제 오류", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sinister Strike", "왼쪽 사선 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bully", "불량배", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legion", "군단", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodborn", "피의 자손", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Divination", "점술", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exhume", "발굴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eternal", "영원", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goated", "염소의 축복", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healer", "치유사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After [creature] is played, the opponent is obligated to skip their next turn.", "[creature] 카드를 낸 후 상대는 다음 턴을 건너뛰어야 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, random creatures of the same tribe will be played for free to its left and right.", "[creature] 카드를 내면 그 왼쪽과 오른쪽에 같은 부족의 무작위 피조물이 무료로 나온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owners turn, [creature] will draw opposing creatures in front of itself.", "주인의 턴 시작 시 [creature] 카드는 상대 피조물을 자신의 정면으로 끌어당긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Afterlife", "사후 세계", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a spectral copy of it is created in your hand. This copy lacks the Afterlife sigil, is free, and is both Immaterial and Doomed. ", "[creature] 카드가 죽으면 당신의 패에 이 카드의 유령 사본이 생성된다. 사본은 사후 세계 도장이 없고 비용이 없으며, 실체 없는 존재와 운명에 묶인 자를 모두 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blast Resistant", "폭발 저항", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] would take 10 or more damage from a single source, it takes 1 damage instead.", "[creature] 카드가 한 원인으로부터 피해를 10 이상 받으려 하면 대신 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lanky", "호리호리한", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage directly to the opponent, it will always deal 1 less damage than it should.", "[creature] 카드가 상대에게 직접 주는 피해는 항상 원래보다 1 적다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Peer Pressure", "또래 압박", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains +1 power for each adjacent occupied space.", "인접한 칸이 차 있을 때마다 [creature] 카드는 공격력을 +1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healthy", "건강", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifice [creature] to increase the health of a creature of your choosing by 4.", "[creature] 카드를 희생해 당신이 고른 피조물의 체력을 4 늘린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Micromachine", "마이크로머신", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vagrant Spirit", "떠도는 영체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endoskeleton", "내골격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletal Beast", "해골 야수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buttress", "버팀벽", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil a number of times equal to how many times it damaged another creature this turn.", "주인의 턴 종료 시 [creature] 카드는 이번 턴에 다른 피조물에게 피해를 준 횟수만큼 도장에 표시된 방향으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] does not strike another creature during its turn, it will perish at the start of the owner's next turn.", "[creature] 카드는 자신의 턴에 다른 피조물을 공격해 맞히지 못하면 주인의 다음 턴 시작 시 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unnatural Contraption", "부자연스러운 장치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unnatural Cadaver", "부자연스러운 시체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carrot On A Stick", "막대 끝 당근", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mind Controller", "정신 조종기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mycology", "균류학", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, opposing creatures are drawn into its slot. If two creatures are drawn into the same slot this way, they become merged.", "[creature] 카드가 전투로 죽으면 상대 피조물이 이 카드의 슬롯으로 끌려온다. 이 방식으로 두 피조물이 같은 슬롯에 끌려오면 서로 융합한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mutate", "돌연변이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] destroys another creatre, this gains 1 point. When activated, the owner is presented with a choice of three sigils to augment the card til the end of battle. Selecting a sigil spends points, and the more points accumulated when the sigil is activated, the higher quality the presented sigils will be.", "[creature] 카드가 다른 피조물을 파괴하면 점수를 1 얻는다. 활성화하면 주인은 도장 세 개 중 하나를 골라 전투가 끝날 때까지 이 카드를 강화할 수 있다. 도장을 고르면 점수가 소모되며, 활성화할 때 모인 점수가 많을수록 제시되는 도장의 품질이 높아진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raise Undead", "언데드 소환", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw 3 skeletons from your side deck to your hand.", "[creature] 카드를 내면 당신의 보조 덱에서 해골을 3장 뽑아 패에 넣는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Growth Factor", "성장 인자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When another creature is played opposing [creature], this card gains health equal to that creature's health.", "다른 피조물이 [creature] 카드의 맞은편에 나오면 이 카드는 그 피조물의 체력만큼 체력을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shuffle", "뒤섞기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, every card on the board is shuffled into a random space.", "[creature] 카드를 내면 보드의 모든 카드가 무작위 칸으로 뒤섞인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ambidextrous", "양손잡이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, you draw an additional card at the start of your turn.", "[creature] 카드가 보드에 있는 동안 당신의 턴 시작 시 카드를 한 장 더 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Circuit Dependant", "회로 의존", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is not within a completed circuit, it will perish.", "[creature] 카드는 완성된 회로 안에 없으면 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rapid", "신속", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move as far as possible in the direction inscribed in the sigil.", "주인의 턴 종료 시 [creature] 카드는 도장에 표시된 방향으로 가능한 한 멀리 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resistance", "저항", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is within a completed circuit, it adds 1 power to the conduits making up the circuit.", "[creature] 카드가 완성된 회로 안에 있는 동안 그 회로를 구성하는 전도체는 공격력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dig Deep", "깊이 파기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 bone. This number increases by 1 when [creature] kills another creature.", "주인의 턴 종료 시 [creature] 카드는 뼈를 1개 생성한다. [creature] 카드가 다른 피조물을 죽일 때마다 이 수가 1 늘어난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Startled", "깜짝 놀람", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], this card will transform to or from it's alternate form.", "피조물이 [creature] 카드의 맞은편 칸으로 이동하면 이 카드는 다른 형태로 변하거나 원래 형태로 돌아온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reflexive", "반사 반응", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When its owner is dealt damage directly, [creature] will transform to or from it's alternate form.", "주인이 직접 피해를 받으면 [creature] 카드는 다른 형태로 변하거나 원래 형태로 돌아온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talons", "발톱", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, choose any card on the board. You may move it to any open space on the same side of the board.", "[creature] 카드를 내면 보드의 아무 카드나 선택한다. 그 카드를 보드의 같은 편에 있는 원하는 빈칸으로 옮길 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mycobeast", "균류 야수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mycodaver", "균류 시체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Endoskeleton", "에메랄드 내골격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Endoskeleton", "루비 내골격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Endoskeleton", "사파이어 내골격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may add to a bond, but provides no additional effect.", "[creature] 카드는 결속에 참여할 수 있지만 추가 효과를 주지는 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures that are a part of a bond containing [creature] will gain flight at the start of each turn.", "매 턴 시작 시 [creature] 카드와 같은 결속에 속한 피조물은 비행 능력을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures that are a part of a bond containing [creature] will heal equal to the number of cards in the bond at the start of the owners turn.", "주인의 턴 시작 시 [creature] 카드와 같은 결속에 속한 피조물은 그 결속의 카드 수만큼 체력을 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is part of a completed bond, fill all empty spaces on the same side of the board with squirrels at the end of turn.", "[creature] 카드가 완성된 결속에 속하면 턴 종료 시 보드의 같은 편에 있는 모든 빈칸을 다람쥐로 채운다.", Language.Korean);
        }
    }
    public class AllTheSigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for AllTheSigils Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acid Puddle", "산 웅덩이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A puddle of Acid, dangerous to the touch", "산 웅덩이. 만지면 위험하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jackalope", "잭칼로프", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jacka", "잭카", Language.Korean);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abundance", "풍년", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will grant one tooth per instance of Abundance when killed.", "[creature] 카드가 죽임을 당하면 풍년 중첩 하나당 이빨을 1개 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acidic Trail", "산성 자취", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil, and deal 1 damage to the opposing creature if it is able to move.", "주인의 턴 종료 시 [creature] 카드는 도장에 표시된 방향으로 이동한다. 이동할 수 있으면 맞은편 피조물에게 피해를 1 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Activated Latch Brittle", "활성형 취약성 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When activated for a cost of 1 energy will allow the owner to give a creature Brittle.", "에너지를 1 지불해 활성화하면 주인은 피조물에게 취약성 도장을 줄 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Activated Latch Explode On Death", "활성형 기폭 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When activated for a cost of 1 energy will allow the owner to give a creature Explode On Death.", "에너지를 2 지불해 활성화하면 주인은 피조물에게 기폭 장치 도장을 줄 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Activated Latch Nano Shield", "활성형 나노 보호막 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When activated for a cost of 1 energy / 2 bones will allow the owner to give a creature Nano Shield.", "에너지 1 / 뼈 2를 지불해 활성화하면 주인은 피조물에게 장갑 도장을 줄 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Activated Latch Reach", "활성형 도약 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When activated for a cost of 2 energy will allow the owner to give a creature Reach.", "에너지를 2 지불해 활성화하면 주인은 피조물에게 위대한 도약 도장을 줄 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Agile", "민첩", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, it will move out of the way.", "[creature] 카드는 공격에 맞기 직전 자리를 옮겨 피한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Card jumped out of the way to save itself...", "그 카드는 살아남으려고 옆으로 뛰어 피했다...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trail they leave behind, hurts.", "그들이 남긴 자취는 아프다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All seeing", "모든 것을 보는 눈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all talking cards on your side of the board get +2 health.", "[creature] 카드가 보드에 있는 동안 당신 측 보드의 모든 말하는 카드는 체력을 +2 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alternating Scratch", "번갈아 할퀴기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks it will also attack a space adjacent to the attacked slot, the adjacent slot that it will attack will change between left or right at the end of each opponent's turn.", "[creature] 카드는 공격할 때 대상 슬롯에 인접한 칸도 공격한다. 이 추가 공격 칸은 상대의 매 턴 종료 시 왼쪽과 오른쪽 사이에서 바뀐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ambush", "매복", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], they are dealt 1 damage.", "피조물이 [creature] 카드의 맞은편 칸으로 이동하면 그 피조물은 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antler Bearer", "뿔을 지닌 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is killed, gain three random hooved tribe cards.", "[creature] 카드가 죽임을 당하면 무작위 유제류 부족 카드를 세 장 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The herd sticks together.", "무리는 함께한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shielded", "보호막 방어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is dealt damage, the damage dealt is halved, rounded down.", "[creature] 카드가 받는 피해는 절반으로 줄어들며 내림한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asleep", "휴면", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] has 0 attack for as long as it has this sigil, at the start of the player's turn this sigil will be removed from [creature].", "[creature] 카드는 이 도장을 지닌 동안 공격력이 0이 된다. 플레이어의 턴 시작 시 [creature] 카드에서 이 도장이 제거된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bait", "미끼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opposing creature is played and there is no card opposite of [creature], the opposing creature will move to that spot.", "상대 피조물이 나올 때 [creature] 카드의 맞은편에 카드가 없으면 그 피조물은 그 칸으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noble Sacrifice", "고귀한 희생", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is counted as 2 blood rather than 1 blood when sacrificed.", "[creature] 카드는 희생될 때 피 1 대신 피 2로 계산된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blight", "마름병", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it subtracts its stat values to the card it was sacrificed for.", "[creature] 카드가 희생되면 그 희생으로 낸 카드의 능력치에서 이 카드의 능력치만큼을 뺀다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Strike", "무작위 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike at opponent slots randomly when it attacks.", "[creature] 카드는 공격할 때 상대 슬롯을 무작위로 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blinding Strike", "눈멀리는 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature gains the Random Strikes Sigil.", "[creature] 카드가 다른 피조물에게 피해를 주면 그 피조물은 무작위 타격 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They strike widly...", "마구 공격한다...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Growth", "피의 성장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, the amount of blood it is counted as when sacrificed will increase.", "[creature] 카드가 공격하면 희생될 때 계산되는 피의 양이 늘어난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is power in the blood.", "피에는 힘이 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BloodGuzzler", "피를 들이켜는 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals damage, it gains 1 Health for each damage dealt.", "[creature] 카드는 피해를 1 줄 때마다 체력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain life from the blood.", "피에서 생명을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood shifter", "피의 변신", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another card, it will turn into that card.", "[creature] 카드가 다른 카드를 죽이면 그 카드로 변한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bodyguard", "경호원", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will redirect the initial attack of a card to it, if the attack was targeting a card in an adjacent space.", "카드의 첫 공격이 인접한 칸의 카드를 겨냥하면 [creature] 카드는 그 공격이 자신을 향하게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A protector, till the very end.", "마지막 순간까지 지키는 자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombardier", "폭격벌레", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal 10 damage to a random creature during the end phase of the owner's turn.", "주인의 턴 종료 단계에 [creature] 카드는 무작위 피조물에게 피해를 10 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bond", "유대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any creatures adjacent to [creature] will gain either +1 attack or +1 health, depending on which stat it is closest to.", "[creature] 카드는 왼쪽에 인접한 카드가 있으면 공격력을 +1, 오른쪽에 인접한 카드가 있으면 체력을 +1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gives no bones! Any bones gained from sigils or death will be negated.", "[creature] 카드는 뼈를 주지 않는다! 이 카드의 도장이나 죽음으로 얻는 모든 뼈는 무효가 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That creature has no bones!", "그 피조물은 뼈가 없다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Picker", "뼈 줍는 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] kills a creature, it will generate 1 Bone.", "[creature] 카드가 피조물을 죽이면 뼈를 1개 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Shard", "뼛조각", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will generate 1 bone when hit, if it lives through the attack.", "[creature] 카드가 공격에 맞고도 살아남으면 뼈를 1개 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A splinter of bone.", "작은 뼛조각.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Box", "상자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will get removed from your deck on death, and a new creature contained within will be added to it.", "[creature] 카드는 죽으면 당신의 덱에서 제거되고 그 안에 있던 새 피조물이 덱에 추가된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken", "부서진", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is permanently removed from your deck if it dies.", "[creature] 카드는 죽으면 당신의 덱에서 영구적으로 제거된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is on fire, and will gain 1 power and loose 1 health each upkeep. Blocked by Fire Resistance.", "[creature] 카드는 불타고 있으며, 주인의 매 턴 시작 시 공격력을 1 얻고 체력을 1 잃는다. 내화로 막을 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It rampages while on fire.", "불타면서 날뛴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the towner's turn, [creature] will move in the direction inscribed in the sigil, and drop an acid puddle in their old space.", "주인의 턴 종료 시 [creature] 카드는 도장에 표시된 방향으로 이동하고 원래 칸에 산 웅덩이를 남긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] counts as a Chicken.", "[creature] 카드는 닭으로 취급된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choreography", "안무", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On activation [creature] will cycle through: don't move, move left and move right. At the end of the owner's turn [creature] will move in the chosen way.", "활성화할 때마다 [creature] 카드는 이동하지 않기, 왼쪽 이동, 오른쪽 이동을 차례로 전환한다. 주인의 턴 종료 시 [creature] 카드는 선택한 방식으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coin Finder", "동전 찾는 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will grant the owner 1 foil.", "주인의 턴 종료 시 [creature] 카드는 주인에게 포일을 1 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tooth for your thoughts?", "무슨 생각을 하는지 이빨 하나 받고 말해 줄래?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Consumer", "소비자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, it gains 2 health.", "[creature] 카드가 다른 피조물을 죽이면 체력을 2 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly", "겁쟁이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not attack a card with a power 2 higher than its own.", "[creature] 카드는 자신보다 공격력이 2를 초과해 높은 카드를 공격하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deadly Waters", "죽음의 물결", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will kill cards that attacked over it while it was face-down. Does not affect cards that have Airborne or Made of Stone.", "[creature] 카드는 자신이 뒷면일 때 자신을 넘어 공격한 카드를 죽인다. 공수나 굳건함 도장이 있는 카드에는 효과가 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deathburst", "죽음의 폭발", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal 1 damage to each oppsing space to the left, right, and center of it.", "[creature] 카드가 죽으면 맞은편 칸과 그 왼쪽, 오른쪽 칸에 각각 피해를 1 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the Start of its owner's turn [creature] will lose -1 attack and will gain +1 health.", "주인의 턴 시작 시 [creature] 카드의 공격력이 -1, 체력이 +1 변한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desperation", "절박함", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is damaged to 1 health, it will gain 3 power.", "[creature] 카드는 피해를 받아 체력이 1이 되면 공격력을 3 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When so close to death, it strikes out.", "죽음이 가까워지면 반격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disease Absorbtion", "질병 흡수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When played, [creature] will take all negative sigils onto itself.", "[creature] 카드를 내면 같은 편의 다른 카드들에서 모든 부정적인 도장을 자신에게 옮긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How Noble.", "참 고귀하군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dive (Bones)", "잠수 (뼈)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 bones to cause this card to flip face down at the end of the owner's turn.", "뼈를 2개 지불해 주인의 턴 종료 시 이 카드를 뒷면으로 뒤집는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dive (Energy)", "잠수 (에너지)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 energy to cause this card to flip face down at the end of the owner's turn.", "에너지를 2 지불해 주인의 턴 종료 시 이 카드를 뒷면으로 뒤집는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multi-Strike", "다중 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike a card multiple times, if it lives through the first attack. Will not trigger -on attack- or -on damage- effects with the extra strikes.", "대상 카드가 첫 공격을 받고도 살아남으면 [creature] 카드는 그 카드를 여러 번 공격한다. 추가 공격은 공격 시 또는 피해를 줄 때의 효과를 발동하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double scratch", "이중 할퀴기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks it attacks twice and the space right and left of the attacked slot.", "[creature] 카드는 공격할 때 두 번 공격하고 대상 슬롯의 오른쪽과 왼쪽 칸도 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Blood", "피 그리기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card costing blood is created in your hand.", "[creature] 카드를 내면 당신의 패에 피 비용의 무작위 카드가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Bone", "뼈 그리기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card costing bone is created in your hand.", "[creature] 카드를 내면 당신의 패에 뼈 비용의 무작위 카드가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Card", "카드 그리기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a card relating to it's ice cube parameter (default Stoat) is created in your hand.", "[creature] 카드를 내면 이 카드의 얼음덩이 매개변수에 해당하는 카드가 당신의 패에 생성된다. 기본값은 담비다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Jackalope", "잭칼로프 굴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Jackalope is created in your hand.", "[creature] 카드를 내면 당신의 패에 잭칼로프가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Strafe", "이동 그리기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] moves, a random card with a movement sigil is created in your hand.", "[creature] 카드가 이동하면 당신의 패에 이동 도장을 지닌 무작위 카드가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Cost", "비용 그리기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card that has the same cost type as [creature] is created in your hand.", "[creature] 카드를 내면 당신의 패에 [creature] 카드와 같은 비용 유형의 무작위 카드가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Energy", "에너지 그리기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card costing energy is created in your hand.", "[creature] 카드를 내면 당신의 패에 에너지 비용의 무작위 카드가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Mox", "목스 그리기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random card costing mox is created in your hand.", "[creature] 카드를 내면 당신의 패에 목스 비용의 무작위 카드가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Support call", "지원 요청", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a card from your sidedeck is created in your hand.", "[creature] 카드를 내면 보조 덱의 카드가 당신의 패에 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drunk", "취함", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike a random one of the opposing spaces to the left and right of the space across from it.", "[creature] 카드는 맞은편 칸의 왼쪽이나 오른쪽 중 한 칸을 무작위로 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dwarf", "왜소화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, it will loose one unit of cost, as well as 1 power and 2 health (can't go below 1 health). A unit is defined as: 1 blood, 3 bones, 3 energy, or all mox.", "[creature] 카드를 뽑으면 비용이 한 단위 줄고 공격력을 1, 체력을 2 잃는다. 체력은 1 미만이 되지 않는다. 한 단위는 피 1, 뼈 3, 에너지 3 또는 모든 목스 비용을 뜻한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dying", "죽어 가는 중", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will die after X number of turns.", "[creature] 카드는 X턴 후 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To The Slaughter", "도살장으로", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn [creature] will eat a random Chicken gaining the same amount of attack as the eaten chicken's health, and gaining the same amount of health as the eaten chicken's attack.", "매 턴 종료 시 [creature] 카드는 무작위 닭을 먹고 그 닭의 체력만큼 공격력을, 공격력만큼 체력을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Electric", "전력 유도", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] decalres an attack, they will deal half the damage to cards adjacent to the target.", "[creature] 카드가 공격을 선언하면 대상에 인접한 카드들에게 절반의 피해를 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enforcer", "집행자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, [creature] will cause adjacent creatures to attack.", "주인의 턴 시작 시 [creature] 카드는 인접한 피조물이 공격하게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enrage", "오버클럭 우두머리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will empower adjacent allies, increasing their strenght by 2. However, if they perish while empowered, they are permamently removed from your deck.", "[creature] 카드는 인접한 아군의 공격력을 2 늘린다. 단, 강화된 상태에서 죽으면 당신의 덱에서 영구적으로 제거된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Entomophage", "곤충 포식자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal 2 additional damage to cards of the insect tribe.", "[creature] 카드는 곤충 부족 카드에게 피해를 2 더 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They are a good source of protine I hear.", "좋은 단백질 공급원이라더군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A familiar will help with attacking when it's adjacent allies attack a card.", "사역마는 인접한 아군이 카드를 공격할 때 공격을 돕는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fearful", "겁먹음", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is struck without it resulting in death, it will be returned to its owner's hand.", "[creature] 카드가 공격받고도 살아남으면 주인의 패로 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charge", "충전", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 bones to choose an enemy creature that [creature] will strike.", "뼈를 3개 지불해 [creature] 카드가 공격할 적 피조물을 선택한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firestarter", "들불", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature will gain the Burning Sigil. The Burning Sigil is define as: Each upkeep, this creature gains 1 strength but looses 1 health.", "[creature] 카드가 다른 피조물에게 피해를 주면 그 피조물은 연소 도장을 얻는다. 연소는 해당 피조물 주인의 매 턴 시작 시 그 피조물이 공격력을 1 얻고 체력을 1 잃는 효과다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even once combat is over, it leaves a deadly mark", "전투가 끝나도 치명적인 흔적이 남는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lure", "유인", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will cause facedown cards to become face up when attacking.", "[creature] 카드는 공격할 때 뒷면인 카드를 앞면으로 뒤집는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Submerge are brought back to the surface", "잠수한 피조물이 수면 위로 끌려온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature], a targeted card is moved to the owner's side of the board.", "[creature] 카드를 내면 지정한 카드를 주인 측 보드로 옮긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone lord 5", "뼈의 왕 5", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, 5 bones are rewarded instead of 1.", "[creature] 카드가 죽으면 뼈를 1개 대신 5개 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frightened", "겁에 질림", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], [creature] will move away from that card to a random free adjacent spot, while prioritizing slots without any opposing creatures.", "피조물이 [creature] 카드의 맞은편 칸으로 이동하면 [creature] 카드는 그 피조물에게서 벗어나 인접한 무작위 빈칸으로 이동하며, 맞은편에 피조물이 없는 칸을 우선한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frightful", "무시무시함", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will cause opposing creatures to move out of the way when it attacks.", "[creature] 카드는 공격할 때 상대 피조물을 비켜나게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, it will gain one unit blood of cost, as well as one attack and two health.", "[creature] 카드를 뽑으면 피 비용이 한 단위 늘고 공격력을 1, 체력을 2 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a large creature you have there", "거 참 커다란 피조물이로군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grazing", "풀 뜯기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will regen 1 health if there is no opposing creature.", "주인의 턴 종료 시 맞은편에 피조물이 없으면 [creature] 카드는 체력을 1 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature will heal 1 Health at the end of it's owner's turn.", "이 피조물은 주인의 턴 종료 시 체력을 1 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gripper", "움켜쥐는 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil, and try to move the opposing creature with it if it can.", "주인의 턴 종료 시 [creature] 카드는 도장에 표시된 방향으로 이동하며, 가능하면 맞은편 피조물도 함께 옮기려 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trail they leave behind, hurts.", "그들이 남긴 자취는 아프다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haste", "서두름", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack as soon as it gets played on the board if played not during combat.", "공격 단계가 아닐 때 [creature] 카드를 내면 보드에 나오자마자 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hasteful", "성급한 공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack as soon as it gets played on the board. It will not attack during normal combat. It will attack at the start of the owner's turn.", "[creature] 카드는 보드에 나오자마자 공격한다. 일반 공격 단계에는 공격하지 않고 주인의 턴 시작 시 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herd", "무리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will summon a copy of itself each upkeep, up to three times.", "주인의 턴 시작 시 [creature] 카드는 같은 편의 무작위 빈칸에 자신의 사본을 소환한다. 최대 세 번까지 가능하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hermit", "은둔자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may be placed on any terrain card. If it is their sigils and stats will be combined, and a name combination will be created.", "[creature] 카드는 어떤 지형 카드 위에도 놓을 수 있다. 그러면 양쪽의 도장과 능력치가 합쳐지고 이름도 결합된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "High Tide", "밀물", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, it will grant the waterborne sigil of cards that are played after it on it's side of the board. Does not affect cards that are Airborne.", "[creature] 카드가 보드에 있는 동안 이후 같은 편 보드에 나오는 카드는 수생 도장을 얻는다. 공수 카드에는 효과가 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The waters rise.", "물이 차오른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homing", "추적", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the opposing slot is empty, and there is a creature in a neighbouring lane, [creature] will attack that creature instead of attacking the opposing slot.", "맞은편 슬롯이 비어 있고 인접한 공격로에 피조물이 있으면 [creature] 카드는 맞은편 슬롯 대신 그 피조물을 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hoodini", "후디니의 마술", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it will swap places with the opposing creature.", "[creature] 카드를 내면 맞은편 피조물과 위치를 바꾼다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Host", "둥지", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is the host of other creatures. It will give you such creature when struck.", "[creature] 카드는 다른 피조물의 숙주다. 공격받으면 그 피조물을 당신에게 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will cause the opponant to skip their turn when played.", "[creature] 카드를 내면 상대가 다음 턴을 건너뛴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sands of time tic away", "시간의 모래가 흘러간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exhaustion", "탈진", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The attack of [creature] will be decreased by the same amount as its lost health.", "[creature] 카드의 공격력은 잃은 체력만큼 줄어든다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hyped", "흥분", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attack at the start of the owner's turn in addition to during normal combat.", "[creature] 카드는 일반 공격 단계 외에도 주인의 턴 시작 시 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imbuing", "힘 주입", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will get specific buffs depending on which tribe is most promenent in the sacrifices that were used to summon it.", "[creature] 카드는 자신을 내기 위해 희생한 피조물들 중 가장 많은 부족에 따라 특정 강화 효과를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inaccurate", "부정확", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike a random one of the opposing spaces to the left and right of the spaces across from it as well as the space in front of it.", "[creature] 카드는 맞은편 칸과 그 왼쪽, 오른쪽 칸 중 한 칸을 무작위로 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Timer", "고참", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the Start of its owner's turn [creature] will gain +1 attack and will take 1 damage.", "주인의 턴 시작 시 [creature] 카드는 공격력을 +1 얻고 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Injured", "부상", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is hurt and will lose 1 health each time it declares an attack due to the strain of the injuries.", "[creature] 카드는 다쳤으며, 공격을 선언할 때마다 상처에 무리가 가서 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Instant", "순간", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will perish immediately after its played.", "[creature] 카드는 나온 직후 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Launcher", "발사기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, [creature] will create another creature on a random empty space on the owner's side of the table.", "주인의 턴 종료 시 [creature] 카드는 주인 측 보드의 무작위 빈칸에 다른 피조물을 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lead (Bones)", "이끌기 (뼈)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 bones to move this card one slot in the direction inscribed on the sigil.", "뼈를 2개 지불해 이 카드를 도장에 표시된 방향으로 한 슬롯 이동시킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "one can lead  a horse to water...", "말을 물가로 데려갈 수는 있어도...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lead (Energy)", "이끌기 (에너지)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 energy to move this card one slot in the direction inscribed on the sigil.", "에너지를 2 지불해 이 카드를 도장에 표시된 방향으로 한 슬롯 이동시킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leech", "거머리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, it will heal 1 Health for each damage dealt to a card.", "[creature] 카드는 카드에 피해를 1 줄 때마다 체력을 1 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vigor from blood!", "피에서 활력을!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Left scratch", "왼쪽 할퀴기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks it will also attack the space on the left of the attacked slot.", "[creature] 카드는 공격할 때 대상 슬롯의 왼쪽 칸도 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life Gambler", "목숨 도박꾼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will deal 2 damage to the owner in exchange for a 0 to 6 increase in stats. Failing to pay this cost will result in death.", "주인의 턴이 끝날 때 [creature] 카드는 능력치를 합계 0부터 5까지 높인 뒤 플레이어에게 피해를 2 준다. 플레이어가 이 대가를 감당하지 못하면 패배한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your blood, their strength!", "당신의 피가 그들의 힘이 된다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Linguist", "언어학자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all talking cards on your side of the board get +1 attack.", "[creature] 카드가 보드에 있는 동안 당신 측 보드의 모든 말하는 카드는 공격력을 +1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Low Tide", "썰물", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, it will negate the waterborne sigil of cards that are played after it on it's side of the board.", "[creature] 카드가 보드에 있는 동안 이후 같은 편 보드에 나오는 카드의 수생 도장을 무효화한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lullaby", "자장가", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, all opposing creatures gain the asleep sigil.", "[creature] 카드가 죽으면 모든 상대 피조물이 휴면 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maneuver", "기동", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, [creature] will strafe in the direction inscribed on the sigil if there is a creature in the opposing slot from it. Else it will strafe in the opposite direction inscribed on the sigil.", "주인의 턴 시작 시 맞은편 슬롯에 피조물이 있으면 [creature] 카드는 도장에 표시된 방향으로 이동하고, 없으면 반대 방향으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It runs", "달린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Medic", "의무병", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, [creature] will try heal 1 damage to a friendly card for each instance of Medic.", "주인의 턴 시작 시 [creature] 카드는 다른 아군 카드 한 장을 무작위로 고른다. 그 카드가 피해를 입었다면 의무병 중첩 하나당 체력을 1 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A good patching", "제대로 된 응급처치.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Medical Aid", "의료 지원", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the opponent's turn, choose a hurt creature on the owner's side to heal for 1.", "상대의 턴 종료 시 주인 측의 다친 피조물을 골라 체력을 1 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Midas", "황금화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] kills a creature, it will generate 1 Foil for each instance of Midas the card has.", "[creature] 카드가 피조물을 죽이면 이 카드의 황금화 중첩 하나당 포일을 1 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bounty, paid in full.", "현상금, 전액 지급.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mount", "탈것", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards may be played on top of [creature]. If they are their sigils and stats will be combined, and a name combination will be created.", "[creature] 카드 위에 카드를 낼 수 있다. 그러면 양쪽의 도장과 능력치가 합쳐지고 이름도 결합된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Power from Movement", "이동의 힘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, [creature] will gain 1 power and 1 health if it moved last round.", "주인의 턴 시작 시 [creature] 카드가 지난 라운드에 이동했다면 공격력을 1, 체력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each move, it grows", "움직일 때마다 자란다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nurse", "간호사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the opponent's turn, [creature] will heal any adjacent friendly cards.", "상대의 턴 종료 시 [creature] 카드는 인접한 모든 아군 카드를 치료한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nutritious", "영양 풍부", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it adds 1 power and 2 health to the card it was sacrificed for.", "[creature] 카드가 희생되면 그 희생으로 낸 카드의 공격력이 1, 체력이 2 늘어난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That creature is so full of nutrients, the creature you play comes in stronger!", "그 피조물은 영양이 가득해서 당신이 내는 피조물이 더 강해진다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone hoarder 1", "뼈의 선물 1", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, 1 bone is rewarded.", "[creature] 카드를 내면 뼈를 1개 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Opportunist", "기회주의자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 1 power for each instance of Opportunist, when the opposing slot is empty.", "맞은편 슬롯이 비어 있으면 [creature] 카드는 기회주의자 중첩 하나당 공격력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It takes it's chance when it gets it.", "기회가 오면 놓치지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paralysis", "마비", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will only attack every other turn. Some effects from sigils may bypass this.", "[creature] 카드는 한 턴 걸러 한 번만 공격한다. 일부 도장 효과는 이 제한을 우회할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A shocking event.", "충격적인 사건.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasite", "기생충", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may be placed on top of any card. If it is their sigils and stats will be combined, and a name combination will be created.", "[creature] 카드는 어떤 카드 위에도 놓을 수 있다. 그러면 양쪽의 도장과 능력치가 합쳐지고 이름도 결합된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pathetic Sacrifice", "한심한 희생", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is so pathetic, it is not a worthy or noble sacrifice. [creature] is meant to stay on the board, and thus can't be targeted by the hammer.", "[creature] 카드는 너무 한심해서 희생 제물로도 쓸 수 없다. [creature] 카드는 보드에 남아 있어야 하며 망치의 대상으로도 삼을 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That is not a noble, or worthy sacrifice", "고귀하지도 가치 있지도 않은 희생이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Picky", "까다로움", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannnot be summoned by using any free cards as sacrifice.", "비용이 없는 카드를 희생해 [creature] 카드를 소환할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pierce", "꿰뚫기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] attacks the card in queue behind it's initial target first when declaring an attack.", "[creature] 카드는 공격을 선언하면 원래 대상 뒤에서 대기 중인 카드를 먼저 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My creatures!", "내 피조물들이!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poisonous", "유독성", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the creature that killed it perishes as well.", "[creature] 카드가 죽으면 이 카드를 죽인 피조물도 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Attacking something poisonous, isn't that smart.", "독이 있는 것을 공격하다니, 현명하지 못하군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessor", "빙의자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it will grant a random friendly card that is on the board it's base power and health.", "[creature] 카드가 죽으면 자신의 기본 공격력과 기본 체력을 보드의 무작위 다른 아군 카드에 더한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It passes it's strength onto those who remain", "남은 이들에게 힘을 전한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Powerful Possessor", "강력한 빙의자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it will grant a random friendly card that is on the board it's base plus modified power and base plus modified health.", "[creature] 카드가 죽으면 자신의 기본값에 보정값을 합한 공격력과 체력을 보드의 무작위 다른 아군 카드에 더한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Predator", "포식자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will gain 1 power for each instance of Predator, when the opposing slot has a card.", "맞은편 슬롯에 카드가 있으면 [creature] 카드는 포식자 중첩 하나당 공격력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prideful", "오만함", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not attack a card with a power 2 lower than its own.", "[creature] 카드는 자신보다 공격력이 2를 초과해 낮은 카드를 공격하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A creature's pride will be it's downfall.", "피조물의 오만은 몰락을 부른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protector", "보호자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attacks on adjacent allies to hit directly.", "[creature] 카드는 인접한 아군을 향한 공격을 그 주인에게 직접 가하는 공격으로 바꾼다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They protect their allies, but who protects you?", "아군은 지켜 주지만, 당신은 누가 지키지?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppets gift", "꼭두각시의 선물", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is on the board any cards with brittle won't die because of brittle.", "[creature] 카드가 보드에 있는 동안 취약성을 지닌 카드는 취약성 때문에 죽지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Superior Sacrifice", "우월한 희생", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is counted as 4 blood rather than 1 blood when sacrificed.", "[creature] 카드는 희생될 때 피 1 대신 피 4로 계산된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ram", "들이받기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will try to ram the card infront of it when played, or every upkeep till it succeeds once. It will send the rammed target to the queue if on my side, or back to the hand if on your side. Does not work during combat.", "[creature] 카드를 내면 맞은편 카드를 들이받으려 하며, 한 번 성공할 때까지 주인의 매 턴 시작 시에도 시도한다. 들이받힌 카드가 상대편에 있으면 대기열로, 플레이어 편에 있으면 패로 돌아간다. 공격 단계에는 작동하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moving creatures around? How Rude!", "피조물을 멋대로 옮기다니, 무례하군!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Strafe", "무작위 이동", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is drawn, it will gain a random strafe sigil.", "[creature] 카드를 뽑으면 이 도장을 숨기고 무작위 이동 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How will it move?", "어떻게 움직일까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recoil", "반동", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will take 1 damage each time they attack.", "[creature] 카드는 공격할 때마다 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The strength causes the creature pain.", "그 힘이 피조물을 고통스럽게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regen 1", "재생 1", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will regen 1 health.", "주인의 턴 종료 시 [creature] 카드는 체력을 1 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature will heal 1 Health at the end of it's owner's turn.", "이 피조물은 주인의 턴 종료 시 체력을 1 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regen 2", "재생 2", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will regen 2 health.", "주인의 턴 종료 시 [creature] 카드는 체력을 2 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature will heal 2 Health at the end of it's owner's turn.", "이 피조물은 주인의 턴 종료 시 체력을 2 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regen 3", "재생 3", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will regen 3 health.", "주인의 턴 종료 시 [creature] 카드는 체력을 3 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature will heal 3 Health at the end of it's owner's turn.", "이 피조물은 주인의 턴 종료 시 체력을 3 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regen", "재생", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will regen to full health.", "주인의 턴 종료 시 [creature] 카드는 체력을 모두 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature will heal to full Health at the end of it's owner's turn.", "이 피조물은 주인의 턴 종료 시 체력을 모두 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repellant", "밀어내기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the creature that killed it gets pushed into the back row.", "[creature] 카드가 죽으면 이 카드를 죽인 피조물은 뒷줄로 밀려난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resistant", "저항력", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will only ever take 1 damage from most things. Some effects might bypass this.", "[creature] 카드는 대부분의 원인으로부터 피해를 1만 받는다. 일부 효과는 이 제한을 우회할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hardy creature that one is.", "참 끈질긴 피조물이군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resourceful", "자원 풍부", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, instead of dying, it loses a random sigil. Resourceful will only remove itself when there are no other sigils on the card.", "[creature] 카드가 희생되면 죽는 대신 무작위 도장 하나를 잃는다. 자원 풍부는 카드에 다른 도장이 없을 때만 자신을 제거한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Retaliate", "응징", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike those who strike their adjacent allies.", "[creature] 카드는 인접한 아군을 공격한 자를 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Right scratch", "오른쪽 할퀴기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks it will also attack the space on the right of the attacked slot.", "[creature] 카드는 공격할 때 대상 슬롯의 오른쪽 칸도 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rushing march", "돌진 행군", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, [creature] will move in the direction inscribed on the sigil, however if it hits a card whilst moving, [creature] will stop and the card it hit will perish.", "주인의 턴 종료 시 [creature] 카드는 도장에 표시된 방향으로 이동한다. 이동 중 카드와 부딪히면 [creature] 카드는 멈추고 부딪힌 카드는 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Schooling", "물고기 떼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will grant creatures with the waterborn 1 power.", "[creature] 카드는 수생을 지닌 피조물에게 공격력을 1 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The waterborn stick together.", "수생 피조물은 함께한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a targeted card cut in two.", "[creature] 카드를 내면 지정한 카드를 반으로 자른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My card!", "내 카드가!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shapeshifter", "변신자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is ever changing. It will change its form once it's struck.", "[creature] 카드는 끊임없이 변하며 공격에 맞으면 형태를 바꾼다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Short", "작은 키", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not be blocked by an opposing creature bearing the airborn sigil.", "[creature] 카드는 공수 도장을 지닌 맞은편 피조물에게 막히지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sickness", "질병 창궐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will loose 1 attack each time it declares an attack.", "[creature] 카드는 공격을 선언할 때마다 공격력을 1 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature's strength leaves it as it strikes.", "피조물은 공격할수록 힘을 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone lord 6", "뼈의 왕 6", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, 6 bones are rewarded instead of 1.", "[creature] 카드가 죽으면 뼈를 1개 대신 6개 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sluggish", "굼뜸", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will not attack during normal combat. It will instead attack after the Opponent's cards attack.", "[creature] 카드는 일반 공격 단계에는 공격하지 않고 상대 카드들이 공격한 뒤에 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bit slow there eh?", "조금 느리군, 안 그래?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Song of sleep", "잠의 노래", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a creature moves into the space opposing [creature], that creature will obtain the asleep sigil.", "피조물이 [creature] 카드의 맞은편 칸으로 이동하면 그 피조물은 휴면 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawner", "생성 이동", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, [creature] will move in the direction inscribed on the sigil and will create another creature in its old space.", "주인의 턴 종료 시 [creature] 카드는 도장에 표시된 방향으로 이동하고 원래 칸에 다른 피조물을 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stampede", "무리 돌진", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will cause adjacent creatures to attack when played on the board if played not during combat.", "공격 단계가 아닐 때 [creature] 카드를 내면 인접한 피조물들이 공격하게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Power in Numbers", "수가 힘이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sticky", "찰싹", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the card opposing [creature] moves, [creature] will try to move with it", "[creature] 카드의 맞은편 카드가 이동하면 [creature] 카드도 함께 이동하려 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Velocity", "속도", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. If it is able to move, it will gain 1 power and 1 health.", "주인의 턴 종료 시 [creature] 카드는 도장에 표시된 방향으로 이동한다. 이동할 수 있으면 공격력을 1, 체력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Wind", "강풍", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is on the board, negate the airbone sigil of all cards that are played after it.", "[creature] 카드가 보드에 있는 동안 이후 나오는 모든 카드의 공수 도장을 무효화한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Wind forces a landing.", "바람이 착륙을 강요한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerged Ambush", "수중 매복", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will deal 1 damage to cards that attacked over it while it was face-down. Does not affect cards that are Airborne.", "[creature] 카드는 자신이 뒷면일 때 자신을 넘어 공격한 카드에게 피해를 1 준다. 공수 카드에는 효과가 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It strikes from the water.", "물속에서 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swallower", "삼키는 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After [creature] attacks, it will destroy the card it attacks if it has less health than it and heal to full health.", "[creature] 카드가 카드에 피해를 준 뒤, 대상이 살아 있고 체력이 이 카드보다 낮으며 굳건함이 없다면 대상을 파괴하고 체력을 모두 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gone in one gulp.", "한입에 꿀꺽.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sympathetic", "동정심", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will only attack if the opposing creature has more or equal health to it.", "[creature] 카드는 맞은편 피조물의 체력이 자신 이상일 때만 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take-Off (Bones)", "이륙 (뼈)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 bones to give this card Airborne till the start of owner's next turn.", "뼈를 2개 지불해 주인의 다음 턴 시작 시까지 이 카드에 공수를 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spread your wings and fly.", "날개를 펴고 날아라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take-Off (Energy)", "이륙 (에너지)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 energy to give this card Airborne till the start of the owner's next turn.", "에너지를 2 지불해 주인의 다음 턴 시작 시까지 이 카드에 공수를 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrified", "공포에 질림", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], [creature] will move away from that card to a random free adjacent spot while pushing any creatures in it's way, while prioritizing slots without any opposing creatures.", "피조물이 [creature] 카드의 맞은편 칸으로 이동하면 [creature] 카드는 길을 막는 피조물을 밀어내며 인접한 무작위 빈칸으로 달아나고, 맞은편에 피조물이 없는 칸을 우선한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thick Shell", "두꺼운 껍질", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When attacked, [creature] takes 1 less damage.", "[creature] 카드는 공격받을 때 피해를 1 덜 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The thick shell on that creature protected it from one damage!", "그 피조물의 두꺼운 껍질이 피해를 1 막았다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will try to steal a random default sigil from a card in the opposing lane when played, or at the start of the owner's turn until it does.", "[creature] 카드를 내면 맞은편 공격로의 카드가 원래 지닌 도장 하나를 무작위로 훔치려 한다. 성공할 때까지 주인의 매 턴 시작 시에도 시도한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If only I could steal the moon...", "달도 훔칠 수 있다면...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone prince 3", "뼈 왕자 3", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, 3 bones are rewarded instead of 1.", "[creature] 카드가 죽으면 뼈를 1개 대신 3개 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone hoarder 3", "뼈의 선물 3", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, 3 bones are rewarded.", "[creature] 카드를 내면 뼈를 3개 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tooth Bargain", "이빨 거래", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it will put 1 point of damage of it's opponent's side of the scale. When it perishes, it will put 2 damage on the owner's side of the scale.", "[creature] 카드를 내면 저울의 상대 쪽에 피해를 1 더한다. 이 카드가 죽으면 주인 쪽에 피해를 2 더한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A deal with a devil I see...", "악마와의 거래로군...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toothpuller", "이빨 뽑기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will add one point of damage to the opponent's scale.", "주인의 턴 종료 시 [creature] 카드는 저울의 상대 쪽에 피해를 1 더한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That Hurts", "아프군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tooth Shard", "이빨 조각", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will generate 1 foil when hit, if it lives through the attack.", "[creature] 카드가 공격에 맞고도 살아남으면 포일을 1 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A splinter of gold.", "금 조각이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxin", "혼합 독소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature looses 1 power and 1 health.", "[creature] 카드가 다른 피조물에게 피해를 주면 그 피조물은 공격력과 체력을 각각 1 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All things can be worn down, and in different ways.", "모든 것은 저마다 다른 방식으로 닳아 간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxin (Deadly)", "치명적 독소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature gains the Dying Sigil. The Dying Sigil is defined as: [creature] will die after 2 number of turns.", "[creature] 카드가 다른 피조물에게 피해를 주면 그 피조물은 빈사 도장을 얻는다. 빈사의 효과: [creature] 카드는 2턴 후 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even once combat is over, it leaves a deadly mark", "전투가 끝나도 치명적인 흔적이 남는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxin (Sickening)", "질병 유발 독소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature gains the Sickness Sigil. The Sickness Sigil is defined as: When ever a creature bearing this sigil declares an attack, they will loose one attack.", "[creature] 카드가 다른 피조물에게 피해를 주면 그 피조물은 질병 창궐 도장을 얻는다. 질병 창궐의 효과: 이 도장을 지닌 피조물은 공격을 선언할 때마다 공격력을 1 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even once combat is over, it leaves sickness spreads in what it fights.", "전투가 끝난 뒤에도 싸웠던 상대에게 병이 퍼진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxin (Strength)", "힘의 독소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature looses 1 power.", "[creature] 카드가 다른 피조물에게 피해를 주면 그 피조물은 공격력을 1 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even once combat is over, strength leaves it's target", "전투가 끝난 뒤에도 대상의 힘은 사라진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxin (Vigor)", "활력 독소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature looses 1 health.", "[creature] 카드가 다른 피조물에게 피해를 주면 그 피조물은 체력을 1 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trample", "짓밟기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals overkill damage to a card, the overkill damage will be sent to the owner.", "[creature] 카드가 다른 카드에 초과 피해를 주면 초과분은 그 카드의 주인에게 전달된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stampede can not be stopped.", "질주하는 무리는 막을 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transform Chicken (Enemy Only)", "닭으로 변환 (적만)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will transform a random creature on the board on the opponent's side into a Chicken. A Chicken is defined as 1 Attack, 1 Health.", "매 턴이 끝날 때 [creature] 카드는 상대 측 보드의 무작위 피조물 하나를 닭으로 바꾼다. 닭의 능력치는 공격력 1, 체력 1이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transform Chicken (Loose Cannon)", "닭으로 변환 (무차별)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will transform a random creature on the board into a Chicken. A Chicken is defined as 1 Attack, 1 Health.", "매 턴이 끝날 때 [creature] 카드는 보드의 무작위 피조물 하나를 닭으로 바꾼다. 닭의 능력치는 공격력 1, 체력 1이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transform Chicken (Opposing)", "닭으로 변환 (맞은편)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played opposing [creature] it will turn into a Chicken. A Chicken is defined as 1 Attack, 1 Health.", "[creature] 카드의 맞은편에 피조물을 내거나 피조물이 그 칸으로 이동하면 그 피조물은 닭으로 변한다. 닭의 능력치는 공격력 1, 체력 1이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transient", "덧없는 존재", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will return to your hand.", "주인의 턴이 끝날 때 [creature] 카드는 당신의 패로 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature blinks back into the owner's hand at the end of their turn.", "턴이 끝나면 피조물이 주인의 패로 순식간에 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tribal Ally", "부족 동맹", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, A card of the same tribe is created in your hand. No tribe counts as a tribe of tribeless.", "[creature] 카드를 내면 같은 부족의 카드 한 장이 당신의 패에 생성된다. 부족 없음도 '부족 없음'이라는 부족으로 취급한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It calls for it's kin.", "동족을 부른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tribal Tutor", "부족 탐색", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may search your deck for a card of the same tribe and take it into your hand. No tribe counts as a tribe of tribeless.", "[creature] 카드를 내면 덱에서 같은 부족의 카드 한 장을 찾아 패로 가져올 수 있다. 부족 없음도 '부족 없음'이라는 부족으로 취급한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tribe Attack", "부족 공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all other cards on your side of the board of the same tribe will gain +1 attack.", "[creature] 카드가 보드에 있는 동안 당신 측 보드의 같은 부족인 다른 카드들은 모두 공격력을 +1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tribe Health", "부족 체력", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on the board, all other cards on your side of the board of the same tribe will gain +1 health.", "[creature] 카드가 보드에 있는 동안 당신 측 보드의 같은 부족인 다른 카드들은 모두 체력을 +1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turbulent Waters", "거친 물결", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will force other creatures with waterborne to resurface and take 1 damage at the start of the owner's turn.", "주인의 턴 시작 시 [creature] 카드는 수생 도장을 지닌 다른 피조물들을 수면 위로 떠오르게 하고 피해를 1 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The waters be rough.", "물이 거칠게 출렁인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone prince 2", "뼈 왕자 2", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, 2 bones are rewarded instead of 1.", "[creature] 카드가 죽으면 뼈 1개 대신 2개를 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone hoarder 2", "뼈의 선물 2", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, 2 bones are rewarded.", "[creature] 카드를 내면 뼈 2개를 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Underdog", "약자의 편", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can only be played when you are losing.", "[creature] 카드는 당신이 지고 있을 때만 낼 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vicious", "포악함", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is attacked, it gains 1 power.", "[creature] 카드는 공격당하면 공격력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hit just makes it angry.", "한 대 맞으면 화만 더 난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warper", "공간 이동자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, [creature] will move to the right, jumping over any creatures in its path, if it encounters the edge of the board, it will loop over to the other side.", "주인의 턴이 끝날 때 [creature] 카드는 오른쪽으로 움직이며 경로의 모든 피조물을 뛰어넘는다. 보드 끝에 닿으면 반대편으로 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wild hunger", "야생의 굶주림", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its owner's turn, [creature] will move in the direction inscribed on the sigil, however if it hits a card whilst moving, [creature] will stop, the card it hit will perish and [creature] will gain 1+/1+.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 움직인다. [creature] 카드가 카드에 부딪히면 그 카드를 죽이고 공격력과 체력을 각각 +1 얻는다. 칸이 비면 [creature] 카드는 그곳으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Withering", "시들기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will perish at the end of the opponant's turn.", "상대의 턴이 끝날 때 [creature] 카드는 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zapper", "마비의 손길", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] damages another creature, that creature will gain the Paralysis Sigil. The Paralysis sigil is defined as: A card bearing this sigil will only attack every other turn.", "[creature] 카드가 다른 피조물에게 피해를 주면 그 피조물은 마비 도장을 얻는다. 마비의 효과: 이 도장을 지닌 카드는 한 턴 걸러 한 번만 공격한다.", Language.Korean);
        }
    }
    public class BittysSigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for BittysSigils Mod");
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blocked on both sides. No Eggs for you.", "양쪽이 막혔다. 알은 줄 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No empty spaces. No firs for you.", "빈칸이 없다. 전나무는 줄 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explosive Squirrel Reproduction", "다람쥐 대폭발 번식", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, fill your side deck with squirrels.", "[creature] 카드를 내면 보조 덱을 다람쥐로 가득 채운다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hauler", "운반자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. Adjacent friendly creatures will be pulled in the same direction.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 움직인다. 인접한 아군 피조물도 같은 방향으로 끌려간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart Swap", "마음 교환", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all cards on the board swap their power and health.", "[creature] 카드를 내면 보드의 모든 카드가 공격력과 체력을 서로 바꾼다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mutual Hire", "상호 고용", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a copy of it is created in the opposing space.", "[creature] 카드를 내면 맞은편 칸에 그 카드의 사본이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charged Barrage", "충전 탄막", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 life to increase the power of all cards on your side of the board by 1.", "생명 4를 지불해 당신 측 보드에 있는 모든 카드의 공격력을 1 높인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Health Roll", "체력 주사위", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Energy to set the health of [creature] randomly between 1 and 6.", "에너지 1을 소비해 [creature] 카드의 체력을 1에서 6 사이의 무작위 값으로 정한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sigil Roll", "도장 주사위", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Life to add a random sigil to [creature].", "생명 4를 지불해 [creature] 카드에 무작위 도장 하나를 추가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wildlife Camera", "야수 카메라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another card, a copy of the killed card is created in your hand.", "[creature] 카드가 다른 카드를 처치하면 처치된 카드의 사본이 당신의 패에 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dusty Quill", "먼지 쌓인 깃펜", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever a creature dies while [creature] is on the board, a corpse is raised in it's place. Corpses are defined as: 0/1.", "[creature] 카드가 보드에 있는 동안 피조물이 죽을 때마다 그 자리에 시체가 생긴다. 시체의 능력치는 0/1이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleached Brush", "표백 붓", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, the opposing card will lose all its sigils.", "[creature] 카드를 내면 맞은편 카드는 모든 도장을 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Soul", "강인한 영혼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not recieve sigils from another card.", "[creature] 카드는 다른 카드로부터 도장을 받을 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak Soul", "약한 영혼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not have its sigils transferred to another card.", "[creature] 카드의 도장은 다른 카드로 옮길 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nonexistent Soul", "존재하지 않는 영혼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not have sigils transferred to, or from this card.", "[creature] 카드에 도장을 옮기거나 그 카드에서 도장을 옮길 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrophobia", "화염공포증", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not be buffed at campsites.", "[creature] 카드는 모닥불에서 강화할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrophobia (Attack)", "화염공포증 (공격력)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not recieve power buffs from campsites.", "[creature] 카드는 모닥불에서 공격력 강화를 받을 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrophobia (Health)", "화염공포증 (체력)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not recieve health buffs from campsites.", "[creature] 카드는 모닥불에서 체력 강화를 받을 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repulsion", "반발", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not attack.", "[creature] 카드는 공격할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mysterious Mushrooms", "신비한 버섯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, if there is a card on either side of [creature], they are fused together.", "주인의 턴이 끝날 때 [creature] 카드의 왼쪽이나 오른쪽에 카드가 있으면 그 카드는 이 카드와 융합한다. 양쪽은 각각 판정한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move the opposing card and itself in the direction inscribed in the sigil.", "주인의 턴이 끝날 때 [creature] 카드는 자신과 맞은편 카드를 도장에 표시된 방향으로 움직인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counter Attack", "반격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once [creature] is struck, the striker is then dealt damage equal to this card's attack.", "[creature] 카드가 공격당하면 공격자는 이 카드의 공격력만큼 피해를 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror Counter", "거울 반격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once [creature] is struck, the striker is then dealt damage equal to the striker's attack.", "[creature] 카드가 공격당하면 공격자는 자신의 공격력만큼 피해를 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Board Shifter", "보드 이동", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. All cards will shift in the same direction, looping to the other edge of the board.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 움직인다. 모든 카드는 같은 방향으로 이동하며 보드의 반대편으로 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Board Shifter (Owner)", "보드 이동 (아군)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. Friendly cards will shift in the same direction, looping to the other edge of the board.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 움직인다. 아군 카드들은 같은 방향으로 이동하며 보드의 반대편으로 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Board Shifter (Opposing)", "보드 이동 (상대)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. The opposing cards will shift in the same direction, looping to the other edge of the board.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 움직인다. 상대 카드들은 같은 방향으로 이동하며 보드의 반대편으로 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deathbell", "죽음의 종", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the battle phase, [creature] perishes.", "주인의 전투 단계가 시작되어 종이 울릴 때 [creature] 카드는 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clockwise", "시계 방향", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, move all cards on the board clockwise.", "[creature] 카드를 내면 보드의 모든 카드가 시계 방향으로 움직인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stubborn", "고집불통", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not have its stats swapped.", "[creature] 카드의 능력치는 교환할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn [creature] is on the board, move all cards on the board clockwise.", "[creature] 카드가 보드에 있는 동안 매 턴이 끝날 때 보드의 모든 카드를 시계 방향으로 움직인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fleeting", "덧없음", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn [creature] will be discarded from your hand.", "턴이 끝날 때 [creature] 카드는 당신의 패에서 버려진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Link", "영혼 연결", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, all other allied cards bearing this sigil perish as well.", "[creature] 카드가 죽으면 이 도장을 지닌 다른 아군 카드도 모두 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hollow Draw", "공허한 뽑기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, discard the oldest card in your hand, draw a card.", "[creature] 카드를 내면 패에서 가장 오래된 카드를 버리고 카드를 한 장 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hollow Barrage", "공허한 탄막", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all cards take 1 damage.", "[creature] 카드를 내면 모든 카드가 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Phobic", "보석 공포증", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls a Mox card, [creature] perishes.", "[creature] 카드의 주인이 목스 카드를 조종하고 있으면 [creature] 카드는 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foolhardy", "무모함", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not recieve modifications from any source.", "[creature] 카드는 어떤 출처에서도 변경을 받을 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jumper", "점프꾼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move itself to the first empty space in the direction inscribed in the sigil.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향의 첫 번째 빈칸으로 움직인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Super Sprinter", "슈퍼 질주자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move itself as far as possible in the direction inscribed in the sigil.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 최대한 멀리 움직인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eggist", "알 예술가", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, an Egg is created on each empty adjacent space.", "[creature] 카드를 내면 인접한 각 빈칸에 알이 하나씩 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fir Caller", "숲을 부르는 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Fir is created in each of the owner's spaces.", "[creature] 카드를 내면 주인 측의 각 빈칸에 큰 전나무가 하나씩 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flipper", "뒤집개", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] swaps its stats.", "주인의 턴이 끝날 때 [creature] 카드의 능력치가 서로 바뀐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fleeting Draw", "덧없는 뽑기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw 1 card with Fleeting.", "[creature] 카드를 내면 덧없음 도장을 지닌 카드 1장을 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Outcast", "추방자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, [creature] is shuffled into the deck.", "턴이 끝날 때 [creature] 카드는 덱에 섞여 들어간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hollow Repeater", "공허한 재발동", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, all On Play sigils on that card are activated.", "[creature] 카드가 죽으면 그 카드의 출전 시 발동하는 도장이 모두 활성화된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Replenish", "보충", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, draw a card.", "[creature] 카드를 뽑으면 카드를 한 장 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Target Swap", "대상 교환", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Target a Card: the card's stats are swapped.", "[creature] 카드를 내면 카드 한 장을 지정한다. 그 카드의 능력치가 서로 바뀐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificial Growth", "희생 성장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is sacrificed, it will grow into a more powerful form.", "[creature] 카드가 희생되면 더 강력한 형태로 성장한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Transformer", "루비 변신자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls a Ruby Mox, [creature] will be transformed; otherwise [creature] will transform into its base form.", "[creature] 카드의 주인이 루비 목스를 조종하고 있으면 [creature] 카드는 변신한다. 그렇지 않으면 [creature] 카드는 기본 형태로 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gemify", "보석화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains buffs based on moxes in play on the owner's side. Orange is 1 Power. Green is 2 Health. Blue is lower Cost.", "[creature] 카드는 주인 측 보드에 놓인 목스에 따라 강화된다. 오렌지색은 공격력 1, 녹색은 체력 2, 파란색은 비용 감소를 제공한다.", Language.Korean);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corpse", "시체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TestCard", "시험 카드", Language.Korean);
        }
    }
    public class BittysChallengesMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for BittysChallenges Mod");
            // DialogueEvent
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is that a clover?", "저건 클로버인가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see.", "그렇군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh?", "오?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you not like having a stacked deck?", "조작된 덱이 마음에 들지 않았나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's fine with me.", "난 상관없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It will be more fair this way anyways.", "어차피 이쪽이 더 공평하겠지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "oh?", "오?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "my very own ouroboros.", "나만의 우로보로스군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "i will be sure to put it to good use.", "잘 써 주도록 하지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the ouroboros has followed you.", "우로보로스가 당신을 따라왔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it's fangs are beared, and it's ready for another fight.", "녀석은 송곳니를 드러내고 다시 싸울 준비를 마쳤다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the unyielding ouroboros has returned,", "굴하지 않는 우로보로스가 돌아왔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "growing stronger every death.", "죽을 때마다 더욱 강해지면서.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "as inevitable as death,", "죽음처럼 피할 수 없는 존재,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the ouroboros has returned.", "우로보로스가 돌아왔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a serpent slithers out from the undergrowth.", "뱀 한 마리가 덤불에서 기어 나온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "perhaps you have seen it before?", "전에 본 적이 있지 않은가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the ouroboros has died.", "우로보로스가 죽었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and yet, it will return.", "하지만 녀석은 돌아올 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the serpent's wrath has been delayed.", "뱀의 분노는 미뤄졌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "for now.", "지금은 말이지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the ouroboros only grows stronger from death.", "우로보로스는 죽음으로 더욱 강해질 뿐이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it will be back.", "녀석은 다시 돌아올 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a-ah, the sigils...", "아, 아, 도장이...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "o-oh, the power...", "오, 오, 이 공격력은...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a-ah, the health...", "아, 아, 이 체력은...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah...", "아...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chrysomallos, the golden ram.", "황금 양, 황금빛 숫양이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "what a glorious pelt....", "참으로 아름다운 가죽이군...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The golden ram.", "황금 숫양이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "catch it before it escapes.", "도망치기 전에 잡아라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a rare sight", "보기 드문 광경이군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it will not stay for long", "오래 머물지는 않을 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "what glittering wool,", "참으로 빛나는 털이군,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "attached to such a rare creature.", "이토록 희귀한 피조물에 붙어 있다니.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "oh?", "오?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a rare chance to get a rare pelt.", "희귀한 가죽을 얻을 수 있는 드문 기회다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "best make the most of it.", "기회를 최대한 활용하는 게 좋겠군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You slay the glimmering creature, stealing its pelt.", "당신은 빛나는 피조물을 죽이고 그 가죽을 빼앗았다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The end of such a glorious creature.", "그토록 찬란한 피조물의 최후로군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And what a glorious pelt you have obtained.", "그리고 당신은 참으로 아름다운 가죽을 얻었군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chrysomallos...", "황금 양이여...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How tragic your tale is...", "그대의 이야기는 얼마나 비극적인가...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To be killed for your pelt...", "가죽 때문에 죽임을 당하다니...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Golden Ram lives another day.", "황금 숫양은 하루를 더 살아남았다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time's up.", "시간이 다 됐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Golden Ram has found an escape route.", "황금 숫양이 도망칠 길을 찾았다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The glimmer of the Golden Ram's fur blinds you,", "황금 숫양 털의 반짝임이 당신의 눈을 멀게 하여,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "giving it the opportunity to escape.", "녀석에게 도망칠 기회를 주었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "아...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [v:0] has taken a devastating blow from the [v:1].", "당신의 [v:0]이(가) [v:1]에게 엄청난 타격을 받았다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will not be able to take it with your caravan.", "그것을 당신의 일행에 데려갈 수는 없을 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "아...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You won't be seeing your [v:0] again,", "당신의 [v:0]을(를) 다시 볼 수 없을 것이다,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It has taken too much damage.", "너무 큰 피해를 입었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "아...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you permanently kill your [v:0] on purpose?", "당신의 [v:0]을(를) 일부러 영원히 죽인 건가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A shame...", "안타깝군...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ha! There be my first mate!", "하! 내 일등 항해사가 왔군!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Argh! There be snakes on me ship as well!", "으악! 내 배에도 뱀이 있잖아!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ha!", "하!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I should hire ye to get rid of the rest of them!", "남은 놈들도 없애게 자네를 고용해야겠어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ha! It's dead!", "하! 죽었다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "what?", "뭐라고?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pirates?", "해적이라고?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll allow it.", "허락하지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "what?", "뭐라고?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "cheating?", "속임수인가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "how dissapointing...", "실망스럽군...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the game will be soured from a pitifully easy ascent.", "한심할 정도로 쉬운 등반은 이 게임의 재미를 망칠 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "cheater...", "속임수쟁이...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have you no shame?", "부끄럽지도 않은가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To cheat so blatantly...", "이렇게 대놓고 속임수를 쓰다니...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you should be dead.", "당신은 죽었어야 했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and yet...", "그런데도...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "how dissapointing...", "정말 실망스럽군...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't tolerate this for much longer...", "더는 오래 참지 않을 것이다...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enough of this.", "이제 그만.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yer not dead?", "자네, 안 죽었나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah...", "아...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "back to normal then?", "그럼 원래대로 돌아온 건가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll admit, I had gotten used to the changes...", "인정하겠다. 그 변화에 익숙해져 있었어...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak Cards?", "약해진 카드?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is hard to explain...", "설명하기 어렵군...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps they are sick? Yes.", "아마 병에 걸린 걸까? 그래.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A crippling disease afflicted your meager troupe of creatures.", "몸을 쇠약하게 하는 병이 당신의 보잘것없는 피조물 무리를 덮쳤다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Waterborne Cards?", "수생 카드?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is hard to explain...", "설명하기 어렵군...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps a mutation? Yes.", "돌연변이일까? 그래.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your caravan of creatures had a startling mutation,", "당신의 피조물 일행에 놀라운 돌연변이가 일어났다,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They could only survive in the water.", "녀석들은 물속에서만 살아남을 수 있었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paralyzed Cards?", "마비된 카드?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm...", "흠...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your group of creatures were fatigued from the long journey,", "당신의 피조물들은 긴 여정으로 지쳐 있었지만,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "but there would be a long way to go yet.", "앞으로 갈 길도 멀었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak Souled Cards?", "약한 영혼 카드?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm...", "흠...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will not be able to extract their souls into new creatures,", "녀석들의 영혼을 추출해 새로운 피조물에 넣을 수는 없을 것이다,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For better or worse...", "좋든 나쁘든...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lives of past challengers weighed down on you...", "과거 도전자들의 삶이 당신을 짓누르고 있었다...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "응?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How to explain this...", "어떻게 설명해야 할까...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You were running low on supplies that day...", "그날 당신의 보급품은 거의 바닥나 있었다...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll have fewer [c:G][v:0]s[c:] to work with.", "사용할 수 있는 [c:G][v:0][c:]의 수가 줄어들 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "응?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An abundance of [c:G][v:0]s[c:]...", "넘쳐나는 [c:G][v:0][c:]...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Must be mating season...", "짝짓기 철인가 보군...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "응?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environmental effects?", "환경 효과?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "how interesting...", "흥미롭군...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In order to proceed,", "앞으로 나아가려면,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you had to slog through the wetter parts of the swamp.", "당신은 늪의 더 축축한 곳을 힘겹게 지나야 했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The thick[c:G][c:G]mud[c:] stuck to your boots, and hindered your movements...", "진득한 [c:G][c:G]진흙탕[c:]이 장화에 달라붙어 움직임을 방해했다...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frigid air was not the only obstacle in your way,", "매서운 추위만이 당신의 앞길을 막는 것은 아니었다,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the harsh ice and unforgiving snow also stood in your path.", "혹독한 얼음과 무자비한 눈도 당신의 길을 가로막았다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "before long you found yourself in...", "얼마 지나지 않아 당신은 그 한가운데 있었다...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a [c:B]hailstorm.[c:]", "[c:B]우박 폭풍.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You found yourself cornered against a sheer rock wall,", "당신은 가파른 암벽 앞에 몰려 있었다,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the [c:G]cliffside.[c:]", "[c:G]절벽 가장자리.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Against the cold stone, there would be less space to fight.", "차가운 바위에 맞서 싸울 공간은 더 좁아질 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mycologists had left one of their experiments behind,", "진균학자들이 실험체 하나를 남겨 두고 갔다,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "unbeknownst to them, it began to fester and grow.", "그들이 모르는 사이 그것은 곪아 자라기 시작했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "even the creatures fighting you would not be safe from the [c:G]fungal mass.[c:]", "당신과 싸우는 피조물조차 [c:G]균류 덩어리[c:]로부터 안전하지 않을 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You stumbled across one of the Prospector's Camps.", "당신은 광부의 야영지 하나를 우연히 발견했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The camp was filled with prospecting tools.", "야영지는 채굴 도구로 가득했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "pickaxes, headlamps...", "곡괭이, 헤드램프...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and [c:bR]dynamite.[c:]", "그리고 [c:bR]다이너마이트.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You came across one of the Angler's Ponds.", "당신은 낚시꾼의 연못 하나를 발견했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the area stank of rotting fish", "주변에는 썩은 물고기 냄새가 진동했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "emanating from the nearby abandoned buckets of [c:dB]bait.[c:]", "냄새는 근처에 버려진 [c:dB]미끼[c:] 양동이에서 풍겨 나왔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You came across one of the Trapper's Hunting Grounds.", "당신은 덫 사냥꾼의 사냥터 하나에 도착했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the stench of blood hung in the air...", "공기에 피비린내가 감돌았다...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you noticed the numerous [c:G]traps[c:] lying in wait.", "당신은 수많은 [c:G]덫[c:]이 놓여 있는 것을 알아차렸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You came upon a strange [c:bR]totem.[c:]", "당신은 기이한 [c:bR]토템[c:]을 발견했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a mysterious energy swirled around it,", "신비로운 에너지가 그 주위를 휘돌고,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the creatures nearby seem more agressive than usual...", "근처 피조물들은 평소보다 공격적인 듯하다...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "아...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a [c:bR]Blood Moon.[c:]", "[c:bR]핏빛 달.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Er...", "어...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You...", "당신은...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...What?", "...뭐라고?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am at a loss for words.", "할 말을 잃었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wind was howling around you.", "당신 주위로 바람이 거세게 울부짖었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stuck in the middle of a blizzard,", "눈보라 한가운데 갇힌 당신은,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You heard rumbling from the mountains above.", "위쪽 산에서 우르릉거리는 소리를 들었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here it comes...", "온다...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "an [c:B]avalanche.[c:]", "[c:B]눈사태다.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You stumble across a strange black stone.", "당신은 기이한 검은 돌을 우연히 발견했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stone tablet sits in front of it, clearly made for sacrifices.", "그 앞에는 누가 봐도 희생을 위해 만든 석판이 놓여 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps a certain creature may cause a reaction?", "특정 피조물이 반응을 일으킬 수 있을까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The obelisk trembles in delight.", "오벨리스크가 기쁨에 떨린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A goat is truly a worthy sacrifice.", "염소는 참으로 가치 있는 제물이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You won't be seeing it again.", "당신은 그것을 다시 볼 수 없을 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The obelisk rumbles with anger.", "오벨리스크가 분노에 으르렁거린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pelt is a truly pitiful sacrifice.", "가죽은 참으로 보잘것없는 제물이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...", "…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...That is not a proper sacrifice.", "...그것은 적절한 제물이 아니다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop this.", "그만둬라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You...", "당신은...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is bloodshed without meaning.", "이것은 의미 없는 유혈이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[v:0]...", "[v:0]...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmm?", "흠?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is this?", "이것은 무엇인가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heh heh heh...", "헤헤헤...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ye walked into th' pirate's cove!", "해적의 만에 발을 들였군!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Me crew will get rid of ye quick!", "내 선원들이 자네를 금방 해치울 거다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You carve through the thick underbrush and foilage.", "당신은 빽빽한 관목과 나뭇잎을 베어 가며 나아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trees blotting out the sun...", "나무들이 햇빛을 가리고...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you travel, you hear the woods start to creak around you.", "길을 가던 중 주위 숲에서 삐걱거리는 소리가 들리기 시작했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should know better than to walk in the darkness...", "어둠 속을 걷지 말았어야 한다는 걸 알 텐데...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As your caravan of creatures travels, you hear a rushing sound.", "피조물 일행이 나아가는 동안 거센 물소리가 들렸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You climb to a higher place as water flows around you.", "당신 주위로 물이 흐르자 더 높은 곳으로 올라갔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are caught in a [c:B]flood.[c:]", "당신은 [c:B]홍수[c:]에 휩쓸렸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the terrain and flying creatures will be able to avoid the waters.", "지형과 날아다니는 피조물만 물을 피할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As your caravan of creatures moves across a clearing, the winds blow stronger.", "피조물 일행이 빈터를 가로지를 때 바람이 거세졌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strong breeze greets your face, and you grasp onto the surroundings for dear life.", "거센 바람이 얼굴을 때리자 당신은 살기 위해 주변을 필사적으로 붙잡았다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your creatures are blown [c:G]airborne.[c:]", "피조물들이 바람에 [c:G]공중으로 날아올랐다.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only burrowing and submerged creatures will be able to avoid the gusts.", "땅속에 숨거나 물속에 잠긴 피조물만 돌풍을 피할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Breeze blows...", "산들바람이 분다...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You come across a pile of corpses.", "당신은 시체 더미를 발견했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange energy swirls around them as you approach.", "당신이 다가가자 기이한 에너지가 그 주변을 휘돌았다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Then...", "그리고...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]The dead walk.[c:]", "[c:R]죽은 자들이 걸어 다닌다.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]The dead walk.[c:]", "[c:R]죽은 자들이 걸어 다닌다.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You came across an overgrown glade.", "당신은 풀이 무성한 숲속 빈터를 발견했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trees seemed taller, and stronger than usual.", "나무들은 평소보다 더 크고 튼튼해 보였다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your creatures grew faster as well.", "당신의 피조물들도 더 빨리 자랐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<color=#25C102>Flash Growth.</color>", "<color=#25C102>급속 성장.</color>", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "응?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're decreasing the number of vessels you have?", "그릇의 수를 줄이겠다고?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surely a player as bad as you needs the extra chump blockers?", "너처럼 못하는 플레이어라면 막아 줄 희생양이 더 필요할 텐데?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll see.", "곧 알게 될 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "응?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're increasing the number of vessels you have?", "그릇의 수를 늘리겠다고?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Makes sense.", "그럴 만하지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After all, a player as bad as you needs the extra chump blockers.", "너처럼 못하는 플레이어에겐 막아 줄 희생양이 더 필요할 테니까.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[v:0] vessels...", "그릇 [v:0]개...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh?", "오?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You couldn't even stick to the changes?", "그 변경조차 유지하지 못했나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pathetic.", "한심하군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh?", "오?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My own Ourobot?", "나만의 우로봇이라고?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must be masochistic if you thought this was a good idea.", "이게 좋은 생각이라고 여겼다면 넌 분명 피학적인 성향이 있군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your funeral.", "네가 자초한 일이야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There it goes.", "사라졌군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You just made it stronger.", "넌 그것을 더 강하게 만들었을 뿐이야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Of course, you knew that already.", "물론 이미 알고 있었겠지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not worried.", "난 걱정 안 해.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It'll come back to crush you later.", "나중에 돌아와 널 짓밟을 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "응?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weaker starting cards?", "약해진 시작 카드?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As if one health will make a difference.", "체력 1이 무슨 차이를 만든다고.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm?", "응?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Were my environments not good enough for you?", "내 환경이 마음에 들지 않았나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fine.", "좋아.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm...", "흠...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have found a...", "넌 발견했다...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Robot scrapyard.", "로봇 폐차장.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There's broken down robots everywhere.", "고장 난 로봇이 사방에 널려 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every robot in this area dies twice.", "이 구역의 모든 로봇은 두 번 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's the scrapyard again.", "또 폐차장이군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know the drill.", "어떻게 하는지는 알지?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eugh", "으", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is one of [c:O]HIS.[c:]", "이건 [c:O]그 녀석[c:]의 것이군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your... transformer bots will be more effective here.", "네... 변신자 봇들이 여기선 더 효과적일 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They'll transform when played.", "카드를 내면 변신할 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll see.", "곧 알게 될 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your transformer bots will be more effective here.", "네 변신자 봇들이 여기선 더 효과적일 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They'll tranform when played.", "카드를 내면 변신할 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "아...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A favorite of mine.", "내가 좋아하는 것 중 하나지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each of your turns all cards will be moved clockwise.", "네 매 턴 시작 시 모든 카드가 시계 방향으로 움직인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sure you've seen it before.", "전에 본 적이 있을 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each of your turns all cards will be moved clockwise.", "네 매 턴 시작 시 모든 카드가 시계 방향으로 움직인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've seen it before.", "전에 본 적이 있지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah...", "아...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your <color=#25C102>G</color>[c:O]E[c:][c:B]M[c:]s will be more useful.", "네 <color=#25C102>보</color>[c:O]석[c:][c:B]이[c:] 더 유용해질 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "More useful than [c:R]he[c:] ever was able to make them...", "[c:R]그 녀석[c:]이 쓸 때보다 훨씬 더 유용하게...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...As long as you keep that one alive.", "...그것 하나를 살려 둔다면 말이지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your <color=#25C102>G</color>[c:O]E[c:][c:B]M[c:]s will be more useful.", "네 <color=#25C102>보</color>[c:O]석[c:][c:B]이[c:] 더 유용해질 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...As long as you keep that one alive.", "...그것 하나를 살려 둔다면 말이지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heh", "흥", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one will be quite...", "이건 상당히...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shocking.", "충격적일 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You find yourself in an electrical storm.", "넌 뇌우 한가운데에 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card is played, it will take 1 damage.", "카드를 내면 그 카드가 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If it survives, it'll be stronger for a bit.", "살아남으면 잠시 더 강해질 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think you'll find this one quite...", "이건 상당히... 할 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shocking.", "충격적일 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undead Parrot", "언데드 앵무새", Language.Korean);

            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascender's Bane", "등반자의 재앙", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You start with a useless card in the deck.", "시작 덱에 쓸모없는 카드 한 장을 지닌 채 시작한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Champions", "챔피언", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Opponent cards have a chance to become a champion.", "상대 카드가 일정 확률로 챔피언이 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environmental Effects", "환경 효과", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each battle, a random environmental effect may activate.", "매 전투 시작 시 무작위 환경 효과가 활성화될 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Famine", "기근", Language.Korean);
            for (int amnt = 0; amnt < 10; amnt++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The side deck has " + amnt.ToString() + " more cards.", "보조 덱의 카드가 " + amnt.ToString() + "장 늘어난다.", Language.Korean);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The side deck has " + amnt.ToString() + " less cards.", "보조 덱의 카드가 " + amnt.ToString() + "장 줄어든다.", Language.Korean);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Runaway Side Deck", "폭주하는 보조 덱", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your Side Deck cards have the Fleeting sigil.", "당신의 보조 덱 카드들은 덧없음 도장을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Golden Fleece", "황금 양털", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Golden Ram appears randomly throughout the run.", "도전 중 황금 숫양이 무작위로 나타난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harder Bosses", "더 강한 보스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bosses' main cards are more powerful, and bosses are more agressive.", "보스의 주력 카드가 더 강해지고 보스가 더 공격적으로 행동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "True Pirate", "진정한 해적", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pirates invade Bosses. The Final Boss Challenge is harder.", "해적이 보스전에 침입한다. 최종 보스 도전이 더 어려워진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Extra Lives", "추가 생명", Language.Korean);
            for (int amnt = 0; amnt < 10; amnt++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The scales will reset once they hit 0, up to " + amnt.ToString() + " times for each candle.", "저울이 0에 도달하면 초기화되며 촛불 하나당 최대 " + amnt.ToString() + "번까지 가능하다.", Language.Korean);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Botched Experiments", "엉망이 된 실험", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mycologists have a chance to make mistakes while fusing cards.", "진균학자가 카드를 융합할 때 실수할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Old Fecundity", "옛 생식력", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reverts the Fecundity Nerf.", "생식력의 하향을 되돌린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mulligan", "다시 뽑기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You may redraw your hand at the start of each battle.", "매 전투 시작 시 패를 다시 뽑을 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reverse Scales", "반대 저울", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start all battles with 1 damage on the opponent's side of the scale.", "모든 전투를 저울의 상대 쪽에 피해 1이 놓인 상태로 시작한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shocked Starters", "충격받은 시작 카드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards in starting deck attack every other turn.", "시작 덱의 카드들은 한 턴 걸러 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sprintmaggedon", "질주의 종말", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards get a random Sprinter sigil when drawn.", "모든 카드는 뽑힐 때 무작위 질주자 도장 하나를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Traveling Ouroboros", "여행하는 우로보로스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A traveling Ouroboros appears throughout the run.", "여행하는 우로보로스가 도전 중에 나타난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unfair Hand", "불공평한 패", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your starting hand is randomly drawn.", "시작 패를 무작위로 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explosive Noise", "폭발 소음", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card dies, a loud boom will play. All cards explode on death.", "카드가 죽으면 큰 폭발음이 난다. 모든 카드는 죽을 때 폭발한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aquatic Starters", "수생 시작 카드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards in starting deck have the Waterborne sigil.", "시작 덱의 카드들은 수생 도장을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unspirited Starters", "영혼 잃은 시작 카드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards in the starting deck may not have their sigils transferred.", "시작 덱 카드들의 도장은 옮길 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weak Starters", "약해진 시작 카드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards in the starting deck have 1 less health.", "시작 덱의 카드들은 체력이 1 적다.", Language.Korean);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Champion", "파란색 챔피언", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion will cause all other non-Terrain cards on the same side to gain flight, as long as the champion is alive.", "이 챔피언이 살아 있는 동안 같은 편의 다른 지형이 아닌 카드들은 모두 공수를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bright Red Champion", "선명한 빨간색 챔피언", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each turn, this champion will heal all other non-terrain creatures on the opponent's side by 1.", "매 턴 시작 시 이 챔피언은 상대편의 다른 지형이 아닌 피조물들을 모두 체력 1만큼 치유한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cyan Champion", "청록색 챔피언", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this champion perishes, it will deal 1 damage to every other creature on the board.", "이 챔피언이 죽으면 보드의 다른 모든 피조물에게 피해를 1 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explosive", "폭발물", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Other cards may be placed on top of [creature]; the other card, adjacent cards, and opposing cards will all be dealt 10 damage.", "다른 카드를 [creature] 카드 위에 놓을 수 있다. 놓은 카드와 인접한 카드, 맞은편 카드가 모두 피해를 10 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a copy of it is created in the opponent's hand.", "[creature] 카드가 죽으면 그 카드의 사본이 상대의 패에 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fragile", "깨지기 쉬움", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] perishes, it is permanently removed from your deck.", "[creature] 카드가 죽으면 당신의 덱에서 영구적으로 제거된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Champion", "녹색 챔피언", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion will deal 1 damage directly to you, after it destroys another creature.", "이 챔피언은 다른 피조물을 파괴한 뒤 그 챔피언의 상대에게 직접 피해를 1 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Light Blue Champion", "연한 파란색 챔피언", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this champion perishes, it will deal 3 damage to creatures to the left and right of it as well as the opposing creature.", "이 챔피언이 죽으면 좌우의 피조물과 맞은편 피조물에게 피해를 3 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Light Green Champion", "연한 녹색 챔피언", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion will prevent all damage from the first strike dealt to it. Damage from effects like sigils will not be prevented.", "이 챔피언은 자신에게 가해진 첫 번째 공격의 피해를 모두 막는다. 도장 등의 효과로 인한 피해는 막지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magenta Champion", "자홍색 챔피언", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each turn, this champion will attack for 1 damage in a random space on your side.", "매 턴 시작 시 이 챔피언은 당신 측의 무작위 칸을 공격하여 피해를 1 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muddy", "오물의 파도", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Other cards may be placed on top of [creature], but will be unable to attack for one turn and will gain Muddy. If [creature] is sacrificed, the sacrificing creature will be unable to attack for one turn.", "다른 카드를 [creature] 카드 위에 놓을 수 있지만, 그 카드는 한 턴 동안 공격할 수 없고 오물의 파도를 얻는다. [creature] 카드가 희생되면 그 희생으로 나온 피조물은 한 턴 동안 공격할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificial Slab", "희생 석판", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Other cards may be placed on top of [creature]; the other card will die.", "다른 카드를 [creature] 카드 위에 놓을 수 있다. 놓은 카드는 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Champion", "오렌지색 챔피언", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion will steal 2 golden teeth from you if it damages you directly.", "이 챔피언이 당신에게 직접 피해를 주면 금니 2개를 훔친다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] may not attack every other turn.", "[creature] 카드는 한 턴 걸러 공격할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purple Champion", "보라색 챔피언", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each time you play a card, if the space opposing this champion is empty, that card will move to that space.", "당신이 카드를 낼 때마다 이 챔피언의 맞은편 칸이 비어 있으면 그 카드는 그 칸으로 움직인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seaworthy", "항해 적합", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Other cards may be placed on top of [creature], any Waterborne sigils on the card will be negated.", "다른 카드를 [creature] 카드 위에 놓을 수 있다. 그 카드의 수생 도장은 모두 무효화된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Red Champion", "빨간색 챔피언", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion starts with 2 additional Health.", "이 챔피언은 체력 2를 추가로 지닌 채 시작한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shelter", "피난처", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adjacent cards are sheltered from environmental effects.", "인접한 카드는 환경 효과로부터 보호받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avalancher", "눈사태 유발자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. Creatures in the way will be killed. If [creature] is at the right most side of the board, it dies.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 움직인다. 길을 막는 피조물은 죽는다. [creature] 카드가 보드의 맨 오른쪽에 있으면 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in the direction inscribed in the sigil. Creatures in the way will be killed.", "주인의 턴이 끝날 때 [creature] 카드는 도장에 표시된 방향으로 움직인다. 길을 막는 피조물은 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move to the right, jumping over any creatures in its path. If it encounters the edge of the board, it will loop over to the other side.", "주인의 턴이 끝날 때 [creature] 카드는 오른쪽으로 움직이며 경로의 모든 피조물을 뛰어넘는다. 보드 끝에 닿으면 반대편으로 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "White Champion", "흰색 챔피언", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this champion perishes, it will create a Boulder in its space. [define:Boulder]", "이 챔피언이 죽으면 자신의 칸에 바위를 생성한다. [define:Boulder]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yellow Champion", "노란색 챔피언", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This champion starts with 1 additional Power.", "이 챔피언은 공격력 1을 추가로 지닌 채 시작한다.", Language.Korean);

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slot Spawner", "슬롯 생성기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When played, spawns a slot. Used for testing.", "카드를 내면 슬롯을 생성한다. 시험용이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When played, converts the slot into a Raft.", "카드를 내면 그 슬롯을 뗏목으로 바꾼다.", Language.Korean);
            // Boon
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Angler's Pond", "환경: 낚시꾼의 연못", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Bait Buckets.", "상대는 미끼 양동이를 지닌 채 전투를 시작한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Blizzard", "환경: 눈보라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each turn, if there is not an Avalanche present on the board, one will be created on the left-most side of the board.", "매 턴 시작 시 보드에 눈사태가 없으면 보드의 맨 왼쪽에 하나가 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Blood Moon", "환경: 핏빛 달", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Dire Wolf Pups.", "상대는 이리 새끼를 지닌 채 전투를 시작한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Breeze", "환경: 산들바람", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of every turn, all creatures gain or lose Airborne. Terrain, and creatures with Waterborne or Burrower are ignored.", "매 턴 시작 시 모든 피조물은 공수를 얻거나 잃는다. 지형과 수생 또는 굴살이를 지닌 피조물은 영향을 받지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Carrot Patch", "환경: 당근밭", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Rabbits.", "상대는 토끼를 지닌 채 전투를 시작한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Cliffside", "환경: 절벽 가장자리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the battle, the leftmost lane will be blocked with Cliffs.", "전투 시작 시 맨 왼쪽 공격로가 절벽으로 막힌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Factory", "환경: 공장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "On Upkeep, all cards are rotated clockwise.", "유지 단계에 모든 카드가 시계 방향으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Dark Forest", "환경: 어두운 숲", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Trees. All of the opponent's terrain have +1 power.", "상대는 나무를 지닌 채 전투를 시작한다. 상대의 모든 지형은 공격력을 +1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Prospector's Camp", "환경: 광부의 야영지", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will start the battle with Dynamite on some of your spaces.", "전투를 시작할 때 당신 측 일부 칸에 다이너마이트가 놓인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Electrical Storm", "환경: 뇌우", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card is played, it takes 1 damage and gains 1 power.", "카드를 내면 그 카드는 피해를 1 받고 공격력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Flash Growth", "환경: 급속 성장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card is played, any sigils that activate at the start of the turn are activated.", "카드를 내면 그 카드의 턴 시작 시 활성화되는 도장이 모두 활성화된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Flood", "환경: 홍수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever a creature is played, it gains Waterborne. Terrain, and creatures with Airborne are ignored.", "피조물을 낼 때마다 그 피조물은 수생을 얻는다. 지형과 공수를 지닌 피조물은 영향을 받지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Gem Sanctuary", "환경: 보석 성소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All gems have +1 power.", "모든 보석은 공격력을 +1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Graveyard", "환경: 묘지", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature dies, it dies again.", "피조물이 죽으면 다시 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Hail Storm", "환경: 우박 폭풍", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of each turn, all of the turn owner's non-terrain cards take 1 damage.", "매 턴 시작 시 해당 턴 주인의 지형이 아닌 모든 카드는 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Pirate's Hollow", "환경: 해적의 골짜기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with a Minicello.", "상대는 미니첼로 호를 지닌 채 전투를 시작한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Mud Swamp", "환경: 진흙탕", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will start the battle with Mud on some of your spaces.", "전투를 시작할 때 당신 측 일부 칸에 진흙탕이 놓인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Fungal Field", "환경: 균류 들판", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Mushrooms.", "상대는 버섯을 지닌 채 전투를 시작한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Obelisk", "환경: 오벨리스크", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with an Obelisk.", "상대는 오벨리스크를 지닌 채 전투를 시작한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Cursed Totem", "환경: 저주받은 토템", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Cursed Totems.", "상대는 저주받은 토템을 지닌 채 전투를 시작한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Environment: Trapper's Hunting Grounds", "환경: 덫 사냥꾼의 사냥터", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The opponent will start the battle with Steel Traps.", "상대는 강철 덫을 지닌 채 전투를 시작한다.", Language.Korean);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascender's Bane", "등반자의 재앙", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A reminder of past challengers.", "과거 도전자들을 떠올리게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avalanche", "눈사태", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A monsterous mound of snow.", "거대한 눈더미다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cliff", "절벽", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A solid wall of rock.", "단단한 바위 벽이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clover", "클로버", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal member of Royal's crew.", "로얄 선원들의 충실한 일원이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dynamite", "다이너마이트", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A box of dynamite.", "다이너마이트 한 상자다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chrysomallos", "황금 양", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mystical, glittering being.", "신비롭게 반짝이는 존재다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Cube", "얼음덩이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A block of ice.", "얼음덩어리다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minicello", "미니첼로 호", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A miniture version of a famous pirate's ship.", "유명한 해적선의 축소판이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mud", "진흙탕", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mushrooms", "버섯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of strange mushrooms. They attract anything nearby.", "기이한 버섯 무리다. 근처의 모든 것을 끌어당긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obelisk", "오벨리스크", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tall mysterious stone.", "높이 솟은 신비로운 돌이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrificial Altar", "희생 제단", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flat mysterious stone.", "납작한 신비로운 돌이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raft", "뗏목", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A dry patch in the flood.", "홍수 속의 마른 땅이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shelter", "피난처", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shelter from the storm.", "폭풍을 피할 수 있는 피난처다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Totem", "저주받은 토템", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A totem surrounded in mysterious energy.", "신비로운 에너지에 둘러싸인 토템이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My very own Ouroboros.", "나만의 우로보로스다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wooden Board", "나무판자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A regular wooden board.", "평범한 나무판자다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mole Firstmate", "두더지 일등 항해사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ourobot", "우로봇", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Living {0}", "살아 있는 {0}", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps a mutation?", "돌연변이일까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raft Slot", "뗏목 슬롯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prevents creatures on this slot from submerging into the water.", "이 슬롯의 피조물이 물속에 잠기는 것을 막는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muddy Slot", "진흙탕 슬롯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played on this slot, it cannot attack for one turn.", "이 슬롯에 피조물을 내면 그 피조물은 한 턴 동안 공격할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hail Slot", "우박 슬롯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, a creature in this slot takes 1 damage.", "주인의 턴 시작 시 이 슬롯의 피조물은 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flooded Slot", "침수된 슬롯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played in this slot, it gets submerged in the water unless it is flying.", "이 슬롯에 피조물을 내면 날고 있지 않은 한 물속에 잠긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Windy Slot", "바람 부는 슬롯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, a creature in this slot will alternate between flying and not flying. This effect is ignored if the creature naturally flies, submerges, or burrows.", "주인의 턴 시작 시 이 슬롯의 피조물은 비행과 비행하지 않는 상태를 번갈아 오간다. 원래 날거나 잠수하거나 땅을 파는 피조물은 이 효과를 무시한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Slot", "음산한 슬롯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature dies in this slot, it dies again.", "이 슬롯에서 피조물이 죽으면 다시 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Growth Slot", "성장 슬롯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played in this slot, instantly evolve it if it has an evolve related sigil. If it does not have Fledgling, it instead gains Fledgling.", "이 슬롯에 피조물을 내면 진화 관련 도장이 있을 경우 즉시 진화한다. 햇병아리가 없다면 대신 햇병아리를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overclocking Slot", "오버클럭 슬롯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played in this slot, it takes 1 damage and gains 1 attack.", "이 슬롯에 피조물을 내면 그 피조물은 피해를 1 받고 공격력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dynamite Slot", "다이너마이트 슬롯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played in this slot, it takes 10 damage and explodes. The dynamite is removed.", "이 슬롯에 피조물을 내면 그 피조물은 피해를 10 받고 폭발한다. 다이너마이트는 제거된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obelisk Tablet", "오벨리스크 석판", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature is played in this slot, it is sacrificed.", "이 슬롯에 피조물을 내면 그 피조물은 희생된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is truly a worthy sacrifice.", "이것은 참으로 가치 있는 제물이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a thing... does not bleed.", "이런 것은... 피를 흘리지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The obelisk does not react.", "오벨리스크는 반응하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps, something greater.", "아마 더 위대한 것이 필요할지도 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The thick [c:G]mud[c:] stuck to your boots, and hindered your movements...", "진득한 [c:G]진흙탕[c:]이 장화에 달라붙어 움직임을 방해했다...", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The glade glowed with unnatural light.", "숲속 빈터가 부자연스러운 빛을 발했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the area stank of rotting fish,", "주변에는 썩은 물고기 냄새가 진동했고,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps they are sick?", "아마 병에 걸린 걸까?", Language.Korean);
        }
    }
    public class NewSpellCardToolkitMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for NewSpellCardToolkit Mod");
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Attack Up", "공격력 증가", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Increases the target's attack for the rest of the battle.", "전투가 끝날 때까지 대상의 공격력을 높인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Attack Down", "공격력 감소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Decreases the target's attack for the rest of the battle.", "전투가 끝날 때까지 대상의 공격력을 낮춘다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cataclysm", "대격변", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, all other cards on the boards perish as well.", "[creature] 카드가 죽으면 보드의 다른 모든 카드도 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Direct Damage", "직접 피해", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deals damage directly to a target.", "대상에게 직접 피해를 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Direct Heal", "직접 치유", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heals the target. This can heal the target beyond its original max health.", "대상을 치유한다. 이 효과로 대상의 체력을 원래 최대치보다 높일 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draw Twice", "두 번 뽑기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, draw two more cards and add them to your deck.", "[creature] 카드가 죽으면 카드를 두 장 더 뽑아 패에 넣는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Control", "제어권 획득", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Takes control of the targeted creature.", "대상 피조물의 제어권을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give Sigils", "도장 부여", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gives this card's sigils to the target.", "이 카드의 도장을 대상에게 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give Stats", "능력치 부여", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gives this card's stats to the target.", "이 카드의 능력치를 대상에게 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give Stats and Sigils", "능력치와 도장 부여", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gives this card's stats and sigils to the target.", "이 카드의 능력치와 도장을 대상에게 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell (Global)", "주문 (전체)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played anywhere on the board, it will cause an immediate effect and then disappear.", "이 카드를 보드의 어느 곳에든 내면 즉시 효과가 발동하고 사라진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GLOBAL SPELL.", "전체 주문.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell (Global, Instant)", "주문 (전체, 즉시)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played, it will cause an immediate effect and then disappear.", "이 카드를 내면 즉시 효과가 발동하고 사라진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INSTA-GLOBAL SPELL.", "즉시 전체 주문.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell (Targeted)", "주문 (대상 지정)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played, it will target and affect a chosen space on the board and then disappear.", "이 카드를 내면 보드에서 선택한 칸을 대상으로 효과를 발휘한 뒤 사라진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TARGETED SPELL.", "대상 지정 주문.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Command (Global)", "명령 (전체)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played anywhere on the board, it will cause an immediate effect and then disappear.", "이 카드를 보드의 어느 곳에든 내면 즉시 효과가 발동하고 사라진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GLOBAL COMMAND.", "전체 명령.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Command (Global, Instant)", "명령 (전체, 즉시)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played, it will cause an immediate effect and then disappear.", "이 카드를 내면 즉시 효과가 발동하고 사라진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INSTA-GLOBAL COMMAND.", "즉시 전체 명령.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Command (Targeted)", "명령 (대상 지정)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is played, it will target and affect a chosen space on the board and then disappear.", "이 카드를 내면 보드에서 선택한 칸을 대상으로 효과를 발휘한 뒤 사라진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TARGETED COMMAND.", "대상 지정 명령.", Language.Korean);

        }
    }
    public class P03SigilariumMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for P03Sigilarium Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Urch1n Cell", "기계 성게 배터리", Language.Korean);
            P03InKayceesModMod.RegisterCard("Urch1n Cell", "기계 성게 배터리");
            P03InKayceesModMod.RegisterCardPart("Urch1n", "기계 성게");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charge!", "충전!", Language.Korean);
            P03InKayceesModMod.RegisterCard("Charge!", "충전!");
            P03InKayceesModMod.RegisterCardPart("Charge!", "충전!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upgrade!", "업그레이드!", Language.Korean);
            P03InKayceesModMod.RegisterCard("Upgrade!", "업그레이드!");
            P03InKayceesModMod.RegisterCardPart("Upgrade!", "업그레이드!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zap!", "전기 충격!", Language.Korean);
            P03InKayceesModMod.RegisterCard("Zap!", "전기 충격!");
            P03InKayceesModMod.RegisterCardPart("Zap!", "전기 충격!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blast!", "폭발!", Language.Korean);
            P03InKayceesModMod.RegisterCard("Blast!", "폭발!");
            P03InKayceesModMod.RegisterCardPart("Blast!", "폭발!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defend!", "방어!", Language.Korean);
            P03InKayceesModMod.RegisterCard("Defend!", "방어!");
            P03InKayceesModMod.RegisterCardPart("Defend!", "방어!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Junk", "고철 더미", Language.Korean);
            P03InKayceesModMod.RegisterCard("Junk", "고철 더미");
            P03InKayceesModMod.RegisterCardPart("Junk", "고철 더미");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "S4LM0N", "기계 연어", Language.Korean);
            P03InKayceesModMod.RegisterCard("S4LM0N", "기계 연어");
            P03InKayceesModMod.RegisterCardPart("S4LM0N", "기계 연어");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seed", "씨앗", Language.Korean);
            P03InKayceesModMod.RegisterCard("Seed", "씨앗");
            P03InKayceesModMod.RegisterCardPart("Seed", "씨앗");

            // Ability

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "APPENDIX XII, SUBSECTION I - Additional Mechanics {0}", "부록 XII, 제 I 절 - 추가 규칙 {0}", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shield Absorption", "보호막 흡수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all creatures lose their shields. This creature gains 1 attack for each shield lost this way.", "[creature] 카드를 내면 모든 피조물이 보호막을 잃는다. 이렇게 잃은 보호막 하나마다 이 피조물은 공격력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rapid Recycle", "고속 재활용", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Energy to choose another card you control to die and immediately respawn. You may only activate this ability once per turn.", "에너지 1을 소비해 당신이 조종하는 다른 카드 하나를 선택하여 죽이고 즉시 다시 등장시킨다. 이 능력은 턴당 한 번만 활성화할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Supercharge", "과충전", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: friendly cards gain 1 power until the end of the turn. This ability can only be activated once per turn.", "연료 하나를 소비한다: 아군 카드들이 턴이 끝날 때까지 공격력을 1 얻는다. 이 능력은 턴당 한 번만 활성화할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Copy and Paste", "복사와 붙여넣기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The controller of [creature] chooses two cards they control. The second card's sigils are replaced with the sigils of the first.", "[creature] 카드의 조종자는 자신이 조종하는 카드 두 장을 선택한다. 두 번째 카드의 도장이 첫 번째 카드의 도장으로 대체된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a card to copy sigils from", "도장을 복사할 카드를 선택한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a card to paste sigils onto", "도장을 붙여넣을 카드를 선택한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cannon Fire", "대포 발사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: Create a Blast! card in hand. Blast! is defined as a spell that costs 2 energy and sets the target on fire. This ability can only be activated once per turn.", "연료 하나를 소비한다: 패에 '폭발!' 카드 한 장을 생성한다. '폭발!'은 비용이 에너지 2이며 대상에 불을 붙이는 주문이다. 이 능력은 턴당 한 번만 활성화할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: Create a Blast! card in hand. Blast! is defined as a command that costs 2 energy and sets the target on fire. This ability can only be activated once per turn.", "연료 하나를 소비한다: 패에 '폭발!' 카드 한 장을 생성한다. '폭발!'은 비용이 에너지 2이며 대상에 불을 붙이는 명령이다. 이 능력은 턴당 한 번만 활성화할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recharge Reserves", "충전 비축", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Energy to create a Charge in your hand. Charge is defined as a spell that refills 1 Energy when played.", "에너지 2를 소비해 패에 '충전!'을 생성한다. '충전!'은 낼 때 에너지 1을 회복하는 주문이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Energy to create a Charge in your hand. Charge is defined as a command that refills 1 Energy when played.", "에너지 2를 소비해 패에 '충전!'을 생성한다. '충전!'은 낼 때 에너지 1을 회복하는 명령이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Holo Weaver", "홀로그램 직조자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, create a Defend! card in hand. Defend! is defined as a spell that costs 2 energy and gives the target a shield.", "턴당 한 번, 패에 '방어!' 카드 한 장을 생성한다. '방어!'는 비용이 에너지 2이며 대상에게 보호막을 주는 주문이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, create a Defend! card in hand. Defend! is defined as a command that costs 2 energy and gives the target a shield.", "턴당 한 번, 패에 '방어!' 카드 한 장을 생성한다. '방어!'는 비용이 에너지 2이며 대상에게 보호막을 주는 명령이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Future Sight", "미래 예지", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Look at the top card of your deck. You can play it.", "덱 맨 위의 카드를 본다. 그 카드를 낼 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fossil Fuel", "화석 연료", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Provides an additional energy cell.", "추가 에너지 슬롯 하나를 제공한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dispenser", "분배기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain a random item.", "무작위 아이템 하나를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overcharge", "과충전", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Energy to increase the Power of this card by 1.", "에너지 4를 소비해 이 카드의 공격력을 1 높인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enrage", "오버클럭 우두머리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay Energy equal to the Power of this card plus 2 to increase the Power of this card by 1.", "이 카드의 공격력에 2를 더한 만큼의 에너지를 소비해 이 카드의 공격력을 1 높인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drive", "구동", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: move in the direction inscribed in this sigil. This ability can only be activated once per turn.", "연료 하나를 소비한다: 이 도장에 표시된 방향으로 움직인다. 이 능력은 턴당 한 번만 활성화할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "D-Pad", "십자키", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Move to an adjacent empty lane.", "인접한 빈 공격로로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "D-Pad Left", "십자키 왼쪽", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Move to the lane to the left, if it is empty.", "왼쪽 공격로가 비어 있으면 그곳으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "D-Pad Right", "십자키 오른쪽", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Move to the lane to the right, if it is empty.", "오른쪽 공격로가 비어 있으면 그곳으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerge", "잠수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: submerge during the opponent's turn. While submerged, opposing creatures attack its owner directly.", "연료 하나를 소비한다: 상대의 턴 동안 물속에 잠긴다. 잠수 중에는 상대 피조물이 그 주인을 직접 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tow Hook", "견인 갈고리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spend one fuel: tow an opposing creature to your side of the board until end of turn. Creatures being towed cannot be hammered. This ability can only be activated once per turn.", "연료 하나를 소비한다: 상대 피조물 하나를 턴이 끝날 때까지 당신 측 보드로 끌어온다. 끌려온 피조물은 망치로 칠 수 없다. 이 능력은 턴당 한 번만 활성화할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Button Pusher", "버튼 누르기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all activated sigils and sigils that trigger on play or on death are activated.", "[creature] 카드를 내면 모든 활성화 도장과 출전 또는 사망 시 발동하는 도장이 활성화된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasitic Control", "기생 지배", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all opposing cards are moved to your side of the board.", "[creature] 카드를 내면 상대 카드들이 모두 당신 측 보드로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Power", "에너지 공격력", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of times the player has spent energy this turn.", "이 도장이 나타내는 값은 플레이어가 이번 턴에 에너지를 소비한 횟수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Holo Trap", "홀로그램 함정", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the creature opposing it perishes as well. A Vessel is created in your hand.", "이 도장을 지닌 카드가 죽으면 맞은편 피조물도 죽는다. 패에 그릇 한 장이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brittle Lord", "취약성의 영주", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, cards with Brittle have Unkillable.", "[creature] 카드가 살아 있는 동안 취약성을 지닌 카드들은 불사를 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buck Wild", "거친 돌진", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon taking damage, this card will charge into the opposing slot, killing anything in its way.", "이 카드는 피해를 받으면 맞은편 슬롯으로 돌진해 길을 막는 모든 것을 죽인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Slot (1)", "불타는 슬롯 (1)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slot is on fire! It deals one damage to the card in it at the end of the turn. This effect lasts one turn.", "이 슬롯에 불이 붙었다! 턴이 끝날 때 안에 있는 카드에 피해를 하나 준다. 이 효과는 한 턴 지속된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Slot (2)", "불타는 슬롯 (2)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slot is on fire! It deals one damage to the card in it at the end of the turn. This effect lasts two turns.", "이 슬롯에 불이 붙었다! 턴이 끝날 때 안에 있는 카드에 피해를 하나 준다. 이 효과는 두 턴 지속된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Slot (3)", "불타는 슬롯 (3)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slot is on fire! It deals one damage to the card in it at the end of the turn. This effect lasts three turns.", "이 슬롯에 불이 붙었다! 턴이 끝날 때 안에 있는 카드에 피해를 하나 준다. 이 효과는 세 턴 지속된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Slot (4)", "불타는 슬롯 (4)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This slot is on fire! It deals one damage to the card in it at the end of the turn. This effect lasts four turns.", "이 슬롯에 불이 붙었다! 턴이 끝날 때 안에 있는 카드에 피해를 하나 준다. 이 효과는 네 턴 지속된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burnt Out", "연소 소진", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it sets the land on fire for three turns.", "[creature] 카드가 죽으면 땅에 불을 붙여 세 턴 동안 타게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "on fire", "불타는 중", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catch Fire", "불붙이기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] targets a slot, the target is set on fire.", "[creature] 카드가 슬롯을 대상으로 삼으면 그 슬롯에 불이 붙는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transforms When Unpowered", "충전되지 않았을 때 변신", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is NOT within a circuit at the beginning of the turn, it will transform back into its original form.", "턴 시작 시 [creature] 카드가 회로 안에 없으면 원래 형태로 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Waterborne When Unpowered", "충전되지 않았을 때 수생", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is NOT within a circuit it submerges itself during its opponent's turn. While submerged, opposing creatures attack its owner directly.", "[creature] 카드가 회로 안에 없으면 상대의 턴 동안 물속에 잠긴다. 잠수 중에는 상대 피조물이 그 주인을 직접 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Short Circuit", "합선", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit at the beginning of the turn, create a Zap! in your hand. Zap! is defined as a spell that costs 2 energy and deals 1 damage to any target.", "턴 시작 시 [creature] 카드가 회로 안에 있으면 패에 '전기 충격!'을 생성한다. '전기 충격!'은 비용이 에너지 2이며 원하는 대상에게 피해를 1 주는 주문이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit at the beginning of the turn, create a Zap! in your hand. Zap! is defined as a command that costs 2 energy and deals 1 damage to any target.", "턴 시작 시 [creature] 카드가 회로 안에 있으면 패에 '전기 충격!'을 생성한다. '전기 충격!'은 비용이 에너지 2이며 원하는 대상에게 피해를 1 주는 명령이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transforms When Powered", "충전되었을 때 변신", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit at the beginning of the turn, it will transform into a stronger form.", "턴 시작 시 [creature] 카드가 회로 안에 있으면 더 강한 형태로 변신한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explodonate When Powered", "충전 시 체리 폭탄", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit, it detonates itself and deals 10 damage to all five adjacent spaces.", "[creature] 카드가 회로 안에 있으면 스스로 폭발해 인접한 다섯 칸 모두에 피해를 10 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mental Gemnastics When Powered", "충전 시 심리적 뵤기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, if it is within a circuit, its owner draw cards equal to the number of Mox Cards on their side of the game board.", "[creature] 카드를 낼 때 회로 안에 있으면 그 주인은 자기 측 보드의 목스 카드 수만큼 카드를 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trap When Powered", "충전 시 함정", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes while in a circuit, the creature opposing it perishes as well. A Vessel is created in your hand.", "이 도장을 지닌 카드가 회로 안에서 죽으면 맞은편 피조물도 죽는다. 패에 그릇 한 장이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unkillable When Powered", "충전 시 불사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is within a circuit when it perishes, a copy of it is created in your hand.", "[creature] 카드가 회로 안에서 죽으면 그 카드의 사본이 패에 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Splice Conduit", "접합 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] completes a circuit, all cards within that circuit are moved towards it, splicing with it if possible.", "[creature] 카드가 회로를 완성하면 그 회로 안의 모든 카드가 그 카드 쪽으로 움직이며 가능하면 접합된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky Conduit", "구린내 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards within a circuit completed by [creature] have Stinky.", "[creature] 카드가 완성한 회로 안의 카드들은 구린내를 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Airborne Conduit", "공수 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards within a circuit completed by [creature] have Airborne.", "[creature] 카드가 완성한 회로 안의 카드들은 공수를 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gas Conduit", "가스 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards within a circuit completed by [creature] have Fire Strike and Burnt Out.", "[creature] 카드가 완성한 회로 안의 카드들은 화염 타격과 연소 소진을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bedazzling Conduit", "찬란한 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards within a circuit completed by [creature] are Gemified.", "[creature] 카드가 완성한 회로 안의 카드들은 보석화된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Static Electricity", "정전기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will cause all friendly cards to behave as if they are part of a completed conduit.", "[creature] 카드는 모든 아군 카드가 완성된 회로 안에 있는 것처럼 작동하게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gas Generator", "가스 발전기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as it has fuel, [creature] will cause all friendly cards to behave as if they are part of a completed conduit.", "연료가 있는 동안 [creature] 카드는 모든 아군 카드가 완성된 회로 안에 있는 것처럼 작동하게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conduit Protector", "전도체 수호자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is within a completed circuit, damage that would be dealt to the conduits is dealt to this creature instead.", "[creature] 카드가 완성된 회로 안에 있으면 전도체가 받을 피해를 이 피조물이 대신 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Byte", "죽음의 바이트", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, take 1 damage.", "이 도장을 지닌 카드가 죽으면 당신은 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Sprinter", "이중 질주", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, a card bearing this sigil will move in the direction inscribed in the sigil twice.", "주인의 턴이 끝날 때 이 도장을 지닌 카드는 도장에 표시된 방향으로 두 번 움직인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brittle Summoner", "취약성 소환사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a random brittle card is created in your hand.", "[creature] 카드를 내면 패에 무작위 취약성 카드 한 장이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iterate", "반복", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a copy of it with a different cost is created in your hand.", "[creature] 카드를 내면 비용이 다른 사본이 패에 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tinkerer", "수리공", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, create three spell cards selected at random.", "[creature] 카드를 내면 무작위로 선택된 주문 카드 세 장을 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, create three command cards selected at random.", "[creature] 카드를 내면 무작위로 선택된 명령 카드 세 장을 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phasers Ready", "페이저 준비 완료", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, create two Zap! cards in hand. Zap! is defined as a spell that costs 2 energy and deals 1 damage to any target.", "[creature] 카드를 내면 패에 '전기 충격!' 카드 두 장을 생성한다. '전기 충격!'은 비용이 에너지 2이며 원하는 대상에게 피해를 1 주는 주문이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, create two Zap! cards in hand. Zap! is defined as a command that costs 2 energy and deals 1 damage to any target.", "[creature] 카드를 내면 패에 '전기 충격!' 카드 두 장을 생성한다. '전기 충격!'은 비용이 에너지 2이며 원하는 대상에게 피해를 1 주는 명령이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Combat Research", "전투 연구", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, create a Forced Upgrade card in hand. Forced Upgrade is defined as a spell that costs 2 energy and caused any target to upgrade to a new version.", "[creature] 카드가 피해를 주면 패에 '강제 업그레이드'를 생성한다. '강제 업그레이드'는 비용이 에너지 2이며 원하는 대상을 새 버전으로 업그레이드하는 주문이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, create a Forced Upgrade card in hand. Forced Upgrade is defined as a command that costs 2 energy and caused any target to upgrade to a new version.", "[creature] 카드가 피해를 주면 패에 '강제 업그레이드'를 생성한다. '강제 업그레이드'는 비용이 에너지 2이며 원하는 대상을 새 버전으로 업그레이드하는 명령이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Electric", "전력 유도", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] declares an attack, it will deal half the damage to cards adjacent to the target.", "[creature] 카드가 공격을 선언하면 대상과 인접한 카드들에 절반의 피해를 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Mox Buff", "초록 목스 강화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it gains two health for each Green Mox its owner controls.", "[creature] 카드를 내면 주인이 조종하는 초록 목스 하나마다 체력을 2 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Blessing", "에메랄드 축복", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] provides +2 Health to all creatures you control.", "[creature] 카드는 당신이 조종하는 모든 피조물에게 체력 +2를 제공한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Shard", "에메랄드 조각", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, an Emerald Mox is created in its place and a card bearing this sigil moves to the right.", "[creature] 카드가 공격받으려 할 때 그 자리에 에메랄드 목스가 생성되고 이 도장을 지닌 카드는 오른쪽으로 움직인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Armor Giver", "장갑 부여자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] enters, all opposing cards gain Nano Armor.", "[creature] 카드가 등장하면 모든 상대 카드가 나노 장갑을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Siphon", "에너지 흡수관", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever another card you own dies in combat, [creature] creates a Charge in your hand. Charge is a spell that refills 1 Energy when played.", "당신이 소유한 다른 카드가 전투 중 죽을 때마다 [creature] 카드는 패에 '충전!'을 생성한다. '충전!'은 낼 때 에너지 1을 회복하는 주문이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever another card you own dies in combat, [creature] creates a Charge in your hand. Charge is a command that refills 1 Energy when played.", "당신이 소유한 다른 카드가 전투 중 죽을 때마다 [creature] 카드는 패에 '충전!'을 생성한다. '충전!'은 낼 때 에너지 1을 회복하는 명령이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explodonate", "체리 폭탄", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it explodes and deals 10 damage to all five adjacent slots.", "[creature] 카드가 죽으면 폭발해 인접한 다섯 슬롯 모두에 피해를 10 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire Strike", "화염 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, it sets the target space on fire for three turns.", "[creature] 카드가 공격하면 대상 칸에 불을 붙여 세 턴 동안 타게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire Strike When Fueled", "연료가 있을 때 화염 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] attacks, if it is fueled, it consumes one fuel to set the target space on fire for three turns.", "[creature] 카드가 공격할 때 연료가 있으면 연료 하나를 소비해 대상 칸에 불을 붙여 세 턴 동안 타게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame Stoker", "불길을 키우는 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While [creature] is on board, all fires you start will be stronger, causing them to last one turn longer.", "[creature] 카드가 보드에 있는 동안 당신이 붙인 모든 불이 강해져 한 턴 더 오래 지속된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fling", "내던지기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, if one or more cards was sacrificed to play it, [creature] deals damage to a card of the player's choice equal to the total attack value of all sacrificed cards.", "[creature] 카드를 내기 위해 카드 한 장 이상을 희생했다면, 낼 때 [creature] 카드는 플레이어가 선택한 카드에 희생한 모든 카드의 공격력 합계만큼 피해를 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upgrade", "강제 업그레이드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] targets a slot, the target is immediately upgraded to a stronger version of itself.", "[creature] 카드가 슬롯을 대상으로 삼으면 대상은 즉시 더 강한 버전으로 업그레이드된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Donation", "헌혈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, all friendly cards can be sacrificed to pay blood costs even if they normally could not.", "[creature] 카드가 살아 있는 동안 평소 희생할 수 없는 카드까지 모든 아군 카드를 피 비용을 지불하기 위해 희생할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stone Giver", "굳건함 부여자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, all friendly cards are Made of Stone", "[creature] 카드가 살아 있는 동안 모든 아군 카드는 굳건함을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dust Giver", "가루 부여자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, all friendly cards have Magic Dust.", "[creature] 카드가 살아 있는 동안 모든 아군 카드는 마법 가루를 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coal Roller", "검은 매연", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, all friendly cards which have fuel are Stinky.", "[creature] 카드가 살아 있는 동안 연료가 있는 모든 아군 카드는 구린내를 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Ignition", "보석 점화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] is alive, all friendly gems have +1 Power, Flame Strike, Brittle, and Burnt Out.", "[creature] 카드가 살아 있는 동안 모든 아군 보석은 공격력 +1, 화염 타격, 취약성, 연소 소진을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fuel Strike", "연료 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] consumes one fuel to attack and can only attack if it has fuel.", "[creature] 카드는 공격할 때 연료 하나를 소비하며 연료가 있을 때만 공격할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card carries an external fuel source which powers one or more of its sigils. When a card's fuel tank empties, those sigils cease to function.", "이 카드는 하나 이상의 도장에 동력을 공급하는 외부 연료원을 지닌다. 카드의 연료 탱크가 비면 해당 도장들은 작동을 멈춘다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fuel", "연료", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fuel Shield", "연료 보호막", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as [creature] has fuel, it takes damage by losing fuel instead of health.", "[creature] 카드는 연료가 있는 동안 피해를 받으면 체력 대신 연료를 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fuel Siphon", "연료 흡수관", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever [creature] deals damage directly to the opponent, it gains that much fuel.", "[creature] 카드가 상대에게 직접 피해를 줄 때마다 그만큼의 연료를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full of Blood", "피로 가득함", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can be sacrificed to pay blood costs.", "[creature] 카드는 피 비용을 지불하기 위해 희생할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full of Oil", "연료 가득", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it adds 3 health to each card on either side and across from it.", "[creature] 카드가 죽으면 양옆과 맞은편의 각 카드에 체력을 3 더한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fully Loaded", "만재", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it leaves a permanent +1 attack bonus in the lane it occupied.", "[creature] 카드가 죽으면 자신이 있던 공격로에 영구적인 공격력 +1 보너스를 남긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot has its power increased by one.", "이 슬롯에 있는 카드의 공격력이 1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defend", "방어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] targets a slot, the target gains Nano Armor.", "[creature] 카드가 슬롯을 대상으로 삼으면 대상은 나노 장갑을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Mox Gift", "파란 목스 선물", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, if you control an Blue Mox, gain a random card.", "[creature] 카드가 죽으면 당신이 파란 목스를 조종할 경우 무작위 카드 한 장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Mox Looter", "파란 목스 노획자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage directly, if you control a Blue Mox, draw a card for each damage dealt.", "[creature] 카드가 직접 피해를 주면 당신이 파란 목스를 조종할 경우 피해 1당 카드 한 장을 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purist With Blue", "파란 순수주의", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If the owner of [creature] controls a Blue Mox, cards opposing [creature] have their sigils removed.", "[creature] 카드의 주인이 파란 목스를 조종하고 있으면 [creature] 카드의 맞은편 카드들은 도장을 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Without Green", "초록 없으면 구타유발자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature opposing [creature] gains 1 power unless the owner of [creature] also controls a Green Mox.", "[creature] 카드의 맞은편 피조물은 공격력을 1 얻는다. 단, [creature] 카드의 주인이 초록 목스도 조종하고 있으면 얻지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Mox Gift", "초록 목스 선물", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, if you control a Green Mox, gain a random card.", "[creature] 카드가 죽으면 당신이 초록 목스를 조종할 경우 무작위 카드 한 장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brittle Without Orange", "오렌지 없으면 취약성", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] will perish if its owner does not control an Orange Mox.", "[creature] 카드는 공격 후 주인이 오렌지 목스를 조종하고 있지 않으면 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Mox Airborne", "오렌지 목스 공수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you control an Orange Mox, [creature] will ignore opposing cards and strike an opponent directly.", "당신이 오렌지 목스를 조종하고 있으면 [creature] 카드는 맞은편 카드를 무시하고 상대를 직접 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Mox Printer", "오렌지 목스 프린터", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you control an Orange Mox, [creature] will draw a card from your side deck at the start of every turn.", "당신이 오렌지 목스를 조종하고 있으면 [creature] 카드는 매 턴 시작 시 당신의 보조 덱에서 카드 한 장을 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Strike", "보석 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] attacks once for each gem provider its owner controls.", "[creature] 카드는 주인이 조종하는 보석 제공자 하나당 한 번 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Power", "에메랄드의 힘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of green gems its owner controls.", "이 도장이 나타내는 값은 주인이 조종하는 초록 보석의 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hopper", "호퍼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, [creature] moves to an empty space of its owner's choosing.", "매 턴이 끝날 때 [creature] 카드는 주인이 선택한 빈칸으로 움직인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kraken Transformer", "크라켄 변신자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the beginning of your turn, [creature] will transform to, or from, Kraken mode.", "당신의 턴 시작 시 [creature] 카드는 크라켄 형태로 변하거나 그 형태에서 돌아온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Latch", "구타유발자 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Annoying sigil.", "[creature] 카드가 죽으면 주인은 구타유발자 도장을 부여할 피조물 하나를 고른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Latch", "죽음 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will die at the end of the turn. When [creature] perishes, its owner chooses a creature to gain this sigil. This will repeat.", "[creature] 카드는 턴이 끝날 때 죽는다. [creature] 카드가 죽으면 주인은 이 도장을 부여할 피조물 하나를 고른다. 이 과정이 반복된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Latch", "첫 도장 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the first sigil this card has.", "[creature] 카드가 죽으면 주인은 이 카드의 첫 번째 도장을 부여할 피조물 하나를 고른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Airborne Latch", "공수 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Airborne sigil.", "[creature] 카드가 죽으면 주인은 공수 도장을 부여할 피조물 하나를 고른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conduit Latch", "전도체 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Null Conduit sigil.", "[creature] 카드가 죽으면 주인은 무효화 전도체 도장을 부여할 피조물 하나를 고른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rampage Latch", "난동 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Rampager sigil. The target will immediately rampage once when the latch is applied.", "[creature] 카드가 죽으면 주인은 난동꾼 도장을 부여할 피조물 하나를 고른다. 대상은 랫치가 적용될 때 즉시 한 번 난동을 부린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky Latch", "구린내 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Stinky sigil.", "[creature] 카드가 죽으면 주인은 구린내 도장을 부여할 피조물 하나를 고른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swapper Latch", "교환자 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Swapper sigil. The target will immediately swap stats once when the latch is applied.", "[creature] 카드가 죽으면 주인은 교환자 도장을 부여할 피조물 하나를 고른다. 대상은 랫치가 적용될 때 즉시 능력치를 한 번 교환한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lootbox", "전리품 상자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever [creature] kills a card, a random card is created in your hand.", "[creature] 카드가 카드를 처치할 때마다 패에 무작위 카드 한 장이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Synchronized Fate", "운명 공유", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, you lose the game.", "[creature] 카드가 죽으면 당신은 게임에서 패배한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Dust", "마법 가루", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it leaves one of its gems behind on the board. Any future cards in that space will provide those gems.", "[creature] 카드가 죽으면 자신이 가진 보석 중 하나를 보드에 남긴다. 이후 그 칸에 놓이는 카드들은 해당 보석을 제공한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Mox Slot", "파란 목스 슬롯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot will provide a Blue Mox.", "이 슬롯의 카드는 파란 목스를 제공한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Mox Slot", "오렌지 목스 슬롯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot will provide an Orange Mox.", "이 슬롯의 카드는 오렌지 목스를 제공한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Green Mox Slot", "초록 목스 슬롯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot will provide a Green Mox.", "이 슬롯의 카드는 초록 목스를 제공한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great Mox Slot", "위대한 목스 슬롯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot will provide all three moxen.", "이 슬롯의 카드는 세 종류의 목스를 모두 제공한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miner", "광부", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] buries itself during its opponent's turn. While buried, opposing creatures attack its owner directly. When it comes back up, it creates a card in its owner's hand.", "[creature] 카드는 상대의 턴 동안 땅속에 숨는다. 숨어 있는 동안 상대 피조물은 그 주인을 직접 공격한다. 다시 올라오면 주인의 패에 카드를 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rubber Stamp", "고무 도장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever you play [creature], it becomes a copy of another creature of your choosing. If this creature has other abilities, those abilities will be transferred (up to the maximum of 4).", "[creature] 카드를 낼 때마다 당신이 선택한 다른 피조물의 사본이 된다. 이 피조물에게 다른 능력이 있으면 그 능력도 이전된다(최대 4개).", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Launch Missile", "미사일 발사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can skip its attack this turn to launch a missile that lands on the next turn, splashing damage to adjacent spaces. Use carefully - ammo is limited.", "[creature] 카드는 이번 턴의 공격을 건너뛰고 다음 턴에 떨어져 인접한 칸에도 피해를 주는 미사일을 발사할 수 있다. 탄약이 제한되어 있으니 신중히 사용하자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Launch Self", "자신 발사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can sacrifice itself to launch a missile that lands on the next turn, splashing damage to adjacent spaces.", "[creature] 카드는 자신을 희생해 다음 턴에 떨어져 인접한 칸에도 피해를 주는 미사일을 발사할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flammable", "가연성", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it detonates and sets adjacent spaces on fire for three turns.", "[creature] 카드가 죽으면 폭발해 인접한 칸에 불을 붙여 세 턴 동안 타게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arsonist", "방화범", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it sets all spaces on the board on fire for four turns.", "[creature] 카드를 내면 보드의 모든 칸에 불이 붙어 네 턴 동안 탄다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Refueler", "연료 보급자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As long as it has fuel, [creature] will attempt to move beside any creatures you play that also use fuel. Each turn, [creature] will refuel adjacent creatures.", "연료가 있는 동안 [creature] 카드는 당신이 내는 연료를 사용하는 피조물 옆으로 움직이려 한다. 매 턴 [creature] 카드는 인접한 피조물에 연료를 보급한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Second Chance", "두 번째 기회", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever a friendly non-Brittle creature dies, if [creature] is on the battlefield, a 1/1 skeleton will be created in its place.", "취약성이 없는 아군 피조물이 죽을 때 [creature] 카드가 전장에 있으면 그 자리에 1/1 해골이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonus Energy Conduit", "추가 에너지 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature] is part of a completed circuit, it provides a reserve of energy equal to the player's current maximum energy.", "[creature] 카드가 완성된 회로의 일부라면 플레이어의 현재 최대 에너지와 같은 양의 예비 에너지를 제공한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleclocked", "외골격 오버클록", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it permanently becomes an Exeskeleton with the same abilities. If [creature] has Unkillable, it will be unaffected.", "[creature] 카드가 죽으면 같은 능력을 지닌 Exe스켈레톤으로 영구히 변한다. [creature] 카드가 불사를 지녔다면 영향을 받지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overheat", "과열", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the scales are in your favor, [creature] loses 1 power. When the scales aren't in your favor, [creature] gains 1 power.", "저울이 당신에게 유리하면 [creature] 카드는 공격력을 1 잃는다. 유리하지 않으면 [creature] 카드는 공격력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Power Drain", "전력 유출", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] consumes all of its owner's available energy each turn.", "[creature] 카드는 매 턴 주인의 사용 가능한 에너지를 모두 소비한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purist", "순수주의", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards opposing [creature] have their sigils removed.", "[creature] 카드의 맞은편 카드들은 도장을 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This handles actually removing abilities. You should never see this ability on a card!!!", "이 능력은 실제 능력 제거를 처리한다. 카드에서 이 능력이 보이면 안 된다!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bounty Hunter", "현상금 사냥꾼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When drawn, [creature] will turn into a random bounty hunter.", "[creature] 카드를 뽑으면 무작위 현상금 사냥꾼으로 변한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nerf This!", "이걸 하향해 봐!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, it gains a randomly selected negative ability.", "[creature] 카드를 뽑으면 무작위로 선택된 부정적 능력 하나를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apotheosis", "신격화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, it gains a randomly selected rare ability.", "[creature] 카드를 뽑으면 무작위로 선택된 희귀 능력 하나를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recharge", "힘 모으기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, one energy will be refilled (up to the player's maximum energy)", "[creature] 카드를 내면 플레이어의 최대 에너지 한도 내에서 에너지 하나를 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alarm Clock", "알람시계", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The creature that this sigil is pointing to will gain +1 attack. The clock will turn at the beginning of the player's turn.", "이 도장이 가리키는 피조물은 공격력을 +1 얻는다. 시계는 플레이어의 턴 시작 시 회전한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Blessing", "루비 축복", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] provides +1 Attack to all creatures you control.", "[creature] 카드는 당신이 조종하는 모든 피조물에게 공격력 +1을 제공한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orange Mox Warrior", "오렌지 목스 전사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it attacks all enemy cards opposite Orange Mox providers its owner controls.", "[creature] 카드를 내면 주인이 조종하는 오렌지 목스 제공자들의 맞은편에 있는 모든 적 카드를 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burst", "폭발", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards sacrificed to pay for [creature] explode, dealing 10 damage to each adjacent card.", "[creature] 카드의 비용을 지불하기 위해 희생된 카드들은 폭발하여 인접한 각 카드에 피해를 10 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Consumer", "보석 소비자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all gem vessels on its owner's side of the board are sacrificed.", "[creature] 카드를 내면 주인 측 보드에 있는 모든 보석 그릇이 희생된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emergence Latch", "용출 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When cards sacrificed to pay for [creature] die, their owner chooses a card to gain their first sigil.", "[creature] 카드의 비용을 지불하기 위해 희생된 카드가 죽으면 그 주인은 카드를 골라 죽은 카드의 첫 번째 도장을 부여한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Macabre Growth", "섬뜩한 성장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains the attack and health of all cards sacrificed to play it.", "[creature] 카드는 내기 위해 희생된 모든 카드의 공격력과 체력을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shatter", "산산조각", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards sacrificed to pay for [creature] drop 4 bones instead of 1 when they die.", "[creature] 카드의 비용을 지불하기 위해 희생된 카드들은 죽을 때 뼈 1개 대신 4개를 떨어뜨린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guts Sacrifice", "내장 희생", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards sacrificed to pay for [creature] slime the opposing slot when they die. Cards in slimed slots have one less power.", "[creature] 카드의 비용을 지불하기 위해 희생된 카드는 죽을 때 맞은편 슬롯에 점액을 묻힌다. 점액 슬롯의 카드는 공격력이 1 낮다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Mox Charger", "파란 목스 충전기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it creates a Charge in your hand for each Blue Mox its owner controls. Charge is a spell that refills 1 Energy when played.", "[creature] 카드를 내면 주인이 조종하는 파란 목스 하나마다 당신의 패에 '충전!'을 생성한다. '충전!'은 낼 때 에너지 1을 회복하는 주문이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it creates a Charge in your hand for each Blue Mox its owner controls. Charge is a command that refills 1 Energy when played.", "[creature] 카드를 내면 주인이 조종하는 파란 목스 하나마다 당신의 패에 '충전!'을 생성한다. '충전!'은 낼 때 에너지 1을 회복하는 명령이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Blessing", "사파이어 축복", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] reduces the cost of all cards in your hand by 1.", "[creature] 카드는 당신의 패에 있는 모든 카드의 비용을 1 줄인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrap Dumper", "고철 투척기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, a broken bot is played on the opposing space.", "이 도장을 지닌 카드를 내면 맞은편 칸에 망가진 봇이 나온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scrap Salvage", "고철 회수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, add the total cost of all cards sacrificed to play it, then create a Charge! for each energy, create a Zap! for each gem, create an Upgrade! for each blood, and create a Defend! for each bone.", "[creature] 카드를 내면 내기 위해 희생된 모든 카드의 비용을 합산한다. 에너지 하나마다 '충전!', 보석 하나마다 '전기 충격!', 피 하나마다 '업그레이드!', 뼈 하나마다 '방어!'를 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bulldoze", "불도저", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Energy to cause this card to move in the direction inscribed in the sigil. Creatures that are in the way will be pushed in the same direction.", "에너지 1을 소비해 이 카드를 도장에 표시된 방향으로 움직인다. 길을 막는 피조물은 같은 방향으로 밀려난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shred", "분쇄", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shred a card from your hand to get +1 Attack (until end of turn). The shredded card behaves as if it died. Unkillable cards and cards Made of Stone cannot be shredded.", "패의 카드 한 장을 분쇄해 턴이 끝날 때까지 공격력 +1을 얻는다. 분쇄된 카드는 죽은 것처럼 취급된다. 불사 카드와 굳건함 카드는 분쇄할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Side Deck Power", "보조 덱 공격력", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of cards its owner has drawn from the side deck.", "이 도장이 나타내는 값은 주인이 보조 덱에서 뽑은 카드의 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimed Slot", "점액 슬롯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The card in this slot will have its attack reduced by one.", "이 슬롯에 있는 카드의 공격력이 1 감소한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phase Through", "위상 통과", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its controller's turn, [creature] moves one space in the direction indicated, moving through other cards if necessary until it finds an empty space.", "조종자의 턴이 끝날 때 [creature] 카드는 표시된 방향으로 한 칸 이동하며 필요하면 다른 카드를 통과해 빈칸을 찾는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Solar Heart", "태양의 심장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, its heart stays behind and provides conduit power to the slot.", "[creature] 카드가 죽으면 심장이 남아 그 슬롯에 전도체 전력을 공급한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Solar Powered", "태양광 동력", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card slot stays powered at all times, even if it is not in a completed circuit.", "이 슬롯은 완성된 회로 안에 있지 않아도 항상 전력이 공급된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overwhelming Entrance", "압도적인 등장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, all opposing creatures are tossed into new slots. Non-conduit terrain is not affected.", "[creature] 카드를 내면 모든 상대 피조물이 새로운 슬롯으로 내던져진다. 전도체가 아닌 지형은 영향을 받지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Familiar", "사역마 소환", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it plays a techbeast in an empty adjacent slot.", "[creature] 카드를 내면 인접한 빈 슬롯에 기술 짐승을 낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zip of Death", "죽음의 속도", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take 2 damage.", "피해를 2 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Target Required", "대상 필요", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] can only attack lanes that have cards in them.", "[creature] 카드는 카드가 있는 공격로만 공격할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Controlled", "조종된", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is under control of its opponent. At the end of the turn, it will return to its owner. While being controlled, it cannot be hammered.", "[creature] 카드는 상대에게 조종당하고 있다. 턴이 끝날 때 주인에게 돌아간다. 조종당하는 동안 망치로 칠 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "화염구 주문", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its turn, [creature] chooses a card slot to set on fire for three turns.", "자신의 턴이 끝날 때 [creature] 카드는 슬롯 하나를 골라 불을 붙여 세 턴 동안 타게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slimeball", "점액 덩이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its turn, [creature] will choose one slot to become slimed. Cards in a slimed slot lose one power.", "자신의 턴이 끝날 때 [creature] 카드는 슬롯 하나를 골라 점액을 묻힌다. 점액 슬롯의 카드는 공격력을 1 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime Vandal", "점액 파괴자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it slimes all slots on the board. Cards in slimed slots lose one power.", "[creature] 카드를 내면 보드의 모든 슬롯에 점액을 묻힌다. 점액 슬롯의 카드는 공격력을 1 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full of Guts", "내장 가득", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it slimes the opposing slot.", "[creature] 카드가 죽으면 맞은편 슬롯에 점액을 묻힌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seed Sprinter", "씨앗 질주자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of its controller's turn, [creature] moves one space in the direction indicated (if it can) and plants a seed in its previous space.", "조종자의 턴이 끝날 때 [creature] 카드는 가능하면 표시된 방향으로 한 칸 이동하고 원래 칸에 씨앗을 심는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vessel Heart", "그릇의 심장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, a vessel is created in its place.", "이 도장을 지닌 카드가 죽으면 그 자리에 그릇이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zap", "전기 충격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deals damage directly to the target.", "대상에게 직접 피해를 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Urchin Spawn Conduit", "성게 생성 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empty spaces within a circuit completed by [creature] spawn Urchin Cells at the end of the owner's turn.", "[creature] 카드가 완성한 회로 안의 빈칸은 주인의 턴이 끝날 때 성게 전지를 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Energy to set the power of [creature] randomly between 1 and 6.", "에너지 2를 소비해 [creature] 카드의 공격력을 1에서 6 사이의 무작위 값으로 정한다.", Language.Korean);
        }
    }
    public class P03InKayceesModMod
    {
        public static Dictionary<string, string> Consumables = new();
        public static Dictionary<string, string> Mods = new();
        public static Dictionary<string, string> Cards = new();
        public static Dictionary<string, string> CardParts = new();

        public static void RegisterConsumable(string en, string zh)
        {
            Consumables.Add(en, zh);
        }

        public static void RegisterMod(string en, string zh)
        {
            Mods.Add(en, zh);
        }
        public static void RegisterCard(string en, string zh)
        {
            Cards[en] = zh;
        }
        public static void RegisterCardPart(string en, string zh)
        {
            CardParts[en] = zh;
        }
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for P03InKayceesMod Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW P03 RUN", "P03 새 도전", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONTINUE P03 RUN", "P03 도전 계속하기", Language.Korean);

            // Ability: Base
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Death", "이중 죽음", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Head Shot", "헤드샷", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is immune to the effects of Touch of Death, Stinky, and fire.", "[creature] 카드는 죽음의 손길, 구린내, 불의 효과에 면역이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If [creature]'s owner controls no Gem Vessels, [creature] perishes.", "[creature] 카드의 주인이 보석 그릇을 조종하고 있지 않으면 [creature] 카드는 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mine Cryptocurrency", "암호화폐 채굴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When part of a conduit, [creature] will generate cryptocurrency.", "전도체의 일부일 때 [creature] 카드는 암호화폐를 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stamp Paperwork", "서류에 도장 찍기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Energy to stamp this paperwork as properly filed and ready for further processing.", "에너지 1을 소비해 이 서류가 올바르게 접수되어 다음 처리를 받을 준비가 되었음을 도장으로 확인한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Strike", "큰 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] attacks all cards in all lanes opposing it, or attacks just the center opposing lane if there are no cards it can attack.", "[creature] 카드는 맞은편 모든 공격로의 카드들을 공격한다. 공격할 수 있는 카드가 없으면 중앙 맞은편 공격로만 공격한다.", Language.Korean);
            // Ability: Multiverse
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Bomb Latch", "다중우주 폭탄 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature in any universe to gain the Multiverse Detonator sigil.", "[creature] 카드가 죽으면 주인은 어느 우주에서든 다중우주 기폭 장치 도장을 부여할 피조물 하나를 고른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Brittle Latch", "다중우주 취약성 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature in any universe to gain the Brittle sigil.", "[creature] 카드가 죽으면 주인은 어느 우주에서든 취약성 도장을 부여할 피조물 하나를 고른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Detonator", "다중우주 기폭 장치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, all adjacent cards in all universes are dealt 10 damage", "[creature] 카드가 죽으면 모든 우주의 인접한 카드들이 피해를 10 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Full of Oil", "다중우주 연료 가득", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it adds 3 health to the creature on either side and across from it in every universe.", "[creature] 카드가 죽으면 모든 우주의 양옆과 맞은편 피조물에게 각각 체력을 3 더한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Fully Loaded", "다중우주 만재", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, it leaves a permanent +1 attack bonus in the lane it occupied in every universe.", "[creature] 카드가 죽으면 모든 우주에서 자신이 있던 공격로에 영구적인 공격력 +1 보너스를 남긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Guardian", "다중우주 수호자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opposing creature is placed opposite to an empty space in any universe, [creature] will move to that empty space.", "어느 우주에서든 상대 피조물이 빈칸 맞은편에 놓이면 [creature] 카드는 그 빈칸으로 움직인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Burrower", "다중우주 굴살이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an empty space would be struck, [creature] will cross universes to move to that space to receive the strike instead.", "빈칸이 공격받으려 할 때 [creature] 카드는 우주를 넘어 그 칸으로 이동해 대신 공격을 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Null Conduit", "다중우주 무효화 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Circuits completed by [creature] are completed in every universe.", "[creature] 카드가 완성한 회로는 모든 우주에서도 완성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Mighty Leap", "다중우주 위대한 도약", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will leap across universes to block attacks that occur in this lane in any universe.", "[creature] 카드는 우주를 넘어 뛰어가 어느 우주에서든 이 공격로에 가해지는 공격을 막는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Sentry", "다중우주 보초", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature] in any universe, they are dealt 1 damage.", "어느 우주에서든 피조물이 [creature] 카드의 맞은편 칸으로 이동하면 그 피조물은 피해를 1 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Shield Latch", "다중우주 방어 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature in any universe to gain the Nano Armor sigil.", "[creature] 카드가 죽으면 주인은 어느 우주에서든 나노 장갑 도장을 부여할 피조물 하나를 고른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Sprinter", "다중우주 질주자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move to the next universe.", "주인의 턴이 끝날 때 [creature] 카드는 다음 우주로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Strike", "다중우주 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space in every universe other than its own.", "[creature] 카드는 자신이 있는 우주를 제외한 모든 우주의 맞은편 각 칸을 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Great Mox", "다중우주 위대한 목스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Green, Orange, and Blue Gem is provided to the owner's side in every universe.", "[creature] 카드를 내면 모든 우주의 주인 측에 초록, 오렌지, 파란 보석이 하나씩 제공된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiverse Hoarder", "다중우주 축적가", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may search the multiverse for a card that has perished that is capable of traversing the multiverse.", "[creature] 카드를 내면 다중우주를 가로지를 수 있는 죽은 카드 한 장을 다중우주에서 찾아도 된다.", Language.Korean);


            // Card: Base
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mega Gunner", "4연장 사수", Language.Korean);
            RegisterCard("Mega Gunner", "4연장 사수");
