            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying Anchovi", "날아다니는 멸치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flying fish, how ridiculous.", "날아다니는 물고기라니, 우스꽝스럽다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bad Rat", "나쁜 쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bad rat. No, not that kind.", "나쁜 쥐다. 아니, 그런 뜻은 아니다.", Language.Korean);
