    public class InGameCardCreatorMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for InGame_Card_Creator Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You entered the [c:bR]card creation[c:] mode.", "[c:bR]카드 생성[c:] 모드에 들어갔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears that you lost normally.", "정상적으로 패배한 모양이군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only worthy challengers may access the Card Creator.", "자격을 갖춘 도전자만 카드 생성기를 사용할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try again, but this time open the backroom door normally.", "다시 해 봐라. 이번에는 뒷방 문을 정상적으로 열어라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "current card", "현재 카드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should give it a name.", "이름을 지어 줘야 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please type the description.", "설명을 입력하세요.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time for you to return.", "이제 돌아갈 시간이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loading portraits.", "카드 그림을 불러오는 중.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "previous page", "이전 페이지", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "next page", "다음 페이지", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And another. This time I will use its [c:bR]power[c:].", "하나 더. 이번에는 그 카드의 [c:bR]공격력[c:]을 사용하겠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose the [c:bR]complexity[c:] of card. This determines when it is unlocked in the tutorial.", "카드의 [c:bR]복잡도[c:]를 선택하라. 튜토리얼에서 언제 잠금이 해제되는지 결정한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "free", "무료", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, choose a card to draw the [c:bR]cost[c:] from.", "[c:bR]비용[c:]을 가져올 카드를 선택하라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you want to add another [c:bR]cost[c:]?", "다른 [c:bR]비용[c:]을 추가하겠는가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose which card it will evolve into.", "어떤 카드로 진화할지 선택하라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose which card it will create upon death.", "죽을 때 생성할 카드를 선택하라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]How many turns[c:] should it take for this card to evolve?", "이 카드가 진화하기까지 [c:bR]몇 턴[c:]이 걸리게 하겠는가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And another. This time I will use its [c:bR]health[c:].", "하나 더. 이번에는 그 카드의 [c:bR]체력[c:]을 사용하겠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "regular", "일반", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "rare", "희귀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hidden", "숨겨진", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose the [c:bR]type[c:] of card.", "카드의 [c:bR]유형[c:]을 선택하라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now choose some cards from which we will extract the [c:bR]sigils[c:]. Note that some may not work correctly.", "[c:bR]도장[c:]을 추출할 카드들을 선택하라. 일부는 제대로 작동하지 않을 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finally, choose the hidden [c:bR]special abilities[c:] and [c:bR]traits[c:]. Again, some may not function properly.", "마지막으로 숨겨진 [c:bR]특수 능력[c:]과 [c:bR]특성[c:]을 선택하라. 이 역시 일부는 제대로 작동하지 않을 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "cost (set)", "비용 (설정)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "cost (add)", "비용 (추가)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "sigils", "도장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "tribes", "부족", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "sp. abilities", "특수 능력", Language.Korean);
