    public class AgasMagnificusExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for AgasMagnificusExpansion Mod");

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aga's Magnificus Expansion", "Aga의 매그니피쿠스 확장팩", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An unofficial expansion to the Magnificus Mod featuring [count] unique and colourful mages", "매그니피쿠스 모드의 비공식 확장팩. 독특하고 다채로운 마법사 [count]명을 담았다.", Language.Korean);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascension Mage", "승천 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Ascension Mage", "승천 마법사", "Utilising the power of time they grant knowledge and experience from far beyond", "시간의 힘을 이용해 머나먼 곳의 지식과 경험을 전한다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utilising the power of time they grant knowledge and experience from far beyond", "시간의 힘을 이용해 머나먼 곳의 지식과 경험을 전한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ash Mage", "재 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Ash Mage", "재 마법사", "Ashes he sheds from his own body, scorching any and all who oppose him", "자신의 몸에서 재를 흩뿌려 맞서는 모든 이를 태운다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ashes he sheds from his own body, scorching any and all who oppose him", "자신의 몸에서 재를 흩뿌려 맞서는 모든 이를 태운다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Egg", "부서진 알", Language.Korean);
            MagnificusMod.RegisterCard("Broken Egg", "부서진 알", "Only the greatest of trainers might find this treasure", "가장 위대한 조련사만이 이 보물을 찾을 수 있을지도 모른다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "가장 위대한 조련사만이 이 보물을 찾을 수 있을지도 모른다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chosen One", "선택받은 자", Language.Korean);
            MagnificusMod.RegisterCard("Chosen One", "선택받은 자", "My selected favourite. He still clings to his elders though...", "내가 직접 고른 총애하는 자. 하지만 여전히 어른들에게 매달린다…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My selected favourite. He still clings to his elders though...", "내가 직접 고른 총애하는 자. 하지만 여전히 어른들에게 매달린다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanliness Mage", "청소 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Cleanliness Mage", "청소 마법사", "The proudest of all my pupils. None come close to his bath superpowers", "내 모든 제자 중 가장 자부심이 강하다. 목욕 초능력은 아무도 따라오지 못한다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The proudest of all my pupils. None come close to his bath superpowers", "내 모든 제자 중 가장 자부심이 강하다. 목욕 초능력은 아무도 따라오지 못한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleric", "성직자", Language.Korean);
            MagnificusMod.RegisterCard("Cleric", "성직자", "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "신성한 마법의 힘으로 모두의 고통을 짊어지고 상처를 없애 준다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "신성한 마법의 힘으로 모두의 고통을 짊어지고 상처를 없애 준다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clock Mage", "시계 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Clock Mage", "시계 마법사", "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "시간 자체를 다스리는 마법사. 죽음이 가까워지면 과거로 돌아가 다시 살아난다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "시간 자체를 다스리는 마법사. 죽음이 가까워지면 과거로 돌아가 다시 살아난다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creature Collector", "피조물 수집가", Language.Korean);
            MagnificusMod.RegisterCard("Creature Collector", "피조물 수집가", "He had searched far and wide for his little companion, you see", "그는 작은 동료를 찾아 사방을 헤맸지");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He had searched far and wide for his little companion, you see", "그는 작은 동료를 찾아 사방을 헤맸지", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division Mage", "분열 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Division Mage", "분열 마법사", "So the card says at least... I assumed those freaks were long dealth with", "적어도 카드에는 그렇게 적혀 있군… 그 괴짜들은 진작 처리된 줄 알았는데");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So the card says at least... I assumed those freaks were long dealth with", "적어도 카드에는 그렇게 적혀 있군… 그 괴짜들은 진작 처리된 줄 알았는데", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg", "알", Language.Korean);
            MagnificusMod.RegisterCard("Egg", "알", "Only the greatest of trainers might find this treasure", "가장 위대한 조련사만이 이 보물을 찾을 수 있을지도 모른다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "가장 위대한 조련사만이 이 보물을 찾을 수 있을지도 모른다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Druid", "드루이드", Language.Korean);
            MagnificusMod.RegisterCard("Druid", "드루이드", "Nature's primal devotee, feeding on sapped mana to cure his allies", "자연의 원초적인 신봉자. 빼앗은 마나를 먹고 아군을 치유한다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nature's primal devotee, feeding on sapped mana to cure his allies", "자연의 원초적인 신봉자. 빼앗은 마나를 먹고 아군을 치유한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanter", "마력 부여사", Language.Korean);
            MagnificusMod.RegisterCard("Enchanter", "마력 부여사", "He spews cosmic magicks upon his demise, enchanting everything nearby", "죽을 때 우주의 마법을 내뿜어 주변의 모든 것에 마력을 부여한다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He spews cosmic magicks upon his demise, enchanting everything nearby", "죽을 때 우주의 마법을 내뿜어 주변의 모든 것에 마력을 부여한다", Language.Korean);
