            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evoker", "방출술사", Language.Korean);
            MagnificusMod.RegisterCard("Evoker", "방출술사", "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "역겨운 가르침을 전하는 불길한 멍청이. 소환하는 뱀은 가장 치명적인 종류다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "역겨운 가르침을 전하는 불길한 멍청이. 소환하는 뱀은 가장 치명적인 종류다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Summon", "뱀 소환", Language.Korean);
            MagnificusMod.RegisterCard("Serpent Summon", "뱀 소환", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firebender", "방화광", Language.Korean);
            MagnificusMod.RegisterCard("Firebender", "방화광", "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "치열한 전투에서도 기운차게 다음 화염구 희생자를 찾아다닌다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "치열한 전투에서도 기운차게 다음 화염구 희생자를 찾아다닌다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "선견 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Foresight Mage", "선견 마법사", "As he gazes upon your future, attacks that may come his way he forever predicts", "당신의 미래를 바라보며 자신에게 닥칠 공격을 언제나 예견한다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As he gazes upon your future, attacks that may come his way he forever predicts", "당신의 미래를 바라보며 자신에게 닥칠 공격을 언제나 예견한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "선견 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Foresight Mage", "선견 마법사", "Gazing into the future, he may see any body who dares make an approach", "미래를 바라보며 감히 다가오는 자를 볼 수 있을지도 모른다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gazing into the future, he may see any body who dares make an approach", "미래를 바라보며 감히 다가오는 자를 볼 수 있을지도 모른다", Language.Korean);
