            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the elite warrior unit enchanted with the aura of my moxen", "내 목스의 기운으로 마력을 부여받은 정예 전사 부대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grand Astrologer", "별의 탐구자", Language.Korean);
            MagnificusMod.RegisterCard("Grand Astrologer", "별의 탐구자", "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "전장은 영원히 그의 놀이터이며 공간은 그의 무기다. 모든 것이 그 앞에 드러난다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "전장은 영원히 그의 놀이터이며 공간은 그의 무기다. 모든 것이 그 앞에 드러난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravity Mage", "중력 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Gravity Mage", "중력 마법사", "A master of the forces of gravity. Any and all mox bend to his unwavering will", "중력을 다스리는 대가. 모든 목스는 그의 확고한 의지에 굴복한다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A master of the forces of gravity. Any and all mox bend to his unwavering will", "중력을 다스리는 대가. 모든 목스는 그의 확고한 의지에 굴복한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Illusion Mage", "환술사", Language.Korean);
            MagnificusMod.RegisterCard("Illusion Mage", "환술사", "Dawning his tricks and disguises, there is none scarier. At first glance", "속임수와 변장을 두르면 그보다 무서운 자는 없다. 첫눈에는 말이다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dawning his tricks and disguises, there is none scarier. At first glance", "속임수와 변장을 두르면 그보다 무서운 자는 없다. 첫눈에는 말이다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infestation Mage", "감염 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Infestation Mage", "감염 마법사", "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "너 같은 찬탈자 도전자도 변신의 사술을 조금은 즐길 수 있겠지");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "너 같은 찬탈자 도전자도 변신의 사술을 조금은 즐길 수 있겠지", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insulting Mirror", "모욕하는 거울", Language.Korean);
            MagnificusMod.RegisterCard("Insulting Mirror", "모욕하는 거울", "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "마법의 위협이 날아다니며 도발과 건방진 말을 쏟아 낸다. 당신의 분노를 제 힘으로 바꾼다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "마법의 위협이 날아다니며 도발과 건방진 말을 쏟아 낸다. 당신의 분노를 제 힘으로 바꾼다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iron Maiden", "철의 처녀", Language.Korean);
            MagnificusMod.RegisterCard("Iron Maiden", "철의 처녀", "My finest of paladins working the finest of hours. No soul goes through his grand wall", "가장 훌륭한 시간에 일하는 내 최고의 성기사. 그의 거대한 벽을 통과할 자는 없다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My finest of paladins working the finest of hours. No soul goes through his grand wall", "가장 훌륭한 시간에 일하는 내 최고의 성기사. 그의 거대한 벽을 통과할 자는 없다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kickmoxer", "목스 학살자", Language.Korean);
            MagnificusMod.RegisterCard("Kickmoxer", "목스 학살자", "He dedicated his life to the art of combat, and may adapt to whomever he faces", "평생을 전투 기술에 바쳤으며 누구를 상대하든 적응할 수 있다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He dedicated his life to the art of combat, and may adapt to whomever he faces", "평생을 전투 기술에 바쳤으며 누구를 상대하든 적응할 수 있다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mass Grave", "집단 묘지", Language.Korean);
            MagnificusMod.RegisterCard("Mass Grave", "집단 묘지", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Agairan", "마스터 아가이란", Language.Korean);
            MagnificusMod.RegisterCard("Master Agairan", "마스터 아가이란", "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "진홍의 키메라. 연금술의 스승이 가장 치명적인 독을 주입한다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "진홍의 키메라. 연금술의 스승이 가장 치명적인 독을 주입한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Bluetwo", "마스터 블루투", Language.Korean);
            MagnificusMod.RegisterCard("Master Bluetwo", "마스터 블루투", "The steel knight of sapphire. Even after death her psychic presence commands our foes", "사파이어의 강철 기사. 죽은 뒤에도 그녀의 정신이 적들을 지휘한다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The steel knight of sapphire. Even after death her psychic presence commands our foes", "사파이어의 강철 기사. 죽은 뒤에도 그녀의 정신이 적들을 지휘한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Doublin", "마스터 더블린", Language.Korean);
            MagnificusMod.RegisterCard("Master Doublin", "마스터 더블린", "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "뼈의 왕의 구세주. 기도의 스승은 정수를 능숙하게 훔치는 법을 배웠다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "뼈의 왕의 구세주. 기도의 스승은 정수를 능숙하게 훔치는 법을 배웠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megawizard", "슈퍼 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Megawizard", "슈퍼 마법사", "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "위협적으로 거대한 몸집에 우둔함마저 으스스하다. 그런 원초적인 힘도 영원히 지속되지는 않는다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "위협적으로 거대한 몸집에 우둔함마저 으스스하다. 그런 원초적인 힘도 영원히 지속되지는 않는다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meteorologist", "기상학자", Language.Korean);
            MagnificusMod.RegisterCard("Meteorologist", "기상학자", "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "우주를 주의 깊게 관찰하고 마음에 드는 대상에게 유성우를 쏟아붓는다. 잔인한 걸까? 아닐까? 그들만이 안다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "우주를 주의 깊게 관찰하고 마음에 드는 대상에게 유성우를 쏟아붓는다. 잔인한 걸까? 아닐까? 그들만이 안다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miniwizard", "꼬마 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Miniwizard", "꼬마 마법사", "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "너무 작은 몸 때문에 저주받은 마법사. 걱정하지 마라. 해결책을 찾았으니까.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "너무 작은 몸 때문에 저주받은 마법사. 걱정하지 마라. 해결책을 찾았으니까.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Thief", "환영 도적", Language.Korean);
            MagnificusMod.RegisterCard("Phantom Thief", "환영 도적", "A billowing cloud of crime, darting in and out, and stealing his foes", "범죄의 구름이 넘실거리며 재빨리 드나들고 적을 훔쳐 간다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A billowing cloud of crime, darting in and out, and stealing his foes", "범죄의 구름이 넘실거리며 재빨리 드나들고 적을 훔쳐 간다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Preformence Mage", "서문 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Preformence Mage", "서문 마법사", "Who knows to what ends his mystery rabbit has been through", "그의 신비로운 토끼가 무슨 일을 겪었는지 누가 알겠는가");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows to what ends his mystery rabbit has been through", "그의 신비로운 토끼가 무슨 일을 겪었는지 누가 알겠는가", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Queen's Familiar", "여왕의 사역마", Language.Korean);
            MagnificusMod.RegisterCard("Queen's Familiar", "여왕의 사역마", "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "아름다운 야수들로 이루어진 장엄한 키메라. 몸 안에 군대를 품고 있다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "아름다운 야수들로 이루어진 장엄한 키메라. 몸 안에 군대를 품고 있다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RisingHunger", "심해지는 굶주림", Language.Korean);
            MagnificusMod.RegisterCard("RisingHunger", "심해지는 굶주림", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roach Familiar", "바퀴벌레 하인", Language.Korean);
            MagnificusMod.RegisterCard("Roach Familiar", "바퀴벌레 하인", "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "정신으로 만들어진 바퀴벌레. 의지의 힘으로 부활할 수 있다! 결국 실패하지만.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "정신으로 만들어진 바퀴벌레. 의지의 힘으로 부활할 수 있다! 결국 실패하지만.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Wizard", "환영 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Shadow Wizard", "환영 마법사", "A mobster of the underseen. He calls the shadows to gang on it's foes", "보이지 않는 세계의 폭력배. 그림자들을 불러 적을 함께 공격한다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mobster of the underseen. He calls the shadows to gang on it's foes", "보이지 않는 세계의 폭력배. 그림자들을 불러 적을 함께 공격한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shinobi", "닌자", Language.Korean);
            MagnificusMod.RegisterCard("Shinobi", "닌자", "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "어둠의 전사. 아무도 차지하거나 볼 수 없는 곳에서 기습한다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "어둠의 전사. 아무도 차지하거나 볼 수 없는 곳에서 기습한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shower Mage", "샤워 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Shower Mage", "샤워 마법사", "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "내 학교에서 쫓겨난 자, 당연한 일이지! 그의 악취는 마법으로만 표현할 수 있을 정도다…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "내 학교에서 쫓겨난 자, 당연한 일이지! 그의 악취는 마법으로만 표현할 수 있을 정도다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sludge Mage", "진흙 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Sludge Mage", "진흙 마법사", "An entity of unknown origins, powered off the ill spreading plague to all", "기원이 알려지지 않은 개체. 병든 자에게서 힘을 얻어 모두에게 역병을 퍼뜨린다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An entity of unknown origins, powered off the ill spreading plague to all", "기원이 알려지지 않은 개체. 병든 자에게서 힘을 얻어 모두에게 역병을 퍼뜨린다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sui-Sage", "수이 성인", Language.Korean);
            MagnificusMod.RegisterCard("Sui-Sage", "수이 성인", "The leader of a pack, soon to be packed away", "무리의 우두머리. 곧 짐처럼 싸여 갈 것이다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The leader of a pack, soon to be packed away", "무리의 우두머리. 곧 짐처럼 싸여 갈 것이다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "소환사", Language.Korean);
            MagnificusMod.RegisterCard("Summoner", "소환사", "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "생명의 기술에 미친 자. 무에서 생명을 만들어 내며 감각마저 섬뜩하다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "생명의 기술에 미친 자. 무에서 생명을 만들어 내며 감각마저 섬뜩하다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Symmetrical Mage", "대칭 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Symmetrical Mage", "대칭 마법사", "Everyone has two sides to them, you see. Especially once they mess with my temper", "누구나 양면이 있지. 특히 내 성질을 건드리고 나면 말이야");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone has two sides to them, you see. Especially once they mess with my temper", "누구나 양면이 있지. 특히 내 성질을 건드리고 나면 말이야", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Teleportation Mage", "순간이동 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Teleportation Mage", "순간이동 마법사", "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "끝없는 차원의 문을 알리는 자. 전장을 무한히 돌아다니며 다가오는 공격을 무효화한다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "끝없는 차원의 문을 알리는 자. 전장을 무한히 돌아다니며 다가오는 공격을 무효화한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torrent Mage", "급류 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Torrent Mage", "급류 마법사", "An apprentice of the ocean utilising it to drown the lands and the terrain above", "바다의 제자. 바다를 이용해 땅과 지형을 물에 잠기게 한다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An apprentice of the ocean utilising it to drown the lands and the terrain above", "바다의 제자. 바다를 이용해 땅과 지형을 물에 잠기게 한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Untamed Dragon", "야생 마룡", Language.Korean);
            MagnificusMod.RegisterCard("Untamed Dragon", "야생 마룡", "Legends whisper this beast, was once a companion to the mox master Goranj", "전설에 따르면 이 야수는 한때 목스의 대가 마스터 고란즈의 동료였다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legends whisper this beast, was once a companion to the mox master Goranj", "전설에 따르면 이 야수는 한때 목스의 대가 마스터 고란즈의 동료였다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warlock", "흑마법사", Language.Korean);
            MagnificusMod.RegisterCard("Warlock", "흑마법사", "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "피의 마법을 연구하는 검게 그을린 마법사. 흘린 피를 끔찍한 무기로 만든다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "피의 마법을 연구하는 검게 그을린 마법사. 흘린 피를 끔찍한 무기로 만든다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wicked Witch", "죄악의 마녀", Language.Korean);
            MagnificusMod.RegisterCard("Wicked Witch", "죄악의 마녀", "A flying jesting witch, laughing your sorrows and posioning your armies", "날아다니는 장난꾸러기 마녀. 당신의 슬픔을 비웃고 군대에 독을 퍼뜨린다");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flying jesting witch, laughing your sorrows and posioning your armies", "날아다니는 장난꾸러기 마녀. 당신의 슬픔을 비웃고 군대에 독을 퍼뜨린다", Language.Korean);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acid Aura", "산성 기운", Language.Korean);
            MagnificusMod.RegisterAbility("Acid Aura", "산성 기운");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals 1 damage to the creature opposing it every turn", "[creature]은(는) 매 턴 맞은편 피조물에게 피해 1을 준다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakening", "우화등선", Language.Korean);
            MagnificusMod.RegisterAbility("Awakening", "우화등선");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner chooses an ally creature to evolve into a higher form.", "[creature]을(를) 내면 주인이 아군 피조물 하나를 선택해 더 높은 형태로 진화시킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backfire Strike", "역류 타격", Language.Korean);
            MagnificusMod.RegisterAbility("Backfire Strike", "역류 타격");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] damages creatures that oppose those it attacks.", "[creature]이(가) 공격할 때 공격 대상의 맞은편에 있는 보유자 측 피조물에게도 피해를 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "피고래", Language.Korean);
            MagnificusMod.RegisterAbility("Blood Guzzler", "피고래");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, it gains 1 health for each damage dealt.", "[creature]이(가) 피해를 주면 입힌 피해 1당 체력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brute Parasite", "잔혹한 기생", Language.Korean);
            MagnificusMod.RegisterAbility("Brute Parasite", "잔혹한 기생");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, an Egg is created on the opposing space.", "[creature]을(를) 내면 맞은편 칸에 알이 하나 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deluge", "격류", Language.Korean);
            MagnificusMod.RegisterAbility("Deluge", "격류");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, opponent creatures with 0 power drown and get given the Waterborne sigil.", "[creature]을(를) 내면 공격력이 0인 상대 피조물이 잠수하고 수생 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division", "분열", Language.Korean);
            MagnificusMod.RegisterAbility("Division", "분열");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] splits into 2 identical clones, each bearing half of it's original stats.", "공격 후 [creature]이(가) 동일한 사본 2개로 나뉜다. 각각 원래 능력치의 절반을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sentry", "보초", Language.Korean);
            MagnificusMod.RegisterAbility("Sentry", "보초");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], they are dealt 1 damage.", "피조물이 [creature] 맞은편 칸으로 이동하면 그 피조물이 피해 1을 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, let one never underestimate the speed of a Foresight Mage.", "아, 선견 마법사의 속도를 절대 얕보지 마라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healing Aura", "치유의 기운", Language.Korean);
            MagnificusMod.RegisterAbility("Healing Aura", "치유의 기운");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] heals nearby allied creatures. The healing is proportionate to it's power.", "[creature]은(는) 근처 아군 피조물을 치유한다. 치유량은 자신의 공격력에 비례한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart Stealer", "마음을 훔치는 자", Language.Korean);
            MagnificusMod.RegisterAbility("Heart Stealer", "마음을 훔치는 자");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "when [creature] kills a creature, it gets added to your hand.", "[creature]이(가) 피조물을 죽이면 죽은 피조물의 카드가 당신의 패에 추가된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignis Incant", "화염 주문", Language.Korean);
            MagnificusMod.RegisterAbility("Ignis Incant", "화염 주문");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood for [creature] to deal 2 damage to a chosen opposing slot.", "피 1을 소비해 [creature]이(가) 선택한 상대 슬롯에 피해 2를 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intimidate", "위협", Language.Korean);
            MagnificusMod.RegisterAbility("Intimidate", "위협");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is placed on the board, the creature opposing it will flee to their right.", "[creature]이(가) 보드에 놓이면 맞은편 피조물이 자신의 오른쪽으로 도망친다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonesome", "외로운", Language.Korean);
            MagnificusMod.RegisterAbility("Lonesome", "외로운");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains +1 power for each adjacent empty space.", "인접한 빈칸마다 [creature] 카드의 공격력이 +1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Burst", "마법 폭발", Language.Korean);
            MagnificusMod.RegisterAbility("Magic Burst", "마법 폭발");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After perishing, creatures adjascent to [creature] have their powers increased by 1.", "[creature]이(가) 사망하면 인접한 피조물의 공격력이 1 증가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psystrike", "사이코브레이크", Language.Korean);
            MagnificusMod.RegisterAbility("Psystrike", "사이코브레이크");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After [creature] perishes, it manipulates the creature opposing it to strike both of it's adjascent allies.", "[creature]이(가) 사망하면 맞은편 피조물을 조종해 그 양옆의 아군을 공격하게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Master", "뱀 조련의 대가", Language.Korean);
            MagnificusMod.RegisterAbility("Serpent Master", "뱀 조련의 대가");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of every turn, [creature] spawns a Summon Serpent on a space of it's owner's choosing. A Summon Serpent is defined as: 1 power, 1 health.", "매 턴 시작 시 [creature]이(가) 주인이 선택한 칸에 뱀 소환을 생성한다. 뱀 소환은 공격력 1, 체력 1이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Strike", "환영 일격", Language.Korean);
            MagnificusMod.RegisterAbility("Shadow Strike", "환영 일격");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] calls upon the shadows of creatures adjascent to it's target to strike it as well.", "[creature]은(는) 대상에 인접한 피조물의 그림자도 불러 대상을 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tidal Lock", "조력 고정", Language.Korean);
            MagnificusMod.RegisterAbility("Tidal Lock", "조력 고정");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the beginning of it's owner's turn, [creature] will pull small creatures, like squirrels, into it's orbit.", "주인의 턴이 시작될 때 [creature]이(가) 다람쥐 같은 작은 피조물을 자신의 궤도로 끌어들인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wizard's Heart", "마법사의 심장", Language.Korean);
            MagnificusMod.RegisterAbility("Wizard's Heart", "마법사의 심장");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Mox card corresponding to the current gems you control takes it's place.", "[creature]이(가) 사망하면 현재 당신이 가진 보석에 대응하는 목스 카드가 그 자리를 차지한다.", Language.Korean);

        }
    }
    public class MagModExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MagModExpansion Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beaver's Defense", "비버의 방어", Language.Korean);
            MagnificusMod.RegisterCard("Beaver's Defense", "비버의 방어", "Curating defensive dams upon use, not bad for a dire situation.", "사용할 때 방어용 댐을 만든다. 위급할 때는 나쁘지 않다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curating defensive dams upon use, not bad for a dire situation.", "사용할 때 방어용 댐을 만든다. 위급할 때는 나쁘지 않다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Sage", "폭탄 현자", Language.Korean);
            MagnificusMod.RegisterCard("Bomb Sage", "폭탄 현자", "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "이 현자는 공격받으면 폭발하기로 유명하다… 말 그대로도, 비유적으로도.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "이 현자는 공격받으면 폭발하기로 유명하다… 말 그대로도, 비유적으로도.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boxing Champ", "권투 챔피언", Language.Korean);
            MagnificusMod.RegisterCard("Boxing Champ", "권투 챔피언", "Rejecting the use of wands, this champion prefers to settle things with his fists.", "이 챔피언은 지팡이 사용을 거부하고 주먹으로 일을 해결하기를 선호한다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejecting the use of wands, this champion prefers to settle things with his fists.", "이 챔피언은 지팡이 사용을 거부하고 주먹으로 일을 해결하기를 선호한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "브론토사우루스", Language.Korean);
            MagnificusMod.RegisterCard("Brontosaurus", "브론토사우루스", "I LOVE DINO MOD!!!!!", "공룡 모드 최고!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "공룡 모드 최고!!!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "치즈 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Cheese Wizard", "치즈 마법사", "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "훈련받은 요리사 마법사인 치즈 마법사들은 지성과 신비한 힘으로 목표를 이룬다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "훈련받은 요리사 마법사인 치즈 마법사들은 지성과 신비한 힘으로 목표를 이룬다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheezling", "치즐링", Language.Korean);
            MagnificusMod.RegisterCard("Cheezling", "치즐링", "With cheese like this, who needs friends?", "이런 치즈가 있는데 친구가 무슨 필요야?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With cheese like this, who needs friends?", "이런 치즈가 있는데 친구가 무슨 필요야?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Telepathy", "텔레파시", Language.Korean);
            MagnificusMod.RegisterCard("Telepathy", "텔레파시", "A pupil can gather all the resources they need through sheer will alone.", "제자는 오직 의지만으로 필요한 모든 자원을 모을 수 있다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pupil can gather all the resources they need through sheer will alone.", "제자는 오직 의지만으로 필요한 모든 자원을 모을 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Direct Hit", "직접 피해", Language.Korean);
            MagnificusMod.RegisterCard("Direct Hit", "직접 피해", "Upon being casted, your opponent will instantly take three damage.", "시전하면 상대가 즉시 피해 3을 받는다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon being casted, your opponent will instantly take three damage.", "시전하면 상대가 즉시 피해 3을 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mysterious Egg", "신비한 알", Language.Korean);
            MagnificusMod.RegisterCard("Mysterious Egg", "신비한 알", "Who knows what could hatch from this egg...", "이 알에서 무엇이 부화할지 누가 알겠는가…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows what could hatch from this egg...", "이 알에서 무엇이 부화할지 누가 알겠는가…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faceless", "얼굴 없는 자", Language.Korean);
            MagnificusMod.RegisterCard("Faceless", "얼굴 없는 자", "A hollow shell of a mage, desperately looking for something to call its own.", "마법사의 텅 빈 껍데기. 자기 것이라 부를 만한 무언가를 필사적으로 찾고 있다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hollow shell of a mage, desperately looking for something to call its own.", "마법사의 텅 빈 껍데기. 자기 것이라 부를 만한 무언가를 필사적으로 찾고 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faker", "위조자", Language.Korean);
            MagnificusMod.RegisterCard("Faker", "위조자", "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "거짓말, 속임수, 부정. 위조자는 다치지 않고 도망치기 위해 무슨 일이든 한다…");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "거짓말, 속임수, 부정. 위조자는 다치지 않고 도망치기 위해 무슨 일이든 한다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Figletar", "피글레타", Language.Korean);
            MagnificusMod.RegisterCard("Figletar", "피글레타", "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "사악한 왕에게 끔찍한 운명을 안긴 마법사. 링 위에서도 제법 실력이 있다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "사악한 왕에게 끔찍한 운명을 안긴 마법사. 링 위에서도 제법 실력이 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firestarter", "들불", Language.Korean);
            MagnificusMod.RegisterCard("Firestarter", "들불", "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "이 주문을 시전할 때는 조심하자. 제자들에 따르면 결투장이 조금 뜨거워질 수 있다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "이 주문을 시전할 때는 조심하자. 제자들에 따르면 결투장이 조금 뜨거워질 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fridge Mage", "냉장고 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Fridge Mage", "냉장고 마법사", "Its cold atmosphere will chill foes, weakening their offensive power.", "차가운 기운으로 적을 얼어붙게 해 공격력을 약화한다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its cold atmosphere will chill foes, weakening their offensive power.", "차가운 기운으로 적을 얼어붙게 해 공격력을 약화한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembro", "보석 형제", Language.Korean);
            MagnificusMod.RegisterCard("Gembro", "보석 형제", "The ability to tank any hit once, this pupil has high gusto.", "어떤 공격이든 한 번은 버틸 수 있는 의욕 넘치는 제자.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ability to tank any hit once, this pupil has high gusto.", "어떤 공격이든 한 번은 버틸 수 있는 의욕 넘치는 제자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Tick", "보석 진드기", Language.Korean);
            MagnificusMod.RegisterCard("Gem Tick", "보석 진드기", "An elusive tick, which grants power to others via its mox body.", "잡기 힘든 진드기. 목스 몸으로 다른 이들에게 힘을 준다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elusive tick, which grants power to others via its mox body.", "잡기 힘든 진드기. 목스 몸으로 다른 이들에게 힘을 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Dinosaur", "유령 공룡", Language.Korean);
            MagnificusMod.RegisterCard("Ghost Dinosaur", "유령 공룡", "I LOVE DINO MOD!!!!!", "공룡 모드 최고!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "공룡 모드 최고!!!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third Eye", "제3의 눈", Language.Korean);
            MagnificusMod.RegisterCard("Third Eye", "제3의 눈", "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "제3의 눈의 힘으로 이 주문은 시전자의 덱에서 원하는 카드 한 장을 골라 패에 넣는다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "제3의 눈의 힘으로 이 주문은 시전자의 덱에서 원하는 카드 한 장을 골라 패에 넣는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "야구 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Baseball Mage", "야구 마법사", "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "이 마법사의 지팡이는 야구 방망이로도 쓰인다. 놀라울 만큼 튼튼하다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "이 마법사의 지팡이는 야구 방망이로도 쓰인다. 놀라울 만큼 튼튼하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Golem", "얼음 골렘", Language.Korean);
            MagnificusMod.RegisterCard("Ice Golem", "얼음 골렘", "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "얼어붙은 산꼭대기 출신. 녹아내리는 일도 이 난폭한 자에게는 문제가 되지 않는 듯하다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "얼어붙은 산꼭대기 출신. 녹아내리는 일도 이 난폭한 자에게는 문제가 되지 않는 듯하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looting Bandit", "약탈 도적", Language.Korean);
            MagnificusMod.RegisterCard("Looting Bandit", "약탈 도적", "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "마스터 오를루의 발키리를 멀리서 따르며 그들처럼 되기 위해 수련한다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "마스터 오를루의 발키리를 멀리서 따르며 그들처럼 되기 위해 수련한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mage", "마나 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Mana Mage", "마나 마법사", "Brings together the energy that emits from Mana to deliver powerful strikes.", "마나에서 나오는 에너지를 모아 강력한 타격을 날린다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brings together the energy that emits from Mana to deliver powerful strikes.", "마나에서 나오는 에너지를 모아 강력한 타격을 날린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pondering Pupil", "고뇌하는 제자", Language.Korean);
            MagnificusMod.RegisterCard("Pondering Pupil", "고뇌하는 제자", "It draws from your gem pile using the powers of its mind alone.", "오직 정신의 힘만으로 당신의 보석 더미에서 카드를 뽑는다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It draws from your gem pile using the powers of its mind alone.", "오직 정신의 힘만으로 당신의 보석 더미에서 카드를 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror Mage", "거울 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Mirror Mage", "거울 마법사", "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "거울아, 거울아. 모든 필경자 중 누가 제일이니?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "거울아, 거울아. 모든 필경자 중 누가 제일이니?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whack-A-Mage", "굴 파는 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Whack-A-Mage", "굴 파는 마법사", "Always popping up to cause mischief whenever he can.", "기회만 생기면 나타나 말썽을 부린다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always popping up to cause mischief whenever he can.", "기회만 생기면 나타나 말썽을 부린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mononykus", "모노니쿠스", Language.Korean);
            MagnificusMod.RegisterCard("Mononykus", "모노니쿠스", "I LOVE DINO MOD!!!!!", "공룡 모드 최고!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "공룡 모드 최고!!!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PLUTO", "명왕성", Language.Korean);
            MagnificusMod.RegisterCard("PLUTO", "명왕성", "Hmph. So this is where that one went.", "흠. 그 녀석이 여기로 왔었군.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph. So this is where that one went.", "흠. 그 녀석이 여기로 왔었군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protect", "보호", Language.Korean);
            MagnificusMod.RegisterCard("Protect", "보호", "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "곤경에 빠졌나? 이 주문은 당신의 카드 한 장이 다음 공격을 완전히 무시하게 한다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "곤경에 빠졌나? 이 주문은 당신의 카드 한 장이 다음 공격을 완전히 무시하게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodactyl", "익룡", Language.Korean);
            MagnificusMod.RegisterCard("Pterodactyl", "익룡", "I LOVE DINO MOD!!!!!", "공룡 모드 최고!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "공룡 모드 최고!!!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbid Sage", "미친 토끼 현자", Language.Korean);
            MagnificusMod.RegisterCard("Rabbid Sage", "미친 토끼 현자", "A raving magician with a field of electricity at his disposal.", "전기장을 마음대로 다루는 광란의 마술사.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A raving magician with a field of electricity at his disposal.", "전기장을 마음대로 다루는 광란의 마술사.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemox", "목스 해골", Language.Korean);
            MagnificusMod.RegisterCard("Skelemox", "목스 해골", "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "초록 목스에 조종당하는 불쌍한 해골. 조금 안쓰럽기까지 하다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "초록 목스에 조종당하는 불쌍한 해골. 조금 안쓰럽기까지 하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime Wiz", "점액 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Slime Wiz", "점액 마법사", "It'll use the slime against the enemies, to drop their attack whence struck.", "점액으로 적을 상대해 공격받을 때 적의 공격력을 낮춘다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It'll use the slime against the enemies, to drop their attack whence struck.", "점액으로 적을 상대해 공격받을 때 적의 공격력을 낮춘다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smug Witch", "자만하는 마녀", Language.Korean);
            MagnificusMod.RegisterCard("Smug Witch", "자만하는 마녀", "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "온 세상에서 가장 잘난 체하는 제자. 그의 자만 투척은 견줄 자가 없다고 한다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "온 세상에서 가장 잘난 체하는 제자. 그의 자만 투척은 견줄 자가 없다고 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Spear", "소환의 창", Language.Korean);
            MagnificusMod.RegisterCard("Summon Spear", "소환의 창", "Roots up a spear from the ground, acting as a sturdy counter.", "땅에서 창을 뽑아 든든한 반격을 가한다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roots up a spear from the ground, acting as a sturdy counter.", "땅에서 창을 뽑아 든든한 반격을 가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spike Mage", "가시 마법사", Language.Korean);
            MagnificusMod.RegisterCard("Spike Mage", "가시 마법사", "This mage learned from the best of my Pike Mage's Scarecrows.", "이 마법사는 내 최고의 장창 마법사의 허수아비에게서 배웠다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage learned from the best of my Pike Mage's Scarecrows.", "이 마법사는 내 최고의 장창 마법사의 허수아비에게서 배웠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T-Rex", "티라노사우루스", Language.Korean);
            MagnificusMod.RegisterCard("T-Rex", "티라노사우루스", "I LOVE DINO MOD!!!!!", "공룡 모드 최고!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "공룡 모드 최고!!!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Virtual King", "가상 군주", Language.Korean);
            MagnificusMod.RegisterCard("Virtual King", "가상 군주", "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "가상 세계의 자칭 지배자. 하찮은 ‘카드 게임 규칙’ 따위는 따르지 않는다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "가상 세계의 자칭 지배자. 하찮은 ‘카드 게임 규칙’ 따위는 따르지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moron Core", "저능한 코어", Language.Korean);
            MagnificusMod.RegisterCard("Moron Core", "저능한 코어", "An odd core hailing from an abandoned factory, hates the word \"moron\".", "버려진 공장에서 온 이상한 코어. ‘멍청이’라는 말을 싫어한다.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An odd core hailing from an abandoned factory, hates the word \"moron\".", "버려진 공장에서 온 이상한 코어. ‘멍청이’라는 말을 싫어한다.", Language.Korean);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smughtro's MagMod Expansion", "Smughtro의 매그니피쿠스 모드 확장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds 19 common cards, 7 rare cards, 7 spells, and 6 token cards to Magnificus Mod.", "매그니피쿠스 모드에 일반 카드 19장, 희귀 카드 7장, 주문 7개, 토큰 카드 6장을 추가한다.", Language.Korean);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Assist", "죽음의 지원", Language.Korean);
            MagnificusMod.RegisterAbility("Death Assist", "죽음의 지원");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it will deal 3 damage to the opponent.", "이 도장을 지닌 카드가 사망하면 상대에게 피해 3을 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emmental Elemental", "치즈 정령", Language.Korean);
            MagnificusMod.RegisterAbility("Emmental Elemental", "치즈 정령");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, summon a Cheezling.", "이 도장을 지닌 카드를 내면 치즐링을 소환한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Strike", "선제 타격", Language.Korean);
            MagnificusMod.RegisterAbility("First Strike", "선제 타격");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will instantly attack the opposing lane. If there are no opposing cards, no damage will be dealt.", "이 도장을 지닌 카드를 내면 즉시 맞은편 공격로를 공격한다. 맞은편에 카드가 없으면 피해를 주지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unknown Hatching", "미지의 부화", Language.Korean);
            MagnificusMod.RegisterAbility("Unknown Hatching", "미지의 부화");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of your turn, a card bearing this sigil will hatch into a random dinosaur.", "주인의 턴이 시작될 때 이 도장을 지닌 카드는 무작위 공룡으로 부화한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healthy Death", "생명의 종언", Language.Korean);
            MagnificusMod.RegisterAbility("Healthy Death", "생명의 종언");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the cards to the left and right of the sigil bearer heal 1 health.", "이 도장을 지닌 카드가 사망하면 보유자의 좌우 카드가 각각 체력을 1 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mess", "마나의 혼돈", Language.Korean);
            MagnificusMod.RegisterAbility("Mana Mess", "마나의 혼돈");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random non-rare Mana costing card.", "이 도장을 지닌 카드를 내면 마나를 비용으로 쓰는 희귀하지 않은 카드 한 장을 무작위로 뽑는다.", Language.Korean);

        }
    }
    public class FloweysMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for FloweysMod Mod");


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flowey", "플라위", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fanatical leader hell-bent on bringing about the apocalypse by reviving the great Cthulhu through behind-the-scenes scheming.", "막후에서 음모를 꾸며 위대한 크툴루를 부활시키고 종말을 일으키려는 광신적인 지도자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You Idiot", "이 바보야", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an Idiot if you think you can defeat me!", "날 이길 수 있다고 생각한다면 정말 바보야!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Omega Flowey", "오메가 플라위", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an idiot.", "넌 정말 바보야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patience", "인내", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "patient.", "인내심이 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bravery", "용기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brave.", "용감하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Integrity", "고결", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "integrant.", "고결하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perseverence", "끈기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persevering.", "끈기 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kindness", "자비", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kind.", "자비롭다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice", "정의", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice.", "정의롭다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy- Uh i meant Are you ready to Die?", "안녕! 아, 아니. 죽을 준비는 됐어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy! it's me Flowey, Flowey the Flower!", "안녕! 난 플라위야, 꽃 플라위!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know whats going on here, dont you?", "여기서 무슨 일이 일어나는지 알지?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You just wanted to see me suffer[c:0]!", "넌 그저 내가 고통받는 모습을 보고 싶었던 거야[c:0]!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do You know that ive been watching you?", "내가 계속 널 지켜보고 있었다는 걸 알아?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well i took over Inscryption now!", "이제 인스크립션은 내가 장악했어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and i know what Secrets are hiding beneath Inscryption...", "그리고 인스크립션 밑에 어떤 비밀이 숨겨져 있는지도 알아…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now nothing stands in my Way to take over the World now!", "이제 내가 세상을 지배하는 걸 막을 것은 아무것도 없어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do you think this Fight was about?", "이 싸움이 무슨 목적이었다고 생각해?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just used it as a cover to snoop through Inscryptions Files!", "이 싸움을 엄폐물 삼아 인스크립션의 파일을 몰래 뒤졌을 뿐이야!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And your PC of course!", "물론 네 컴퓨터도!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you may have noticed, BUT iam now connected to the Internet!", "눈치챘을지도 모르지만, 난 이제 인터넷에 연결됐어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So now its time to begin Uploading Inscryption!", "이제 인스크립션을 업로드할 시간이야!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You REALLY are an Idiot!", "넌 정말 바보야!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't even need the Power of Human Souls if i just use the OLD_DATA!", "구_데이터만 쓰면 인간 영혼의 힘 따위 필요 없어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Do you know what you are achieving by this? Nothing", "[c:bR]이렇게 해서 뭘 이룰 수 있는지 알아? 아무것도 없어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]You cant get rid of me! No matter what you do, i will always be there!", "[c:bR]날 없앨 수는 없어! 네가 뭘 하든 난 언제나 여기 있을 거야!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Th- The Souls?", "[c:bR]여, 영혼들?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]wh- where are my Powers?", "[c:bR]내, 내 힘이 어디 갔지?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHAT HAVE YOU DONE?!", "[c:bR]무슨 짓을 한 거야?!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Floweys Defence dropped to [c:bR]0!", "플라위의 방어가 [c:bR]0이 되었다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOOOOOO", "[c:bR]안 돼애애애", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What just happened...", "방금 무슨 일이 일어난 거지…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph seemms you have won this time...", "흥, 이번에는 네가 이긴 모양이군…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOBODY IS GOING TO HELP YOU!", "[c:bR]아무도 널 도와주지 않을 거야!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP CALLING FOR [c:bR]HELP!", "더는 [c:bR]도움을 청하지 마!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Did you really think id let you kill me so easily?", "[c:bR]내가 그렇게 쉽게 죽어 줄 거라고 생각했어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]what the-", "[c:bR]뭐, 뭐야—", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Flowey thought they could just use me...", "[c:bR]플라위는 나를 마음대로 이용할 수 있다고 생각했지…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]He didnt even know what I am!", "[c:bR]그는 내가 무엇인지조차 몰랐어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]But now IAM in control...", "[c:bR]하지만 이제 주도권은 내게 있어…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]How pathetic of him to not set his HP to Infinite... I won't make that mistake", "[c:bR]HP를 무한으로 설정하지 않다니 한심하군… 난 그런 실수를 하지 않아", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Try all you want you can't kill me!", "[c:bR]아무리 애써도 날 죽일 수 없어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Now lets see what this does...", "[c:bR]자, 이게 무슨 일을 하는지 볼까…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHY CANT I UNDO THIS???", "[c:bR]왜 이걸 되돌릴 수 없는 거야???", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SEEING YOU DIE OVER AND OVER AGIAN IS REALLY [c:bR]FUN!", "네가 계속해서 죽는 모습을 보는 건 정말 [c:bR]재밌어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT EVEN A SINGLE POINT OF DAMAGE!", "피해를 단 1도 주지 못했어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOMEONE LIKE [c:bR]YOUCANT BEAT ME!", "[c:bR]너 따위는 날 이길 수 없어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Starvation wont interrupt this fight!", "[c:bR]기아는 이 전투를 방해하지 못해!", Language.Korean);


        }
    }
    public class UndertaleMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for UndertaleMod Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack:U", "카드 팩: U", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aaron", "아론", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, Aaron the bold, aaron the beautiful. can you manage to take your eyes off his muscles?", "아, 대담하고 아름다운 아론. 그의 근육에서 눈을 뗄 수 있겠는가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alphys", "알피스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr. Alphys is responsible for the creation of some of the more 'unnerving' individuals you've seen here... or should I say... MULTI-viduals.", "알피스 박사는 여기서 본 다소 ‘섬뜩한’ 개체들을 만들었다… 아니, 여럿이 합쳐진 개체라고 해야 하나.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loveable, yet pestulant. The duality of this creature is unparalleled.", "사랑스럽지만 짜증스럽다. 이 피조물의 양면성은 타의 추종을 불허한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asgore", "아스고어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The king of monsters... he truly is an intimidating force of brute strength, but also... compassion?", "괴물들의 왕… 무시무시한 힘을 지녔지만, 그에게도… 자비가 있다고?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "asriel dreemurr", "아스리엘 드리무어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the most powerful being in the underground... hopefully you find some use for him.", "지하 세계에서 가장 강력한 존재… 그를 잘 활용할 수 있기를 바란다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astigmatism", "난시 눈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frustrating astigmatism... it can't make up its mind.", "성가신 난시 눈… 마음을 정하지 못한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gaster Blaster", "가스터 블라스터", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Block of Ice", "얼음덩어리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiarly large ice cube... Who knows what could be inside.", "유난히 큰 얼음덩이… 안에 무엇이 들었을까.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chara", "차라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy", "도그미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy and his wife, Dogaressa, love to tag-team the battlefield. Just don't let one of them perish...", "도그미와 아내 도그레사는 전장에서 함께 싸우는 걸 좋아한다. 둘 중 하나라도 죽게 두지 마라…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogaressa", "도그레사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doggo", "도고", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, the blind doggo... He leaps towards any sound of movement.", "아, 눈먼 도고… 움직이는 소리만 들리면 달려든다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doodlebog", "두들보그", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy", "인형", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bland dummy... not as charismatic as its 'mad' counterpart", "밋밋한 인형… ‘화난’ 동료만큼 매력적이지는 않다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amalgamate", "합체 괴물", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endogeny", "엔도제니", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "null", "무", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Froggit", "파이널 프로깃", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the ultimate boss of froggits... Still as easily fooled as its lesser evolved kin.", "아, 프로깃의 궁극적인 우두머리… 덜 진화한 동족만큼이나 쉽게 속는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frisk", "프리스크", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Froggit", "프로깃", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, as shy as they come... the froggit wishes not to engage in conflict. how unfortunate.", "아, 아주 수줍은 프로깃… 싸움에 끼어들고 싶어 하지 않는다. 안타깝군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "W.D.Gaster", "W.D. 가스터", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "glyde", "글라이드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a narcisist, it can only attack if a card is in front of it to watch.", "정말 자기애가 강하다. 앞에서 지켜보는 카드가 있어야만 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Dog", "대형견", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "truly and nobly adequate, it is the highest form of evolution a canine can become.", "진정 고귀하고 흠잡을 데 없는, 개가 도달할 수 있는 최고의 진화 형태다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gyftrot", "기프트롯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be kind to this creature, it has gone through enough.", "이 피조물에게 친절히 대해 주자. 이미 충분히 많은 일을 겪었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Wolf", "얼음 늑대", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, this buff creature spawns a block of ice upon death.", "아, 이 근육질 피조물은 죽으면 얼음덩어리를 만든다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Icecap", "아이스캡", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jerry", "제리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just ditch him already.", "이제 그만 그를 버리고 가자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knight Knight", "나이트나이트", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the forboding knight knight... a sentinel of sleep. She is relentless in her conquest..", "아, 불길한 나이트나이트… 잠의 파수꾼. 그녀의 정복은 거침없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lemon Bread", "레몬 브레드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Dog", "소형견", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mediocre canine at best... at least in its current form.", "기껏해야 평범한 개다… 적어도 지금 모습으로는.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loox", "눈딱이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cunning Loox EyeWalker... you would be wise not to pick on him.", "교활한 눈딱이 아이워커… 괴롭히지 않는 게 좋을 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mad Dummy", "매드 더미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy?", "인형?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks can be deceiving...", "겉모습은 사람을 속일 수 있다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Madjick", "매직", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "quite the magician...", "꽤나 대단한 마술사군…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Memoryhead", "메모리헤드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton", "메타톤", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hyper-intelligent, systematic, complex data analyzer... reminds me of an old 'friend'.", "초고지능의 체계적이고 복잡한 데이터 분석기… 옛 ‘친구’가 떠오른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton Ex", "메타톤 EX", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migosp", "미고스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the irritable Migosp... its attack increases in a crowd.", "화를 잘 내는 미고스… 무리 속에 있으면 공격력이 높아진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migospel", "미고스펠", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldbygg", "몰드빅", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldsmal", "몰드스멀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one's giving me imposter vibes.", "이 녀석은 가짜 같은 느낌이 든다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldessa", "몰데사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the gelatinous moldsmal. you probably never wondered what it's made of.", "아, 젤리 같은 몰드스멀. 무엇으로 이루어졌는지 생각해 본 적은 없겠지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muffet", "머펫", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the spider queen. her rapid play game is remarkable.", "아, 거미 여왕. 빠르게 카드를 내는 솜씨가 놀랍다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Napstablook", "냅스타블룩", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most melancholy of ghosts... it cares not of battle, but still fights to impress.", "가장 우울한 유령… 전투에는 관심이 없지만 인상을 남기기 위해 싸운다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "onionsan", "어니언상", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not much strategy with one... It becomes a random tentcle card one the second turn.", "전략이 그다지 필요 없다… 두 번째 턴에 무작위 촉수 카드로 변한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A boney brute, papyrus is. He will generate bones like nobody's business.", "뼈만 남은 덩치 파피루스. 누구보다도 뼈를 잘 만들어 낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parsnik", "파스닉", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrope", "파이로프", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Pyrope wants nothing more than to crank up the heat, let's see how fatal that can be.", "파이로프는 열을 올리는 것만을 원한다. 얼마나 치명적인지 보자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reaper Bird", "리퍼 버드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Guards", "왕실 경비병", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "two star-crossed lovers... will they ever focus on what's important?", "운명이 엇갈린 연인들… 중요한 일에 집중할 수 있을까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "if you pick this card, i feel like i'm going to have a bad time.", "이 카드를 고르면 내가 고생할 것 같은데.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shyren", "샤이렌", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The musically inclined shyren... strike her bells to watch her sing.", "음악을 좋아하는 샤이렌… 종을 울리면 노래하는 모습을 볼 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snowdrake", "스노우드레이크", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The laughable Snowdrake... striving to prove his father wrong. Will you let him succeed?", "우스꽝스러운 스노우드레이크… 아버지가 틀렸다는 것을 증명하려 애쓴다. 성공하게 해 주겠는가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So Cold", "너무 추워", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "so sorry", "정말 미안해", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "he's very sorry", "그는 정말 미안해한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie", "테미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie the immortal cat... at least i think she's a feline. Nothing to lose, everything to gain.", "불사의 고양이 테미… 적어도 고양잇과인 것 같다. 잃을 것은 없고 얻을 것은 많다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toriel", "토리엘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keeper of the ruins... She will protect your side of the board to the best of her ability.", "유적의 수호자… 최선을 다해 당신 측 보드를 지킬 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tsunderplane", "츤데레 비행기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She can't decide between wanting your attention and wanting you to back off... i suggest the latter.", "당신의 관심을 끌고 싶은지 멀리하라고 하고 싶은지 정하지 못한다… 후자를 추천한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undyne", "언다인", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How could I forget Undyne? She is a true warrior, with an almighty aim on her spear.", "언다인을 어찌 잊겠는가? 진정한 전사로, 창을 겨누는 솜씨가 대단하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vegetoid", "베지토이드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "eat your greens. (not monitored by the fda)", "채소를 먹자. (미국 식품의약국의 감독을 받지 않음)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vulkin", "벌킨", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A very passionate creature, this one. It's not his intention to harm, but that doesn't stop him.", "아주 열정적인 피조물. 해칠 의도는 없지만 그렇다고 해를 끼치지 않는 것은 아니다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsalot", "우울한 벌레 경", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the noble whimsalot... pray that it deems your conquest riteous.", "고귀한 우울한 벌레 경… 당신의 정복이 정당하다고 인정해 주길 기도하자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsun", "우울한 작은 벌레", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the insignificant whimsun... it flees the battle after a single attack.", "보잘것없는 우울한 작은 벌레…… 스스로 한 번 공격하면 전투에서 달아난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woshua", "워슈아", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature has no lust for blood. His will lies with helping others. But it will fight if provoked.", "이 피조물은 피를 갈망하지 않고 남을 돕고자 한다. 하지만 도발당하면 싸운다.", Language.Korean);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antisocial", "비사교적", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will gain an attack buff if you have at least 1 other card on your side of the board.", "당신 측 보드에 다른 카드가 적어도 1장 있으면 이 도장을 지닌 카드의 공격력이 강화된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanser", "정화자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will heal every card on its owner's side of the board, except the sigil bearer, for 1 health, at the start of every turn.", "주인의 전투 단계가 시작할 때 이 도장을 지닌 카드는 주인 측 보드에 있는 다른 모든 카드의 체력을 1 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Determination", "결의", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move to any open slot its owner chooses, it will also gain EXP and LV after a kill. But is that really what you want?", "이 도장을 지닌 카드는 주인이 선택한 빈 슬롯으로 이동할 수 있으며, 적을 죽이면 EXP와 LV도 얻는다. 하지만 정말 그것을 원하는가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incendiary", "방화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil damages a card, that card gains the \"ablaze\" sigil. While a card is ablaze, it will lose one health per turn.", "이 도장을 지닌 카드가 다른 카드를 공격하면 대상은 ‘작열’ 도장을 얻는다. 작열 도장을 지닌 카드는 주인의 전투 단계가 시작할 때 피해 1을 입는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ablaze", "작열", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will take 1 damage at the start of its owner's turn.", "주인의 전투 단계가 시작할 때 이 도장을 지닌 카드는 피해 1을 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indecisive", "우유부단", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it has a 50/50 chance to either gain a stat buff, or perish; creating a copy of this card in your hand.", "이 도장을 지닌 카드가 맞으면 능력치가 강화되거나 사망하고 패에 그 카드의 사본을 생성할 확률이 각각 절반이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone knows Jerry. Makes Turns 2 seconds longer. Cards gain a stat buff when Jerry is killed or sacrificed.", "누구나 제리를 안다. 턴을 2초 길게 만든다. 제리가 죽거나 희생되면 플레이어 측 카드의 능력치가 강화된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mercy", "자비", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A 'Determined' card will be granted this sigil when the card opposing it has low health, prompting the player to make a moral decision.", "‘결의’가 있는 카드는 맞은편 카드의 체력이 낮아지면 이 도장을 얻어 플레이어에게 도덕적 선택을 요구한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insight", "통찰", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you wanna have a bad time?", "힘든 시간을 보내고 싶어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doodler", "두들러", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it will sometimes summon doodlebogs on adjacent spaces.", "이 도장을 지닌 카드가 맞으면 가끔 인접한 칸에 두들보그를 소환한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid", "소심함", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opponent card moves into the opposing space of a card bearing this sigil, the sigil bearer will try to move one space over.", "상대 카드가 이 도장을 지닌 카드의 맞은편 칸으로 이동하면 도장 보유자가 한 칸 이동하려 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You ditched Jerry.", "제리를 따돌렸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow, you guys SUCK at this.", "와, 너희 정말 못한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wi-fi here sucks.", "여기 와이파이 진짜 별로야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHHHH! Im THINKING, guys!!", "쉿! 나 생각 중이야, 얘들아!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get your own, twerp.", "네 건 네가 구해, 꼬맹이.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why are we doing this? What a fail.", "우리가 왜 이걸 하는 거야? 완전 실패네.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guys. its COLD. Does ANYONE care?", "얘들아, 춥다고. 신경 쓰는 사람 없어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ka-SIGH", "하아아.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DUH! Who DOESNT know?", "당연하지! 누가 몰라?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well... can YOU give me a ride home?", "저기… 집까지 태워다 줄 수 있어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awkwarrrd.", "어색해애.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So, like, what are you even doing?", "그래서 대체 뭘 하는 거야?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Huh? Did they ditch me...? SOME friends!", "어? 다들 날 버리고 갔어… 친구라는 것들이!", Language.Korean);



        }
    }
    public class RevenantMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for RevenantMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DanseMacabre", "죽음의 무도", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to reverse this sigil effect. At the end of the owner's turn, all creatures on the board gain 1 health.", "뼈 2개를 지불해 이 도장의 효과를 반전한다. 주인의 턴이 끝날 때 보드의 모든 피조물이 체력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LifeDraw", "생명 드로우", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Blood to draw a card from your main deck.", "피 1을 지불해 주 덱에서 카드 한 장을 뽑는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "영혼 영역의 문", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to gain 1 Energy, lose as much Max Energy at the end of the owner's turn.", "뼈 1개를 지불해 에너지 1을 얻고 주인의 턴이 끝날 때 그만큼 최대 에너지를 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evocation", "환기술", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Energy to return the oldest non-Brittle allied creature from the graveyard to your hand.", "에너지 3을 지불해 무덤에서 가장 먼저 들어간 취약성이 없는 아군 피조물을 패로 되돌린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dormant", "휴면", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay Bones equal to the Power of [creature] to disable this sigil for 1 turn. [creature] cannot attack normally.", "[creature]의 공격력과 같은 수의 뼈를 지불해 이 도장을 1턴 동안 비활성화한다. [creature]은(는) 일반 공격을 할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transmute", "변환", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to transform [creature] to its alternate form.", "뼈 2개를 지불해 [creature]을(를) 다른 형태로 변신시킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protector", "보호자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] gain 1 max health.", "[creature]에 인접한 피조물은 최대 체력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CalamityEffusion", "재앙의 분출", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board lose 1 health.", "주인의 턴이 끝날 때 보드의 모든 피조물이 체력을 1 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ComfortAura", "위안의 기운", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, creatures adjacent to [creature] heal 1 health.", "주인의 턴이 끝날 때 [creature]에 인접한 피조물은 체력을 1 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CorpseParty", "시체 파티", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, a Zombie enters your hand. A Zombie is defined as: 1 Power, 1 Health.", "주인 측에서 취약성이 없는 피조물이 전투로 사망하면 좀비 한 장이 패에 들어온다. 좀비는 공격력 1, 체력 1이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathKnock", "죽음의 반격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, it strikes back then perishes.", "[creature]이(가) 전투로 사망하면 반격한 뒤 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathMetal", "데스 메탈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, adjacent creatures and opposing creatures to the left, right, and center of it take 1 damage. It gains 1 Power for each affected creature.", "[creature]을(를) 내면 인접한 피조물과 맞은편 왼쪽, 오른쪽, 중앙의 상대 피조물이 피해 1을 받는다. 영향을 받은 피조물 하나당 공격력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defiler", "오염자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, draw a card then choose one to discard from your hand.", "[creature]이(가) 사망하면 카드 한 장을 뽑은 뒤 패에서 한 장을 골라 버린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Encroachment", "침식", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] creates a copy of it in your hand after 2 turns on the board.", "[creature]이(가) 보드에 2턴 있으면 패에 자신의 사본 한 장을 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletonize", "해골화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Skeleton with its old sigils enters your hand. A Skeleton is defined as: 1 Power, 1 Health, Brittle.", "[creature]이(가) 사망하면 원래 도장을 지닌 해골이 패에 들어온다. 해골은 공격력 1, 체력 1, 취약성을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcise", "퇴마", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Bones equal to the Bone cost of the opposing creature are granted to the player.", "[creature]을(를) 내면 맞은편 피조물의 뼈 비용만큼 뼈를 플레이어가 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ExplodingCorpse", "폭발하는 시체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, all empty spaces on the board are filled with a Guts card.", "[creature]이(가) 전투로 사망하면 보드의 모든 빈칸이 내장 카드로 채워진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GrudgeCollector", "원한 수집가", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power for every 2 times opponent creatures deal direct damage to its owner.", "상대 피조물이 주인에게 직접 피해를 2번 줄 때마다 [creature]은(는) 공격력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Power", "종의 힘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bell cards on the board.", "이 도장이 나타내는 값은 보드의 종 카드 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Digger Power", "뼈 발굴의 힘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bone and Digger related sigils on the board.", "이 도장이 나타내는 값은 보드에 있는 뼈와 발굴 관련 도장의 수와 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignition", "점화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power at the cost of 1 health after each turn on the board.", "[creature]은(는) 보드에 있는 동안 매 턴 체력 1을 대가로 공격력 1을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Digger Latch", "뼈 발굴 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain the Bone Digger sigil.", "주인의 턴이 끝날 때 [creature]은(는) 뼈 1개를 생성한다. 사망하면 주인이 뼈 발굴 도장을 줄 피조물을 선택한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Primed Digger Latch", "강화 뼈 발굴 랫치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain this sigil.", "주인의 턴이 끝날 때 [creature]은(는) 뼈 1개를 생성한다. 사망하면 주인이 이 도장을 줄 피조물을 선택한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejuvenation", "회춘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Fledgling sigil.", "[creature]이(가) 사망하면 주인이 햇병아리 도장을 줄 피조물을 선택한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skull Storm", "해골 폭풍", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, this sigil is replaced with another sigil at random. When it perishes, its owner chooses a creature to gain this sigil.", "주인의 턴이 끝날 때 이 도장은 무작위의 다른 도장으로 바뀐다. 이 카드가 사망하면 주인이 이 도장을 줄 피조물을 선택한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "불붙이기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Ignition sigil.", "[creature]이(가) 사망하면 주인이 점화 도장을 줄 피조물을 선택한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MacabreBonePulse", "음산한 뼈의 파동", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it perishes immediately, dropping Bones equal to double the amount of creatures on the owner's side.", "[creature]을(를) 내면 즉시 사망하며 주인 측 피조물 수의 두 배만큼 뼈를 떨어뜨린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maternal", "모성", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] are inscrybed by Waterborne.", "[creature]에 인접한 피조물에게 수생 도장이 새겨진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Necrosis", "괴사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 power and 1 max health after each turn on the board.", "[creature]은(는) 보드에 있는 동안 매 턴 공격력과 최대 체력을 각각 1 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Limbo", "림보", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it returns to the top of your deck.", "[creature]이(가) 사망하면 당신의 덱 맨 위로 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RelentlessRevenant", "끈질긴 망령", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, creatures adjacent to [creature] transform into a Revenant. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "주인의 턴이 시작될 때 [creature]에 인접한 피조물은 망령으로 변한다. 망령은 공격력 3, 체력 1, 취약성을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revedue", "망령의 귀환", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] perishes, then shuffle 2 Revenants with its old sigils into your side deck. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "공격 후 [creature]이(가) 사망하고 원래 도장을 지닌 망령 2장을 보조 덱에 섞어 넣는다. 망령은 공격력 3, 체력 1, 취약성을 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bad Omen", "불길한 징조", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will deal 1 damage to the owner.", "주인의 턴이 끝날 때 [creature]은(는) 주인에게 피해 1을 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rancor", "원한", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it leaves a permanent 1 power buff in the space it occupied.", "[creature]이(가) 사망하면 원래 있던 칸에 영구적인 공격력 1 증가 효과를 남긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SoothingMeadows", "위안의 초원", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board gain 1 health.", "주인의 턴이 끝날 때 보드의 모든 피조물이 체력을 1 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PartingStroke", "마지막 일격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, its owner chooses a creature to lose all of its sigils.", "주인 측에서 취약성이 없는 피조물이 전투로 사망하면 주인이 피조물을 선택해 모든 도장을 잃게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SplittingCorpse", "분열하는 시체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, create a Dysmorphia on each empty adjacent space.", "[creature]이(가) 전투로 사망하면 인접한 각 빈칸에 기형체를 하나씩 생성한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torpid", "둔감", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot attack normally.", "[creature]은(는) 일반 공격을 할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Epitaph", "음산한 묘비명", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may choose a card that has already been put to rest, to bring back to your hand.", "[creature]을(를) 내면 이미 안식에 든 카드 한 장을 선택해 패로 되돌릴 수 있다.", Language.Korean);


            //card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigfoot", "거대한 발", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a mysterious creature lurking the forests, only few have claimed to see one.", "숲에 숨어 사는 신비로운 피조물. 소수만이 보았다고 주장한다.", Language.Korean);
            GrimoraMod.RegisterCard("Bigfoot", "거대한 발");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goblin", "고블린", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal barbaric beast, a fine addition to your army.", "충성스러운 야만의 야수. 당신의 군대에 좋은 전력이 된다.", Language.Korean);
            GrimoraMod.RegisterCard("Goblin", "고블린");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vila", "빌라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love at first sight, at least that's what it wants you to think.", "첫눈에 반했다. 적어도 녀석은 당신이 그렇게 믿기를 바란다.", Language.Korean);
            GrimoraMod.RegisterCard("Vila", "빌라");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yaramayawho", "붉은 피부 개구리 마물", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to finish it's meals...", "식사를 끝까지 해치우는 법이 없는 것 같다…", Language.Korean);
            GrimoraMod.RegisterCard("Yaramayawho", "붉은 피부 개구리 마물");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Test Limbs", "시험용 팔다리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those parts used to belong to someone, or now some thing...(Test)", "이 부위들은 한때 누군가의 것이었다. 이제는 어떤 것의 것이지만… (테스트)", Language.Korean);
            GrimoraMod.RegisterCard("Test Limbs", "시험용 팔다리");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allip", "광기의 원혼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remnants of the insane! You never know what story lies behind that face, but it's sure to be filled with fervor.", "미치광이의 잔해! 저 얼굴 뒤에 어떤 이야기가 있는지는 알 수 없지만 분명 열광으로 가득할 것이다.", Language.Korean);
            GrimoraMod.RegisterCard("Allip", "광기의 원혼");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amami Rabbit", "아마미검은멧토끼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiding their young in holes, they wish for their best safety.", "새끼를 구멍에 숨겨 최대한 안전하기를 바란다.", Language.Korean);
            GrimoraMod.RegisterCard("Amami Rabbit", "아마미검은멧토끼");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankhame", "안카 주물", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A relic that is drawn to your blood, perhaps you could give it a swing!", "당신의 피에 이끌리는 유물. 한번 휘둘러 보는 게 어떨까!", Language.Korean);
            GrimoraMod.RegisterCard("Ankhame", "안카 주물");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anneta", "아네타", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That ink keeps on pouring, is she even there anymore? All that death promises is that you will wake up again.", "잉크가 계속 쏟아진다. 그녀는 아직 거기 있는 걸까? 죽음이 약속하는 것은 다시 깨어난다는 것뿐이다.", Language.Korean);
            GrimoraMod.RegisterCard("Anneta", "아네타");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anorexia", "거식의 마물", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overflowing you with self loathing, you never know what form it may take on next.", "당신을 자기혐오로 가득 채운다. 다음에는 어떤 형태를 취할지 알 수 없다.", Language.Korean);
            GrimoraMod.RegisterCard("Anorexia", "거식의 마물");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lych Bell", "리치의 종", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems like they found a new way to use bells.", "종을 사용하는 새로운 방법을 찾은 모양이다.", Language.Korean);
            GrimoraMod.RegisterCard("Lych Bell", "리치의 종");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TheBloated", "부푼 시체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grotesque boils, ready to burst.", "곧 터질 듯한 흉측한 종기.", Language.Korean);
            GrimoraMod.RegisterCard("TheBloated", "부푼 시체");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BrainJar", "기형 뇌 통조림", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One shudders to imagine what inhuman thoughts lie inside that jar...", "저 병 안에 어떤 비인간적인 생각이 있는지 상상만 해도 몸서리쳐진다…", Language.Korean);
            GrimoraMod.RegisterCard("BrainJar", "기형 뇌 통조림");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Combustor", "폭연 시체 껍질", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, what a fall from such a stimulatingly high status, now all that's left is a metal carcass, and the last of that watchful substance...", "이런, 그토록 자극적으로 높은 지위에서 추락하다니. 이제 남은 것은 금속 시체와 마지막으로 경계하는 물질뿐이다…", Language.Korean);
            GrimoraMod.RegisterCard("Combustor", "폭연 시체 껍질");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Misplayed Stoat", "문드러진 담비", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A decaying Stoat whose oh-so perfect strategies failed him tremendously.", "썩어 가는 담비. 그토록 완벽하던 전략이 그를 크게 저버렸다.", Language.Korean);
            GrimoraMod.RegisterCard("Misplayed Stoat", "문드러진 담비");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia", "기형체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Left.", "왼쪽 기형체.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Right.", "오른쪽 기형체.", Language.Korean);
            GrimoraMod.RegisterCard("Dysmorphia", "기형체");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcist", "퇴마 도사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He still thinks banishing the dammed will do him good, does he know where he is?", "그는 저주받은 자들을 쫓아내면 자신에게 좋을 거라 아직도 생각한다. 여기가 어딘지 알고 있을까?", Language.Korean);
            GrimoraMod.RegisterCard("Exorcist", "퇴마 도사");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flembones", "고름 뼈 망령", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait until he plays with his webcam.", "그가 웹캠을 가지고 놀 때까지 기다리자.", Language.Korean);
            GrimoraMod.RegisterCard("Flembones", "고름 뼈 망령");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stein & Frank", "스타인과 프랭크", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even hell was not hot enough to split them.", "지옥조차 그들을 갈라놓을 만큼 뜨겁지는 않았다.", Language.Korean);
            GrimoraMod.RegisterCard("Stein & Frank", "스타인과 프랭크");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulmineSkull", "뇌성 두개골", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you listen closely, you can still hear the cackling of flame on bone... as well as their voice.", "귀를 기울이면 뼈 위에서 불꽃이 타닥거리는 소리가 아직 들린다… 그들의 목소리도.", Language.Korean);
            GrimoraMod.RegisterCard("FulmineSkull", "뇌성 두개골");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulurOssa", "우레 증골", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It never truly left the electric chair.", "그것은 전기 의자를 진정으로 떠난 적이 없다.", Language.Korean);
            GrimoraMod.RegisterCard("FulurOssa", "우레 증골");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PrometheusFlame", "프로메테우스의 불꽃", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one is quite unique, the lingering spoils of a thief to benefit humanity! Fancy liver by chance?", "꽤 독특한 것. 인류를 도운 도둑이 남긴 전리품이다! 간이라도 먹겠는가?", Language.Korean);
            GrimoraMod.RegisterCard("PrometheusFlame", "프로메테우스의 불꽃");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guts", "내장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying guts.", "성가신 내장.", Language.Korean);
            GrimoraMod.RegisterCard("Guts", "내장");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harbinger", "선구자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A powerful fiend that extols a heavy price for its servitude.", "강력한 마귀. 그를 부리려면 큰 대가를 치러야 한다.", Language.Korean);
            GrimoraMod.RegisterCard("Harbinger", "선구자");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hastur", "하스터", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He came from beyond the stars, gifting pieces of his reflection to kings and fools alike. Will you accept this piece?", "그는 별 너머에서 와 자신의 비친 모습의 조각을 왕과 바보 모두에게 선물했다. 이 조각을 받겠는가?", Language.Korean);
            GrimoraMod.RegisterCard("Hastur", "하스터");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Common Imp", "평범한 임프", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tiny creature known for causing trouble and mayhem wherever it goes, with its mischievous grin and playful nature!", "장난스러운 미소와 성격으로 가는 곳마다 말썽과 혼란을 일으키는 작은 피조물!", Language.Korean);
            GrimoraMod.RegisterCard("Common Imp", "평범한 임프");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochimitama", "오로치의 잔혼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... He is not supposed to be here...", "아… 그는 여기 있어서는 안 되는데…", Language.Korean);
            GrimoraMod.RegisterCard("Orochimitama", "오로치의 잔혼");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inochi", "생명의 숨결", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A soothing presence to heal your creatures, a calm before the storm.", "당신의 피조물들을 치유하는 편안한 존재. 폭풍 전의 고요다.", Language.Korean);
            GrimoraMod.RegisterCard("Inochi", "생명의 숨결");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trail of Torment.", "고통의 길.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessed Limbs", "기이한 팔다리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once attached to a living person, they now belong to something else entirely.", "한때 살아 있는 사람에게 붙어 있었지만 이제는 전혀 다른 것의 일부다.", Language.Korean);
            GrimoraMod.RegisterCard("Possessed Limbs", "기이한 팔다리");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mole Digger", "무덤 파는 두더지", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stalwart Mole... Digger? Whatever this is...", "굳건한 두더지… 무덤 파는 자? 이게 뭐든 간에…", Language.Korean);
            GrimoraMod.RegisterCard("Mole Digger", "무덤 파는 두더지");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros", "네크로스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros possesses the board, challenger. Death is his playground.", "네크로스가 보드를 지배한다, 도전자여. 죽음은 그의 놀이터다.", Language.Korean);
            GrimoraMod.RegisterCard("Nekros", "네크로스");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NekrosPrime", "네크로스 프라임", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will find no greater power... than the simple thought of your own name... inscrybed upon a grave.", "더 큰 힘은 찾을 수 없으리라… 자신의 이름이… 묘비에 새겨진다는 생각보다 강한 힘은.", Language.Korean);
            GrimoraMod.RegisterCard("NekrosPrime", "네크로스 프라임");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nuckelavee", "누켈라비", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Administrator of its sea, you better hope it's breath doesn't taint your Thralls!", "바다의 관리자. 그 숨결이 당신의 노예들을 더럽히지 않기를 바라는 게 좋을 것이다!", Language.Korean);
            GrimoraMod.RegisterCard("Nuckelavee", "누켈라비");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OdiousMass", "추악한 거체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How unsightly.", "정말 흉측하군.", Language.Korean);
            GrimoraMod.RegisterCard("OdiousMass", "추악한 거체");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochi", "야마타노오로치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "희생이 필요하다.", Language.Korean);
            GrimoraMod.RegisterCard("Orochi", "야마타노오로치");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Ouro", "마스터 오우로", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "From within the endless torment and suffering, they had somehow learned a way to see inside this poor broken thing... and take away its pain.", "끝없는 고통과 괴로움 속에서 그들은 어떻게든 이 불쌍하고 부서진 것의 속을 들여다보는 방법을 찾았다… 그리고 고통을 없애 주었다.", Language.Korean);
            GrimoraMod.RegisterCard("Master Ouro", "마스터 오우로");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An endless cycle of life and death has taken a toll on these discarded remains. The pain was real, but death is never final!", "끝없는 삶과 죽음의 순환이 버려진 이 잔해들을 지치게 했다. 고통은 진짜였지만 죽음은 결코 끝이 아니다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GanCeann", "듀라한", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Countless legends tell of the dullahan, but all fail to convey the true extent of its pique.", "듀라한에 관한 전설은 무수하지만 그 분노가 얼마나 큰지 제대로 전하는 것은 없다.", Language.Korean);
            GrimoraMod.RegisterCard("GanCeann", "듀라한");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dark Prince", "어둠의 왕자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of fluffy bois shines within you.", "복슬복슬한 녀석들의 힘이 당신 안에서 빛난다.", Language.Korean);
            GrimoraMod.RegisterCard("Dark Prince", "어둠의 왕자");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stillborn Raven", "요절한 까마귀 영혼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feels good to be young again!", "다시 젊어지니 좋군!", Language.Korean);
            GrimoraMod.RegisterCard("Stillborn Raven", "요절한 까마귀 영혼");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reanimated", "되살아난 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRINGING THE SCYTHE OF DEATH, THE REVENANT... WAIT, WHAT?", "죽음의 낫을 들고 오는 망령… 잠깐, 뭐라고?", Language.Korean);
            GrimoraMod.RegisterCard("Reanimated", "되살아난 자");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RevenantEldritch", "되살아난 이형", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The source of Calamity, relentless and unerring.", "재앙의 근원. 끈질기고 빗나가는 법이 없다.", Language.Korean);
            GrimoraMod.RegisterCard("RevenantEldritch", "되살아난 이형");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Bones", "게으른 뼈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slothful skeleton with a knack for jokes. I adore him.", "농담에 재주가 있는 게으른 해골. 나는 그가 아주 좋다.", Language.Korean);
            GrimoraMod.RegisterCard("Lazy Bones", "게으른 뼈");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelephone", "해골 축음기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A way to communicate with the dead, for a price.", "죽은 자와 대화하는 방법. 대가는 필요하다.", Language.Korean);
            GrimoraMod.RegisterCard("Skelephone", "해골 축음기");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "영혼 영역의 문", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A chance to enter the soul realm, how delightful? I hope you can afford the price.", "영혼의 영역에 들어갈 기회라니, 얼마나 즐거운가? 대가를 치를 수 있기를 바란다.", Language.Korean);
            GrimoraMod.RegisterCard("Soulgate", "영혼 영역의 문");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SpadeWarrior", "스페이드 전사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This fearsome warrior will put you six feet under, in every possible sense.", "이 무시무시한 전사는 모든 의미에서 당신을 땅속 깊이 묻을 것이다.", Language.Korean);
            GrimoraMod.RegisterCard("SpadeWarrior", "스페이드 전사");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadCivilian", "불사의 시민", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lost in eternal darkness, this poor soul desperately seeks a way out. Perhaps you can light his way?", "영원한 어둠에 갇힌 불쌍한 영혼이 필사적으로 출구를 찾는다. 당신이 그의 길을 밝혀 줄 수 있을까?", Language.Korean);
            GrimoraMod.RegisterCard("UndeadCivilian", "불사의 시민");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadVillage", "망자를 묻는 마을", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abandoned and forlorn, this village seeks new residents to fill its decrepit homes.", "버려지고 황량한 마을. 낡은 집들을 채울 새 주민을 찾는다.", Language.Korean);
            GrimoraMod.RegisterCard("UndeadVillage", "망자를 묻는 마을");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In every town, in every city, someone must work to bury the dead. In time, they too will be buried.", "모든 마을과 도시에는 죽은 자를 묻는 사람이 있다. 언젠가는 그들도 묻힐 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr.Bones", "본즈 박사", Language.Korean);
            GrimoraMod.RegisterCard("Dr.Bones", "본즈 박사");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whatever doesn't kill you simply makes you, saner.", "너를 죽이지 못하는 것은 너를 더 제정신으로 만들 뿐이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wendigo", "웬디고", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Returned from the deep wilds, reminds me of a friend.", "깊은 야생에서 돌아왔다. 친구가 떠오르는군.", Language.Korean);
            GrimoraMod.RegisterCard("Wendigo", "웬디고");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mister Win", "미스터 윈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card that wins. It always wins. That's why it's called Mister Win.", "이기는 카드. 언제나 이긴다. 그래서 미스터 윈이라고 부른다.", Language.Korean);
            GrimoraMod.RegisterCard("Mister Win", "미스터 윈");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not that one, I'm afraid.", "유감이지만 그건 아니다.", Language.Korean);

            // Dlg
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You... you murderous monster.", "너… 이 살인 괴물.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh Dear... The flow of Calamity will pursue you.", "이런… 재앙의 흐름이 당신을 쫓을 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hecatomb the village you once lived.", "한때 살았던 마을을 피로 물들여라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seak for the shovel that digs forever.", "영원히 땅을 파는 삽을 찾아라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bring me the lost one with a spark in hand.", "손에 불꽃을 쥔 길 잃은 자를 내게 데려와라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compelled by the beckoning of an ancient entity,", "고대 존재의 부름에 이끌려", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a forbidden ritual has been initiated.", "금지된 의식이 시작되었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The pain reaches the ancient great serpent of death.", "고통이 고대의 거대한 죽음의 뱀에게 닿는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "희생이 필요하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... There are no dead cards yet.", "아… 아직 죽은 카드가 없다.", Language.Korean);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant Mod Card Pack", "망령 모드 카드팩", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack consists of mainly cards that return to the player in a variety of ways.", "다양한 방식으로 플레이어의 패에 돌아오는 카드를 주로 담은 카드팩.", Language.Korean);
        }
    }
    public class SquirrelBombMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SquirrelBombMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis", "피피스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis.", "피피스.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Help", "도움", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn [creature] will sacrifice itself to heal the adjacent cards by 1.", "주인의 턴이 끝날 때 [creature]이(가) 자신을 희생해 인접한 카드의 체력을 1 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pass-through", "통과", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is about to get attacked by a card with an attack higher than this card's health, this card perishes.", "[creature]이(가) 이 카드의 체력보다 공격력이 높은 카드에 공격받기 직전, 이 카드는 사망한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Call", "스팸 전화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empty spaces within a circuit completed by [creature] spawn Spam Mail at the end of the owner's turn.", "주인의 턴이 끝날 때 [creature]이(가) 완성한 회로 안의 빈칸에 스팸 메일이 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEO Strike", "NEO 타격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space that is occupied by a creature and additionally every side of the board occupied by a creature. It will strike directly if no creatures oppose it.", "[creature]이(가) 공격할 때 상대 보드의 왼쪽과 오른쪽 절반에 직접 공격을 막는 피조물이 있으면 해당 절반의 두 칸을 공격하고, 그런 피조물마다 추가 공격한다. 막는 피조물이 없으면 중앙 두 칸을 직접 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Call for Help", "도움 요청", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will call for help.", "주인의 턴이 끝날 때 [creature]이(가) 도움을 요청한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Run Forth", "전진", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before [creature] attacks, its power will be set to at least 1.", "[creature]이(가) 공격하기 전에 공격력이 최소 1로 설정된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying Head", "날아다니는 머리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most important part.", "가장 중요한 부분.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Cart", "스팸 카트", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with spam mail. Absorbs all kinds of attacks.", "스팸 메일로 가득하다. 모든 종류의 공격을 흡수한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Mail", "스팸 메일", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Has all kinds of unforgettable deals.", "온갖 잊지 못할 특가 상품이 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Shooter", "빅 슈터", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoots big shots.", "커다란 탄환을 쏜다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart on a Chain", "사슬에 묶인 심장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beautiful.", "아름답다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spamgel", "스팸젤", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The result of pressing F1.", "F1을 누른 결과.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand Phone", "휴대 전화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you really need anyone else?", "정말 다른 사람이 더 필요한가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE POWER OF NEO!!!", "NEO의 힘!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you wanna be a big shot?", "거물이 되고 싶지 않아?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Receiver", "수신기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voice runs out eventually.", "목소리는 언젠가 사라진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis", "회색곰 할인권", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis.", "회색곰 할인권.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Cart", "곰 카트", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with bears. Absorbs all kinds of attacks.", "곰으로 가득하다. 모든 종류의 공격을 흡수한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Mail", "곰 메일", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mail for bears.", "곰에게 보내는 메일.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear on a Chain", "사슬에 묶인 곰", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Hand", "곰 손", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Bomb", "다람쥐 폭탄", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrels explode when killed, dealing 10 damage to adjacent cards.", "다람쥐는 죽으면 폭발해 인접한 카드에 피해 10을 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance Party", "댄스 파티", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your cards move each turn. The cards that can't move die.", "당신의 카드가 매 턴 이동한다. 이동할 수 없는 카드는 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Again", "다시 한번", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All opponent cards attack twice.", "상대의 모든 카드가 두 번 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starving", "굶주림", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pray.", "기도하라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogfish", "곱상어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each battle starts with a Bait Bucket that has Guardian.", "매 전투 시작 시 상대 측에 빈칸이 있으면 수호자 도장을 지닌 미끼 양동이가 나타난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Totems", "구타유발자 토템", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with an Annoying totem for your most used tribe.", "매 전투 시작 시 가장 많이 사용한 부족에 구타유발자 토템이 생긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Draws", "고통스러운 드로우", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the main deck deals 1 damage.", "주 덱에서 카드를 뽑으면 피해 1을 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Squirrels", "고통스러운 다람쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the side deck deals 1 damage.", "보조 덱에서 카드를 뽑으면 피해 1을 받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Runes", "룬", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enemy cards of the dominant tribe get random sigils.", "주요 부족의 적 카드가 무작위 도장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dentistry", "치과 치료", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Item events and Trinket Bearer cards only give pliers.", "아이템 이벤트와 싸구려 장신구 카드에서는 펜치만 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archived", "보관됨", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A random card choice is hidden in every card choice event.", "카드 선택 이벤트마다 무작위 카드 선택지 하나가 숨겨진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foundation", "기초", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards have 1 less attack. Side deck cards have Leader.", "당신의 카드가 공격력이 0보다 크면 공격력이 1 감소한다. 보조 덱의 카드는 리더를 지닌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Boss v2", "최종 보스 v2", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Replaces Leshy as the final boss with a true BIG SHOT.", "진정한 거물이 레쉬를 대신해 최종 보스로 등장한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must dance! Don't stop dancing!!", "춤춰야 해! 춤을 멈추지 마!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whoever stops dancing at my party will suffer the consequences.", "내 파티에서 춤을 멈추는 자는 그 대가를 치를 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is that mechanic annoying?", "그 방식이 성가신가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect. That's the point of it.", "좋아. 바로 그게 목적이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance my puppet! Daaaance.", "춤춰라, 내 꼭두각시! 춤추라고오.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need to pass, remember?", "통과해야 한다는 걸 기억하지?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M [_spamton_0,STEALING] YOUR KROMER", "네 크로머를 [_spamton_0,훔치고] 있다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOLY [_spamton_0,CUNGADERO] DO I FEEL GOOD", "맙소사 [_spamton_0,세상에] 기분이 너무 좋다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HERE I AM!!!", "내가 왔다!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BIG", "거대한", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<size=10>BIG!!!</size>", "<size=10>크다!!!</size>", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<size=15>[_spamton_0,BIGGER AND BETTER THAN EVER]</size>", "<size=15>[_spamton_0,그 어느 때보다 크고 좋아졌다]</size>", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AND NOW THAT I'M IN THIS [_spamton_0,GAME OF CARDS]", "이제 내가 이 [_spamton_0,카드 게임]에 들어왔으니", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I CAN'T BE DEFEATED!!!", "날 이길 수는 없다!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO GET [_spamton_0,ABSOLUTELY OBLITERATED] BY [_spamton_0,THE POWER OF NEO]!!!", "[_spamton_0,NEO의 힘]에 [_spamton_0,완전히 박살 날] 준비나 해라!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,THIS] AGAIN???", "또 [_spamton_0,이거]냐???", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO GET [_spamton_0,DESTROYED]!!!", "[_spamton_0,파괴당할] 준비나 해라!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU WON'T STAND A CHANGE, YOU [_spamton_0,LITTLE RING WORM]!!!", "넌 승산이 없어, 이 [_spamton_0,작은 버짐벌레]야!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO [_spamton_0,GET PUNCHED] IN YOUR [_spamton_0,FACE]!!!", "네 [_spamton_0,얼굴]에 [_spamton_0,주먹을 맞을] 준비나 해라!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEHOLED [_spamton_0,ME]!!! BEHOLD [_spamton_0,YOU]!!!", "[_spamton_0,나]를 봐라!!! [_spamton_0,너]를 봐라!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,HYPERLINK BLOCKED]", "[_spamton_0,하이퍼링크 차단됨]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ISN'T THIS BODY JUST [_spamton_0,HEAVEN]LY?", "이 몸은 마치 [_spamton_0,천국] 같지 않나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "2X THE [_spamton_0,FIRE]POWER", "[_spamton_0,화력] 2배", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "3X THE [_spamton_0,WATER]POWER", "[_spamton_0,수력] 3배", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AND MOST IMPORTANTLY", "그리고 가장 중요한 것은", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FLYING HEADS!!!", "날아다니는 머리다!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WE'LL TURN THOSE [_spamton_0,SCHMOES] AND [_spamton_0,DAVES]", "저 [_spamton_0,멍청이들]과 [_spamton_0,얼간이들]을", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INTO [_spamton_0,ROSEN GRAVES]", "[_spamton_0,장미 무덤]으로 바꾸겠다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOSE [_spamton_0,CATHODE SCREENS]", "저 [_spamton_0,브라운관 화면]을", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INTO [_spamton_0,CATHODE SCREAMS]", "[_spamton_0,브라운관 비명]으로 바꾸겠다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA BE [_spamton_0,PART] OF MY BEAUTIFUL [_spamton_0,HEART]?!", "내 아름다운 [_spamton_0,심장]의 [_spamton_0,일부]가 되고 싶지 않나?!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OR... DID YOU NEED A LITTLE [_spamton_0,SPECIL TOUR]?", "아니면… 짧은 [_spamton_0,특별 투어]가 필요한가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHAT]?!", "[_spamton_0,뭐]?!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU [_spamton_0,STOLE] MY [_spamton_0,HEART]?", "내 [_spamton_0,심장]을 [_spamton_0,훔쳤다고]?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CAN'T BE [_spamton_0,STEALING] MY [_spamton_0,HEART], IT IS MY [_spamton_0,HEART]!", "내 [_spamton_0,심장]을 [_spamton_0,훔치면] 안 돼. 그건 내 [_spamton_0,심장]이야!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP [_spamton_0,STEALING] MY HEART YOU [_spamton_0,!@#$]", "내 심장을 [_spamton_0,훔치는] 걸 멈춰라, 이 [_spamton_0,!@#$]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "O U C [_spamton_0,HYPERLINK BLOCKED]", "아 야 [_spamton_0,하이퍼링크 차단됨]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU JUST [_spamton_0,BROKE] MY [_spamton_0,$4.99] HEART", "네가 내 [_spamton_0,$4.99]짜리 심장을 [_spamton_0,부쉈다]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO YOU KNOW THAT IT [_spamton_0,HURTS] WHEN YOU [_spamton_0,DO] THAT?!", "네가 그렇게 [_spamton_0,하면] 얼마나 [_spamton_0,아픈지] 아나?!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA HELP YOUR OLD PAL SPAMTON?", "오랜 친구 스팸톤을 돕고 싶지 않나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THINK! WHAT ARE MY [_spamton_0,EGGS] GOING TO DO!?", "생각해 봐! 내 [_spamton_0,알]들은 어떡하라고?!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S CALLING...", "부르고 있다…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY [_spamton_0,HEART]...", "내 [_spamton_0,심장]…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY [_spamton_0,HANDS]...", "내 [_spamton_0,손]…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOOK AT THE [_spamton_0,POWER OF NEO] AND ASK YOURSELF...", "[_spamton_0,NEO의 힘]을 보고 스스로에게 물어봐라…", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU?", "그러고 싶지 않나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA BE A [_spamton_0,BIG SHOT]!?", "[_spamton_0,거물]이 되고 싶지 않나?!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY ESTEEM CUSTOMER I SEE YOU ARE ATTEMPTING TO DEPLETE MY HP!", "존경하는 고객님, 내 HP를 바닥내려는 게 보이는군!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'LL ADMIT YOU'VE GOT SOME [_spamton_0,GUTS]!", "네게 [_spamton_0,배짱]이 있다는 건 인정하지!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BUT IN A [_spamton_0,1 FOR 1] BATTLE, NEO NEVER LOSES!!!", "하지만 [_spamton_0,1 대 1] 전투에서 NEO는 지지 않는다!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S TIME FOR A LITTLE [_spamton_0,BLUELIGHT SPECIL]", "이제 [_spamton_0,블루라이트 특가] 시간이다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARE YOU [_spamton_0,SURPRISED] THAT YOU CAN'T JUST [_spamton_0,DESTROY] ME WITH YOUR [_spamton_0,PATHETIC LITTLE] [_spamton_0,CARDS]?", "네 [_spamton_0,한심하고 작은] [_spamton_0,카드]로 나를 [_spamton_0,파괴]할 수 없어서 [_spamton_0,놀랐나]?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DIDN'T YOU KNOW [_spamton_0,NEO] IS FAMOUS FOR ITS HIGH DEFENSE!?", "[_spamton_0,NEO]가 높은 방어력으로 유명하다는 걸 몰랐나?!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOW... ENJ0Y THE FIR3WORKS!!!", "자… 불꽃놀이를 즐겨라!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ENJOY THE FIREWORKS!!!!", "불꽃놀이를 즐겨라!!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT?", "뭐?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHO] ARE YOU TRYING TO [_spamton_0,CALL]???", "대체 [_spamton_0,누구]에게 [_spamton_0,전화]하려는 거냐???", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE NO [_spamton_0,FRIENDS] IN THIS [_spamton_0,WORLD]!!!", "이 [_spamton_0,세계]에 네 [_spamton_0,친구]는 없다!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY'RE ALL [_spamton_0,PAPER CARDS]!!!", "모두 [_spamton_0,종이 카드]일 뿐이다!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHO'RE YOU GONNA CALL, THE [_spamton_0,POLICE]?", "[_spamton_0,경찰]이라도 부르려고?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU'RE [_spamton_0,PATHETIC]!!", "정말 [_spamton_0,한심하군]!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,SCREAMING] FOR [_spamton_0,HELP] [_spamton_0,AT THE BOTTOM OF A DUMPSTER]!!!", "[_spamton_0,쓰레기통 바닥에서] [_spamton_0,도움]을 청하며 [_spamton_0,비명을 지르는군]!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE'S NO [_spamton_0,HELP] FOR YOU!!!", "널 [_spamton_0,도울] 사람은 없다!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR [_spamton_0,VOICE] IS GOING TO RUN OUT EVENTUALLY!!", "네 [_spamton_0,목소리]도 언젠가 다할 거다!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GIVE UP!!!", "포기해라!!!", Language.Korean);
