            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I AM UNSTOPPABLE!!!", "나를 막을 수는 없다!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR [_spamton_0,FREE TRIAL OF] LIFE IS ABOUT TO [_spamton_0,EXPIRE]!!!", "네 인생의 [_spamton_0,무료 체험]이 곧 [_spamton_0,만료된다]!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,GOOBERT]?", "[_spamton_0,구버트]?", Language.Korean);
