            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HA! I'M NOT EVEN SURE THAT HE IS [_spamton_0,ALIVE AND WELL]!!!", "하! 그가 아직 [_spamton_0,멀쩡히 살아 있는지]도 모르겠군!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_1,ROYAL]?", "[_spamton_1,로얄]?", Language.Korean);
