            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE'S NO WAY A [_spamton_0,SHIP] COULD FIT IN THIS LITTLE [_spamton_0,CABIN FOR SALE]", "[_spamton_0,배]가 이 작은 [_spamton_0,판매 중인 오두막]에 들어올 리 없어", Language.Korean);
