            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "diseased airborne dragon", "역병 공중 비룡", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's become an unholy nightmare", "불경한 악몽이 되어 버렸군", Language.Korean);
