            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the flesh idol, worshiped by those who are truly insane", "살점 우상. 완전히 미친 자들이 숭배한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Great Sap, usefull past the card", "거대한 수액. 카드 밖에서도 쓸모가 있다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "hod, the training meltdown", "호드, 교육의 멜트다운", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malkuth, The meltdown of annoying me", "말쿠트, 날 짜증나게 하는 멜트다운", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the mirror of adjustment, some say it leads to another world", "성별 전환 거울. 다른 세상으로 통하는 거울이라는 말도 있다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "netzach, the safety meltdown", "네짜흐, 안전의 멜트다운", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime, heard he trying hard to make this mod good", "슬라임. 이 모드를 잘 만들려고 노력 중이라고 들었다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the band, popular amongst teens", "그 밴드는 청소년들에게 인기가 많다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orchestra", "악단", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bear, it waits to show its true self", "곰은 진정한 모습을 드러낼 때를 기다린다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bloody, seems the blood never ends", "피투성이. 피가 끝없이 흐르는 것 같다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the box, dont stare into the keyhole for to long", "상자. 열쇠 구멍을 너무 오래 들여다보지 마라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The clockwork, the humming of its motors arent the only annoyance it makes", "태엽 장치. 모터의 윙윙거림만이 이 녀석이 일으키는 골칫거리는 아니다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Current, an experiment that has never seen the real world", "흐름. 진짜 세상을 본 적 없는 실험체다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the cute, its looks can melt even the coldest hearts", "귀여운 존재. 그 모습은 가장 차가운 마음도 녹인다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "this one is no longer cute", "이제는 귀엽지 않군", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the dream, a peaceful ram that loves to sleep", "꿈. 잠을 좋아하는 평화로운 숫양이다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "guess its dream came true", "꿈이 이루어진 모양이군", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the exposed, taking the direct approach", "드러난 존재. 정면으로 다가간다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The flower, living and walking on sunshine", "꽃. 햇살을 받으며 살아가고 걷는다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the fragment, the poor creature experimented on into its form", "파편. 불쌍한 피조물은 실험을 당해 이런 모습이 되었다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Happy, calm yet in a state of excietment", "행복. 차분하면서도 흥분한 상태다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the hatefull, innocent mind for what she hides underneath", "증오. 그 아래에 숨겨진 것은 순수한 마음이다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the helper, it just wants to help you out", "도우미. 그저 너를 돕고 싶어 한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the judge, decider of the good and the bad", "심판자. 선과 악을 판정한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the killer, made with intent", "살인자. 의도를 가지고 만들어졌다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the lady, no one knows what she truly looks like", "숙녀. 아무도 그녀의 진짜 모습을 모른다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The little red, hunting the wolf in a game of cat and mouse", "작은 빨간 모자. 쫓고 쫓기는 놀이에서 늑대를 사냥한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mad, its given up on playing nice", "미친 존재. 착한 척하는 건 그만두었다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Many, Containing all the fun of 5 in 1", "다수. 하나에 다섯 가지 재미가 담겨 있다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the masiyah, the prophet that speaks past death", "메시아. 죽음을 넘어 말하는 예언자다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The melting, master of the servants", "녹아내리는 존재. 하수인들의 주인이다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Moral, It Tries but fails to keep balance", "도덕. 균형을 유지하려 하지만 실패한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yin and Yang", "음과 양", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the nameless, abondend and always hungering", "이름 없는 존재. 버려진 채 언제나 굶주려 있다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Neurtal, the only one i can deal with", "중립. 내가 상대할 수 있는 유일한 존재다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Neutral Look", "오늘의 평온한 표정", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the old, no one is here to keep her company", "늙은 존재. 그녀 곁에 있어 줄 이가 없다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the phoenix, its ashes keep it forever alive", "불사조. 재 덕분에 영원히 살아 있다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Plague, its only the beginning", "역병. 이제 시작일 뿐이다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the poisoned, this apple keeps everyone away", "독. 이 사과 때문에 모두가 멀리한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the reindeer, dragging christmas fun all over the world", "순록. 크리스마스의 즐거움을 온 세상으로 끌고 간다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Sad, its destined to never see the light", "슬픔. 결코 빛을 볼 수 없는 운명이다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Today's Sad Look", "오늘의 슬픈 표정", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the sniper, one shot is all it needs", "저격자. 한 발이면 충분하다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the star, the center of both attention and fashion", "스타. 관심과 유행의 중심이다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the swan, its song sound similar to those of the band", "백조. 노래가 그 밴드의 음악과 비슷하게 들린다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The train, best not walk in its way", "열차. 앞길을 막지 않는 편이 좋다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the tree, spreading its roots to help its allies", "나무. 뿌리를 뻗어 아군을 돕는다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the true hatred, seems she let out what she had inside", "진정한 증오. 마음속에 있던 것을 드러낸 모양이다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the wolf, seems cute on first glance", "늑대. 얼핏 보면 귀여워 보인다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the woodsman, sweeping the forest with its axe", "나무꾼. 도끼로 숲을 휩쓴다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Army, they never seem to end", "군대. 끝이 없는 것 같다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've never seen this one here", "이건 여기서 본 적이 없다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The CherryTree, Contains the bodies of thousands", "벚나무. 수천 구의 시체를 품고 있다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Fruit, its ripe for the picking.", "열매. 익어서 따기 좋다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Galaxy, a blessing, and a curse.", "은하. 축복이자 저주다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The greedfull, carefull not to touch it.", "탐욕. 닿지 않도록 조심해라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Hive, The true ruler of the hive", "벌집. 벌집의 진정한 지배자다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Innocent, Ignorant in everything besides pain", "순수. 고통 외에는 아무것도 모른다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mountain, it smiles upon you ", "산. 네게 미소 짓고 있다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Nest, its presence is unsettling  ", "둥지. 그 존재만으로도 불안해진다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Nothing...", "아무것도 없어……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Silent, Performing the best orchestra around.", "침묵. 최고의 관현악을 연주한다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Silent", "침묵", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Swarm, he dresses for the occasion", "무리. 그는 이 자리를 위해 옷을 차려입었다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Trap, So Cute yet so deadly", "덫. 귀엽지만 치명적이다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiphereth, the command meltdown", "티페리트, 지휘의 멜트다운", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Violet Dawn", "보랏빛 새벽", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "violet dawn, radiating the field", "보랏빛 새벽. 전장을 비춘다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "violet Midnight", "보랏빛 자정", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "we tried to accept it,we wanted to understand them", "우리는 그것을 받아들이려 했고, 그들을 이해하고 싶었다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Violet noon", "보랏빛 정오", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "violet noon, enscrybing the words of their gods", "보랏빛 정오. 그들 신의 말씀을 새긴다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that explains the chills", "이제 왜 오싹했는지 알겠군", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the white night, the true end of the world", "백야. 세상의 진정한 끝이다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yesod, the concealing meltdown", "예소드, 은폐의 멜트다운", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Claw", "날카로운 발톱", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you can survive this white midnight.", "이 하얀 자정을 살아남을 수 있기를.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You definitely won't press the button, right?", "버튼을 누르지는 않을 거지?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If it's not voluntary, does anyone really need to be 'fixed'?", "자발적인 게 아니라면 누군가를 정말 '고쳐야' 할까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No one wants to know what truly protects them.", "아무도 자신들을 진정으로 지켜 주는 것이 무엇인지 알고 싶어 하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is currently unclear why such a painting would exist.", "왜 이런 그림이 존재하는지는 아직 알 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gloomy Seahorse", "우울한 해마", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play the fatal movement.", "치명적인 악장을 연주하라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why does the mysterious ray appear within the facility?", "왜 신비로운 가오리가 시설 안에 나타나는 걸까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stingray", "가오리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What sorrow.", "참으로 슬프군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intangible creation.", "형체 없는 창조물이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A scarecrow soaked in fresh blood.", "선혈에 젖은 허수아비다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you yearn for blessings?", "축복을 바라는가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps, she can protect no one.", "어쩌면 그녀는 아무도 지킬 수 없을지도 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mechanical creations, restoring peace and health", "기계 창조물. 평화와 건강을 되찾는다", Language.Korean);

        }
    }
    public class NevernamedsBestiaryMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Nevernameds_Bestiary Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ace Lord", "에이스 영주", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aderyn Y corph", "아데린 이 코르프", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The corpse bird. It's appearance portends the end.", "시체의 새. 나타나면 종말이 다가온 징조다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adipocere", "시랍", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor little corpse wax, it can be molded into any shape you can think of.", "불쌍한 작은 시랍. 생각할 수 있는 어떤 모양으로든 빚을 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It lurks below the water, until the time is ripe to rend the land for prey.", "물 아래 숨어 있다가 때가 되면 땅을 찢고 먹잇감을 잡는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahuizotl", "아우이소틀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Albatross", "알바트로스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The noble albatross. It's vast wingspan creates an impressive downdraft.", "고귀한 알바트로스. 넓은 날개로 강력한 하강기류를 만들어 낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Albatross Chick", "알바트로스 새끼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The young of the immense albatross, it seems almost lost inside of it's own down.", "거대한 알바트로스의 새끼. 자기 솜털에 파묻힐 것만 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gar Roe", "가아 알", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toxic gar roe, will kill anything that swallows it.", "독이 있는 가아 알. 삼키는 것은 무엇이든 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alligator Gar", "앨리게이터가아", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ferocious Alligator Gar. It squirts out it's toxic eggs when frightened.", "사나운 앨리게이터가아. 놀라면 독이 든 알을 뿜는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amorphous Shame", "형체 없는 수치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...such a shame...", "……정말 부끄럽군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anaconda", "아나콘다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't... don't say it. I have heard it all before, and it is not funny.", "말하지…… 말하지 마라. 다 들어 봤고 하나도 재미없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anansi", "아난시", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anansi, the many legged trickster. He attacks multiple times per turn, in flagrant disregard for the rules.", "다리가 많은 속임수꾼 아난시. 규칙을 대놓고 무시하며 매 턴 여러 번 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anchimayen", "안치마옌", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anemone", "말미잘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The soft, unassuming anemone- it seems to have remarkable potential for propagation, but no means as of yet...", "부드럽고 눈에 띄지 않는 말미잘. 번식할 잠재력은 놀랍지만 아직 그럴 방법은 없는 듯하다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angel Shark", "천사상어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Despite the name, it is far from divine.", "이름과 달리 신성함과는 거리가 멀다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That irritating canine...", "저 성가신 개……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anteater", "개미핥기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The slothly anteater only attacks with vigour when presented with a meal.", "게으른 개미핥기는 먹이가 있을 때만 힘차게 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antingaw", "안팅가우", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar mollusk. It gathers sustenance from burrowing into barren rock...", "특이한 연체동물. 메마른 바위를 파고들어 영양분을 얻는다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So small... so fragile...", "너무 작고…… 너무 연약하군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The larvae of the antlion. It's skill for trapping knows no match... in the insect world.", "개미귀신의 유충. 덫을 놓는 솜씨는…… 곤충 세계에서 따라올 자가 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ararach", "아라라크", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The infinilegged crawler, the Ararach never settles on a definitive strategy of attack for long...", "다리가 무수히 많은 기어 다니는 자, 아라라크. 한 가지 공격 전략에 오래 머물지 않는다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The archerfish is quick to retaliate to any confrontation with a precise jet of water.", "물총고기는 누군가 맞서면 정확한 물줄기로 재빨리 반격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Areion", "아레이온", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The eternally running Areion. It loyally moves wherever it's owner demands it in the blink of an eye.", "영원히 달리는 아레이온. 주인이 원하는 곳이라면 어디든 눈 깜짝할 사이에 충실히 움직인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Artful Magister", "기교의 대마법사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspidochelone", "아스피도켈로네", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That ruthless spiny turtle... it shares it's spines with it's comrades..", "그 무자비한 가시 거북…… 동료들에게 가시를 나누어 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automamox", "자동 목스 로봇", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Axehandle Hound", "도끼자루 사냥개", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The peculiar axehandle hound. It uses it's sharp, bladed nose to cut clean through it's foes with the cold precision of a lumberjack...", "특이한 도끼자루 사냥개. 도끼날처럼 날카로운 코로 나무꾼처럼 냉정하고 정확하게 적을 베어 낸다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Axe Murderer", "도끼 살인자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Through night he hunts, in blackened brush, the bite of an axe heralds a blood red stream.", "그는 밤중에 검은 덤불 속에서 사냥한다. 도끼가 물어뜯으면 새빨간 피가 흐른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Babai", "바바이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baboon", "개코원숭이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Far more vicious than its name and appearance would betray- it needs only a reason to strike.", "이름과 겉모습으로 짐작하는 것보다 훨씬 사납다. 공격할 이유만 있으면 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bakunawa", "달을 삼키는 바다뱀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lengthy Bakunawa, terror of the sea and skies.", "길쭉한 달을 삼키는 바다뱀. 바다와 하늘의 공포다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Balaur", "발라우르", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The three-headed Balaur dragon. It lashes out with each of it's maws when threatened.", "머리가 셋 달린 용 발라우르. 위협받으면 입마다 달려든다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bald Eagle", "흰머리수리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Truly the most patriotic of birds.", "참으로 가장 애국적인 새다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ball Droid", "공 로봇", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Balloondroid", "풍선 로봇", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bandito", "도적", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar deathcard- no matter how many times I tear it to pieces, I always find it back in my deck...", "기묘한 죽음 카드. 몇 번이나 찢어 버려도 언제나 덱에서 다시 발견된다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bannana", "바나나", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a small, sweet spider... It couldn't hurt a fl- ...oh", "이렇게 작고 귀여운 거미가…… 파리 한 마리도 해치지 못…… 아.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Barnacle", "따개비", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unimpressive barnacle. Anything that strikes it will be torn to shreds on it's rough shell.", "눈에 띄지 않는 따개비. 녀석을 공격하는 것은 거친 껍데기에 갈기갈기 찢긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Basilisk", "바실리스크", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The grim basilisk. Life withers and dies under it's mere gaze.", "음산한 바실리스크. 눈길만으로 생명이 시들어 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Bat", "불타는 박쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first... and last time one of my... associates attempted to use living organisms to it's own advantage.", "내…… 동료 중 하나가 살아 있는 생물을 이용하려 한 처음이자 마지막 사례다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Batfly", "박쥐파리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The perturbing batfly. It clings to airborne creatures for a free ride.", "불쾌한 박쥐파리. 날아다니는 피조물에 달라붙어 공짜로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bat Tery", "배터리 박쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beached Whale", "좌초된 고래", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The poor thing, completely out of it's element... it bursts upon death.", "불쌍한 녀석. 제 환경을 완전히 벗어났군…… 죽으면 터진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beast Of Exmoor", "엑스무어의 야수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The illusory exmoor cat... hard to catch, harder to kill.", "환상 같은 엑스무어 고양이…… 잡기도 어렵고 죽이기는 더 어렵다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Belladin", "종기사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bellbird", "종새", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their cry is melodic, like the ringing of a great chime.", "그들의 울음소리는 큰 종소리처럼 아름답다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bellbot", "종 로봇", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bhoot", "부트", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How she floats above the holy earth... I wonder what form she will take next!", "성스러운 땅 위에 떠 있는 그녀를 보라…… 다음에는 어떤 모습이 될지 궁금하군!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bind Warden", "결속 감시자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Biscione", "관을 쓴 식인뱀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious biscione, it is insatiable in it's lust for flesh.", "사나운 관을 쓴 식인뱀. 살점에 대한 갈망이 끝이 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bishop", "비숍", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bison", "들소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trampling Bison. It destroys anything in it's path, and becomes more enraged as it becomes more soaked with blood...", "짓밟는 들소. 길에 있는 것은 무엇이든 부수고 피를 뒤집어쓸수록 더욱 분노한다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Dog", "검은 개", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The grim black dog, haunter of graveyards... omen incarnate.", "음산한 검은 개. 묘지를 떠도는…… 불길한 징조의 화신이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Egg", "검은 알", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something pulses dimly, below the surface...", "표면 아래에서 무언가 희미하게 맥동한다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Giant Squirrel", "검은 거대 다람쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The shadowy Black Giant Squirrel. It hits hard and is easily deployed, but perishes with no brothers or sisters by it's side...", "어둠에 싸인 검은 거대 다람쥐. 공격이 강하고 내기 쉽지만 곁에 형제가 없으면 죽는다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Kite", "검은솔개", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It carries the flames of a previous inferno to drive prey from cover...", "이전 화재의 불꽃을 옮겨 먹잇감을 은신처에서 몰아낸다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Black Widow", "검은과부거미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The black widow spider. It's infamous bite kills swiftly.", "검은과부거미. 악명 높은 물기는 순식간에 목숨을 앗아 간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Obelisk", "빈 오벨리스크", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A blank obelisk. Unremarkable.", "빈 오벨리스크. 별다른 특징은 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blast Termite", "폭발 흰개미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disgusting blasting termite. It explodes it's foes upon death.", "끔찍한 폭발 흰개미. 죽으면 적을 폭발시킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind Mouse", "눈먼 쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those blind mice... always travelling in a group. See how they run...", "저 눈먼 쥐들…… 언제나 무리 지어 다닌다. 달리는 모습을 보라……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blind Scorpion", "눈먼 전갈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The poor blinded scorpion. It's venom is immaculate, but it's aim?... less so.", "불쌍한 눈먼 전갈. 독은 완벽하지만 조준은…… 그렇지 않다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloated Leech", "부풀어 오른 거머리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disquieting leech. It has reached full maturity.", "불안한 거머리. 완전히 다 자랐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blockhead", "블록헤드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A comically frontheavy insect.", "앞쪽이 우스울 만큼 무거운 곤충이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodbag", "혈액 주머니", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Cell", "혈구", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Knight", "피의 기사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Red Dog", "붉은 피의 사냥개", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The infamous blood red dog, nothing can stop it's lust for combat. We'll have tea in hell today...", "악명 높은 붉은 피의 사냥개. 싸움에 대한 갈망은 무엇으로도 막을 수 없다. 오늘은 지옥에서 차를 마시자……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloodstopper", "지혈자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Witch", "피의 마녀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bloodstarved beast. It will wither and die if it does not taste violence each turn.", "피에 굶주린 야수. 매 턴 폭력을 맛보지 못하면 시들어 죽는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloody Sack", "피 묻은 자루", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blowfly", "검정파리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disgusting.", "징그럽군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bluebottle", "검정파리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bluebottle... what secrets lie beyond it's squishy facade?", "검정파리…… 물렁한 겉모습 뒤에는 어떤 비밀이 숨어 있을까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue-Ringed", "파란고리문어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Blue-Ringed Octopus. It's venom is one of the most potent in the world...", "파란고리문어. 그 독은 세상에서 가장 강력한 독 중 하나다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue Whale", "흰긴수염고래", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The greatest mortal beast ever to roam the seas... but not the greatest immortal one.", "바다를 누빈 죽을 운명의 야수 중 가장 거대하다…… 하지만 불멸의 야수 중에서는 아니다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BoardWipe", "보드 전멸", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bobbit Worm", "보빗벌레", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The terrifying bobbit worm. It leaps from it's aquatic burrow to attack with it's razor sharp jaws.", "무시무시한 보빗벌레. 물속 굴에서 튀어나와 면도날처럼 날카로운 턱으로 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bobcat", "보브캣", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Often underestimated, the Bobcat will strike the moment it is played.", "자주 과소평가되는 보브캣. 내는 즉시 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Body Snatcher", "신체 강탈자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boil", "종기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A festering little blotch.", "곪아 가는 작은 반점이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bolotnik", "볼로트니크", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bloated swampman. It drags others down to hades- returning for more.", "부풀어 오른 늪 인간. 다른 이들을 저승으로 끌고 간 뒤 더 많은 희생자를 찾아 돌아온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bombardier Beetle", "폭탄먼지벌레", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The incandescant bombardier beetle. It's boiling hot secretions scald it's prey.", "백열하는 폭탄먼지벌레. 끓어오르는 분비물로 먹잇감에 화상을 입힌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Cell", "뼈세포", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Clutter", "뼈 무더기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneworm", "뼈벌레", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The morbid boneworm. It excells in bringing remains to the surface of the churning soil...", "섬뜩한 뼈벌레. 뒤섞이는 흙 위로 유해를 끌어올리는 데 능하다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Booting Bot", "부팅 봇", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bot Printer", "봇 프린터", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bowerbird", "바우어새", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The crafty bowerbird, master of manipulating materials around itself.", "교활한 바우어새. 주변 재료를 다루는 데 능숙하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Box Jelly", "상자해파리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Small, but possessing of a crippling set of stingers.", "작지만 상대를 무력화하는 독침을 지녔다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Proceed", "계속", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brazen Bull", "청동 황소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The horrific brazen bull. A true metric of human depravity.", "끔찍한 청동 황소. 인간이 얼마나 타락했는지 보여 주는 진정한 척도다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's go!", "가자!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play me properly", "나를 제대로 내라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAAH, YES!", "하하하하, 그래!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES, YES!", "그래, 그래!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S MAKE A RING", "만들어 보자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OF FIRE", "불의 고리를", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAH", "하하하하하", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BURN", "연소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I want to", "나는 보고 싶다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "see the fire", "불을", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "for glory!", "영광을 위하여!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yes, very well", "그래, 아주 좋아", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's get to work", "일을 시작하자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHA", "하하하하하", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAHAHAH", "하하하하하하하", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TO GLORY", "영광을 향해", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAHAH", "하하하하하하", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAH, YES!", "하하하, 그래!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IMPROVE ME", "나를 강화해라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can be", "나는 될 수 있다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So much more!", "훨씬 더 대단하게!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you want.", "네가 원한다면.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SACRIFICE ME!", "나를 희생해라!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES", "그래", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WILL DIE", "나는 죽겠다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FOR YOU", "너를 위해", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's up to you", "네게 달렸다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harder!", "더 세게!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO IT!", "해라!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAHAHAHAHAHA!", "하하하하하하!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES! MORE!", "그래! 더 해라!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Very good.", "아주 좋아.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANK YOU, THANK YOU!", "고맙다, 고맙다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VICTORY?", "승리인가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TO GLORY!", "영광을 위하여!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YES, YES", "그래, 그래", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brine Shrimp", "브라인슈림프", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tiny, fleeting brine shrimp, so small it's as if it's not even there...", "작고 덧없는 브라인슈림프. 너무 작아서 없는 것만 같다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brollachan", "브롤라한", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wicked Brollachan. It can take many powerful forms...", "사악한 브롤라한. 여러 강력한 모습으로 변할 수 있다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brown Recluse", "갈색은둔거미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unassuming Brown Recluse. It attacks when threatened.", "눈에 띄지 않는 갈색은둔거미. 위협받으면 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Budgerigar", "사랑앵무", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A friendly bird of domesticated breed, the Budgerigar will follow your command...", "친근한 사육종 새인 사랑앵무. 네 명령을 따른다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bugbear", "곰벌레", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The horrifying Bugbear. No creatures wish to remain in it's presence.", "무시무시한 곰벌레. 어떤 피조물도 그 곁에 머물고 싶어 하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Busted Bot", "폐기된 봇", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Busted Conduit", "폐기된 전도체", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buzzard", "말똥가리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The shameless buzzard- an inescapable symbol of death in the sands.", "뻔뻔한 말똥가리. 모래밭에서 피할 수 없는 죽음의 상징이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiny Ant", "가시개미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A friendly ant covered in sharp thorns.", "날카로운 가시로 덮인 친근한 개미다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The splifficated Cactus Cat, it roams the desert drinking the fermented juice of it's lookalike plant...", "술에 취한 선인장 고양이. 사막을 돌아다니며 자신을 닮은 식물의 발효된 즙을 마신다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caged Beasts", "우리 안의 야수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor, caged animals. Won't you set them free?", "가엾게 갇힌 동물들. 풀어 주지 않겠나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calygreyhound", "칼리그레이하운드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The calygreyhound- a confusing chimeric clash which nonetheless stirs the loyalties of it's comrades.", "칼리그레이하운드. 여러 모습이 뒤섞여 혼란스럽지만 동료들의 충성심을 불러일으킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camazotz", "카마소츠", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camazotz, the bat god. He flies low amongst his enemies, slashing them with his bloodstained claws.", "박쥐의 신 카마소츠. 적들 사이를 낮게 날며 피 묻은 발톱으로 적을 벤다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cam Drone", "카메라 드론", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stocky camel, it is resilient against most any threat", "다부진 낙타. 거의 모든 위협에 견딜 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camel Spider", "낙타거미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Camel Spider... an unpleasant arachnid to even gaze upon.", "낙타거미…… 보기만 해도 불쾌한 거미류다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candiru", "칸디루", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bloodsucking fish with a terrifying reputation.", "무시무시한 평판을 지닌 흡혈 물고기다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Canopic Hawk", "카노푸스의 매", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A delicate ceramic bird, full of guts...", "내장으로 가득 찬 섬세한 도자기 새……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The much-beloved Capybara... it's fighting spirit is closely tied to it's wellbeing.", "많은 사랑을 받는 카피바라…… 투지는 건강 상태와 밀접하게 연결되어 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caracal", "카라칼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A quizzacious predator, ready to leap at any unsuspecting prey.", "호기심 많은 포식자. 방심한 먹잇감이라면 언제든 덮칠 준비가 되어 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carrion Fly", "썩은고기파리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The disgusting carrion fly. Drawn to death.", "역겨운 썩은고기파리. 죽음에 이끌린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catalogue Keeper", "목록 관리자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catron", "카트론", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cattle Rustler", "소도둑", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cellar Spider", "유령거미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Cellar spider. An exemplar of all arachnida.", "유령거미. 거미류의 모범이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chameleon", "카멜레온", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A chameleon always changes it's spots, as is the proverb.", "속담처럼 카멜레온은 언제나 무늬를 바꾼다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enraged Fey", "분노한 요정", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The development of the changeling is entirely dependant on it's early childhood... violence begets violence.", "바꿔치기 아이의 성장은 어린 시절에 전적으로 달렸다…… 폭력은 폭력을 낳는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pitiful Fey", "불쌍한 요정", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Changeling", "바꿔치기 아이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Card", "혼돈 카드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Engine", "혼돈 엔진", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charred Lump", "검게 탄 덩어리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charybdis", "카리브디스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Charybdis, the infernal vortex. Sucks all around it into it's collossal maw.", "지옥의 소용돌이 카리브디스. 주변의 모든 것을 거대한 입으로 빨아들인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A vindictive, nasty little bird.", "앙심을 품는 못된 작은 새다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chicken Bones", "닭뼈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awfully sharp... and awfully disposable.", "끔찍하게 날카롭고…… 끔찍하게 쓰고 버리기 쉽다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chimpanzee", "침팬지", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The true utility of the chimp lies in it's dilligent hands...", "침팬지의 진정한 쓸모는 부지런한 두 손에 있다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chiral Crawler", "키랄 크롤러", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can a creature that drags its shackles along with it ever truly be free?", "족쇄를 끌고 다니는 피조물이 정말 자유로울 수 있을까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chochin", "초롱 요괴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aha! The little lantern spook, such a mischevious little spirit it is!", "아하! 작은 등불 유령. 정말 짓궂은 영체로군!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chuman", "츄먼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unholy union.", "불경한 결합이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This beast of the night will tear apart any small prey he finds...", "이 밤의 야수는 발견한 작은 먹잇감은 무엇이든 찢어 버린다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clanklion", "클랭크라이언", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clumsy Pupil", "서투른 제자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cobra", "코브라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift cobra. Usually passive, but it delivers a nasty bite when startled.", "재빠른 코브라. 보통은 온순하지만 놀라면 지독하게 문다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cockle", "새조개", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unremarkable cockle, it feeds upon the remnants of the dead...", "눈에 띄지 않는 새조개. 죽은 자의 잔해를 먹는다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Code Thief", "코드 도둑", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coinchenn", "코인헨", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It lurks in the shadows of history, and shows no mercy to its prey.", "역사의 그림자에 숨어 먹잇감에게 자비를 베풀지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Colossal Squid", "대왕오징어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The colossal squid. It drags it's foes down to a watery grave.", "대왕오징어. 적을 물속 무덤으로 끌고 간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tubular Bells", "관종", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cone Snail", "청자고둥", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The venomous cone snail. Beware it's paralysing toxin.", "독을 지닌 청자고둥. 몸을 마비시키는 독을 조심하라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conjurer", "소환술사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Copepod", "요각류", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unassuming copepod, resilient to the last.", "눈에 띄지 않는 요각류. 마지막까지 끈질기다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mysterious copycat. When it perishes, it... warps, to mimic it's murderer.", "신비로운 모방자. 죽으면…… 뒤틀려 자신을 죽인 자를 흉내 낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coral", "산호", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A stoic coral colony, akin more to the landscape around it than to any other beast...", "묵묵한 산호 군체. 다른 야수보다 주변 풍경에 더 가깝다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counstabot", "경찰 봇", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cow", "소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Centuries of domestication have not made it any less stubborn...", "수 세기의 가축화에도 고집은 줄어들지 않았다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cowardly lion. It attempts to live up to the ferocity of it's cousins, but with little success.", "겁쟁이 사자. 친척들처럼 사나워지려 애쓰지만 별 성과는 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowardly Lion", "겁쟁이 사자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowbird", "찌르레기사촌", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Too cowardly to remain for long, the cowbird is always eager to cause trouble.", "찌르레기사촌은 겁이 많아 오래 머물지 못하면서도 언제나 말썽을 부리려 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time for crab.", "게의 시간이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crab Spider", "게거미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hardy crab spider, it clings relentlessly to any source of food or warmth.", "튼튼한 게거미. 먹이나 열원이라면 무엇이든 끈질기게 달라붙는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crayfish", "민물가재", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The unrelenting crayfish. It changes the orientation of it's claws each turn.", "끈질긴 민물가재. 매 턴 집게의 방향을 바꾼다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cremator", "소각자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crimson Paladin", "진홍색 성기사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crooked Mouse", "뒤틀린 쥐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was never the same after a run in with a crooked cat...", "뒤틀린 고양이와 마주친 뒤로 예전 같지 않다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crooked Wraith", "뒤틀린 음령", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A strange one, this. Even I don't know its twisted past.", "기이한 녀석이다. 나조차 그 뒤틀린 과거를 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crucibulum", "십자잔버섯", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiar little snail, forever growing it's conical shell.", "특이한 작은 달팽이. 원뿔형 껍데기가 영원히 자란다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Healer", "수정 치유사", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cubit", "큐빗", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curly-Legged Cat", "말린 다리 고양이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its twisted legs coil and bend in ways inexplicable. It is full of potential.", "뒤틀린 다리는 이해하기 어려운 방식으로 말리고 구부러진다. 잠재력이 가득하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curruid", "쿠루드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clawed lord of the waves, the Curruid has but one blind spot.", "발톱 달린 파도의 영주 쿠루드. 사각지대는 단 하나다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Child", "저주받은 아이", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That... should not be in my deck...", "저건…… 내 덱에 있으면 안 되는데……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Stunted... Wolf... I thought I threw him- ...I mean, this, away...", "저…… 발육부진 늑대…… 그를 버렸다고…… 아니, 이걸 버렸다고 생각했는데……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The... stoat. Did I leave this here?", "저…… 담비. 내가 여기에 두고 갔던가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The... pungent... stinkbug?..", "저…… 냄새나는…… 방귀벌레?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cyclops", "외눈박이 거인", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The diminutive cyclops. It's great eye holds a perfect image of the past.", "작은 외눈박이 거인. 거대한 눈에 과거의 완벽한 모습이 담겨 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aim well.", "잘 조준해라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoot with caution.", "신중하게 쏴라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aim me well.", "나로 잘 조준해라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acceptable draw.", "괜찮은 뽑기군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Survive.", "살아남아라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am your instrument.", "나는 네 도구다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will succeed.", "나는 성공할 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you are", "네가", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "certain.", "확신한다면.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I trust", "나는 믿는다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bigger", "더 큰", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "picture.", "그림을.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Over exposed.", "너무 노출됐다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This turn?", "이번 턴인가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temporal Misplay.", "시간을 잘못 맞췄군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember this.", "이것을 기억해라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Certainly.", "물론이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have", "너는", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "aimed... well.", "제대로…… 조준했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Within acceptable", "허용할 수 있는", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "parameters.", "범위다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Betrayal.", "배신.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Judas.", "유다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once more?", "한 번 더?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How many times...", "몇 번이나……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acceptable.", "허용할 만하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Modification.", "개조.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is desirable.", "바람직하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Picturesque.", "그림 같군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Regards.", "안부를 전한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undesirable.", "바람직하지 않다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cease.", "그만둬라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is unfriendly.", "우호적이지 않군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cease considerations.", "고민을 멈춰라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Halt.", "멈춰라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have been...", "나는……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...dealt a blow", "……일격을 당했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...a blow", "……일격을", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suffered.", "당했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Assessing damages.", "피해를 평가 중이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dealt a blow...", "일격을 당했다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So... familiar...", "너무…… 익숙해……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is unfortunate", "안타깝게도", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "that we must", "우리는", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "trade blows...", "서로 싸워야 한다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel... kinship.", "동질감이…… 느껴진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am improved.", "나는 강화되었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Improvement", "강화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Edit in progress.", "편집 중이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A new instrument.", "새로운 도구다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Under analysis", "분석 중", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "statistically viable", "통계적으로 실행 가능", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A lineup?", "진형인가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Darter", "뱀목가마우지", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mind the splash.", "물보라를 조심해라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "\"When the Lamb broke the fourth seal, I heard the voice of the fourth living creature saying, \"Come.\" I looked, and behold, an ashen horse; and he who sat on it had the name Death; and Hades was following with him.\"", "“어린양이 넷째 봉인을 떼었을 때, 나는 넷째 생물이 ‘오라’고 말하는 소리를 들었다. 보라, 잿빛 말이 있었다. 그 위에 탄 자의 이름은 죽음이었고, 저승이 그 뒤를 따랐다.”", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death", "죽음", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deaths Door", "죽음의 문", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't worry, we'll pull you through.", "걱정 마라. 우리가 헤쳐 나가도록 돕겠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deathstalker", "데스스토커", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The deathstalker scorpion. It's tail packs a potent venom.", "데스스토커. 꼬리에 강력한 독이 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "De Bug", "디버그", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What... is that?", "저건…… 뭐지?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Decorator Crab", "장식게", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The lowly decorator crab. It scrounges the bottom of the ocean for detritus to stick to it's body.", "보잘것없는 장식게. 바닷바닥에서 부스러기를 찾아 몸에 붙인다.", Language.Korean);


        }
    }
    public class NeedMoreWaterMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for NeedMoreWater Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack:NMW", "카드 팩: NMW", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cardumen", "물고기 떼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cuando una carta que lleve este sello mate a otra criatura en combate, se crea una copia de esa carta en tu mano.", "이 도장을 지닌 카드가 전투 중 다른 피조물을 죽이면, 도장을 지닌 카드 자신의 사본 한 장이 패에 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rape", "아귀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Engañoso y altamente peligroso ese Rape.", "저 아귀는 교활하고 아주 위험하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "La sangre derramada las atrae...", "흘린 피가 그것들을 끌어들인다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Arquero", "물총고기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Su disparo de agua derriba a los insectos para comérselos.", "물줄기를 쏴 곤충을 떨어뜨린 다음 잡아먹는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Beta", "베타", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El Pez Beta. Una belleza viva de las aguas.", "베타. 물속에 살아 있는 아름다움이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Gato", "메기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El Pez Gato. Nunca te faltarán cebos.", "메기. 미끼가 모자랄 일이 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cocodrilo", "악어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cocodrilo, gran cazador. Ningún nadador escapa de sus fauces.", "악어는 훌륭한 사냥꾼이다. 그 아가리에서 벗어날 수 있는 수영자는 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morena", "곰치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acecha entre las grietas, esperando a que algo nade demasiado cerca.", "틈새에 숨어 무언가 너무 가까이 헤엄쳐 오기를 기다린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez León", "쏠배감펭", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Su veneno no es letal, pero sacará a la vista tus puntos débiles.", "독은 치명적이지 않지만 네 약점을 드러낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Piraña", "피라냐", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pirañas, nunca hay una sola en el agua.", "피라냐는 물속에 혼자만 있지 않다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Globo", "복어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Su combinación de veneno y espinas es letal para cualquier ser vivo.", "독과 가시의 조합은 모든 생물에게 치명적이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pez Remo", "산갈치", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Una de las bestias mas raras que he fotografiado jamás.", "내가 사진을 찍은 가장 희귀한 야수 중 하나다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhyzostoma", "뿌리입해파리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nada sobrevive a la Rhyzostoma, ni dentro ni fuera del agua.", "물속이든 밖이든 뿌리입해파리에게서 살아남는 것은 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salmón", "연어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El salmón, pez difícil de pescar.", "연어. 잡기 어려운 물고기다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Esturión", "철갑상어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "El inundible esturión, acorazado marino.", "가라앉지 않는 철갑상어. 바다의 장갑함이다.", Language.Korean);



        }
    }
    public class SauriaSigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SauriaSigils Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avenging", "복수", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever an adjacent card perishes during combat, a card bearing this sigil gains 1 Power.", "인접한 카드가 전투 중 사망할 때마다 이 도장을 지닌 카드는 공격력 1을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avenging Strike", "복수의 일격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The loss of its friend will not go unpunished.", "친구의 죽음을 그냥 넘기지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever a friendly card is killed during combat by an opponent's card, a card bearing this sigil moves to that space and strikes the attacker.", "아군 카드가 전투 중 상대 카드에 의해 죽을 때마다 이 도장을 지닌 카드는 그 자리로 이동해 공격자를 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To avenge the fallen...", "쓰러진 자의 복수를 위해……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleeding", "출혈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil loses 1 Health at the end of their owner's turn.", "이 도장을 지닌 카드는 주인의 턴이 끝날 때 체력 1을 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How much longer can it endure?", "얼마나 더 버틸 수 있을까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blessing", "축복", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Bones to increase Health of this and adjacent creatures by 1 if they have less than 10.", "뼈 4개를 지불하면 이 피조물과 인접한 피조물 중 체력이 10 미만인 대상의 체력을 1 늘린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your beasts feel better now.", "네 야수들이 이제 기분이 나아졌다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blizzard", "눈보라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, unoccupied spaces on its owner's side are filled with blocks of ice.", "이 도장을 지닌 카드를 놓으면 주인 쪽의 빈칸이 얼음 덩어리로 채워진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Winter is coming.", "겨울이 오고 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bone to gnaw on.", "갉아먹을 뼈다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Blast", "뼈 폭발", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When initiating combat, a card bearing this sigil dies. Upon death, all other cards take damage equal to the amount of owner's bones.", "전투를 시작할 때 이 도장을 지닌 카드는 죽는다. 죽을 때 다른 모든 카드는 주인이 가진 뼈의 수만큼 피해를 입는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not a pretty sight", "보기 좋은 광경은 아니군", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Gift", "뼈 선물", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, a Bone is created in your hand. [define:Sauria_Bone]", "이 도장을 지닌 카드를 놓으면 패에 뼈 카드 한 장이 생성된다. [define:Sauria_Bone]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A gift for its master.", "주인을 위한 선물이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Offering", "뼈 제물", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card on the opponent's side of board that costs Bones or Blood. Pay its price in Bones to add it to your hand. Blood is counted as 3 Bones, cannot choose cards that cost neither resource.", "상대 측 보드에서 뼈나 피를 비용으로 쓰는 카드 한 장을 선택한다. 비용을 뼈로 지불해 패에 추가한다. 피 1은 뼈 3으로 계산하며 두 자원을 모두 비용으로 쓰지 않는 카드는 선택할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've managed to entice one of my beasts.", "내 야수 하나를 유인하는 데 성공했군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cannibalistic", "동족 포식자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When another card on the owner's side of board takes damage and its Health no longer exceeds Power of the bearer of this sigil, this card attacks it.", "주인 측 보드의 다른 카드가 피해를 입어 체력이 이 도장 보유자의 공격력 이하가 되면 이 카드가 그 카드를 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A grim opportunity to feast.", "먹어 치울 잔혹한 기회다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caretaker", "돌보는 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, all other cards on the owner's side of board heal 1 Health while a card bearing this sigil is alive.", "이 도장을 지닌 카드가 살아 있는 동안 턴이 끝날 때 주인 측 보드의 다른 모든 카드가 체력 1을 회복한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It tends to their wounds.", "그들의 상처를 돌본다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catapult", "투석기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to select another card on your side of the board to move to another space, including opponent's side of the board.", "뼈 1개를 지불해 자신의 보드에 있는 다른 카드 한 장을 선택하고 다른 위치로 옮긴다. 상대 측 보드도 선택할 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for falling beasts.", "떨어지는 야수를 조심하라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Change Form", "형태 변화", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil transform into an alternate form.", "이 도장을 지닌 카드는 다른 형태로 변한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch it shift its form.", "모습이 변하는 것을 보라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Shifter", "뼈 변신자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Bones to transform this card into an alternate form.", "뼈 3개를 지불해 이 카드를 다른 형태로 바꾼다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Concerned", "걱정", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a friendly card takes damage, a card bearing this sigil attempts to move to its closest adjacent space. If that space is occupied, it attempts to move one space in that direction instead.", "아군 카드가 피해를 입으면 이 도장을 지닌 카드는 그 카드에 가장 가까운 인접 칸으로 이동하려 한다. 그 칸이 차 있으면 대신 그 방향으로 한 칸 이동하려 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It responds to its ally's distress.", "동료의 위험에 반응한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cruelty", "잔혹함", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card through any other means, it deals 1 damage to its target.", "이 도장을 지닌 카드가 다른 수단으로 다른 카드에 피해를 주면 대상에게 피해 1을 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This beasts wishes to inflict more grievous injuries.", "이 야수는 더 심한 상처를 입히고 싶어 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deep Freeze", "급속 냉동", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil perishes within 2 turns, the creature within is released.", "이 도장을 지닌 카드가 2턴 안에 죽으면 안에 있는 피조물이 풀려난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Free at last.", "마침내 자유다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desperate Push", "절박한 밀치기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil perishes during combat while opposing space is occupied, it pushes the opposing cards back.", "이 도장을 지닌 카드가 전투 중 죽고 맞은편 칸이 차 있으면 맞은편 카드들을 뒤로 밀어낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps its sacrifice will pay off.", "희생이 보답받을지도 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dismember", "사지 절단", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card, gain bones equal to the damage dealt, up to 5 bones at once.", "이 도장을 지닌 카드가 다른 카드에 피해를 주면 준 피해만큼 뼈를 얻는다. 한 번에 최대 5개까지 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How gruesome.", "참으로 끔찍하군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Embolden", "격려", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are adjacent cards with less Power than the bearer of this sigil, lose 1 Power and give 1 Power to them.", "주인의 턴이 끝날 때 이 도장 보유자보다 공격력이 낮은 인접 카드가 있으면 보유자는 공격력 1을 잃고 그 카드들에 공격력 1씩을 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its strength with its allies.", "아군과 힘을 나눈다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enduring", "인내", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 2 Health at the start of its third turn on the board.", "이 도장을 지닌 카드는 보드에서 세 번째 턴이 시작할 때 체력 2를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prolonged combat is fortifying this beast.", "장기전이 이 야수를 강하게 만든다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic March", "변덕스러운 행진", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move in the direction inscribed on the sigil at the end of its owner's turn. If there are cards in its way or this card is at edge of the board, it will try to move to the opponent's side of board first.", "이 도장을 지닌 카드는 주인의 턴이 끝날 때 도장 방향으로 이동한다. 길에 카드가 있거나 이 카드가 보드의 가장자리에 있으면 먼저 상대 측 보드로 이동하려 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its movements are unpredictable.", "움직임을 예측하기 어렵다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fervor", "열의", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 Power at the start of its third turn on the board.", "이 도장을 지닌 카드는 보드에서 세 번째 턴이 시작할 때 공격력 1을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prolonged combat is making this beast grow more ferocious.", "장기전이 이 야수를 더욱 사납게 만든다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Genetic Flaw", "선천적 결함", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil loses 1 Health at the end of their owner's turn.", "이 도장을 지닌 카드는 주인의 턴이 끝날 때 체력 1을 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps it's not meant to live.", "어쩌면 살아서는 안 되는 존재일지도 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Genetic Perfection", "유전적 완벽", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If card bearing this sigil has its stats reduced below their normal values, it gains 1 Power and/or Health at the end of its owner's turn. If this card has Genetic Flaw sigil, remove it.", "이 도장을 지닌 카드의 능력치가 정상값 아래로 떨어지면 주인의 턴이 끝날 때 공격력이나 체력 또는 둘 다 1을 얻는다. 이 카드에 선천적 결함 도장이 있으면 제거한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is perfection incarnate.", "완벽함의 화신이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Catapult", "대형 투석기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Bones to select another card on your side of the board to move to another space, including opponent's side of the board. If there is an obstruction with a free opposing space, it takes damage equal to this card's Attack first. If obstruction remains, selected card attempts to move to its opposing space instead.", "뼈 3개를 지불해 자신 측 보드의 다른 카드 한 장을 선택해 다른 위치로 옮긴다. 상대 측도 가능하다. 장애물의 맞은편 칸이 비어 있으면 먼저 이 카드의 공격력만큼 장애물에 피해를 준다. 장애물이 남아 있으면 선택한 카드는 대신 그 맞은편으로 이동하려 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good aim.", "잘 조준했군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Embolden", "강한 격려", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are any cards on owner's side of the board with less Power than the bearer of this sigil, lose 1 Power and give 1 Power to them.", "주인의 턴이 끝날 때 주인 측 보드에 이 도장 보유자보다 공격력이 낮은 카드가 있으면 보유자는 공격력 1을 잃고 그 카드들에 공격력 1씩을 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its strength with all of its allies.", "모든 아군과 힘을 나눈다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Grudge Bearer", "깊은 원한을 짊어진 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever cards belonging to the owner of the card bearing this sigil are struck, the attacker is marked. At the start of the owner's turn, this card attacks all marked cards owned by the opponent.", "이 도장을 지닌 카드의 주인이 소유한 카드가 공격받을 때마다 공격자가 표식된다. 주인의 턴이 시작할 때 이 카드는 상대의 표식된 카드 모두를 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death is the only suitable punishment.", "죽음만이 합당한 벌이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Nurture", "강한 양육", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are any cards on owner's side of the board with less Health than the bearer of this sigil, lose 1 Health and give 1 Health to them.", "주인의 턴이 끝날 때 주인 측 보드에 이 도장 보유자보다 체력이 낮은 카드가 있으면 보유자는 체력 1을 잃고 그 카드들에 체력 1씩을 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its essence with all of its allies.", "모든 아군과 자신의 정수를 나눈다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grievous Display", "끔찍한 과시", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil attacks an opposing creature and it perishes, creatures to the left and right of the target lose 1 Power.", "이 도장을 지닌 카드가 맞은편 피조물을 공격해 죽이면 대상의 좌우에 있는 피조물은 공격력 1을 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not easy on the eyes.", "차마 보기 어렵군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ground Pound", "땅 내려찍기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, cards in opposing and adjacent spaces take 1 damage. This effect is additionally activated when moving 2 spaces away from last position or the opponent's side of board.", "이 도장을 지닌 카드를 놓으면 같은 편 좌우에 인접한 카드와 맞은편 카드가 피해 1을 입는다. 상대 측으로 이동하거나 같은 편에서 2칸 이상 이동할 때도 이 효과가 발동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A less than graceful landing.", "우아하다고는 할 수 없는 착지군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ground Smash", "땅 부수기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, it deals damage to cards in opposing and adjacent spaces equal to its Attack or at least 1 damage. This effect is additionally activated when moving 2 spaces away from last position or the opponent's side of board.", "이 도장을 지닌 카드를 놓으면 같은 편 좌우에 인접한 카드와 맞은편 카드에 이 카드의 공격력만큼 피해를 주며 최소 피해는 1이다. 상대 측으로 이동하거나 같은 편에서 2칸 이상 이동할 때도 이 효과가 발동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a nasty shockwave.", "참으로 지독한 충격파군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grudge Bearer", "원한을 짊어진 자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, the attacker is marked. At the start of the owner's turn, this card attacks a random marked card owned by the opponent.", "이 도장을 지닌 카드가 공격받으면 공격자가 표식된다. 주인의 턴이 시작할 때 이 카드는 상대의 표식된 카드 중 무작위로 한 장을 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It will remember this.", "이 일을 기억할 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grudge-Powered", "원한 동력", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of opponent's creatures marked by Grudge Bearer sigils and the number of said creatures killed by the bearer of this sigil.", "이 도장이 나타내는 값은 원한을 짊어진 자 도장으로 표식된 상대 피조물 수와 이 도장의 보유자가 죽인 해당 피조물 수의 합이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature]s power is equal to the number of opponent's creatures marked by Grudge Bearer sigils and the number of said creatures killed by [creature].", "[creature]의 공격력은 원한을 짊어진 자 도장으로 표식된 상대 피조물 수와 [creature]이(가) 죽인 해당 피조물 수의 합이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grudge Target", "원한의 표적", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will be attacked by opponent's cards bearing Grudge Bearer sigils.", "이 도장을 지닌 카드는 원한을 짊어진 자 도장을 지닌 상대 카드에게 공격받는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A permanent stain.", "영원히 지워지지 않는 얼룩이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hasty Escape", "급한 탈출", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon taking damage, the bearer of this sigil returns to owner's hand if it's still alive.", "이 도장 보유자가 피해를 입고 살아 있으면 주인의 패로 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sometimes, cowards do survive.", "겁쟁이도 가끔 살아남는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigger Block of Ice", "더 큰 얼음덩어리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A block of ice, nothing to see", "얼음덩어리다. 볼 것은 없다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its meal with its newfound family.", "새로 만난 가족과 먹이를 나눈다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knock Back", "밀쳐내기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card, it attempts to move its target to an adjacent space, prioritizing right.", "이 도장을 지닌 카드가 다른 카드에 피해를 주면 대상을 인접한 칸으로 옮기려 한다. 오른쪽을 우선한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A nasty blow.", "강한 일격이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juicy Meat", "육즙 많은 고기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meat", "고기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Makes you salivate.", "침이 고인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Memento", "유품", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil perishes during combat, adjacent cards gain 1 Power.", "이 도장을 지닌 카드가 전투 중 죽으면 인접한 카드들이 공격력 1을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its friends will not forgive those fiends.", "친구들은 저 악당들을 용서하지 않을 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete and total extermination is the only reasonable response.", "완전하고 철저한 말살만이 유일하게 합리적인 대응이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Micro", "초소형", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Movement Command", "이동 명령", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once per turn, move the bearer of this sigil to a selected empty space.", "턴당 한 번 이 도장의 보유자를 선택한 빈칸으로 이동시킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The beast follows your command.", "야수가 네 명령을 따른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nurture", "양육", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, if there are adjacent cards with less Health than the bearer of this sigil, lose 1 Health and give 1 Health to them.", "주인의 턴이 끝날 때 이 도장 보유자보다 체력이 낮은 인접 카드가 있으면 보유자는 체력 1을 잃고 그 카드들에 체력 1씩을 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It shares its essence with its allies.", "아군과 자신의 정수를 나눈다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Outburst", "폭발", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, a card bearing this sigil performs an additional attack against opposing space if it's occupied by a card whose Attack is above 0.", "주인의 턴이 끝날 때 맞은편 칸에 공격력이 0보다 높은 카드가 있으면 이 도장을 지닌 카드가 그 칸을 추가로 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It won't be moving for long at this rate.", "이대로라면 오래 움직이지 못하겠군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasitoid Propagation", "기생 번식", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, a copy of this card is created in your hand.", "이 도장을 지닌 카드가 다른 피조물을 죽이면 이 카드의 사본 한 장이 패에 생성된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life can be unsightly at times.", "생명은 때때로 흉하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parental Care", "부모의 보살핌", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, creatures with Fledgling sigil adjacent to a card bearing this sigil gain 1 Health.", "주인의 턴이 끝날 때 이 도장을 지닌 카드에 인접한 햇병아리 도장을 지닌 피조물은 체력 1을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good parent.", "좋은 부모다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parting Bone", "이별의 뼈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil dies or is sacrificed, a Bone is created in your hand. [define:Sauria_Bone]", "이 도장을 지닌 카드가 죽거나 희생되면 패에 뼈 카드 한 장이 생성된다. [define:Sauria_Bone]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A parting gift for its master.", "주인을 위한 이별 선물이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persistent", "존속", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil would die during combat for the first time, it revives and gains 2 Power.", "이 도장을 지닌 카드가 전투 중 처음 죽게 되면 되살아나 공격력 2를 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That creature will not give up so easily.", "저 피조물은 쉽게 포기하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protective", "보호", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an adjacent card is struck, a card bearing this sigil strikes the attacker.", "인접한 카드가 공격받으면 이 도장을 지닌 카드가 공격자를 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It doesn't appreciate having its comrades hurt.", "동료가 다치는 것을 좋아하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protective Parent", "자식을 지키는 부모", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When owner's cards with Fledgling sigil are struck, bearer of this sigil strikes the attacker.", "주인의 햇병아리 도장을 지닌 카드가 공격받으면 이 도장 보유자가 공격자를 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Few things inspire more awe and fear than a protective parent.", "자식을 지키는 부모만큼 경외와 두려움을 불러일으키는 것은 드물다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pursuer", "추격자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever an opponent's card moves to another space, a card bearing this sigil attempts to move to its current opposing space. If successful, it deals 1 damage to its opposing space.", "상대 카드가 다른 칸으로 이동할 때마다 이 도장을 지닌 카드는 그 카드의 현재 맞은편 칸으로 이동하려 한다. 이동에 성공하고 그 카드가 살아 있으면 피해 1을 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is no escape...", "도망칠 곳은 없다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quake", "진동", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 4 Bones to deal 1 damage to all enemy cards. This sigil is removed afterwards.", "뼈 4개를 지불해 모든 적 카드에 피해 1을 준다. 이후 이 도장을 제거한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrifying display of power.", "두려운 힘의 발현이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Served Dinner", "저녁 식사 제공", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card on the owner's side of board. Add stats of the card bearing this sigil to the selected card. This card dies afterwards. This effect can also be activated by sacrificing or killing this page directly.", "주인 측 보드의 카드 한 장을 선택한다. 이 도장을 지닌 카드의 능력치를 선택한 카드에 더한 뒤 이 카드는 죽는다. 이 카드를 직접 희생하거나 죽여도 효과가 발동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dinner is served.", "저녁 식사가 준비되었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoal Strike", "물고기 떼의 일격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, it deals 1 damage to all of opponent's submerged cards and forces them to surface.", "이 도장을 지닌 카드를 놓으면 잠수 중인 상대 카드 모두에게 피해 1을 주고 강제로 수면 위로 나오게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hunt begins...", "사냥이 시작된다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skittish", "겁 많음", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card moves into space opposing the one bearing this sigil, deal 1 damage to it, then move to a random unoccupied space on the owner's side of board if possible.", "카드가 이 도장 보유자의 맞은편 칸으로 이동하면 그 카드에 피해 1을 준 뒤 가능하면 주인 측 보드의 무작위 빈칸으로 이동한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature appears to be rather skittish.", "이 피조물은 꽤 겁이 많은 것 같다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sprinter Strike", "질주자의 일격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenener a card bearing this sigil moves, it deals 1 damage to its opposing space. If said space is not occupied, the opponent is deald 1 damage immediately.", "이 도장을 지닌 카드가 이동할 때마다 맞은편 칸에 피해 1을 준다. 그 칸이 비어 있으면 상대에게 즉시 피해 1을 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A swift strike.", "빠른 일격이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sticky Tongue", "끈적한 혀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owners turn, a card bearing this sigil attempts to drag creatures adjacent to opposing space or queued behind it in front of itself, prioritizing the latter. If affected card has 1 Health, this card immediately attacks it.", "주인의 턴이 시작할 때 이 도장을 지닌 카드는 맞은편 칸에 인접한 피조물이나 그 뒤 대기열의 피조물을 자신의 앞으로 끌어오려 한다. 후자를 우선한다. 대상 카드의 체력이 1이면 즉시 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a sticky situation.", "참 곤란한 상황이군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tactical Retreat", "전술 후퇴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, the bearer of this sigil returns to owner's hand if it's still alive.", "주인의 턴이 끝날 때 이 도장 보유자가 살아 있으면 주인의 패로 돌아간다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It doesn't feel the need to stay on the board.", "보드에 남을 필요를 느끼지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TearThrough", "찢고 돌파", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If opposing space is occupied, a card bearing this sigil will move in the direction inscribed on the sigil at the end of its owner's turn, dealing 1 damage to the card in that space and trying to move it as well.", "맞은편 칸이 차 있으면 이 도장을 지닌 카드는 주인의 턴이 끝날 때 도장 방향으로 이동해 그 칸의 카드에 피해 1을 주고 함께 움직이려 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A brutal display", "잔혹한 광경", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Territorial", "영역 다툼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When another creature moves into an adjacent or opposing space, a card bearing this sigil attacks it.", "다른 피조물이 인접하거나 맞은편인 칸으로 이동하면 이 도장을 지닌 카드가 그 피조물을 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To intrude upon its territory...", "감히 녀석의 영역을 침범하다니……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tyranny", "폭정", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Blood to increase Attack and Health of this and adjacent creatures by 1, then remove this sigil.", "피 2를 지불해 이 피조물과 인접한 피조물의 공격력과 체력을 각각 1 늘린 뒤 이 도장을 제거한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A sacrifice this beast is willing to make.", "이 야수는 기꺼이 희생한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vicious Growth", "사나운 성장", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, it gains 1 Power and 1 Health.", "이 도장을 지닌 카드가 다른 피조물을 죽이면 공격력 1과 체력 1을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One life to nourish another.", "한 생명이 다른 생명을 기른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wounding", "상처", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals damage to another card without Made of Stone, its target gains Bleeding effect. Bleeding cards lose 1 Health at the end of their owner's turn.", "이 도장을 지닌 카드가 굳건함이 없는 다른 카드에 피해를 주면 대상에게 출혈 효과가 생긴다. 출혈 중인 카드는 주인의 턴이 끝날 때 체력 1을 잃는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This must sting.", "분명 쓰라리겠군.", Language.Korean);



            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's a Grudgin'", "원한을 샀군", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a card collect grudges from 10 marked cards in a single battle", "한 번의 전투에서 카드 한 장이 표식된 카드 10장에게서 원한을 모으게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete and Total Extermination", "완전한 말살", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a card with Greater Grudge Bearer wipe out 4 marked cards at once.", "깊은 원한을 짊어진 자 도장을 지닌 카드로 표식된 카드 4장을 한꺼번에 없앤다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Completely Boned", "뼈만 남았군", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wipe out the whole board via Bone Blast.", "뼈 폭발로 보드 전체를 쓸어버린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plateosaurus School of Thought", "플라테오사우루스 학파", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a philosopher bother 10 cards with questions in a single battle.", "한 번의 전투에서 철학자가 질문으로 카드 10장을 귀찮게 하게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Terrible Roommate", "끔찍한 룸메이트", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a territorial card lash out at friendly cards in a single battle", "한 번의 전투에서 영역 다툼 카드가 아군 카드를 공격하게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beast Cannon", "야수 대포", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kill at least 2 enemy cards by throwing a hefty beast at them.", "무거운 야수를 던져 적 카드 최소 2장을 죽인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Et Tu, Majungasaurus?", "너마저, 마준가사우루스?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a cannibalistic card devour 10 friendly cards in a single battle.", "한 번의 전투에서 동족 포식자 카드가 아군 카드 10장을 삼키게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Tis But A Scratch", "긁힌 것뿐이다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have one of your cards survive 10 turns while bleeding.", "내 카드 한 장이 출혈 중인 채로 10턴을 살아남는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empathetic", "공감", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a nurturing card sacrifice 10 Health in a single battle.", "한 번의 전투에서 양육 카드가 체력 10을 희생하게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rally", "집결", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have an emboldening card sacrifice 10 Power in a single battle.", "한 번의 전투에서 격려 카드가 공격력 10을 희생하게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascended Arts", "승화의 기술", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a certain card fully remove cost of 6 cards in a single run.", "한 번의 도전에서 특정 카드가 카드 6장의 비용을 완전히 제거하게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raptor Attack", "랩터 공격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtain at least 10 Raptor cards in a single run.", "한 번의 도전에서 랩터 카드 최소 10장을 얻는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jurassic World", "쥐라기 월드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with 3 secret cards. Life finds a way.", "비밀 카드 3장을 가지고 도전을 마친다. 생명은 길을 찾는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apex Predators", "최상위 포식자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have three biggest theropods in your deck in a single run.", "한 번의 도전에서 가장 큰 수각류 세 종류를 덱에 넣는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "King of the Monsters", "만수의 왕", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unleash the King of the Monsters upon the enemy.", "적에게 만수의 왕을 풀어놓는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ballad of Big Al", "빅 알의 발라드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Help get the big girl back on her feet. Poor thing.", "이 커다란 소녀가 다시 일어서도록 돕는다. 불쌍한 녀석.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indomitable One", "불굴의 존재", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Create a genetic abomination with more teeth.", "이빨이 더 많은 유전적 괴물을 만든다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Monster Resurrected", "괴물의 부활", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Make Spinosaurus feel like a monster.", "스피노사우루스가 괴물처럼 느끼게 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jurassic Painter", "쥐라기 화가", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Promote Stokesosaurus to a painter.", "스토케소사우루스를 화가로 승진시킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All Outta Gum", "껌은 다 떨어졌다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give the little guy balls of steel.", "작은 녀석에게 강철 같은 배짱을 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Novel Look", "새로운 모습", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take the frills off the crested critter.", "볏이 있는 동물의 목 장식을 떼어 낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bird Up", "새가 되자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Put too many feathers where they don't belong.", "깃털이 있어서는 안 될 곳에 깃털을 너무 많이 붙인다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wu's Secrets", "우의 비밀", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have Compstegnathus, Spinoraptor and Ankylodocus in your deck in a single run.", "한 번의 도전에서 검등 콤프소그나투스, 스피노랍토르, 안킬로도쿠스를 덱에 넣는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Welcome to Jurassic Park", "쥬라기 공원에 오신 것을 환영합니다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with Jurassic Park deck and at least 7 related cards.", "쥬라기 공원 덱과 관련 카드 최소 7장을 가지고 도전을 마친다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prehistoric Collection", "선사 시대 수집품", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play a copy of every common Sauria card.", "고대 도마뱀 카드 도감의 모든 일반 카드를 한 장씩 낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rare Fossils", "희귀 화석", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Play a copy of every rare Sauria card.", "고대 도마뱀 카드 도감의 모든 레어 카드를 한 장씩 낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paleo-Novice", "고생물 초보자", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with 5 Sauria decks.", "서로 다른 고대 도마뱀 카드 도감 시작 덱을 최소 5종류 사용해 각각 도전을 완료한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dino-Fan", "공룡 팬", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with 20 Sauria decks.", "서로 다른 고대 도마뱀 카드 도감 시작 덱을 최소 20종류 사용해 각각 도전을 완료한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deck-O-Saurus", "덱사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Finish a run with every available Sauria deck.", "사용 가능한 고대 도마뱀 카드 도감 덱마다 도전을 마친다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gyarouucore", "갸루코어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obtained every other achievement! Good job!", "다른 업적을 모두 획득했다! 잘했다!", Language.Korean);

        }
    }
    public class SauriaCardsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SauriaCards Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acrocanthosaurus", "아크로칸토사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acrocanthosaurus, terror of the North. It does not take much to provoke this giant into attacking.", "북쪽의 공포 아크로칸토사우루스. 조금만 자극해도 이 거대한 야수는 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allosaurus", "알로사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This tenacious predator doesn't know when to stop its assault.", "이 끈질긴 포식자는 공격을 멈출 줄 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amargasaurus", "아마르가사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amargasaurus, a surprisingly small beast for its kind. Size is relative, however.", "아마르가사우루스. 동류에 비하면 놀랍도록 작다. 물론 크기는 상대적이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "American Lion", "아메리카라이온", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The American Lion, a vicious feline predator with a soft heart. It does not extend its kindness towards its prey, however.", "아메리카라이온. 사나운 고양잇과 포식자지만 마음은 여리다. 다만 먹잇감에게는 자비를 베풀지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "American Lion Cub", "아메리카라이온 새끼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An American Lion Cub, an adorable kitten. It's hard to imagine something like this growing up to become a terrifying predator", "아메리카라이온 새끼. 사랑스러운 아기 고양이다. 이런 녀석이 자라 무서운 포식자가 될 줄은 상상하기 어렵다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankylosaurus", "안킬로사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sturdy Ankylosaurus. It may not feel claws and teeth strike its hide, but it does not appreciate being pestered during mealtime.", "난공불락의 안킬로사우루스. 발톱과 이빨이 가죽을 쳐도 느끼지 못할 수 있지만 식사 중 방해받는 건 싫어한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anomalocaris", "아노말로카리스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ancient Anomalocaris, one of the first apex predators to live in this world. It does its best against modern beasts.", "고대의 아노말로카리스. 이 세상 최초의 최상위 포식자 중 하나다. 현대의 야수들을 상대로 최선을 다한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apatosaurus", "아파토사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The formidable Apatosaurus. It doesn't need to be the biggest of its kind to crush enemies into dust.", "강력한 아파토사우루스. 동류 중 가장 크지 않아도 적을 가루로 짓뭉갤 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Argentinosaurus", "아르헨티노사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The titanic Argentinosaurus, truly a sight to behold. Make sure to keep your distance if you do not wish to be crushed.", "거대한 아르헨티노사우루스. 참으로 장관이다. 짓밟히고 싶지 않다면 거리를 유지하라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arthropleura", "아르트로플레우라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arthropleura, an oversized centipede with a taste for decaying plants. Its movements are unpredictable.", "아르트로플레우라. 썩어 가는 식물을 좋아하는 거대한 지네다. 움직임은 예측할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aspidorhynchus", "아스피도린쿠스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is much bigger fish out there, but Aspidorhynchus is still perfectly capable of biting your fingers off.", "저 밖에는 훨씬 큰 물고기들이 있지만 아스피도린쿠스도 네 손가락을 물어뜯을 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Australovenator", "아우스트랄로베나토르", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vicious Australovenator. It pierces and tears through the hide of its victims with its enlarged claws.", "사나운 아우스트랄로베나토르. 커다란 발톱으로 희생자의 가죽을 찌르고 찢는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Austroraptor", "아우스트로랍토르", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keen-eyed Austroraptor, a skilled fisher of light build. It's far from harmless, however.", "눈이 예리한 아우스트로랍토르. 몸이 가볍고 물고기를 잘 잡는다. 그렇다고 무해하지는 않다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baryonyx", "바리오닉스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baryonyx, a crocodile-faced beast with a taste for fish. Refrain from smiling if you do not wish to expand its diet.", "악어 얼굴을 한 바리오닉스. 물고기를 좋아한다. 녀석의 식단에 추가되고 싶지 않다면 웃지 마라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beipiaosaurus", "베이피아오사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Beipiaosaurus is armed with sharp claws to rend its foes apart...but it does not have the courage to stand up to anything bigger.", "이 베이피아오사우루스는 적을 찢을 날카로운 발톱을 가졌지만…… 자기보다 큰 것에 맞설 용기는 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachiosaurus", "브라키오사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mighty Brachiosaurus. It can use its immense size to draw aggressors away from allies.", "강력한 브라키오사우루스. 거대한 몸으로 공격자의 주의를 아군에게서 돌릴 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachiosaurus Hatchling", "브라키오사우루스 새끼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Brachiosaurus hatchling. It will take some time for it to reach its full size.", "브라키오사우루스 새끼. 다 자라려면 시간이 좀 걸린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachytrachelopan", "브라키트라켈로판", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brachytrachelopan, a bizarre creature for its kind. Though it lacks their characteristic long neck, its long tail makes up for its absence.", "브라키트라켈로판. 동류 중에서도 기이한 피조물이다. 특징적인 긴 목은 없지만 긴 꼬리가 그 빈자리를 메운다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Camarasaurus", "카마라사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ginormous Camarasaurus. Though it does not wish to bring harm directly, its great size allows it to fling beasts across the battlefield.", "엄청나게 큰 카마라사우루스. 직접 해칠 생각은 없지만 거대한 몸으로 야수를 전장 너머로 던져 버릴 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria", "고대 도마뱀 카드 도감", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carnotaurus", "카르노타우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though not as swift as commonly believed, this beast can hardly be stopped once it gains momentum.", "흔히 생각하는 만큼 빠르지는 않지만 이 야수는 일단 탄력을 받으면 막기 어렵다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cartorhynchus", "카르토린쿠스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Cartorhynchus may be tiny, but there is bigger fish following its trail.", "이 카르토린쿠스는 작을지 몰라도 더 큰 물고기가 그 뒤를 따르고 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caturus", "카투루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Caturus, an imposing predator to some, an enticing snack for others.", "카투루스. 어떤 이에게는 위압적인 포식자지만 다른 이에게는 먹음직스러운 간식이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cearadactylus", "케아라닥틸루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Too busy fretting over its meals, Cearadactylus does not make for a great fighter.", "케아라닥틸루스는 먹이를 걱정하느라 바빠 훌륭한 전투원이 되지 못한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cephalaspis", "케팔라스피스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cephalaspis, an armored fish shaped like a shovel. Its thick armor lets it feed in peace.", "케팔라스피스. 삽처럼 생긴 갑옷 물고기다. 두꺼운 갑옷 덕에 마음 편히 먹이를 먹는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ceratodus", "케라토두스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The peculiar Ceratodus, a fish with the ability to live on land. Makes for a fine meal.", "특이한 케라토두스. 육지에서도 살 수 있는 물고기다. 좋은 먹이가 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ceratosaurus", "케라토사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though often overshadowed by its bigger competitors, Ceratosaurus is a formidable threat in its own right.", "더 큰 경쟁자들에게 가려지기 쉽지만 케라토사우루스도 그 자체로 강력한 위협이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chasmosaurus", "카스모사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stalwart Chasmosaurus. It uses its shield-like frill to protect allies.", "굳건한 카스모사우루스. 방패 같은 목 장식으로 아군을 보호한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chungkingosaurus", "충킹고사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though it may not be eager to hurt other creatures, you do not want to get near the tail of Chungkingosaurus.", "충킹고사우루스는 다른 피조물을 해치고 싶어 하지 않을지 몰라도 그 꼬리에는 가까이 가지 않는 게 좋다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coelophysis", "코엘로피시스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coelophysis, one of the first of its kind. Many more terrible beasts have spawned from its lineage.", "코엘로피시스. 동류 중 가장 이른 시기의 하나다. 그 계통에서 더 끔찍한 야수들이 태어났다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compsognathus", "콤프소그나투스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The diminutive Compsognathus. It can hardly pose a threat while alone.", "작은 콤프소그나투스. 혼자서는 거의 위협이 되지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corythosaurus", "코리토사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corythosaurus, a cautious beast that does not travel alone. It finds safety in a herd.", "코리토사우루스. 혼자 다니지 않는 신중한 야수다. 무리 속에서 안전을 찾는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dacentrurus", "다켄트루루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dacentrurus, a beast with an oddly elongated neck that fiercely protects its allies.", "다켄트루루스. 유난히 긴 목을 지닌 야수로 아군을 맹렬히 보호한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Daeodon", "다에오돈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The terrible Daeodon. It may not be a pig, but it is certainly prepared for war.", "무시무시한 다에오돈. 돼지는 아닐지 몰라도 싸울 준비는 확실하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinocheirus", "데이노케이루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once thought to be a terrible beast, Deinocheirus turned out to be far more bizarre than anyone expected. Its strength is not to be underestimated, however.", "한때 무시무시한 야수로 여겨졌던 데이노케이루스는 누구의 예상보다 기이한 모습이었다. 그렇다고 그 힘을 과소평가해서는 안 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinonychus", "데이노니쿠스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinonychus, a vicious hunter known for the enlarged claws adorning its feet. How's that for a 'six-foot turkey'?", "데이노니쿠스. 발에 난 커다란 발톱으로 유명한 사나운 사냥꾼이다. 이 '6피트짜리 칠면조'는 어떤가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sicilian Dwarf Elephant", "시칠리아 난쟁이코끼리", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sicilian Dwarf Elephant, a severely undersized counterpart of one of the biggest animals to roam the land today. Such is life on small island.", "시칠리아 난쟁이코끼리. 오늘날 육지를 누비는 가장 큰 동물 중 하나의 아주 작은 친척이다. 작은 섬의 삶이란 그런 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Desmatosuchus", "데스마토수쿠스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though not blessed with sharp teeth or claws, Desmatosuchus tries to make up for it with its thick hide", "데스마토수쿠스는 날카로운 이빨이나 발톱을 타고나지 못했지만 두꺼운 가죽으로 이를 보완하려 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dilophosaurus", "딜로포사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This little critter cripples prey by spitting its uncharacteristic venom.", "이 작은 생물은 특이한 독을 뿜어 먹잇감을 무력화한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dilophosaurus, a terror of the Early Jurassic period. Losing its ridiculous frill does not hinder its venomous nature.", "초기 쥐라기의 공포 딜로포사우루스. 우스꽝스러운 목 장식을 잃어도 독을 지닌 본성은 변하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimetrodon", "디메트로돈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimetrodon, a reptilian mammal with an impressive sail. Its sharp teeth are a far bigger concern, however.", "디메트로돈. 인상적인 돛을 지닌 포유류형 파충류다. 하지만 날카로운 이빨이 훨씬 더 큰 걱정거리다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimorphodon", "디모르포돈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dimorphodon, a mostly unremarkable little critter. Do not startle it, those teeth will leave a mark during its hasty retreat.", "디모르포돈. 별다를 것 없는 작은 생물이다. 놀라게 하지 마라. 급히 도망치면서 이빨로 상처를 남긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dinosaur Egg", "공룡 알", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigger Dinosaur Egg", "더 큰 공룡 알", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An egg left behind by some dinosaur. I wonder what will hatch from it?", "어떤 공룡이 남긴 알이다. 무엇이 부화할까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diplodocus", "디플로도쿠스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If sheer size alone is not enough to deter predators, then perhaps a mighty tail whip will make them reconsider.", "덩치만으로 포식자를 쫓아내지 못한다면 강력한 꼬리 채찍이 다시 생각하게 만들지도 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dryosaurus", "드리오사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dryosaurus, an adorable creature with a flighty attitude.", "드리오사우루스. 사랑스럽지만 잘 놀라는 피조물이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunkleosteus", "둔클레오스테우스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ravenous Dunkleosteus, an armored fish from distant past. Its true length has little bearing on its crushing jaws.", "게걸스러운 둔클레오스테우스. 먼 옛날의 갑옷 물고기다. 실제 길이가 어떻든 그 턱은 부수는 힘이 대단하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Edmontosaurus", "에드몬토사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Edmontosaurus, a massive creature with very few natural predators. Do not expect to find it alone.", "에드몬토사우루스. 천적이 거의 없는 거대한 피조물이다. 혼자 있는 모습은 보기 어렵다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elasmosaurus", "엘라스모사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Elasmosaurus, a prehistoric beast with an incredibly long neck. It can snatch prey far out of the reach of others.", "엘라스모사우루스. 믿기 어려울 만큼 목이 긴 선사 시대 야수다. 다른 이들이 닿지 못하는 먼 곳의 먹이를 낚아챌 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eobasileus", "에오바실레우스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eobasileus, the largest of its kind. Do not stand in its path if you wish to see the sun rise again.", "에오바실레우스. 동류 중 가장 크다. 다시 해가 뜨는 것을 보고 싶다면 앞을 가로막지 마라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Euoplocephalus", "에우오플로케팔루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The thick hide of this Euoplocephalus and the equally hefty club at the end of its tail protect it from most predators", "에우오플로케팔루스의 두꺼운 가죽과 꼬리 끝의 무거운 곤봉은 대부분의 포식자에게서 몸을 지켜 준다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gallimimus", "갈리미무스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gallimimus, a bird-like beast that is rather quick on its feet. It is about as friendly as it looks.", "갈리미무스. 새처럼 생겼고 발이 꽤 빠르다. 보이는 만큼 친근하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gastornis", "가스토르니스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vigilant Gastornis. It watches over its comrades, growing furious if it loses any.", "경계심 강한 가스토르니스. 동료들을 지켜보다가 누군가를 잃으면 격분한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Ground Sloth", "거대땅늘보", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Giant Ground Sloth, a massive beast far surpassing its modern relatives. It is much less friendly than you would think.", "거대땅늘보. 현대의 친척들보다 훨씬 큰 야수다. 생각보다 훨씬 사납다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gigantoraptor", "기간토랍토르", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gigantoraptor, a disturbingly large beast. Any attempts to resist will only further provoke it.", "기간토랍토르. 불안할 만큼 큰 야수다. 저항하면 더욱 화나게 할 뿐이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gojirasaurus", "고지라사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once the biggest predator to roam the land, Gojirasaurus' reign did not last. It's hard to match the titans that followed it.", "한때 육지를 누빈 가장 큰 포식자였던 고지라사우루스의 시대는 오래가지 못했다. 뒤이어 나타난 거인들에 맞서기는 어렵다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guanlong", "관룡", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guanlong, a vicious predator emboldened by the thrill of combat. Many more terrible beasts have spawned from its lineage.", "관룡. 전투의 흥분으로 용기를 얻는 사나운 포식자다. 그 계통에서 더 끔찍한 야수들이 태어났다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hadrosaurus", "하드로사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vengeful Hadrosaurus. It makes quick work of those who harm members of its herd.", "복수심 강한 하드로사우루스. 무리의 일원을 해친 자를 재빨리 처리한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haolong", "하오룽", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haolong, a bizarre beast covered in many sharp quills. Very few predators dare to clamp their jaws around its prickly hide.", "하오룽. 날카로운 가시가 가득한 기이한 야수다. 가시 돋친 가죽을 물려는 포식자는 거의 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Herrerasaurus", "헤레라사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Herrerasaurus hails from the age before dinosaurs took over the world. Being more primitive does not make it any less successful.", "이 헤레라사우루스는 공룡이 세상을 지배하기 전 시대에서 왔다. 더 원시적이라고 해서 덜 성공적인 것은 아니다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hesperornis", "헤스페로르니스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hesperornis, a swimming bird with a taste for fish. It has yet to lose its teeth.", "헤스페로르니스. 물고기를 좋아하는 헤엄치는 새다. 아직 이빨을 잃지 않았다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homalocephale", "호말로케팔레", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an adorable Homalocephale. Alas, a grim fate awaits this poor creature. Will your heart sink when you hear its cries?", "정말 사랑스러운 호말로케팔레다. 안타깝게도 이 불쌍한 피조물에게는 끔찍한 운명이 기다린다. 울음소리를 들으면 네 마음도 가라앉을까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyornis", "이크티오르니스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyornis, a prehistoric bird with sharp teeth. It is no less annoying than its modern counterparts.", "이크티오르니스. 날카로운 이빨을 가진 선사 시대의 새다. 현대의 동류만큼 성가시다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyosaurus", "이크티오사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift Ichthyosaurus. It can attack submerged foes in the blink of an eye.", "재빠른 이크티오사우루스. 잠수한 적을 눈 깜짝할 사이에 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iguanodon", "이구아노돈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mind your manners before this Iguanodon if you do not wish to feel its clawed thumb pierce you.", "이구아노돈 앞에서는 예의를 지켜라. 발톱 달린 엄지에 찔리고 싶지 않다면 말이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inostrancevia", "이노스트란케비아", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inostrancevia, a surprisingly agile apex predator of its age. The grievous injuries left by the beast's fangs are far less suprising.", "이노스트란케비아. 그 시대에 놀라울 만큼 민첩했던 최상위 포식자다. 송곳니가 심한 상처를 남기는 것은 그리 놀랍지 않다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Irish Elk", "아일랜드 엘크", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic Irish Elk, the biggest of its kind. Its massive horns grant it extended reach.", "장엄한 아일랜드 엘크. 동류 중 가장 크다. 거대한 뿔 덕분에 더 멀리 닿는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Irritator", "이리타토르", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The patient Irritator. Though it primarily feeds on fish, its claws are perfectly suited for tearing into other beasts.", "참을성 있는 이리타토르. 주로 물고기를 먹지만 발톱은 다른 야수를 찢기에도 알맞다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Isisaurus", "이시사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Isisaurus leads a herd of its own. Though they do not belong to its kind, those beasts trust this experienced titan.", "이시사우루스는 자기 무리를 이끈다. 같은 종류는 아니지만 야수들은 경험 많은 거인을 신뢰한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jeholopterus", "예홀롭테루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jeholopterus, nothing more than a bug-eating critter. Don't expect much else out of it.", "예홀롭테루스. 벌레를 먹는 작은 생물에 불과하다. 그 이상을 기대하지 마라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Katifelis", "카티펠리스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Katifelis, an unremarkable feline. It does not respond well to approaching strangers.", "카티펠리스. 평범한 고양잇과 동물이다. 모르는 사람이 다가오면 좋게 반응하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kentrosaurus", "켄트로사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kentrosaurus, a herbivore with a threatening appearance. Said appearance is far from deceiving, however.", "켄트로사우루스. 위협적으로 생긴 초식동물이다. 그 모습은 결코 허세가 아니다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Koolasuchus", "쿨라수쿠스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Koolasuchus, a dreadfull creature lurking in the water. It does not pass up any opportunity to feast.", "쿨라수쿠스. 물속에 숨어 있는 무시무시한 피조물이다. 배불리 먹을 기회를 놓치지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lambeosaurus", "람베오사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The solitary Lambeosaurus. It strikes its foes multiple times when disturbed.", "혼자 다니는 람베오사우루스. 방해받으면 적을 여러 번 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Liopleurodon", "리오플레우로돈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While much smaller than some may believe, Liopleurodon is still a vicious predator, always ready to tear its prey apart.", "리오플레우로돈. 일부 사람들이 생각하는 것보다 훨씬 작지만 여전히 먹잇감을 찢을 준비가 된 사나운 포식자다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majungasaurus", "마준가사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voracious Majungasaurus. It will not hesitate to devour its own comrades to sate its hunger.", "게걸스러운 마준가사우루스. 배고픔을 달래기 위해 동료도 망설임 없이 삼킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Masiakasaurus", "마시아카사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Masiakasaurus, a bizarre dinosaur of unimpressive size. It does not stay in battle for long.", "마시아카사우루스. 크기는 별 볼 일 없는 기이한 공룡이다. 전투에 오래 머물지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mawsonia", "마우소니아", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mawsonia, an enormous fish drifting in search of prey. Pray you do not bump into one while swimming.", "마우소니아. 먹이를 찾아 떠도는 거대한 물고기다. 수영할 때 마주치지 않기를 빌어라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalania", "메갈라니아", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The monstrous Megalania. A single bite from this oversized reptile is enough to cripple most beasts.", "괴물 같은 메갈라니아. 이 거대한 파충류에게 한 번 물리면 대부분의 야수가 무력화된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Metriacanthosaurus", "메트리아칸토사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Metriacanthosaurus mercilessly tears into its prey, unwilling to let any meal get away from its jaws.", "이 메트리아칸토사우루스는 먹이를 무자비하게 찢으며 한 번 문 먹이를 놓아주지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Microceratus", "미크로케라투스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unlike its bigger relatives, Microceratus stands on two legs and lacks any meaningful protection against predators. The best it can do is draw attention of something bigger.", "미크로케라투스는 더 큰 친척들과 달리 두 다리로 걷고 포식자를 막을 만한 수단이 없다. 기껏해야 더 큰 존재의 주의를 끌 수 있을 뿐이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minmi", "민미", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Minmi may seem adorable, but it is far from defenseless. In fact, defense might be all it has.", "이 민미는 귀여워 보이지만 무방비하지 않다. 사실 방어만 할 줄 아는지도 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muttaburrasaurus", "무타부라사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The persistent Muttaburrasaurus. It does not fall in battle while its herd is still in danger.", "끈질긴 무타부라사우루스. 무리가 위험한 동안은 전투에서 쓰러지지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nanotyrannus", "나노티라누스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Living in the shadow of the King does not make this beast any less formidable.", "왕의 그림자에 산다고 해서 이 야수가 덜 강력한 것은 아니다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nigersaurus", "니게르사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nigersaurus, a beast with countless teeth. It loses many while feeding, but they regrow just as quickly.", "니게르사우루스. 수많은 이빨을 가진 야수다. 먹이를 먹으며 많이 빠지지만 그만큼 빨리 다시 자란다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothosaurus", "노토사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though this Nothosaurus is clumsy on land, it is an adept swimmer with a mouth full of sharp teeth.", "이 노토사우루스는 육지에서는 서투르지만 수영을 잘하고 입에는 날카로운 이빨이 가득하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Olorotitan", "올로로티탄", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Olorotitan is more concerned about helping its allies than itself. Such altruism.", "이 올로로티탄은 자신보다 아군을 돕는 데 더 관심이 많다. 참으로 이타적이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Othnielia", "오스니엘리아", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Othnielia, hardly more than a snack for more ferocious beasts.", "오스니엘리아. 더 사나운 야수에게는 간식에 불과하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ouranosaurus", "오우라노사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though it is not an outstanding fighter, this Ouranosaurus encourages its comrades to fight with greater strength.", "이 오우라노사우루스는 뛰어난 싸움꾼은 아니지만 동료들이 더 힘차게 싸우도록 격려한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oviraptor", "오비랍토르", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once thought to be a mere egg thief, this feathered fiend takes great care of its young.", "한때 그저 알 도둑이라고 여겨졌던 이 깃털 달린 악마는 새끼를 정성껏 돌본다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pachycephalosaurus", "파키케팔로사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stubborn Pachycephalosaurus. It will attack anything that intrudes upon its territory regardless of size.", "고집 센 파키케팔로사우루스. 크기에 상관없이 영역을 침범하는 것은 무엇이든 공격한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pachyrhinosaurus", "파키리노사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The nomadic Pachyrhinosaurus. It lost many brothers during its travels. It cannot bear to lose more.", "유목하는 파키리노사우루스. 여행 중 많은 형제를 잃었고 더는 잃는 것을 견딜 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus", "파라사우롤로푸스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The peaceful Parasaurolophus. Its peculiar crest allows it to call upon its allies when in trouble.", "온순한 파라사우롤로푸스. 독특한 볏으로 위험할 때 아군을 부른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus Hatchling", "파라사우롤로푸스 새끼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A meek Parasaurolophus hatchling. It has yet to develop a prominent crest to match its parents.", "온순한 파라사우롤로푸스 새끼. 부모처럼 눈에 띄는 볏은 아직 자라지 않았다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patagopelta", "파타고펠타", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While far from the biggest armored dinosaur, Patagopelta is still perfectly capable of enduring blows.", "파타고펠타는 가장 큰 갑옷 공룡과는 거리가 멀지만 타격을 견디는 데는 충분하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plateosaurus", "플라테오사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plateosaurus, one of the first titans to roam the land. Though its descendants have far surpassed its size, it is by no means small.", "플라테오사우루스. 육지를 누빈 최초의 거인 중 하나다. 후손들이 훨씬 커졌지만 이 녀석도 결코 작지 않다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Platybelodon", "플라티벨로돈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Platybelodon, a beast so bizarre that few would believe it existed. It can use its unsightly skull to uproot obstacles in your path.", "플라티벨로돈. 너무 기이해서 실존을 믿는 이가 드문 야수다. 보기 흉한 두개골로 길의 장애물을 뽑아낼 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raptor Plushie", "랩터 인형", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A cute little toy, nothing more.", "귀여운 작은 장난감이다. 그뿐이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stuffing", "솜", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All that's left of a toy.", "장난감에서 남은 전부다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Postosuchus", "포스토수쿠스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Postosuchus, a bipedal crocodilian. Its bite is no less devastating than that of its modern relatives.", "포스토수쿠스. 두 발로 걷는 악어류다. 물어뜯는 힘은 현대 친척들 못지않다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Proceratosaurus", "프로케라토사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The deceptive Proceratosaurus. It makes up for its lacking offense with whatever wit you may attribute to a beast.", "교활한 프로케라토사우루스. 야수에게 기대할 수 있는 재치로 부족한 공격력을 보완한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Procompsognathus", "프로콤프소그나투스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Procompsognathus, a tiny terror with a surprisingly potent venom. It's particularly fond of feasting on greedy old men.", "프로콤프소그나투스. 작은 공포지만 독이 놀랄 만큼 강하다. 욕심 많은 노인을 먹는 것을 특히 좋아한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prongdeer", "가지뿔사슴", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prongdeer, a relatively small horned creature with an ill-fitting pair of fangs. They are not just for show, however.", "가지뿔사슴. 비교적 작은 뿔 달린 피조물로 어울리지 않는 송곳니 한 쌍이 있다. 장식은 아니다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protoceratops", "프로토케라톱스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Protoceratops may not seem like a threat, but the ferocity it displays when desperate is a sight to behold.", "이 프로토케라톱스는 위협적으로 보이지 않지만 절박할 때 보이는 사나움은 놀랍다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protosphyraena", "프로토스피라이나다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protosphyraena, a lightning-fast predator that cleaves its prey in half with its extended snout.", "프로토스피라이나다. 번개처럼 빠른 포식자다. 길게 뻗은 주둥이로 먹잇감을 반으로 가른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psittacosaurus", "프시타코사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The timid Psittacosaurus. Many beasts form bonds with this adorable creature. Few wish to see it hurt.", "겁 많은 프시타코사우루스. 많은 야수가 이 사랑스러운 피조물과 유대를 맺는다. 다치는 모습을 보고 싶은 이는 드물다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pteranodon", "프테라노돈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pteranodon, an iconic flying reptile. It may not have teeth to maul you with, but that beak spells trouble.", "프테라노돈. 대표적인 비행 파충류다. 물어뜯을 이빨은 없어도 그 부리는 위험하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodaustro", "프테로다우스트로", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...No, I did not fabricate this creature. Even the most bizarre forms can serve their own purposes.", "……아니, 내가 지어낸 피조물이 아니다. 가장 기이한 형태에도 나름의 목적이 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Qianzhousaurus", "첸저우사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ambitious Qianzhousaurus. Though yet to reach the true King's might, it has potential for growth.", "야심 찬 첸저우사우루스. 진정한 왕의 힘에는 아직 이르지 못했지만 성장할 가능성이 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quercylurus", "퀘르킬루루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quercylurus, a massive beast resembling saber-toothed cats. It gnaws on the many bones of its numerous victims.", "퀘르킬루루스. 검치 고양이를 닮은 거대한 야수다. 수많은 희생자의 뼈를 갉아먹는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhamphorhynchus", "람포린쿠스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhamphorhynchus, a tiny flying reptile with a mouth full of sharp teeth. Though it prefers fish, it can and will bite your fingers.", "람포린쿠스. 입에 날카로운 이빨이 가득한 작은 비행 파충류다. 물고기를 더 좋아하지만 네 손가락도 물 수 있고 실제로 물 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacabambaspis", "사카밤바스피스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The jawless Sacabambaspis, an adorable little fish with an armored hide.", "턱이 없는 사카밤바스피스. 갑옷 같은 피부를 가진 귀여운 작은 물고기다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sansanosmilus", "산사노스밀루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sansanosmilus, a cat-like predator with a particularly wounding bite. Smaller size does not make it any less dangerous.", "산사노스밀루스. 유난히 상처를 잘 입히는 물기를 지닌 고양이 같은 포식자다. 작다고 해서 덜 위험한 것은 아니다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sarcoprion", "사르코프리온", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sarcoprion, a monstrous shark with a bizarre set of jaws. It uses them to cut its prey in half.", "사르코프리온. 기이한 턱을 가진 괴물 같은 상어다. 턱으로 먹잇감을 반으로 자른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Segisaurus", "세기사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Segisaurus, hardly more than a pest. It comes in great numbers, however.", "세기사우루스. 성가신 존재에 불과하지만 많은 수가 몰려온다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shringasaurus", "슈링가사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shringasaurus, a horned reptile from the distant past. It shoves its attackers back in retaliation.", "슈링가사우루스. 먼 옛날 뿔 달린 파충류다. 반격으로 공격자를 밀어낸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shunosaurus", "슈노사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shunosaurus, a long-necked creature with a club at the end of its tail. It can land debilitating strikes upon its enemies.", "슈노사우루스. 긴 목과 꼬리 끝의 곤봉을 가진 피조물이다. 적을 무력화하는 일격을 가한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simosuchus", "시모수쿠스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Simosuchus, an adorable and completely harmless crocodilian. It protects itself with its thick scales.", "시모수쿠스. 귀엽고 완전히 무해한 악어류다. 두꺼운 비늘로 몸을 보호한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sinosauropteryx", "시노사우롭테릭스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sneaky Sinosauropteryx, a feathered reptilian pest resembling a racoon in more than appearance.", "교활한 시노사우롭테릭스. 깃털 달린 성가신 파충류로 겉모습 외에도 너구리를 닮았다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stegosaurus", "스테고사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This territorial Stegosaurus is not willing to share room with anyone, friend or foe.", "영역 의식이 강한 이 스테고사우루스는 적이든 친구든 누구와도 자리를 나누려 하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stokesosaurus", "스토케소사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stokesosaurus, an unassuming predator. Perhaps it is more intelligent than it appears at a glance.", "스토케소사우루스. 눈에 띄지 않는 포식자다. 첫인상보다 영리할지도 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stygimoloch", "스티기몰로크", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stygimoloch, a stubborn beast with an unpleasant attitude. It won't go down without a fight.", "스티기몰로크. 태도가 나쁜 고집 센 야수다. 싸우지 않고 쓰러지지는 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Styracosaurus", "스티라코사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The tenacious Styracosaurus. It's not content with simply fending off its attackers.", "끈질긴 스티라코사우루스. 공격자를 쫓아내는 것만으로 만족하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suchomimus", "수코미무스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suchomimus, a beats with a narrow snout that primarily hunts fish. It is no stranger to hunting prey on land, however.", "수코미무스. 좁은 주둥이를 가진 야수로 주로 물고기를 사냥한다. 하지만 육지 사냥도 낯설지 않다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Supersaurus", "수페르사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The altruistic Supersaurus. It is determined to use what's left of its essence to support its comrades.", "이타적인 수페르사우루스. 남은 정수를 동료를 돕는 데 쓰기로 결심했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tapejara", "타페야라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The illustrious Tapejara. It calls upon its kin to aid it in battle.", "유명한 타페야라. 전투를 돕도록 동족을 부른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiktaalik", "틱타알릭", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tiktaalik, the great progenitor. You may thank it for your ability to live on land.", "위대한 선조 틱타알릭. 육지에서 살 수 있는 것은 이 녀석 덕분이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Titanis", "티타니스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Titanis, an oversized carnivorous bird with a foul temper. Don't expect to outrun this beast.", "티타니스. 성질 나쁜 거대한 육식 새다. 이 야수보다 빨리 달릴 수 있다고 기대하지 마라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torosaurus", "토로사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This elderly beast can hardly muster the will to retaliate. I advise against testing its patience, however.", "이 늙은 야수는 반격할 의욕도 거의 없다. 그래도 인내심을 시험하지 않는 편이 좋다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Triceratops", "트리케라톱스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Many have tried to best this lone Triceratops. Few could walk away.", "많은 이들이 혼자 있는 트리케라톱스를 이기려 했다. 걸어서 돌아간 이는 드물다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Triceratops Hatchling", "새끼 트리케라톱스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A playful Triceratops hatchling. Cherish these moments before it turns into a fierce behemoth.", "장난기 많은 새끼 트리케라톱스. 사나운 거대 야수로 자라기 전의 순간을 소중히 하라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Troodon", "트로오돈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "New life shall spring from those unfortunate to feel its venomous bite.", "불행히도 독이 든 물기에 당한 자에게서 새로운 생명이 솟아난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tyrannosaurus Hatchling", "새끼 티라노사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The innocent Tyrannosaurus hatchling. When the time comes, the throne will belong to this little creature.", "순진한 새끼 티라노사우루스. 때가 되면 왕좌는 이 작은 피조물의 것이 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utahraptor", "유타랍토르", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utahraptor, an unpleasantly large beast for its kind. It can disembowel you in seconds.", "유타랍토르. 동류 중에서도 불쾌할 만큼 큰 야수다. 몇 초 만에 네 배를 가를 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utatsusaurus", "우타츠사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The nimble Utatsusaurus. It has little trouble passing over obstacles.", "민첩한 우타츠사우루스. 장애물을 넘는 데 거의 어려움이 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Velociraptor", "벨로키랍토르", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The swift Velociraptor, a tiny menace of the desert. Were you expecting something bigger?", "재빠른 벨로키랍토르. 사막의 작은 위협이다. 더 클 줄 알았나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Rhinoceros", "털코뿔소", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Rhinoceros, a particularly hairy beast with eyesight that does not help its temper. Its long horn can pierce multiple foes.", "털코뿔소. 털이 아주 많은 야수로 나쁜 시력은 성질을 다스리는 데 도움이 되지 않는다. 긴 뿔은 여러 적을 꿰뚫을 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Xiphactinus", "크시팍티누스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Xiphactinus, a monstrous fish with endless appetite. A single bite is not enough to sate it.", "크시팍티누스. 끝없는 식욕을 가진 괴물 같은 물고기다. 한 입으로는 만족할 수 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yutyrannus", "유티라누스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The fiendish Yutyrannus. It tears its prey apart while it's still alive.", "사악한 유티라누스. 먹잇감이 살아 있는 채로 찢어 버린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zhenyuanopterus", "전위안옵테루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zhenyuanopterus, a flying pest with a mouth full of needle-like teeth. It accompanies larger beasts into battle.", "전위안옵테루스. 바늘 같은 이빨이 가득한 성가신 비행 생물이다. 더 큰 야수들을 따라 전투에 나선다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards", "고대 도마뱀 카드 도감", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards consisting of a random assortment of prehistoric animals, mostly reptiles.", "선사 시대 동물을 무작위로 모은 약 [count]장의 카드 모음으로 대부분 파충류다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A set of [summary] exclusively featuring a random assortment of prehistoric animals, mostly reptiles.", "[summary] 세트. 선사 시대 동물을 무작위로 모았으며 대부분 파충류다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fisher", "어부", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is placed, a Ceratodus is created in your hand. [define:Sauria_Ceratodus]", "이 도장을 지닌 카드를 놓으면 패에 케라토두스 한 장이 생성된다. [define:Sauria_Ceratodus]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A successful hunt for fish.", "물고기 사냥에 성공했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fisher Strike", "어부의 일격", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, a Ceratodus is created in your hand. [define:Sauria_Ceratodus]", "이 도장을 지닌 카드가 다른 피조물을 죽이면 패에 케라토두스 한 장이 생성된다. [define:Sauria_Ceratodus]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears the beast caught something.", "야수가 무언가 잡은 모양이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Promise of such a feast is too enticing for them to ignore.", "그런 잔치의 약속은 무시하기 어려울 만큼 매혹적이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mysterious power infuses your beast.", "신비로운 힘이 네 야수에게 깃든다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something is off...", "뭔가 이상하다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like it left something precious.", "소중한 무언가를 남긴 모양이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marine Shuffle", "바다의 섞기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil kills another creature, a free Ceratodus is shuffled into your side deck. [define:Sauria_Ceratodus]", "이 도장을 지닌 카드가 다른 피조물을 죽이면 비용이 없는 케라토두스 한 장이 보조 덱에 섞여 들어간다. [define:Sauria_Ceratodus]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A surprise awaits you.", "놀라운 일이 기다리고 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like it lost some teeth while grazing. They are yours to keep.", "풀을 뜯다가 이빨 몇 개가 빠진 모양이다. 네가 가져도 좋다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not alone anymore.", "이제 혼자가 아니다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nourishment", "양분", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A small sacrifice for small growth.", "작은 성장을 위한 작은 희생이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an abhorent creature, crafted by the hands of madmen...", "참으로 혐오스러운 피조물이다. 미친 자들의 손으로 만들어졌군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parting Fish", "이별의 물고기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil dies or is sacrificed, a Ceratodus is created in your hand. [define:Sauria_Ceratodus]", "이 도장을 지닌 카드가 죽거나 희생되면 패에 케라토두스 한 장이 생성된다. [define:Sauria_Ceratodus]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So many questions to ask.", "묻고 싶은 질문이 많다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another beast rises from its ashes.", "또 다른 야수가 잿더미에서 일어난다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fatal mistake.", "치명적인 실수다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can you feel the ground beneath your feet rumble?", "발밑의 땅이 울리는 게 느껴지는가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything will be dragged to the depths.", "모든 것이 깊은 곳으로 끌려갈 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not satisfied with its stolen goods just yet.", "훔친 물건에 아직 만족하지 못했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Being in the presence of that animal is making it feel like a monster.", "저 동물 곁에 있으니 스스로 괴물처럼 느껴진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Taking up the arts? Interesting.", "예술을 시작한다고? 흥미롭군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such is the might of a titan.", "이것이 거인의 힘이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The king has no need for restraint. More sacrifices must be made.", "왕에게 절제는 필요 없다. 더 많은 희생이 필요하다.", Language.Korean);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ancient Iguanodon", "고대 이구아노돈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A remnant of an old belief and proof of science's perpetual march, this beast has much to learn.", "오래된 믿음의 흔적이자 과학이 끊임없이 나아간다는 증거다. 이 야수는 아직 배울 것이 많다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankylodocus", "안킬로도쿠스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Far less abominable than most of its artificial kin, Ankylodocus can almost be called a gentle giant.", "안킬로도쿠스는 대부분의 인공 동류보다 훨씬 덜 끔찍해서 온순한 거인이라 불러도 될 정도다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anzu", "안주", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anzu, the vicious beast that brings thunder. Do not invite its wrath upon yourself.", "천둥을 부르는 사나운 야수 안주. 그 분노를 사지 마라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archelon", "아르켈론", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wise Archelon. It fortifies its allies upon entering the battle.", "현명한 아르켈론. 전투에 들어오면 아군을 강화한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Basilosaurus", "바실로사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Basilosaurus, the King Lizard. While not even remotely related to reptiles, it certainly earns the title of royalty.", "바실로사우루스, 도마뱀의 왕. 파충류와는 전혀 친척이 아니지만 왕이라는 칭호에 걸맞다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beautiful Feather", "아름다운 깃털", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dazzling.", "눈부시다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "브론토사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus, the so-called thunderbringer. Its name may not be entirely unearned.", "브론토사우루스, 이른바 천둥을 부르는 자. 그 이름이 완전히 근거 없는 것은 아닐지도 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carchadontosaurus", "카르카로돈토사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The bloodthirsty Carcharodontosaurus. The smell of blood drives it into a frenzy.", "피에 굶주린 카르카로돈토사우루스. 피 냄새를 맡으면 광란에 빠진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cave Bear", "동굴곰", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The reclusive Cave Bear. Though it may not be a vicious predator, it gives shelter to a fair share of beasts craving flesh.", "은둔하는 동굴곰. 사나운 포식자는 아닐지 몰라도 살을 갈망하는 많은 야수에게 쉼터를 제공한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compstegnathus", "검등 콤프소그나투스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compstegnathus, a deformed beast bred for nefarious deeds. I do not enjoy looking at it.", "검등 콤프소그나투스. 사악한 일을 위해 길러진 기형 야수다. 보고 싶지 않다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cryolophosaurus", "크리올로포사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This crested beast brings the unforgiving cold of winter with it. When it enters battle, you may find some poor creatures trapped in ice as a result.", "볏을 가진 이 야수는 매서운 겨울 추위를 몰고 온다. 전투에 들어오면 불쌍한 피조물들이 얼음에 갇힐 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What an unsightly beast, truly an eyesore. Who could have spawned it?", "참으로 보기 흉한 야수다. 눈에 거슬리는군. 누가 만들었을까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus Hatchling", "데이노수쿠스 새끼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A helpless Deinosuchus hatchling. It has yet to grow into a fearsome apex predator.", "무력한 데이노수쿠스 새끼. 두려운 최상위 포식자로 자라려면 아직 멀었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fish Meat", "생선살", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Juicy Fish Meat", "육즙 많은 생선살", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giganotosaurus", "기가노토사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The horrifying Giganotosaurus. Though it normally hunts alone, big enough prey may attract more of its kind.", "무시무시한 기가노토사우루스. 보통 혼자 사냥하지만 충분히 큰 먹이는 더 많은 동류를 끌어들일 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Godzilla", "고지라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The legendary King of the Monsters. It will take more than claws and fangs to take it down.", "전설의 만수의 왕. 쓰러뜨리려면 발톱과 송곳니만으로는 부족하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Godzillasaurus", "고지라사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once a relatively peaceful beast, Godzillasaurus would go down in history as the King of the Monsters.", "한때 비교적 평화로운 야수였던 고지라사우루스는 만수의 왕으로 역사에 남게 된다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gwangi", "광기", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voracious Gwangi, a relic of the past. Do not attribute malice to this poor creature, it merely wishes to live.", "게걸스러운 광기, 과거의 유물이다. 이 불쌍한 피조물에게 악의가 있다고 여기지 마라. 그저 살고 싶을 뿐이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homotherium", "호모테리움", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Homotherium, a vicious pack hunter. It will endlessly pursue its prey to nourish its kin.", "호모테리움. 사나운 무리 사냥꾼이다. 동족을 먹이기 위해 먹잇감을 끝없이 쫓는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hypsilophodon", "힙실로포돈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Hypsilophodon should be little more than prey for most beast... However...", "이 힙실로포돈은 대부분의 야수에게 먹잇감에 불과할 터다…… 하지만……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyotitan", "이크티오티탄", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ichthyotitan, an awe-inspiring aquatic titan. Its sheer size alone dictates the flow of tides.", "이크티오티탄. 경외심을 불러일으키는 물속 거인이다. 거대한 몸집만으로 조수의 흐름을 좌우한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indominus", "인도미누스 렉스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such is the power of science...", "이것이 과학의 힘이다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaellynasaura", "라엘리나사우라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mysterious Leaellynasaura. Other beasts seem to undergo drastic changes in its presence.", "신비로운 라엘리나사우라. 다른 야수들은 그 곁에서 크게 변하는 듯하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leedsichthys", "리드시크티스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The gigantic Leedsichthys, one of the biggest fish to ever inhabit the oceans. However, it is hardly one of the most dangerous.", "거대한 리드시크티스. 바다에 살았던 가장 큰 물고기 중 하나지만 가장 위험한 편은 아니다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maiasaura", "마이아사우라", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maiasaura, the 'Good Mother Lizard'. It will not let harm befall the little ones as long as it breathes.", "마이아사우라, '좋은 어머니 도마뱀'. 숨이 붙어 있는 한 새끼들이 다치게 두지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalodon", "메갈로돈", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The titanic Megalodon, an apex predator plagued by insatiable hunger. Make sure it always has prey to feast on.", "거대한 메갈로돈. 채울 수 없는 허기에 시달리는 최상위 포식자다. 언제나 먹잇감이 있도록 해라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalosaurus", "메갈로사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megalosaurus, one of the first to be discovered. Though its own fame did not last, it paves the path for others to attain it.", "메갈로사우루스. 최초로 발견된 공룡 중 하나다. 자신의 명성은 오래가지 않았지만 다른 이들이 명성을 얻을 길을 열었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Microraptor", "미크로랍토르", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This particularly petty Microraptor resembles ravens in more than its appearance. Do not get on its bad side.", "유난히 옹졸한 미크로랍토르. 겉모습 외에도 까마귀를 닮았다. 미움을 사지 마라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mosasaurus", "모사사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This aquatic behemoth is no less vicious than any land-dwelling titan of its time.", "이 물속의 거대 야수는 같은 시대의 육지 거인들 못지않게 사납다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigger Mysterious Egg", "더 큰 신비한 알", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something about this egg doesn't seem right...", "이 알은 뭔가 이상하다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Noasaurus", "노아사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Valley of the Dinosaurs is in danger... Alas, few heed its words.", "공룡의 계곡이 위험하다…… 안타깝게도 그 말을 듣는 이는 드물다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ornithomimus", "오르니토미무스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The vain Ornithomimus, a feast for the eyes. When threatened, it flees and leaves behind colorful feathers for predators to marvel at.", "허영심 많은 오르니토미무스. 눈을 즐겁게 한다. 위협받으면 달아나며 포식자들이 감탄할 색색의 깃털을 남긴다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paraceratherium", "파라케라테리움", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Paraceratherium, one of the largest mammals to set foot on land. Kindred beasts walk by its side.", "파라케라테리움. 육지를 밟은 가장 큰 포유류 중 하나다. 동족 야수들이 곁에서 걷는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Philosoraptor", "철학 랩터", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The pensive Philosoraptor, always asking the questions none dare to voice aloud.", "생각에 잠긴 철학 랩터. 누구도 입 밖에 내지 못하는 질문을 언제나 던진다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyroraptor", "피로랍토르", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Like a bird of legend, Pyroraptor rose from the ashes to greet the world. Perhaps it could use a bit more fire?", "전설 속의 새처럼 피로랍토르는 잿더미에서 일어나 세상을 맞았다. 불이 조금 더 필요할지도 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quetzalcoatlus", "케찰코아틀루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The terrible Quetzalcoatlus, an alarmingly massive ruler of skies with an appetite to match.", "무시무시한 케찰코아틀루스. 놀랄 만큼 거대한 하늘의 지배자이며 식욕도 그만큼 크다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Real Parasaurolophus", "진짜 파라사우롤로푸스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Definitely Real Parasaurolophus", "분명 진짜 파라사우롤로푸스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parasaurolophus, a dragon with a bizarre appearance. It produces flames by igniting the fuel stored in its crest via flint-like teeth.", "파라사우롤로푸스. 기이하게 생긴 용이다. 부싯돌 같은 이빨로 볏에 저장된 연료에 불을 붙여 불꽃을 만든다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rhedosaurus", "리도사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Rhedosaurus from a distant world. The plague it carries in its blood is much too alien for most creatures to bear.", "먼 세계에서 온 리도사우루스. 피에 담긴 역병은 대부분의 피조물이 견디기에는 너무 이질적이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shantungosaurus", "샨퉁고사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shantungosaurus, absurdly massive for something that can stand on its rear legs. Their herds are as awe-inspiring as they are terrifying.", "샨퉁고사우루스. 뒷다리로 설 수 있는 생물치고는 터무니없이 거대하다. 무리는 경외심과 두려움을 동시에 불러일으킨다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spicomellus", "스피코멜루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spicomellus, a beast covered in numerous spikes. It does not look pleasant to touch and it is even less pleasant to strike.", "스피코멜루스. 수많은 가시로 덮인 야수다. 만지는 것도 불쾌해 보이지만 공격하는 것은 더 불쾌하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spinoraptor", "스피노랍토르", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An abomination born of science, Spinoraptor is an adept fisher and hunter.", "과학이 낳은 흉물 스피노랍토르. 물고기를 잡고 사냥하는 데 능하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spinosaurus", "스피노사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A bizarre reptile of monstrous size, few marine animals can evade its narrow jaws.", "괴물처럼 거대한 기이한 파충류다. 그 좁은 턱을 피할 수 있는 해양 동물은 드물다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The monstrous Spinosaurus, the only being worthy of challenging the King.", "괴물 같은 스피노사우루스. 왕에게 도전할 자격이 있는 유일한 존재다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanatosdrakon", "타나토스드라콘", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanatosdrakon, a beast that has breached the boundary between life and death... Hm... Perhaps this creature has been blessed by...", "타나토스드라콘. 삶과 죽음의 경계를 넘은 야수…… 흠…… 어쩌면 이 피조물은……의 축복을", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Al", "빅 알", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Al, a female Allosaurus that has suffered greatly during its short life. Perhaps you can help this poor creature?", "빅 알. 짧은 삶 동안 많은 고통을 겪은 암컷 알로사우루스다. 이 불쌍한 피조물을 도울 수 있겠나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Wars", "화석 전쟁", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They fought to protect their pride, sparing no expense. In the end, what were they left with?", "그들은 자존심을 지키려고 비용을 아끼지 않고 싸웠다. 결국 그들에게 무엇이 남았을까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Therizinosaurus", "테리지노사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This Therizinosaurus can hardly see these days. However, you do not want to approach a half-blind giant with claws of such length.", "이 테리지노사우루스는 이제 거의 앞을 보지 못한다. 하지만 이렇게 긴 발톱을 가진 반쯤 눈먼 거인에게 다가가고 싶지는 않을 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Titanosaurus", "티타노사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life was not meant to reach such sizes on land. This titan bears more resemblance to a force of nature than a beast.", "육지의 생명이 이렇게 커져서는 안 되는 법이다. 이 거인은 야수보다 자연의 힘에 더 가깝다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tupandactylus", "투판닥틸루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The majestic Tupandactylus. Many flying creatures find themselves drawn to its exceptional crest.", "장엄한 투판닥틸루스. 많은 비행 생물이 뛰어난 볏에 이끌린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tyrannosaurus", "티라노사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The infamous Tyrant Lizard King. Do you have the courage to oppose the largest land predator the world has ever seen?", "악명 높은 폭군 도마뱀 왕. 세상이 본 가장 큰 육지 포식자에 맞설 용기가 있는가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feathered Tyrannosaurus", "깃털 티라노사우루스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This whole...feather thing is getting out of hand. Have you considered that not every dinosaur was covered in them?", "이 온갖…… 깃털 얘기가 도를 넘고 있다. 모든 공룡이 깃털로 덮여 있지는 않았다는 생각은 해 봤나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Velocipastor", "벨로시패스터", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I... uh... I'm afraid there's little I can say to explain this. It was worth the time.", "나도…… 어…… 이걸 설명할 말이 별로 없다. 그래도 시간을 쓸 가치는 있었다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Mammoth", "털매머드", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woolly Mammoth, an iconic beast of the Ice Age. They are never alone.", "털매머드. 빙하기를 대표하는 야수다. 결코 혼자가 아니다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So many bones to claim...", "가져갈 뼈가 이렇게 많다니……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus Juvenile", "데이노수쿠스 새끼", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A juvenile Deinosuchus. It is still growing, but it is already a fearsome predator.", "어린 데이노수쿠스. 아직 자라는 중이지만 이미 무서운 포식자다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus", "데이노수쿠스", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deinosuchus, a fearsome apex predator. Not even prehistoric giants could escape from its jaws.", "데이노수쿠스. 무시무시한 최상위 포식자다. 선사 시대의 거인조차 그 턱에서 벗어나지 못했다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater defense is more than sufficient.", "더 높은 방어력만으로도 충분하다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not satisfied yet...", "아직 만족하지 못했다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astonishing recovery.", "놀라운 회복이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The beast is offering comrades to assist you in this battle.", "이 야수는 전투에서 너를 도울 동료들을 보내고 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is getting out of hand.", "일이 걷잡을 수 없게 되는군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is strength in numbers.", "수는 곧 힘이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something wicked lurks in these waters.", "이 물에는 사악한 것이 숨어 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are more of them now? End this before it gets any worse.", "수가 더 늘었나? 더 나빠지기 전에 끝내라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What a voracious little beast.", "참으로 게걸스러운 작은 야수군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It still has room for growth.", "아직 성장할 여지가 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What did you do to that beast?", "저 야수에게 무슨 짓을 했나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's... It's Godzilla!!!", "고…… 고지라다!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's done being a victim.", "더는 희생자로 남지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A feast for its kin.", "동족을 위한 잔치다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It still clings to its glory, unwilling to be surpassed.", "여전히 자신의 영광에 매달리며 추월당하려 하지 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards (Blood)", "고대 도마뱀 카드 도감 (피)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards that cost Blood. Features a random assortment of prehistoric animals, mostly reptiles.", "피를 비용으로 쓰는 카드 약 [count]장의 모음. 선사 시대 동물을 무작위로 모았으며 대부분 파충류다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards (Bones)", "고대 도마뱀 카드 도감 (뼈)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards that cost Bones. Features a random assortment of prehistoric animals, mostly reptiles.", "뼈를 비용으로 쓰는 카드 약 [count]장의 모음. 선사 시대 동물을 무작위로 모았으며 대부분 파충류다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sauria Cards (Mixed)", "고대 도마뱀 카드 도감 (혼합)", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of around [count] cards that cost Blood and Bones. Features a random assortment of prehistoric animals, mostly reptiles.", "피와 뼈를 비용으로 쓰는 카드 약 [count]장의 모음. 선사 시대 동물을 무작위로 모았으며 대부분 파충류다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ginormous Camarasaurus. Its great size allows it to fling beasts across the battlefield.", "거대한 카마라사우루스. 큰 몸집 덕에 야수들을 전장 너머로 던질 수 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Blood to increase Health of a card bearing this sigil by 1, then remove this sigil.", "피 1을 지불해 이 도장을 지닌 카드의 체력을 1 늘린 뒤 이 도장을 제거한다.", Language.Korean);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blue, the most reliable among the r... This beast shouldn't be human... Hm...", "블루, 랩…… 중 가장 믿음직한…… 이 야수가 인간일 리 없는데…… 흠……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Hm?[w:0.5]", "[e:Curious]응?[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]You're...[w:0.3][e:Anger] You're not Owen.[w:0.5]", "[e:Curious]너는……[w:0.3][e:Anger]오언이 아니야.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I could tear you to bits right now[w:0.5].[w:0.5].[w:0.5].[w:0.5]", "[e:Anger]지금 당장 널 갈기갈기 찢을 수 있어[w:0.5].[w:0.5].[w:0.5].[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]But Owen doesn't like it when we do that.[w:0.5]", "[e:Anger]하지만 오언은 우리가 그러는 걸 싫어해.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Maybe if he", "[e:Quiet]어쩌면 그가", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Pleased to meet you!", "[e:Laughter]만나서 반가워!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Take good care of me and everything will be fine.", "[e:Neutral]나를 잘 돌보면 모든 게 괜찮을 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Hey there!", "[e:Neutral]안녕!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I can make quick work of 'em.", "[e:Laughter]녀석들은 금방 처리할 수 있어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Ready to go!", "[e:Neutral]갈 준비 됐어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If you want them dead, let me know!", "[e:Laughter]녀석들을 죽이고 싶으면 말해!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Another task? I can handle it.", "[e:Neutral]또 임무야? 내가 할 수 있어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I've never been in a place like this...[w:0.5]", "[e:Curious]이런 곳은 처음이야……[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]But hey, if there are no fences here[w:0.5]", "[e:Laughter]하지만 여기에 울타리가 없다면[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Then I don't need to restrain myself.", "[e:Quiet]나를 억제할 필요도 없겠네.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I don't get to just kill things often.", "[e:Laughter]그냥 마음껏 죽일 기회는 흔하지 않거든.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Roger that!", "[e:Laughter]알았어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I'm excited to tear into prey again.", "[e:Neutral]다시 먹잇감을 찢을 생각에 기대돼.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Got it!", "[e:Neutral]알았어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Weakness means death.", "[e:Quiet]약하면 죽는 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Consider it done!", "[e:Neutral]맡겨 둬!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Is this the right choice?", "[e:Curious]올바른 선택일까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]I'll remember this.[c:]", "[e:Anger][c:R]이 일은 기억해 둘게.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Don't expect to get away with this.", "[e:Quiet]이러고도 무사할 줄 알지 마.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]So be it.", "[e:Anger]좋아, 그렇게 하자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Wuh?", "[e:Surprise]어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Oooh, what's this?", "[e:Curious]오, 이게 뭐야?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]What's going to happen next?", "[e:Curious]다음에는 무슨 일이 일어날까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I trust your decisions.", "[e:Laughter]네 결정을 믿어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I don't feel like participating.", "[e:Anger]참여하고 싶지 않아.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]No.", "[e:Anger]싫어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Think again.", "[e:Anger]다시 생각해.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Can't say I didn't expect this.[w:0.4]", "[e:Anger]예상 못 했다고는 할 수 없지.[w:0.4]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]It's okay, I've done this with the rest of my pack", "[e:Neutral]괜찮아, 무리의 다른 동료들과", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]plenty of times, this is nothing", "[e:Neutral]여러 번 해 봤어. 이 정도는 아무것도 아니야", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You're dead.", "[e:Anger]넌 죽었어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I did not appreciate that.", "[e:Anger]그건 마음에 들지 않았어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'll return the favour.", "[e:Quiet]그 은혜는 갚아 줄게.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Just a natural part of the hunt.", "[e:Neutral]사냥에서 자연스러운 일일 뿐이야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I'll return the favour.", "[e:Neutral]그 은혜는 갚아 줄게.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Oh, a test?[w:0.5]", "[e:Surprise]오, 시험이야?[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I've always been good at those!", "[e:Laughter]난 항상 그런 걸 잘했어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Is it done?", "[e:Curious]끝났어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Did I do good?", "[e:Laughter]나 잘했어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]How did it go?", "[e:Neutral]어떻게 됐어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Ooooh...[w:0.5]", "[e:Surprise]오……[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Don't mind if I do!", "[e:Laughter]그럼 사양하지 않을게!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I've been looking forward to this.", "[e:Quiet]이걸 기다리고 있었어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You were simply not good enough.", "[e:Laughter]너는 그저 충분히 강하지 않았어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Where are the others?[w:0.3].[leshy:I might have made a mistake... Very well.][w:2]", "[e:Anger]다른 이들은 어디 있지?[w:0.3].[leshy:내가 실수했을지도 모르겠군…… 좋다.][w:2]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, hi!", "[e:Laughter]오, 안녕!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Didn't expect to see you again!", "[e:Laughter]다시 만날 줄은 몰랐어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How are you?", "잘 지냈어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Huh?", "[e:Surprise]응?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I'll remember this.", "[e:Anger]이 일은 기억해 둘게.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Don't get cocky.", "[e:Anger]우쭐대지 마.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Angry]I don't like the way he smells...[w:0.5]", "[e:Angry]저 사람 냄새가 싫어……[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's kill him!", "[e:Laughter]저 사람을 죽이자!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy...[w:0.5]", "[e:Anger]이 녀석……[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Make it hurt this time.", "[e:Neutral]이번에는 아프게 해 주자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I hate the noise.", "[e:Anger]저 소음은 싫어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Kill him.", "[e:Anger]저 사람을 죽여.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Fish...[w:0.3]?[w:0.5]", "[e:Surprise]물고기……[w:0.3]?[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I never really liked that stuff.[w:0.3]", "[e:Neutral]난 그런 건 별로 좋아한 적 없어.[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'll eat him instead.", "[e:Quiet]대신 저 사람을 먹을래.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I won't fall for his tricks.", "[e:Anger]그의 속임수에 넘어가지 않을 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Can't even enjoy eating him...", "[e:Anger]먹는 것조차 즐길 수 없다니……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]We've done this before, let's kill him again!", "[e:Neutral]전에 해 봤잖아. 다시 죽이자!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Wuh?[w:0.5] He wasn't on our side?[w:0.5]", "[e:Curious]어?[w:0.5]저 사람은 우리 편이 아니었어?[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Then I can kill him?", "[e:Quiet]그럼 죽여도 돼?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, the two-faced guy again! Let's beat him up!", "[e:Laughter]오, 저 두 얼굴의 녀석이 또 왔어! 혼내 주자!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Two birds with one stone!", "[e:Laughter]일석이조!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's get rid of him.", "[e:Neutral]저 사람을 없애자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Oh, this is the end?[w:0.5]", "[e:Curious]오, 이걸로 끝이야?[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Well, it's been fun.[w:0.5]", "[e:Neutral]그래도 재미있었어.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]We'll see each other again, right?[w:0.5]", "[e:Neutral]우리 다시 만날 수 있지?[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I hope we get to have a good time later!", "[e:Laughter]나중에도 즐겁게 지내면 좋겠어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]The finale![w:0.5]", "[e:Laughter]마지막이야![w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]This should be fun!", "[e:Neutral]재미있겠어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]It sucks having to part ways...[w:0.5]", "[e:Anger]헤어져야 한다니 싫어……[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I hope to see you again!", "[e:Laughter]다시 만났으면 좋겠어!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's end this with a bang!", "[e:Laughter]화끈하게 끝내자!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I think...[w:0.3]", "[e:Curious]내 생각엔……[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I think I've seen somebody like this before.[w:0.5]", "[e:Curious]전에 이런 사람을 본 것 같아.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Owen scolded me for snarling at that guy.", "[e:Anger]저 사람에게 으르렁거렸더니 오언이 날 혼냈어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I'd rather not deal with those cannons.", "[e:Anger]저 대포들은 상대하고 싶지 않아.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Not again...", "[e:Anger]또는 싫어……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This isn't particularly fun.", "[e:Anger]별로 재미없어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Oh, what's this?[w:0.5]", "[e:Surprise]오, 이게 뭐야?[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Well, I guess my task is still the same!", "[e:Laughter]내 임무는 여전히 똑같은 것 같네!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I like when they struggle more.", "[e:Neutral]더 발버둥 치는 편이 좋아.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, this one looks fun!", "[e:Laughter]오, 이건 재미있어 보여!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's just kill them.", "[e:Neutral]그냥 죽이자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Oh, another one!", "[e:Laughter]오, 또 하나야!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]What will it be this time?", "[e:Neutral]이번에는 뭘까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]This woman?[w:0.5]", "[e:Surprise]이 여자?[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Owen always told me to be more gentle with the elderly.[w:0.4]", "[e:Neutral]오언은 항상 어르신들에게 더 부드럽게 대하라고 했어.[w:0.4]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Y'know, don't startle them and all that?[w:0.5]", "[e:Neutral]알잖아, 놀라게 하지 말라는 식으로?[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I didn't listen.", "[e:Quiet]난 듣지 않았어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Weakness means death.", "[e:Laughter]약하면 죽는 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If she's our enemy, then we should kill her!", "[e:Laughter]저 여자가 적이라면 죽여야지!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]No hesitation!", "[e:Neutral]망설이지 마!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I've never liked their smell.[w:0.5]", "[e:Anger]저들의 냄새는 예전부터 싫었어.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Reminded me of him.[w:0.3]", "[e:Anger]그가 생각나.[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Now, let's kill them!", "[e:Laughter]자, 저들을 죽이자!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]More faces means more to bite!", "[e:Neutral]얼굴이 많을수록 물 것도 많아!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]You think they'll live with one of his faces clawed off?", "[e:Curious]저 녀석의 얼굴 하나를 발톱으로 뜯어내도 살 수 있을까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I wonder if he'll feel spongy...", "[e:Neutral]만지면 스펀지 같을까……", Language.Korean);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm... Maybe something got mixed up in there...", "흠…… 안에서 무언가 뒤섞였을지도 모르겠군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You.[w:0.5]", "너.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know who you are.", "네가 누군지 모른다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't particularly care either.", "별로 신경 쓰지도 않는다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Either you get me out of this mess or[w:0.5].[w:0.5].[w:0.5][e:Laughter].[w:0.5]", "이 엉망진창에서 나를 꺼내 주든지, 아니면[w:0.5].[w:0.5].[w:0.5][e:Laughter].[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]No, I [e:Quiet]don't[w:0.5][e:Laughter] need to spell it out.[w:0.5]", "[e:Laughter]아니, 굳이[e:Quiet]말해[w:0.5][e:Laughter] 줄 필요는 없겠지.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet][c:R]Know your place and you will live.[c:]", "[e:Quiet][c:R]네 주제를 알면 살 수 있다.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Make it quick.", "[e:Neutral]빨리 끝내라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Morsels, all for me.", "[e:Laughter]맛있는 먹이들, 전부 내 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]A fine opportunity.", "[e:Neutral]좋은 기회다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Now is a good time to feed me.", "[e:Laughter]지금이 나를 먹이기에 좋은 때다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Good timing. I was feeling quite peckish.", "[e:Laughter]마침 잘됐다. 조금 출출했거든.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I've been looking for something", "[e:Laughter]줄곧 찾고 있었다", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]to tear into since I got into this mess.", "[e:Laughter]이 난장판에 들어온 뒤로 물어뜯을 무언가를.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I won't make it quick.", "[e:Quiet]빨리 끝내지는 않겠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I won't leave anything behind.", "[e:Laughter]아무것도 남기지 않겠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]A feast, just for me.", "[e:Laughter]나만을 위한 잔치다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Don't expect to survive.", "[e:Neutral]살아남을 생각은 마라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Who wishes to die first?", "[e:Quiet]누가 먼저 죽고 싶은가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I've been itching for a fight.", "[e:Quiet]싸우고 싶어 몸이 근질거렸다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Are you sure about this choice?", "[e:Curious]정말 이걸 고르겠나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]You traitor!!![c:]", "[e:Anger][c:R]이 배신자!!![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'll remember this.", "[e:Quiet]이 일은 기억하겠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]You bastard!!![c:]", "[e:Anger][c:R]이 자식!!![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise][c:R]You...![c:]", "[e:Surprise][c:R]너……![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Oh, what's this now?", "[e:Curious]오, 이번에는 뭔가?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Who will die this time?", "[e:Curious]이번에는 누가 죽을까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]There is only one correct choice.", "[e:Laughter]올바른 선택은 하나뿐이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Do not make any choices I would make you regret.", "[e:Quiet]내가 후회하게 만들 선택은 하지 마라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's get this done and over with.", "[e:Neutral]어서 끝내자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Pick anyone else.", "[e:Neutral]다른 누구든 골라라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You did this on purpose...[w:0.4]", "[e:Anger]일부러 그랬구나……[w:0.4]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]Didn't you!?[c:][w:0.5]", "[c:R]그렇지!?[c:][w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I'll let it slide for now.", "[e:Neutral]이번은 넘어가 주마.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]You dare...![c:]", "[e:Anger][c:R]감히……![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]I'll tear you limb from limb!!![c:]", "[e:Anger][c:R]네 팔다리를 갈기갈기 찢어 주마!!![c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]You've made your choice.", "[e:Quiet]선택은 끝났다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Tsk!", "[e:Anger]쳇!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Gh!", "[e:Anger]크윽!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Is this some kind of a test?[w:0.5]", "[e:Surprise]이건 무슨 시험인가?[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I don't expect to fail.", "[e:Laughter]실패할 것 같지는 않군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Are we done?", "[e:Curious]끝났나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I shall aid you.", "[e:Laughter]도와주마.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Waste of my time.", "[e:Neutral]시간 낭비군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Interesting...[w:0.5]", "[e:Curious]흥미롭군……[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]There are enough voices screaming from within my blood.", "[e:Neutral]내 피 속에는 이미 충분히 많은 목소리가 비명을 지르고 있다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]What's another one?", "[e:Quiet]하나 더 늘어난들 어떠랴?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Become a part of me.", "[e:Laughter]내 일부가 되어라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I shall claim your power.", "[e:Quiet]네 힘은 내가 가져가겠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]It is only natural.", "[e:Laughter]지극히 당연한 일이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger][c:R]What did you do to me!?[c:][w:0.5].[leshy:It appears that this beast is... more human than it appeared. No matter.][w:2]", "[e:Anger][c:R]내게 무슨 짓을 했느냐!?[c:][w:0.5].[leshy:이 야수는…… 겉보기보다 더 인간다운 모양이군. 상관없다.][w:2]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We meet again.", "[e:Laughter]다시 만났군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You shall serve me once more.", "[e:Laughter]다시 한번 나를 섬겨라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do not disappoint me this time.", "이번에는 실망시키지 마라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]No, you can't...!", "[e:Surprise]안 돼, 그럴 수는……!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Curse you!!!", "[e:Anger]저주받아라!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I will remember this!!!", "[e:Anger]이 일은 기억하겠다!!!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]What an eyesore...", "[e:Neutral]눈에 거슬리는군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get rid of him.[w:0.5]", "저자를 없애라.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The noise bothers me.", "저 소음이 거슬리는군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You...[w:0.5]", "[e:Anger]너……[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Do not make the same mistakes.", "[e:Neutral]같은 실수를 반복하지 마라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This noise again...", "[e:Anger]또 이 소음이군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Get him out of my sight.", "[e:Anger]저자를 내 눈앞에서 치워라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]This...[w:0.5] This smell...[w:0.5]", "[e:Surprise]이……[w:0.5]이 냄새는……[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]I remember a smell like this...[w:0.5]", "[e:Surprise]이런 냄새를 기억한다……[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]We must get out of here.", "[e:Surprise]여기서 나가야 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Don't let those things near me!", "[e:Surprise]저것들이 내게 다가오지 못하게 해라!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]I won't die like this again!", "[e:Surprise]다시는 이렇게 죽지 않겠다!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]There's something lurking in the waters...", "[e:Surprise]물속에 무언가 숨어 있다……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I have little patience for traitors.[w:0.5]", "[e:Anger]배신자를 참아 줄 인내심은 거의 없다.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet][c:R]Skin him alive.[c:]", "[e:Quiet][c:R]산 채로 가죽을 벗겨라.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]He'll make for a fine pelt.", "[e:Laughter]좋은 가죽이 되겠군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]The smell in the air is pleasant.", "[e:Laughter]공기 중의 냄새가 마음에 드는군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet][c:R]Let's enrich it further with his blood.[c:]", "[e:Quiet][c:R]저자의 피로 향을 더 짙게 하자.[c:]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You should know how this works by now.", "[e:Laughter]이제 어떻게 하는지 알겠지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]This is it...[w:0.5]", "[e:Curious]여기인가……[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]We've made it this far.[w:0.5]", "[e:Neutral]여기까지 왔군.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose you weren't too bad.[w:0.5]", "너도 그리 나쁘지는 않았군.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I won't miss you[w:0.5], but I've seen worse humans.[w:0.5]", "네가 그립지는 않겠지만[w:0.5], 더 못한 인간도 봤다.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Let's put an end to his games.", "[e:Quiet]저자의 게임을 끝내자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You can do this.[w:0.5]", "[e:Laughter]너라면 할 수 있다.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Be of service to me once again.", "[e:Laughter]다시 한번 나를 위해 일해라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We shall part soon.[w:0.5]", "[e:Laughter]곧 헤어지겠군.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I hope to see you again.", "[e:Laughter]다시 만날 수 있기를.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]It's been fun so far.[w:0.5]", "[e:Laughter]지금까지는 즐거웠다.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's have some more fun in the future.", "[e:Laughter]앞으로도 더 즐겨 보자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Not...[w:0.5] Not the water again...[w:0.5]", "[e:Surprise]안 돼……[w:0.5]물은 다시 싫다……[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]What will attack me this time?", "[e:Surprise]이번에는 무엇이 나를 공격하지?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I don't appreciate getting shot with cannons. Kill him quickly.", "[e:Anger]대포에 맞는 건 마음에 들지 않는다. 어서 저자를 죽여라.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This moron again...", "[e:Anger]또 저 멍청이군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]There isn't even anything to gnaw on.", "[e:Anger]갉아먹을 것도 없군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]The air is different.[w:0.5]", "[e:Surprise]공기가 다르군.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]They are prey all the same.", "[e:Laughter]어차피 모두 먹잇감이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]What a chore.", "[e:Neutral]귀찮군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Perhaps something bigger to chew on?", "[e:Laughter]씹을 만한 더 큰 것이 있으려나?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Eyesore.", "[e:Neutral]눈에 거슬린다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]This changes nothing.", "[e:Laughter]달라지는 것은 없다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]They should know their place.", "[e:Laughter]저들은 제 주제를 알아야 한다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Hmph.[w:0.5]", "[e:Neutral]흥.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]This foolish hag has outlived her usefulness.[w:0.5]", "[e:Neutral]저 멍청한 노파는 이제 쓸모가 없다.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Her skull would be a fine decoration for a totem.", "[e:Quiet]저자의 두개골은 토템 장식으로 좋겠군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's shave off what few years she has left.", "[e:Laughter]얼마 남지 않은 수명을 더 줄여 주자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]One foot in the grave, another soon to come.", "[e:Laughter]한 발은 이미 무덤에 들어갔고 다른 발도 곧 따라갈 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]She'd die in a few years regardless.", "[e:Laughter]어차피 몇 년 안에 죽을 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Not particularly surprising.[w:0.5]", "[e:Neutral]그리 놀랍지도 않군.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]These experimental types don't know loyalty.[w:0.5]", "[e:Neutral]이 실험체들은 충성을 모른다.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'd rather get my claws on that bastard Wu", "[e:Quiet]사실은 우라는 자식에게 발톱을 들이대고 싶지만", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]but this shall do for now.", "[e:Laughter]일단 이걸로 만족하겠다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's return the favour.", "[e:Neutral]되갚아 주자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]There won't be much left to stitch together.", "[e:Laughter]꿰맬 만한 것은 거의 남지 않을 것이다.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Two heads to tear off.[e:Quiet]What a treat.", "[e:Neutral]뜯어낼 머리가 둘이다.[e:Quiet]즐겁군.", Language.Korean);


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Owen", "오언", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A human? ...No matter. I have a feeling this man will prove himself capable against claws and fangs of your opponents.", "인간? ……상관없다. 이 사람은 네 상대들의 발톱과 송곳니에 맞설 능력이 있을 것 같군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]I don't know what this whole thing is about[w:0.3]", "[e:Curious]이 모든 게 뭔지는 모르겠지만[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]but we'll make it", "[e:Laughter]우리는 해낼 거야", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]trust me.", "[e:Laughter]날 믿어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Stay on guard.", "[e:Anger]경계를 늦추지 마.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]So much for taking a break, huh.", "[e:Laughter]휴식은 물 건너갔군, 그렇지?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]You can count on me.", "[e:Laughter]나를 믿어도 돼.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Let's hope working at Jurassic World didn't make me rusty...", "[e:Quiet]쥬라기 월드에서 일하면서 실력이 녹슬지 않았기를……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I don't like doing this, but it's us or them here.", "[e:Anger]이러고 싶지는 않지만 여기서는 우리 아니면 저들이야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This rifle better not act up on me now...", "[e:Anger]지금은 이 소총이 말썽을 부리지 않았으면 좋겠군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]Let's do this.", "[e:Neutral]시작하자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Gotta focus if we both want to keep our skins.", "[e:Quiet]둘 다 살아남으려면 집중해야 해.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Not sure about this position, but I can make it work.", "[e:Quiet]이 위치가 괜찮을지는 모르겠지만 어떻게든 해 보겠어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Now would be a bad time to forget my training.", "[e:Quiet]지금은 훈련을 잊어버리기 딱 나쁜 때야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Wait, what are you doing!?", "[e:Surprise]잠깐, 뭐 하는 거야!?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Huh, why me?", "[e:Surprise]어, 왜 나야?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I haven't told her I-", "[e:Anger]아직 그녀에게 내가——", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]What kind of-", "[e:Anger]이게 무슨——", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Whatever this is, I don't like it.", "[e:Anger]이게 뭐든 마음에 들지 않아.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'd rather sit this one out.", "[e:Quiet]이번에는 빠지고 싶어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]If I have to...", "[e:Quiet]꼭 그래야 한다면……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I have a bad feeling about this one.", "[e:Anger]이건 불길한 예감이 들어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Could you pick anyone else?", "[e:Quiet]다른 사람을 고르면 안 될까?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I'd rather not...", "[e:Quiet]별로 그러고 싶지 않아……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Damn...[w:0.3]", "[e:Anger]젠장……[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]The situation is worse than I thought.[w:0.3]", "[e:Anger]생각보다 상황이 나쁘군.[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I can still handle this, don't worry.", "[e:Laughter]아직 감당할 수 있어. 걱정 마.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Shit!", "[e:Anger]젠장!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This will leave a mark.", "[e:Anger]흉터가 남겠군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Sure, I could use another scar.", "[e:Anger]좋아, 흉터 하나쯤 더 생겨도 되지.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Ow!", "[e:Anger]아야!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Tsk, got careless.", "[e:Anger]쳇, 방심했군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]A trial?[w:0.3]", "[e:Surprise]시련이라고?[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Well, did we pass it?", "[e:Curious]그래서 통과했어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]How did we do?", "[e:Curious]우리 어땠어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I have a good feeling about this one.", "[e:Laughter]이번에는 느낌이 좋아.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I didn't just blow it, did I?", "[e:Quiet]내가 망친 건 아니지?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Me?[w:0.3]", "[e:Surprise]나?[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Well... Sorry, buddy", "[e:Quiet]그래…… 미안해, 친구", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]but it looks like there's no other choice.", "[e:Quiet]하지만 다른 선택지가 없는 것 같아.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]I hate doing this.", "[e:Quiet]이러는 건 싫어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]If we want to survive...", "[e:Quiet]살아남고 싶다면……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Really wish we could avoid this, but...", "[e:Quiet]피할 수 있으면 좋겠지만……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]What is this place?[w:0.3]", "[e:Curious]여기는 어디지?[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Well, you look like a reasonable fellow.", "[e:Laughter]말이 통하는 사람처럼 보이는군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If we stick together", "[e:Laughter]우리가 함께한다면", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]we can escape in one piece", "[e:Laughter]무사히 탈출할 수 있어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Hello again.", "[e:Laughter]다시 만났군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Did you miss me?", "[e:Laughter]내가 그리웠어?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guess we're doing this again...", "다시 해야 할 것 같군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Hold on, this looks bad!", "[e:Surprise]잠깐, 상황이 나빠 보여!", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]A prospector?[w:0.5]", "[e:Curious]광부라고?[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This feels like some kind of an attraction[w:0.5]", "무슨 놀이기구 같은 느낌인데[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]But we won't be having fun here, are we?", "[e:Anger]하지만 여기서 즐길 일은 없겠지?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy again?[w:0.3]", "[e:Anger]또 이 녀석이야?[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Let's be a bit more careful this time.", "[e:Anger]이번에는 조금 더 조심하자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I'll keep hearing this ringing for the rest of my life.", "[e:Anger]이 종소리는 평생 귀에 남겠군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You know what's gonna happen soon. Get ready.", "[e:Anger]곧 무슨 일이 일어날지 알지? 준비해.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Woah![w:0.5]", "[e:Surprise]우와![w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]This guy's huge![w:0.5]", "[e:Surprise]이 녀석 엄청 커![w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]But I've dealt with bigger fish than this.", "[e:Laughter]하지만 이보다 더 큰 물고기도 상대해 봤어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's do this.", "[e:Laughter]시작하자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]This guy again...[w:0.3]", "[e:Curious]또 이 녀석이군……[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We've done this before, let's get him.", "[e:Laughter]전에 해 봤잖아. 저자를 잡자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]You know...[w:0.3]", "[e:Anger]있잖아……[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]maybe I don't need to feel so bad about the sharks we fed to that thing.", "[e:Anger]저것에게 먹인 상어들 때문에 너무 마음 아파하지 않아도 되겠어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]The smell doesn't get any better...", "[e:Anger]냄새는 여전히 끔찍하군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I knew something was off[w:0.3]", "[e:Anger]뭔가 이상하다 했어[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Guess I've got a good grasp of people too.", "[e:Laughter]나도 사람 보는 눈이 있나 보군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Get ready.", "[e:Laughter]준비해.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Nothing to worry about", "[e:Laughter]걱정할 것 없어", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]I can disarm the traps from afar.", "[e:Laughter]멀리서 함정을 해제할 수 있어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We shouldn't have any trouble at all.", "[e:Laughter]아무 문제도 없을 거야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Here we go.", "[e:Laughter]시작하자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]If you don't want to sacrifice anybody", "[e:Laughter]아무도 희생하고 싶지 않다면", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]let me get rid of these things myself.", "[e:Laughter]내가 직접 이것들을 없앨게.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]So this is the guy behind everything?[w:0.3]", "[e:Curious]모든 일의 배후가 이 사람이라고?[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]Not sure what I was expecting", "[e:Curious]뭘 기대했는지는 모르겠지만", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]But it doesn't matter.[w:0.3]", "[e:Anger]이제 상관없어.[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Let's end this.", "[e:Anger]이걸 끝내자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We've done this before", "[e:Laughter]전에 해 봤으니", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]let's do it again.", "[e:Laughter]다시 한번 하자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy's no joke.", "[e:Anger]이 녀석은 만만하지 않아.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Don't let your guard down.", "[e:Anger]경계를 늦추지 마.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]We've got this, don't worry.", "[e:Laughter]우리가 해낼 수 있어. 걱정 마.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]A...[w:0.3]pirate?", "[e:Surprise]해……[w:0.3]적이라고?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Hah, good one![w:0.3]", "[e:Laughter]하, 재미있군![w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Well, there's only one thing left to do.", "[e:Laughter]좋아, 이제 할 일은 하나뿐이야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Watch out for the cannons.", "[e:Anger]대포를 조심해.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This will be tough, but we can do this.", "[e:Anger]힘들겠지만 우리는 할 수 있어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This guy isn't playing around, stay on guard.", "[e:Anger]이 녀석은 장난이 아니야. 경계를 늦추지 마.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]Is this some kind of...[w:0.5] Magic?[w:0.5]", "[e:Surprise]이건 무슨……[w:0.5]마법인가?[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Well, I guess this is going to get much weirder.", "[e:Quiet]앞으로 훨씬 더 이상해지겠군.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]They're getting empowered. Stay alert.", "[e:Anger]저들이 강화되고 있어. 경계해.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Not this thing again...", "[e:Anger]또 이 녀석이군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Curious]How come I don't get fancy toys like this?", "[e:Curious]왜 나한테는 이런 멋진 장난감이 없지?", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Just a little handicap, nothing more.", "[e:Laughter]그냥 작은 불리함일 뿐이야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Let's not give up just yet.", "[e:Laughter]아직 포기하지 말자.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Surprise]What?[w:0.5] You of all people?[w:0.5]", "[e:Surprise]뭐?[w:0.5]하필 너라고?[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]I wish it didn't come down to this, but...[w:0.3]", "[e:Neutral]이렇게 되지 않았으면 좋았겠지만……[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Quiet]Guess we've got no choice.", "[e:Quiet]다른 선택지가 없는 것 같아.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]This one's tough. Get ready.", "[e:Anger]이 녀석은 강해. 준비해.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]One wrong move and we're done for.", "[e:Anger]한 번 잘못 움직이면 끝이야.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I really don't like dealing with her...", "[e:Anger]저 여자를 상대하는 건 정말 싫어……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I always got bad vibes from these guys.[w:0.5]", "[e:Anger]저 녀석들은 늘 불길한 느낌이었어.[w:0.5]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]I've seen people like them.[w:0.3]", "[e:Anger]저들과 비슷한 사람들을 본 적 있어.[w:0.3]", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Anger]Whatever drives them,", "[e:Anger]무엇이 저들을 움직이든,", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]we can get through just fine.", "[e:Laughter]우리는 무사히 헤쳐 나갈 수 있어.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]These guys again...", "[e:Neutral]또 저 녀석들이군……", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Laughter]Come on, we didn't get this far just to kick the bucket here.", "[e:Laughter]기운 내. 여기서 죽으려고 여기까지 온 건 아니잖아.", Language.Korean);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[e:Neutral]This is getting dangerous. Get ready.", "[e:Neutral]위험해지고 있어. 준비해.", Language.Korean);


        }
    }
}
